// ─── Global uncaught error handler — collect client crashes to /api/client-errors ──
window.addEventListener('error', (event) => {
  const { message, filename, lineno, colno, error } = event;
  // Ignore favicon/network resource errors — they're noise
  if (!filename || filename.includes('favicon') || filename.includes('.png') || filename.includes('.jpg')) return;
  fetch('/api/client-errors', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ message, source: filename, lineno, colno, stack: error?.stack, url: window.location.href, timestamp: new Date().toISOString() }),
  }).catch(() => {}); // Don't let the error reporter crash the app
});

