// ─── Toast ────────────────────────────────────────────────────────────────────
function toast(msg, type = 'info', duration = 2500) {
  const container = document.getElementById('toast-container');
  if (!container) return;
  const el = document.createElement('div');
  el.className = `toast ${type}`;
  el.textContent = msg;
  container.appendChild(el);
  setTimeout(() => el.remove(), duration);
}

// ─── Checkout return handler ───────────────────────────────────────────────
(function handleCheckoutReturn() {
  const params = new URLSearchParams(window.location.search);
  const checkoutStatus = params.get('checkout');
  const requestedPlan = params.get('plan');

  // Handle checkout return from Stripe
  const storeSuccess = params.get('store_success');
  const purchasedAssetId = params.get('asset_id');
  if (storeSuccess === '1') {
    window.history.replaceState({}, '', window.location.pathname + window.location.hash);
    toast('Asset acquired! Check your library.', 'success', 5000);
    // Refresh store if open
    if (typeof window.openStore === 'function') window.openStore();
  } else if (checkoutStatus === 'success') {
    window.history.replaceState({}, '', window.location.pathname + window.location.hash);
    toast('Subscription activated! Welcome to Atlantist Pro.', 'success', 5000);
  } else if (checkoutStatus === 'cancelled') {
    window.history.replaceState({}, '', window.location.pathname + window.location.hash);
    toast('Checkout cancelled. No charge was made.', 'info');
  }

  // Pricing page CTA landed here — trigger checkout if plan param present
  if (requestedPlan && ['monthly', 'yearly'].includes(requestedPlan)) {
    window.history.replaceState({}, '', window.location.pathname + window.location.hash);
    (async () => {
      try {
        const res = await fetch('/api/auth/me');
        if (!res.ok) throw new Error('not_logged_in');
        const data = await res.json();
        if (data.user?.anonymous || !data.user) throw new Error('not_logged_in');

        // Open account modal and trigger checkout immediately
        _showAccountModal();
        // Give modal a tick to render, then click upgrade
        setTimeout(async () => {
          const btnId = requestedPlan === 'yearly' ? 'account-upgrade-yearly' : 'account-upgrade-monthly';
          const btn = document.getElementById(btnId);
          if (btn) btn.click();
        }, 100);
      } catch (err) {
        // Not logged in — open the signup/login prompt
        const loginPrompt = document.getElementById('account-login-prompt');
        if (loginPrompt) loginPrompt.click();
      }
    })();
  }
})();

// ─── IFC Layer Helpers (module scope — used before DOMContentLoaded fires) ───
function getElementIfcType(el) {
  if (!el) return 'native';
  return el.ifc_type || 'native';
}

// refreshLayerCounts — updates layer count badges in the IFC layers panel.
// Hoisted to module scope so loadAll() can call it at module load time
// (before DOMContentLoaded fires and defines the callback-local version).
function refreshLayerCounts() {
  const counts = {};
  for (const el of state.elements) {
    const t = getElementIfcType(el);
    counts[t] = (counts[t] || 0) + 1;
  }
  for (const fi of state.familyInstances) {
    const t = getElementIfcType(fi);
    if (t !== 'native') counts[t] = (counts[t] || 0) + 1;
  }
  for (const lvl of state.levels) {
    const t = lvl.ifc_type || 'native';
    counts[t] = (counts[t] || 0) + 1;
  }
  Object.keys(counts).forEach(t => {
    const el = document.getElementById('count-' + t);
    if (el) el.textContent = counts[t] || '0';
  });
  const nativeCount = state.elements.filter(e => !e.ifc_type).length
    + state.familyInstances.filter(f => !f.ifc_type).length
    + state.levels.filter(l => !l.ifc_type).length;
  const nativeEl = document.getElementById('count-native');
  if (nativeEl) nativeEl.textContent = nativeCount || '0';
}
window.refreshLayerCounts = refreshLayerCounts;

// ─── API helpers ─────────────────────────────────────────────────────────────
async function api(method, path, body) {
  // Guard: demo projects are read-only — block all writes so visitors can explore safely
  if (window.isDemoProject && method !== 'GET') {
    toast('Demo is read-only — click Fork to create your own editable copy.', 'info', 3500);
    throw new Error('demo_readonly');
  }
  const opts = { method, headers: { 'Content-Type': 'application/json' } };
  if (body) opts.body = JSON.stringify(body);
  try {
    const res = await fetch(path, opts);
    // Content-type validation: reject non-JSON responses before attempting parse
    const contentType = res.headers.get('content-type') || '';
    if (!contentType.includes('application/json')) {
      const rawText = await res.text();
      const preview = rawText.length > 120 ? rawText.slice(0, 120) + '…' : rawText;
      console.error(`[api] Non-JSON response from ${path} (${res.status}) content-type: ${contentType} preview: ${preview}`);
      throw new Error(`Unexpected response (${res.status}) from ${path}`);
    }
    // Safely parse JSON — server may return HTML error pages during deploys or crashes
    let data;
    try {
      data = await res.json();
    } catch (_parseErr) {
      throw new Error(res.status >= 500 ? `Server error (${res.status})` : `Unexpected response (${res.status})`);
    }
    if (!res.ok) throw new Error(data.error || res.statusText);
    // Flash save pill for any successful mutation so users see instant feedback
    if (method !== 'GET') showSavePill('saved');
    return data;
  } catch (err) {
    if (method !== 'GET') {
      // Distinguish offline vs server error
      const offline = !navigator.onLine || err.message === 'Failed to fetch';
      showSavePill(offline ? 'offline' : 'retrying', null, offline ? 0 : 3000);
    }
    throw err;
  }
}

// ─── Data loading ─────────────────────────────────────────────────────────────
export async function loadAll() {
  // Skeleton injection is handled by the boot IIFE (~line 8150) via
  // injectSkeletonOverlay(_treePanel, 'tree') / injectSkeletonOverlay(_propsPanel, 'props').
  // This function must NOT call injectSkeletonOverlay() — it requires (panelEl, kind).
  let projectId = window.currentProjectId;

  // Safety fallback: if currentProjectId is still undefined (pre-boot script may not have
  // resolved yet when this is called) AND the URL has ?demo=, resolve it now synchronously.
  // This prevents loadAll() from sending project_id=undefined on first call.
  if (!projectId) {
    const params = new URLSearchParams(window.location.search);
    const demoSlug = params.get('demo');
    if (demoSlug) {
      try {
        const resp = await fetch('/api/demo/' + encodeURIComponent(demoSlug));
        if (resp.ok) {
          const demo = await resp.json();
          if (demo && demo.id) {
            projectId = demo.id;
            window.currentProjectId = demo.id;
            window.isDemoProject = true;
            console.log('[loadAll safety-fallback] demo resolved via fetch:', demo.name);
            // Auto-seed geometry on first demo load if no elements exist yet
            fetch('/api/demo/seed', { method: 'POST' }).catch(() => {});
          }
        }
      } catch (_) {}
    }
  }

  if (!projectId) {
    console.warn('[loadAll] no projectId set — showing blank scene');
    dismissSkeletonOverlay();
    rebuildScene();
    return;
  }
  // Use allSettled so one failing endpoint doesn't block the entire app
  const urls = [
    `/api/elements?project_id=${projectId}`,
    `/api/levels?project_id=${projectId}`,
    '/api/catalog/wall-types',
    '/api/catalog/column-types',
    '/api/catalog/roof-types',
    `/api/families?project_id=${projectId}`,
    '/api/families/types/doors',
    '/api/families/types/windows',
    `/api/mep-elements?project_id=${projectId}`,
    `/api/stairs?project_id=${projectId}`,
    `/api/railings?project_id=${projectId}`,
    '/api/stairs/types',
    '/api/railings/types',
    `/api/grids?project_id=${projectId}`,
    `/api/rooms?project_id=${projectId}`,
    `/api/floors?project_id=${projectId}`,
    `/api/ceilings?project_id=${projectId}`,
    `/api/curved-surfaces?project_id=${projectId}`,
    `/api/structural/members?project_id=${projectId}`,
    `/api/structural/runs?project_id=${projectId}`,
  ];
  const results = await Promise.allSettled(urls.map(url => api('GET', url)));
  // Extract values — default to empty arrays for failed requests
  const failed = results.filter(r => r.status === 'rejected');
  if (failed.length > 0) {
    console.warn(`[loadAll] ${failed.length}/20 endpoints failed:`, failed.map((r, i) => {
      const idx = results.indexOf(r);
      return `${urls[idx]}: ${r.reason?.message}`;
    }));
  }
  const [elements, levels, wallTypes, columnTypes, roofTypes, familyInstances, doorTypes, windowTypes, mepElements, stairs, railings, stairTypes, railingTypes, grids, rooms, floors, ceilings, curvedSurfaces, structuralMembers, structuralRuns] =
    results.map((r, i) => r.status === 'fulfilled' ? r.value : []);
  state.elements = elements;
  state.levels = levels;
  state.wallTypes = wallTypes;
  state.columnTypes = columnTypes;
  state.roofTypes = roofTypes;
  state.familyInstances = familyInstances;
  state.doorTypes = doorTypes;
  state.windowTypes = windowTypes;
  state.mepElements = mepElements;
  state.stairs = stairs;
  state.railings = railings;
  state.stairTypes = stairTypes;
  state.railingTypes = railingTypes;
  state.grids = grids;
  state.rooms = rooms;
  state.floors = floors;
  state.ceilings = ceilings;
  state.curvedSurfaces = curvedSurfaces;
  // Structural endpoints return { members: [...] } / { runs: [...] } wrappers — unwrap
  state.structuralMembers = Array.isArray(structuralMembers) ? structuralMembers
    : Array.isArray(structuralMembers?.members) ? structuralMembers.members : [];
  state.structuralRuns = Array.isArray(structuralRuns) ? structuralRuns
    : Array.isArray(structuralRuns?.runs) ? structuralRuns.runs : [];

  // Build stress map from pre-computed analysis runs
  state.structuralStressMap = {};
  if (structuralRuns && structuralRuns.length) {
    const completedRun = structuralRuns.find(r => r.status === 'completed') || structuralRuns[0];
    if (completedRun && completedRun.member_results) {
      const results = typeof completedRun.member_results === 'string'
        ? JSON.parse(completedRun.member_results)
        : completedRun.member_results;
      Object.entries(results).forEach(([key, val]) => {
        state.structuralStressMap[key] = val;
      });
    }
  }

  renderLevelList();
  // dismiss skeleton once first scene geometry is ready — progressive elements load after
  dismissSkeletonOverlay();
  rebuildScene();
  if (state.selectedId) refreshPropertiesPanel();
  window.refreshLayerCounts?.();

  // BULK-LIBS: Build BVH acceleration tree for raycasting after scene is populated
  if (scene3d) {
    try { buildBVH(scene3d); } catch (_) {}
  }
}

