// ─── Renderers ────────────────────────────────────────────────────────────────
function makeRenderer(canvasId) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return null;
  const r = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false });
  r.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  r.shadowMap.enabled = true;
  return r;
}
// Safe dummy renderer — used when canvas element is missing so subsequent
// renderer.domElement calls don't throw TypeError. The dummy's domElement
// is null, so canvas-relative operations silently no-op.
function makeDummyRenderer() {
  return {
    domElement: null,
    setSize() {},
    render() {},
    dispose() {},
    getContext() { return null; },
  };
}
// Fully release a WebGL renderer — dispose + forceContextLoss prevents
// "Too many active WebGL contexts" when renderers are recreated.
function disposeRendererFull(r) {
  if (!r || !r.domElement) return;
  try { r.dispose(); } catch (_) {}
  try { r.forceContextLoss(); } catch (_) {}
  // Remove auto-created canvases from DOM (e.g. structural viz creates its own
  // canvas and appends it). Skip named canvases that belong to the HTML template.
  try {
    const el = r.domElement;
    if (el.parentNode && !el.id) el.parentNode.removeChild(el);
  } catch (_) {}
}
// Release all secondary (non-viewport) WebGL renderers: FDS, geotechnical,
// structural viz, energy year-viz, simulation timeline.  Called on discipline
// switch so we never hold >3 active contexts (one per viewport pane).
// Safe to reference module-level let vars because this is only called from
// user-triggered switchDiscipline — well after all top-level lets execute.
function disposeSecondaryRenderers() {
  // Cancel ALL secondary animation loops BEFORE disposing renderers — prevents
  // orphaned rAF callbacks from running on dead GL contexts.
  try { if (fdsAnimId) { cancelAnimationFrame(fdsAnimId); fdsAnimId = null; } } catch (_) {}
  try { if (geoVizMesh) { cancelAnimationFrame(geoVizMesh); geoVizMesh = null; } } catch (_) {}
  try { if (_yvizAnimId) { cancelAnimationFrame(_yvizAnimId); _yvizAnimId = null; } } catch (_) {}
  // Cancel structural viz animation loop — _structVizGetAnimId lives on window
  // because the let declaration is block-scoped inside a DOMContentLoaded callback
  // and unreachable from this top-level function.
  try { if (window._structVizGetAnimId) { cancelAnimationFrame(window._structVizGetAnimId()); window._structVizGetAnimId = null; } } catch (_) {}
  try { if (fdsRenderer) { disposeRendererFull(fdsRenderer); fdsRenderer = null; } } catch (_) {}
  try { if (geoRenderer) { disposeRendererFull(geoRenderer); geoRenderer = null; } } catch (_) {}
  try { if (_yvizMiniRenderer) { disposeRendererFull(_yvizMiniRenderer); _yvizMiniRenderer = null; } } catch (_) {}
  try { if (window._structRenderer) { disposeRendererFull(window._structRenderer); window._structRenderer = null; } } catch (_) {}
  try { destroyTimeline(); } catch (_) {}
}
const renderer3d = makeRenderer('canvas-3d') || makeDummyRenderer();
const rendererPlan = makeRenderer('canvas-plan') || makeDummyRenderer();
const rendererSection = makeRenderer('canvas-section') || makeDummyRenderer();

// ─── Controls ─────────────────────────────────────────────────────────────────
const _dummyCanvas = (() => {
  const d = document.createElement('canvas');
  d.style.display = 'none';
  document.body.appendChild(d);
  return d;
})();
const controls3d = new OrbitControls(cam3d, renderer3d.domElement || _dummyCanvas);
controls3d.enableDamping = true;
controls3d.dampingFactor = 0.08;
controls3d.target.set(5, 2, 5);
// enablePan is true by default; enableDamping enables smooth momentum
controls3d.enablePan = true;

// ── Space+drag pan + middle-mouse pan ──────────────────────────────────────
// Track space-key held state
let _spaceHeld = false;
let _panStartX = 0, _panStartY = 0, _panStartTgtX = 0, _panStartTgtY = 0, _panStartTgtZ = 0;

// Re-wire controls to VP canvas once viewport-manager creates it
function wireControlsToVPCanvas() {
  // Find VP canvas for 3D pane (vp-canvas-p0) or fall back to static canvas-3d
  const vpCanvas = document.getElementById('vp-canvas-p0') || document.getElementById('canvas-3d');
  if (!vpCanvas) return;
  // Repoint OrbitControls to the VP canvas element
  controls3d.dispose();
  const newControls = new OrbitControls(cam3d, vpCanvas);
  newControls.enableDamping = true;
  newControls.dampingFactor = 0.08;
  newControls.target.set(controls3d.target.x, controls3d.target.y, controls3d.target.z);
  newControls.enablePan = true;
  // Copy position
  newControls.object.position.set(cam3d.position.x, cam3d.position.y, cam3d.position.z);
  Object.assign(controls3d, newControls);
  // Do NOT create a new renderer here — watchForVPReady creates _vpRenderer3d
  // which fully replaces renderer3d. Creating one here would leak a GL context
  // because Object.assign cannot transfer WebGL internal state.
}

// Space held → toggles pan mode
document.addEventListener('keydown', (e) => {
  if (e.code === 'Space' && !e.target.matches('input,textarea,select,[contenteditable]')) {
    e.preventDefault();
    _spaceHeld = true;
    document.body.style.cursor = 'grab';
  }
});
document.addEventListener('keyup', (e) => {
  if (e.code === 'Space') {
    _spaceHeld = false;
    document.body.style.cursor = '';
  }
});

// Middle-mouse drag → pan regardless of space
if (!renderer3d.domElement) {
  console.warn('[app] renderer3d.domElement is null — middle-mouse pan will not bind');
} else {
  renderer3d.domElement.addEventListener('mousedown', (e) => {
    if (e.button === 1) {  // Middle mouse
      e.preventDefault();
      controls3d.enabled = false; // Disable OrbitControls during middle-drag
      _panStartX = e.clientX;
      _panStartY = e.clientY;
      _panStartTgtX = controls3d.target.x;
      _panStartTgtY = controls3d.target.y;
      _panStartTgtZ = controls3d.target.z;
      const started = performance.now();
      const onMove = (me) => {
        const dx = (me.clientX - _panStartX) * 0.05;
        const dy = (_panStartY - me.clientY) * 0.05; // Y is flipped
        controls3d.target.set(_panStartTgtX + dx, _panStartTgtY + dy, _panStartTgtZ);
      };
      const onUp = () => {
        controls3d.enabled = true;
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
      };
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
    }
  });
}

// Space+drag pan (camera-relative horizontal panning)
if (!renderer3d.domElement) {
  // Already warned above; space-pan just won't activate.
} else {
  renderer3d.domElement.addEventListener('mousedown', (e) => {
    if (_spaceHeld && e.button === 0) {
    _panStartX = e.clientX;
    _panStartY = e.clientY;
    _panStartTgtX = controls3d.target.x;
    _panStartTgtY = controls3d.target.y;
    _panStartTgtZ = controls3d.target.z;
    controls3d.enabled = false;
    const onMove = (me) => {
      const dx = (me.clientX - _panStartX) * 0.05;
      const dy = (_panStartY - me.clientY) * 0.05;
      controls3d.target.set(_panStartTgtX + dx, _panStartTgtY + dy, _panStartTgtZ);
    };
    const onUp = () => {
      controls3d.enabled = true;
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  }
});
}

// On viewport-manager init: create real WebGL renderers on VP canvases and wire everything.
// watchForVPReady() polls until vp-canvas-p0 exists (built by viewport-manager DOM init).
// WHY module-level vars: passing new renderer instances directly to initViewports avoids
// the broken Object.setPrototypeOf mutation pattern that failed to copy prototype methods.
let _vpWired = false;
let _vpRenderer3d = null;    // renderer bound to VP canvas-p0 (3D)
let _vpRendererPlan = null;  // renderer bound to VP canvas-p1 (Plan)
let _vpRendererSect = null;  // renderer bound to VP canvas-p2 (Elevation)
let _vpControls3d = null;    // OrbitControls bound to VP canvas-p0

// Bootstrap the VP DOM immediately so vp-canvas-p0/p1/p2/p3 exist in the document.
// Pass null renderers so applyViewportCameras no-ops until watchForVPReady creates
// real per-pane WebGL renderers (it calls initCameraMap to swap them in).
// WHY null: the bootstrap WebGLRenderers (canvas-3d etc) are destroyed when
// buildViewportDOM clears #viewport-area innerHTML — passing them to initViewports
// would leave rendererMap pointing at detached nodes.
// WHY here: calling initViewports inside watchForVPReady was a deadlock — it polled
// for vp-canvas-p0 which could only be created by initViewports itself.
initViewports(cam3d, camPlan, camSection, null, null, null);

// Track how many polls have run so we can force-wire after 3s even at 0×0
// (the canvas ResizeObserver in viewport-manager will pick up the real size once laid out)
let _vpWireAttempts = 0;
function watchForVPReady() {
  const vpCanvas = document.getElementById('vp-canvas-p0');
  _vpWireAttempts++;
  // Wait until canvas exists AND has nonzero width, OR give up at 30 attempts (~3s)
  // and wire anyway — ResizeObserver will call applyViewportCameras when size arrives.
  const hasSize = vpCanvas && vpCanvas.clientWidth >= 4;
  if (!vpCanvas || (!hasSize && _vpWireAttempts < 30)) {
    setTimeout(watchForVPReady, 100);
    return;
  }
  if (_vpWired) return;
  _vpWired = true;

  // Stop the bootstrap animation loop started before VP DOM was ready
  cancelAnimationFrame(animId);

  const fallbackW = Math.max(window.innerWidth  || 800, 400);
  const fallbackH = Math.max(window.innerHeight || 600, 300);

  // Dispose bootstrap renderers BEFORE creating VP renderers to keep active
  // WebGL context count as low as possible (browsers cap at ~8-16).
  disposeRendererFull(renderer3d);
  disposeRendererFull(rendererPlan);
  disposeRendererFull(rendererSection);

  // 3D renderer on vp-canvas-p0
  // Use fallback if canvas is still 0×0 (not yet laid out) — ResizeObserver will fix sizes
  const w0 = Math.max(vpCanvas.clientWidth,  fallbackW);
  const h0 = Math.max(vpCanvas.clientHeight, fallbackH);
  _vpRenderer3d = new THREE.WebGLRenderer({ canvas: vpCanvas, antialias: true, alpha: false });
  _vpRenderer3d.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  _vpRenderer3d.shadowMap.enabled = true;
  _vpRenderer3d.shadowMap.type = THREE.PCFSoftShadowMap;
  _vpRenderer3d.toneMapping = THREE.ACESFilmicToneMapping;
  _vpRenderer3d.toneMappingExposure = 1.0;
  _vpRenderer3d.setSize(w0, h0, false);

  // OrbitControls re-pointed to the VP canvas
  controls3d.dispose();
  _vpControls3d = new OrbitControls(cam3d, vpCanvas);
  _vpControls3d.enableDamping = true;
  _vpControls3d.dampingFactor = 0.08;
  _vpControls3d.enablePan = true;
  _vpControls3d.target.copy(controls3d.target);
  // Expose on window so raycaster event listeners can reach it
  window._atlantist_controls3d = _vpControls3d;

  // Plan renderer on vp-canvas-p1
  const vpPlan = document.getElementById('vp-canvas-p1');
  if (vpPlan) {
    const w1 = Math.max(vpPlan.clientWidth,  fallbackW);
    const h1 = Math.max(vpPlan.clientHeight, fallbackH);
    _vpRendererPlan = new THREE.WebGLRenderer({ canvas: vpPlan, antialias: true, alpha: false });
    _vpRendererPlan.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    _vpRendererPlan.shadowMap.enabled = false;
    _vpRendererPlan.toneMapping = THREE.ACESFilmicToneMapping;
    _vpRendererPlan.toneMappingExposure = 1.0;
    _vpRendererPlan.setSize(w1, h1, false);
  }

  // Section/elevation renderer on vp-canvas-p2
  const vpSect = document.getElementById('vp-canvas-p2');
  if (vpSect) {
    const w2 = Math.max(vpSect.clientWidth,  fallbackW);
    const h2 = Math.max(vpSect.clientHeight, fallbackH);
    _vpRendererSect = new THREE.WebGLRenderer({ canvas: vpSect, antialias: true, alpha: false });
    _vpRendererSect.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    _vpRendererSect.shadowMap.enabled = false;
    _vpRendererSect.toneMapping = THREE.ACESFilmicToneMapping;
    _vpRendererSect.toneMappingExposure = 1.0;
    _vpRendererSect.setSize(w2, h2, false);
  }

  // Elevation pane p3 uses the same section scene — create renderer if present
  const vpSect2 = document.getElementById('vp-canvas-p3');
  if (vpSect2 && !_vpRendererSect) {
    const w3 = Math.max(vpSect2.clientWidth,  fallbackW);
    const h3 = Math.max(vpSect2.clientHeight, fallbackH);
    _vpRendererSect = new THREE.WebGLRenderer({ canvas: vpSect2, antialias: true, alpha: false });
    _vpRendererSect.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    _vpRendererSect.shadowMap.enabled = false;
    _vpRendererSect.setSize(w3, h3, false);
  }

  // Swap camera/renderer map to the new per-pane VP renderers — no full DOM rebuild needed.
  // buildViewportDOM already ran via the initial initViewports call above.
  initCameraMap(cam3d, camPlan, camSection,
    _vpRenderer3d   || renderer3d,
    _vpRendererPlan || rendererPlan,
    _vpRendererSect || rendererSection);

  // RP-1: Wire RenderModeManager to per-pane scene/renderer refs.
  // p0 → 3D/perspective, p1 → plan, p2 → elevation X, p3 → elevation Y (shares p2 renderer)
  const paneScenes = new Map([
    ['p0', scene3d],
    ['p1', scenePlan],
    ['p2', sceneSection],
    ['p3', sceneSection],
  ]);
  const paneRenderers = new Map([
    ['p0', _vpRenderer3d   || renderer3d],
    ['p1', _vpRendererPlan || rendererPlan],
    ['p2', _vpRendererSect || rendererSection],
    ['p3', _vpRendererSect || rendererSection],
  ]);
  const paneCamKey = new Map([
    ['p0', '3d'],
    ['p1', 'plan'],
    ['p2', 'section'],
    ['p3', 'section'],
  ]);
  setRenderModeManagerScenes(paneScenes, paneRenderers, paneCamKey);

  // RP-4: preload material atlas textures in the background — avoids pop-in on first
  // Textured mode switch. Runs without blocking any UI init.
  import('../services/render-modes/TexturedMode.js').then(mod => {
    if (mod.preloadAtlases) mod.preloadAtlases().catch(() => {});
  }).catch(() => {});

  // G8 perf fix: ResizeObserver for zero-layout-cost canvas resize detection.
  // Replaces the old syncRendererSizes() call inside the RAF loop which caused
  // layout thrash by reading clientWidth/clientHeight on every frame.
  // Fires at ~60fps but only when size actually changes — not every RAF tick.
  const _resizeObs = new ResizeObserver(() => {
    if (!_vpWired) return;
    try {
      // ResizeObserver may fire during VP teardown — guard against stale state.
      syncRendererSizes();
      if (typeof applyViewportCameras === 'function') applyViewportCameras();
    } catch (_) {}
  });
  // Observe all 4 VP canvas wrappers (p0..p3) for size changes.
  ['canvas-3d-wrap', 'canvas-plan-wrap', 'canvas-section-wrap'].forEach(id => {
    const wrap = document.getElementById(id);
    if (wrap) _resizeObs.observe(wrap);
  });
  // Also observe the legacy bootstrap wraps (hidden but may be re-shown on layout switch)
  ['vp-canvas-p0', 'vp-canvas-p1', 'vp-canvas-p2', 'vp-canvas-p3'].forEach(id => {
    const el = document.getElementById(id);
    if (el) _resizeObs.observe(el);
  });

  // Relocate overlay elements from legacy canvas-3d-wrap into the VP p0 pane
  // so they remain visible after the bootstrap wrap is hidden.
  const vpWrapP0 = document.getElementById('vp-wrap-p0');
  if (vpWrapP0) {
    ['viewcube-wrap', 'cursor-overlay-3d', 'snap-indicator'].forEach(id => {
      const el = document.getElementById(id);
      if (el && el.parentElement !== vpWrapP0) vpWrapP0.appendChild(el);
    });
  }

  // Hide legacy bootstrap canvas wraps — they are replaced by VP canvas elements.
  // Without hiding them, they stack under VP panes and can intercept pointer events
  // or cause WebGL context conflicts on slow devices.
  ['canvas-3d-wrap', 'canvas-plan-wrap', 'canvas-section-wrap'].forEach(id => {
    const el = document.getElementById(id);
    if (el) { el.style.display = 'none'; el.setAttribute('aria-hidden', 'true'); }
  });

  // Re-attach middle-mouse and space+drag pan listeners to the VP canvas
  // (the original listeners were on renderer3d.domElement which was a dummy/null)
  if (!vpCanvas) {
    console.warn('[app] vpCanvas is null in watchForVPReady — VP canvas DOM not found');
    return;
  }
  vpCanvas.addEventListener('mousedown', (e) => {
    const ctrl = _vpControls3d;
    if (!ctrl) return;
    if (e.button === 1) {
      e.preventDefault();
      ctrl.enabled = false;
      const sx = e.clientX, sy = e.clientY;
      const tx = ctrl.target.x, ty = ctrl.target.y, tz = ctrl.target.z;
      const onMove = (me) => {
        ctrl.target.set(tx + (me.clientX - sx) * 0.05, ty + (sy - me.clientY) * 0.05, tz);
      };
      const onUp = () => { ctrl.enabled = true; document.removeEventListener('mousemove', onMove); document.removeEventListener('mouseup', onUp); };
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
    } else if (_spaceHeld && e.button === 0) {
      ctrl.enabled = false;
      const sx = e.clientX, sy = e.clientY;
      const tx = ctrl.target.x, ty = ctrl.target.y, tz = ctrl.target.z;
      const onMove = (me) => {
        ctrl.target.set(tx + (me.clientX - sx) * 0.05, ty + (sy - me.clientY) * 0.05, tz);
      };
      const onUp = () => { ctrl.enabled = true; document.removeEventListener('mousemove', onMove); document.removeEventListener('mouseup', onUp); };
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
    }
  });

  // Re-attach picking to VP canvas
  setupPicking(vpCanvas, _vpRenderer3d, cam3d);

  // Register the post-buildViewportDOM rewire callback — fires every time
  // viewport-manager rebuilds the DOM (fullscreen, layout change, server restore).
  // This ensures renderers are always bound to the live canvas elements.
  setOnAfterBuildViewportDOM(rewireVPRenderers);

  // Start the render loop with VP renderers active
  animate();

  // SP-D: attach ortho viewport click listeners for cross-viewport placement
  _setupOrthoPlacementListeners();

  // SP-D: attach scroll-based close-up zoom during placement
  _setupPlacementScrollZoom();
}
setTimeout(watchForVPReady, 200);

// Rewire WebGL renderers to the current VP canvas elements.
// Called automatically by viewport-manager after every buildViewportDOM() call.
// Without this, renderers remain bound to detached (destroyed) canvas nodes,
// and all subsequent render() calls produce invisible output.
function rewireVPRenderers() {
  const fallbackW = Math.max(window.innerWidth  || 800, 400);
  const fallbackH = Math.max(window.innerHeight || 600, 300);

  const vp0 = document.getElementById('vp-canvas-p0');
  const vp1 = document.getElementById('vp-canvas-p1');
  const vp2 = document.getElementById('vp-canvas-p2');
  const vp3 = document.getElementById('vp-canvas-p3');

  // If VP canvases don't exist yet, skip — watchForVPReady will handle initial wire
  if (!vp0) return;

  // Dispose and replace only if the canvas element changed (DOM rebuild creates new nodes)
  function needsRewire(renderer, canvas) {
    return renderer && canvas && renderer.domElement !== canvas;
  }

  if (needsRewire(_vpRenderer3d, vp0)) {
    disposeRendererFull(_vpRenderer3d);
    const w = Math.max(vp0.clientWidth, fallbackW);
    const h = Math.max(vp0.clientHeight, fallbackH);
    _vpRenderer3d = new THREE.WebGLRenderer({ canvas: vp0, antialias: true, alpha: false });
    _vpRenderer3d.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    _vpRenderer3d.shadowMap.enabled = true;
    _vpRenderer3d.shadowMap.type = THREE.PCFSoftShadowMap;
    _vpRenderer3d.toneMapping = THREE.ACESFilmicToneMapping;
    _vpRenderer3d.toneMappingExposure = 1.0;
    _vpRenderer3d.setSize(w, h, false);
    // Re-bind OrbitControls and picking to the new canvas
    if (_vpControls3d) {
      _vpControls3d.dispose();
      _vpControls3d = new OrbitControls(cam3d, vp0);
      _vpControls3d.enableDamping = true;
      _vpControls3d.dampingFactor = 0.08;
      _vpControls3d.enablePan = true;
      window._atlantist_controls3d = _vpControls3d;
    }
    setupPicking(vp0, _vpRenderer3d, cam3d);
  }

  if (vp1 && needsRewire(_vpRendererPlan, vp1)) {
    disposeRendererFull(_vpRendererPlan);
    const w = Math.max(vp1.clientWidth, fallbackW);
    const h = Math.max(vp1.clientHeight, fallbackH);
    _vpRendererPlan = new THREE.WebGLRenderer({ canvas: vp1, antialias: true, alpha: false });
    _vpRendererPlan.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    _vpRendererPlan.shadowMap.enabled = false;
    _vpRendererPlan.toneMapping = THREE.ACESFilmicToneMapping;
    _vpRendererPlan.toneMappingExposure = 1.0;
    _vpRendererPlan.setSize(w, h, false);
  }

  // Section/elevation: pane p2 or p3 — always create for whichever pane exists
  const sectCanvas = vp2 || vp3;
  if (sectCanvas && needsRewire(_vpRendererSect, sectCanvas)) {
    disposeRendererFull(_vpRendererSect);
    const w = Math.max(sectCanvas.clientWidth, fallbackW);
    const h = Math.max(sectCanvas.clientHeight, fallbackH);
    _vpRendererSect = new THREE.WebGLRenderer({ canvas: sectCanvas, antialias: true, alpha: false });
    _vpRendererSect.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    _vpRendererSect.shadowMap.enabled = false;
    _vpRendererSect.toneMapping = THREE.ACESFilmicToneMapping;
    _vpRendererSect.toneMappingExposure = 1.0;
    _vpRendererSect.setSize(w, h, false);
  }

  // Update the camera/renderer map with the new renderer references
  initCameraMap(cam3d, camPlan, camSection,
    _vpRenderer3d   || renderer3d,
    _vpRendererPlan || rendererPlan,
    _vpRendererSect || rendererSection);

  // RP-1: push updated renderer refs to RenderModeManager after rewire
  const paneRenderers = new Map([
    ['p0', _vpRenderer3d   || renderer3d],
    ['p1', _vpRendererPlan || rendererPlan],
    ['p2', _vpRendererSect || rendererSection],
    ['p3', _vpRendererSect || rendererSection],
  ]);
  const paneScenes = new Map([
    ['p0', scene3d], ['p1', scenePlan], ['p2', sceneSection], ['p3', sceneSection],
  ]);
  const paneCamKey = new Map([
    ['p0', '3d'], ['p1', 'plan'], ['p2', 'section'], ['p3', 'section'],
  ]);
  try { setRenderModeManagerScenes(paneScenes, paneRenderers, paneCamKey); } catch (_) {}

  // Relocate overlay elements (viewcube, cursor, snap) to the new p0 wrap
  const vpWrapP0 = document.getElementById('vp-wrap-p0');
  if (vpWrapP0) {
    ['viewcube-wrap', 'cursor-overlay-3d', 'snap-indicator'].forEach(id => {
      const el = document.getElementById(id);
      if (el && el.parentElement !== vpWrapP0) vpWrapP0.appendChild(el);
    });
  }

  // Force an immediate render pass to populate the new canvas with scene content
  requestAnimationFrame(() => applyViewportCameras());
}

// Sidebar open/close notification hook — called by app-shell.js after layout shift.
// Forces renderer resize + render so VP canvases fill the new available width.
window._atlNotifyVPResize = function() {
  applyViewportCameras();
  notifyPaneVisible();
};

// ─── ViewCube click handler — snap camera to preset orientations ──────────────
// Computes a bounding box center from loaded elements to aim the camera there.
function getModelCenter() {
  const box = new THREE.Box3();
  let hasGeom = false;
  scene3d.traverse(obj => {
    if (obj.isMesh) { box.expandByObject(obj); hasGeom = true; }
  });
  if (!hasGeom) return new THREE.Vector3(5, 5, 5);
  const c = new THREE.Vector3();
  box.getCenter(c);
  return c;
}

const VIEW_PRESETS = {
  top:   { offset: [0, 1, 0] },
  front: { offset: [0, 0, 1] },
  right: { offset: [1, 0, 0] },
  back:  { offset: [0, 0, -1] },
  left:  { offset: [-1, 0, 0] },
  iso:   { offset: [1, 1, 1] },
};

function snapCameraToPreset(presetName) {
  const preset = VIEW_PRESETS[presetName];
  if (!preset) return;
  const center = getModelCenter();
  const dist = 40; // distance from center
  const off = new THREE.Vector3(...preset.offset).normalize().multiplyScalar(dist);
  cam3d.position.copy(center).add(off);
  cam3d.lookAt(center);
  cam3d.updateProjectionMatrix();
  const ctrl = _vpControls3d || controls3d;
  ctrl.target.copy(center);
  ctrl.update();
}
window.snapCameraToPreset = snapCameraToPreset;

// Wire viewcube SVG — click regions map to view presets by quadrant
document.getElementById('viewcube')?.addEventListener('click', (e) => {
  const svg = e.currentTarget;
  const rect = svg.getBoundingClientRect();
  const x = (e.clientX - rect.left) / rect.width;  // 0–1
  const y = (e.clientY - rect.top) / rect.height;   // 0–1
  // Center zone → isometric; top → top; bottom → front; left → left; right → right
  const cx = x - 0.5, cy = y - 0.5;
  const r = Math.sqrt(cx * cx + cy * cy);
  if (r < 0.15) { snapCameraToPreset('iso'); return; }
  if (cy < -0.2) { snapCameraToPreset('top'); return; }
  if (cy > 0.2)  { snapCameraToPreset('front'); return; }
  if (cx < -0.15) { snapCameraToPreset('left'); return; }
  if (cx > 0.15)  { snapCameraToPreset('right'); return; }
  snapCameraToPreset('iso');
});

// ─── Ortho ↔ Perspective toggle ──────────────────────────────────────────────
// Replaces cam3d in-place — copies position/rotation/target. OrbitControls re-bound.
let _cameraIsPerspective = true;

function toggleCameraProjection() {
  const ctrl = _vpControls3d || controls3d;
  const oldPos = cam3d.position.clone();
  const oldTarget = ctrl.target.clone();

  if (_cameraIsPerspective) {
    // Switch to ortho — compute frustum from current FOV + distance
    const dist = oldPos.distanceTo(oldTarget);
    const halfH = dist * Math.tan(THREE.MathUtils.degToRad(cam3d.fov / 2));
    const aspect = cam3d.aspect || 1;
    cam3d.isPerspectiveCamera = false;
    // Morph the existing camera into orthographic projection
    // Three.js cameras are typed at construction; the clean way is to swap the
    // projection matrix directly and update the flag.
    Object.assign(cam3d, {
      left: -halfH * aspect,
      right: halfH * aspect,
      top: halfH,
      bottom: -halfH,
      zoom: 1,
    });
    cam3d.isPerspectiveCamera = false;
    cam3d.isOrthographicCamera = true;
    cam3d.updateProjectionMatrix = function() {
      if (this.isOrthographicCamera) {
        const dx = (this.right - this.left) / (2 * this.zoom);
        const dy = (this.top - this.bottom) / (2 * this.zoom);
        const cx = (this.right + this.left) / 2;
        const cy = (this.top + this.bottom) / 2;
        this.projectionMatrix.makeOrthographic(cx - dx, cx + dx, cy + dy, cy - dy, 0.1, 10000);
        this.projectionMatrixInverse.copy(this.projectionMatrix).invert();
      } else {
        THREE.PerspectiveCamera.prototype.updateProjectionMatrix.call(this);
      }
    };
    _cameraIsPerspective = false;
    const orthoBtn = document.getElementById('btn-ortho-toggle');
    if (orthoBtn) orthoBtn.textContent = 'Ortho';
    toast('Orthographic projection', 'info', 1500);
  } else {
    // Switch back to perspective
    cam3d.isPerspectiveCamera = true;
    cam3d.isOrthographicCamera = false;
    cam3d.updateProjectionMatrix = THREE.PerspectiveCamera.prototype.updateProjectionMatrix;
    cam3d.fov = 45;
    cam3d.near = 0.1;
    cam3d.far = 10000;
    _cameraIsPerspective = true;
    const perspBtn = document.getElementById('btn-ortho-toggle');
    if (perspBtn) perspBtn.textContent = 'Persp';
    toast('Perspective projection', 'info', 1500);
  }
  cam3d.position.copy(oldPos);
  ctrl.target.copy(oldTarget);
  cam3d.updateProjectionMatrix();
  ctrl.update();
}
window.toggleCameraProjection = toggleCameraProjection;

// ─── View type → camera switch ─────────────────────────────────────────────
// viewport-manager.js calls this when a tab's view type changes.
// Handles camera morph (perspective ↔ orthographic) based on view type.
window._atlantist_applyViewportCameraState = function(paneId, viewType, cameraState) {
  // The camera to operate on is always cam3d (the primary 3D camera)
  // For plan/section views, we morph cam3d into ortho mode
  const ctrl = _vpControls3d || controls3d;

  // Decide: perspective or orthographic?
  const isOrtho = ['top', 'front', 'back', 'left', 'right', 'section_x', 'section_y', 'rcp'].includes(viewType);

  if (isOrtho && _cameraIsPerspective) {
    // Morph perspective → ortho
    const oldPos = cam3d.position.clone();
    const oldTarget = ctrl.target.clone();
    const dist = oldPos.distanceTo(oldTarget) || 30;
    const halfH = dist * Math.tan(THREE.MathUtils.degToRad(cam3d.fov / 2));
    const aspect = window.innerWidth / window.innerHeight;

    cam3d.isPerspectiveCamera = false;
    Object.assign(cam3d, {
      left: -halfH * aspect,
      right: halfH * aspect,
      top: halfH,
      bottom: -halfH,
      zoom: 1,
    });
    cam3d.isPerspectiveCamera = false;
    cam3d.isOrthographicCamera = true;
    cam3d.updateProjectionMatrix = function() {
      if (this.isOrthographicCamera) {
        const dx = (this.right - this.left) / (2 * (this.zoom || 1));
        const dy = (this.top - this.bottom) / (2 * (this.zoom || 1));
        const cx = (this.right + this.left) / 2;
        const cy = (this.top + this.bottom) / 2;
        this.projectionMatrix.makeOrthographic(cx - dx, cx + dx, cy + dy, cy - dy, 0.1, 10000);
        this.projectionMatrixInverse.copy(this.projectionMatrix).invert();
      }
    };
    _cameraIsPerspective = false;
    if (document.getElementById('btn-ortho-toggle')) document.getElementById('btn-ortho-toggle').textContent = 'Ortho';
  } else if (!isOrtho && !_cameraIsPerspective) {
    // Morph ortho → perspective
    cam3d.isPerspectiveCamera = true;
    cam3d.isOrthographicCamera = false;
    cam3d.updateProjectionMatrix = THREE.PerspectiveCamera.prototype.updateProjectionMatrix;
    cam3d.fov = 45;
    cam3d.near = 0.1;
    cam3d.far = 10000;
    _cameraIsPerspective = true;
    if (document.getElementById('btn-ortho-toggle')) document.getElementById('btn-ortho-toggle').textContent = 'Persp';
  }

  // Apply camera state (position + target)
  if (cameraState) {
    if (cameraState.position) {
      cam3d.position.set(cameraState.position.x, cameraState.position.y, cameraState.position.z);
    }
    if (cameraState.target) {
      ctrl.target.set(cameraState.target.x, cameraState.target.y, cameraState.target.z);
    }
    if (cameraState.zoom) {
      cam3d.zoom = cameraState.zoom;
      cam3d.updateProjectionMatrix();
      ctrl.update();
    }
  }

  ctrl.update();
};

// Keyboard shortcut: Numpad 5 or 'O' for ortho toggle (Revit convention)
document.addEventListener('keydown', (e) => {
  if (e.target.matches('input,textarea,select,[contenteditable]')) return;
  if (e.key === 'o' || e.key === 'O' || e.code === 'Numpad5') {
    if (!e.ctrlKey && !e.metaKey) toggleCameraProjection();
  }
  // Numpad view presets (Blender convention)
  if (e.code === 'Numpad7') snapCameraToPreset('top');
  if (e.code === 'Numpad1') snapCameraToPreset('front');
  if (e.code === 'Numpad3') snapCameraToPreset('right');
  if (e.code === 'Numpad0') snapCameraToPreset('iso');
});

// ─── Lighting ─────────────────────────────────────────────────────────────────
function addLights(scene) {
  const amb = new THREE.AmbientLight(0xffffff, 0.5);
  const dir = new THREE.DirectionalLight(0xffffff, 1);
  dir.position.set(10, 20, 10);
  dir.castShadow = true;
  const fill = new THREE.DirectionalLight(0x8888ff, 0.3);
  fill.position.set(-10, 5, -5);
  scene.add(amb, dir, fill);
}
addLights(scene3d);
// Fog near/far tuned for 10-story building (~36m) — far must exceed max zoom-out distance
scene3d.fog = new THREE.Fog(COLORS.sky, 80, 500);

function addOrthLights(scene) {
  scene.add(new THREE.AmbientLight(0xffffff, 1.0));
  const dir = new THREE.DirectionalLight(0xffffff, 0.5);
  dir.position.set(0, 50, 0);
  scene.add(dir);
}
addOrthLights(scenePlan);
addOrthLights(sceneSection);

// ─── Selection raycasting ────────────────────────────────────────────────────
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();

// Maps mesh UUID → { id, type: 'element'|'level' }
const pickMap = new Map();

// ─── Adaptive Grid Engine init (SP-B) ─────────────────────────────────────────
// Init once now; re-init with full module config once module_project is loaded.
window._atlantist_scenes = window._atlantist_scenes || { '3d': scene3d, 'plan': scenePlan, 'section': sceneSection };
if (window.AdaptiveGrid) {
  // Use a placeholder config until loadModuleState provides the real values.
  // snapFine/snapCoarse derived the same way as services/module-system.js getModuleDerived.
  const M_mm = 1000;
  window.AdaptiveGrid.initWithModuleConfig({
    M_mm,
    sys: 'si',
    grid: [
      { label: 'M',    value: M_mm },
      { label: 'M/2',  value: M_mm / 2 },
      { label: 'M/4',  value: M_mm / 4 },
      { label: '2M',   value: M_mm * 2 },
      { label: '4M',   value: M_mm * 4 },
    ],
    standardOC_mm: [12, 16, 24, 32, 48].map(v => v * 25.4),
    snap: { fine: M_mm / 8, coarse: M_mm / 4 },
  });
  window.AdaptiveGrid.initGridEngine(
    window._atlantist_scenes,
    window._atlantist_cameras,
    null, // rendMap populated by VP wiring
    raycaster,
    mouse,
  );
}

function setupPicking(canvas, renderer, camera) {
  if (!canvas) return; // guard: canvas may be null if VP manager destroyed it
  canvas?.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(mouse, camera);
    const hits = raycaster.intersectObjects([...pickMap.keys()].map(k => scene3d.getObjectByProperty('uuid', k)).filter(Boolean), false);
    if (hits.length) {
      // Walk up parent chain to find a UUID that has a pickMap entry (for GROUP objects)
      let obj = hits[0].object;
      let meta = null;
      while (obj && !meta) {
        meta = pickMap.get(obj.uuid);
        obj = obj.parent;
      }
      if (meta) {
        if (e.ctrlKey || e.metaKey) {
          // Ctrl/Cmd+click: toggle into multi-selection
          multiToggle(meta.id, meta.type);
        } else {
          // Plain click: clear multi-selection, do single-select
          state.multiSelection = [];
          selectEntity(meta.id, meta.type);
        }
      }
    } else {
      state.multiSelection = [];
      selectEntity(null, null);
    }
  });

  // SP-B: Adaptive Grid — mouse hover activates object-relative grids
  canvas?.addEventListener('mousemove', (e) => {
    if (!window.AdaptiveGrid) return;
    const rect = canvas.getBoundingClientRect();
    mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(mouse, camera);

    // Find the nearest scene to raycast against (prefer 3d for 3D viewports)
    const targetScene = scene3d;
    const allMeshes = [...pickMap.keys()]
      .map(k => targetScene.getObjectByProperty('uuid', k))
      .filter(Boolean);

    const hits = raycaster.intersectObjects(allMeshes, false);
    if (hits.length) {
      // Walk up to find the group that owns this mesh
      let obj = hits[0].object;
      let hitMeta = null;
      while (obj && !hitMeta) {
        hitMeta = pickMap.get(obj.uuid);
        obj = obj.parent;
      }
      if (hitMeta) {
        // Walk further up to the top-level object group for the element
        let group = hits[0].object;
        while (group.parent && !pickMap.has(group.uuid)) group = group.parent;
        const worldPos = hits[0].point;
        window.AdaptiveGrid.onElementHovered(hitMeta.id, group, worldPos);
        return;
      }
    }
    window.AdaptiveGrid.onElementUnhovered();
  });
}

// Toggle an entity in/out of multiSelection without touching selectedId
function multiToggle(id, type) {
  const idx = state.multiSelection.findIndex(s => s.id === id);
  if (idx === -1) {
    // Add — also include the current single-selected item if switching to multi
    if (state.selectedId && !state.multiSelection.some(s => s.id === state.selectedId)) {
      state.multiSelection.push({ id: state.selectedId, type: state.selectedType });
    }
    state.multiSelection.push({ id, type });
    state.selectedId = id;
    state.selectedType = type;
  } else {
    state.multiSelection.splice(idx, 1);
    if (state.multiSelection.length === 0) {
      state.selectedId = null;
      state.selectedType = null;
    }
  }
  rebuildScene();
  updateMultiSelectStatus();
}
// setupPicking is guarded — only call if canvas exists (viewport-manager may replace)
const c3 = document.getElementById('canvas-3d');
const cP = document.getElementById('canvas-plan');
if (c3) setupPicking(c3, renderer3d, cam3d);
if (cP) setupPicking(cP, rendererPlan, camPlan);

// ─── Scene objects (element meshes) ──────────────────────────────────────────
// Maps element/level id → array of Three.js objects
const objectMap = new Map();

function clearMeshes() {
  objectMap.forEach((objs) => objs.forEach(o => {
    if (o.parent) o.parent.remove(o);
    if (o.geometry) { o.geometry.dispose(); o.geometry = null; }
    if (o.material) { o.material.dispose(); o.material = null; }
  }));
  objectMap.clear();
  pickMap.clear();
}

// ─── Debounced scene rebuild ─────────────────────────────────────────────────
// Coalesces rapid rebuildScene() calls (e.g. from debouncedPatch callbacks)
// into a single rebuild after 80ms of silence. Prevents double/triple rebuilds
// when the user changes multiple properties in quick succession.
let _rebuildTimer = null;
let _rebuildPending = false;
function scheduleRebuild() {
  if (_rebuildPending) return; // already scheduled — coalesce
  _rebuildPending = true;
  clearTimeout(_rebuildTimer);
  _rebuildTimer = setTimeout(() => {
    _rebuildPending = false;
    rebuildScene();
  }, 80);
}

function levelElevation(levelId) {
  const l = state.levels.find(l => l.id === levelId);
  return l ? parseFloat(l.elevation) : 0;
}

function buildWallMesh(el, isSelected, wallFamilies = []) {
  const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : (el.parameters || {});
  const computed = typeof el.computed === 'string' ? JSON.parse(el.computed) : (el.computed || {});

  const sx = parseFloat(params.startCoord?.x || 0);
  const sy = parseFloat(params.startCoord?.y || 0);
  const ex = parseFloat(params.endCoord?.x || sx + 5);
  const ey = parseFloat(params.endCoord?.y || sy);
  const length = Math.sqrt((ex - sx) ** 2 + (ey - sy) ** 2) || 1;
  const height = parseFloat(computed.height || 3);
  const thick = parseFloat(computed.thickness || params.thickness || 0.2);
  const baseElev = levelElevation(el.base_level_id);
  const cx = (sx + ex) / 2;
  const cy = (sy + ey) / 2;
  const angle = Math.atan2(ey - sy, ex - sx);

  const color = isSelected ? COLORS.selected : (params.loadBearing ? COLORS.wall_exterior : COLORS.wall_interior);
  const lineColor = isSelected ? 0x7aaff0 : 0x4a5a6a;

  // When no families → single solid wall
  if (wallFamilies.length === 0) {
    const geo = new THREE.BoxGeometry(length, height, thick);
    const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(cx, baseElev + height / 2, cy);
    mesh.rotation.y = -angle;
    const edges = new THREE.EdgesGeometry(geo);
    mesh.add(new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: lineColor })));
    mesh.userData = { id: el.id, type: 'element' };
    pickMap.set(mesh.uuid, { id: el.id, type: 'element' });
    return [mesh];
  }

  // Sort families by u position along wall
  const sorted = [...wallFamilies].sort((a, b) => parseFloat(a.host_face_u) - parseFloat(b.host_face_u));

  // Build wall segments — skip region around each family opening
  const meshes = [];
  const segments = [];

  // Start segment: from wall start to first family opening start
  const firstFam = sorted[0];
  const firstU = parseFloat(firstFam.host_face_u);
  const firstParams = typeof firstFam.parameters === 'string' ? JSON.parse(firstFam.parameters) : (firstFam.parameters || {});
  const firstOpenW = parseFloat(firstParams.width || 0.914);

  if (firstU * length - firstOpenW / 2 > 0) {
    segments.push({ start: -length / 2, end: firstU * length - firstOpenW / 2 });
  }

  // Middle segments: between consecutive family openings
  for (let i = 0; i < sorted.length - 1; i++) {
    const curFam = sorted[i];
    const curParams = typeof curFam.parameters === 'string' ? JSON.parse(curFam.parameters) : (curFam.parameters || {});
    const curU = parseFloat(curFam.host_face_u);
    const curW = parseFloat(curParams.width || 0.914);

    const nextFam = sorted[i + 1];
    const nextParams = typeof nextFam.parameters === 'string' ? JSON.parse(nextFam.parameters) : (nextFam.parameters || {});
    const nextU = parseFloat(nextFam.host_face_u);
    const nextW = parseFloat(nextParams.width || 0.914);

    const segStart = curU * length + curW / 2;
    const segEnd = nextU * length - nextW / 2;
    if (segEnd - segStart > 0) segments.push({ start: segStart, end: segEnd });
  }

  // End segment: from last family opening end to wall end
  const lastFam = sorted[sorted.length - 1];
  const lastParams = typeof lastFam.parameters === 'string' ? JSON.parse(lastFam.parameters) : (lastFam.parameters || {});
  const lastU = parseFloat(lastFam.host_face_u);
  const lastW = parseFloat(lastParams.width || 0.914);

  if (lastU * length + lastW / 2 < length / 2) {
    segments.push({ start: lastU * length + lastW / 2, end: length / 2 });
  }

  for (const seg of segments) {
    const segLen = seg.end - seg.start;
    const geo = new THREE.BoxGeometry(segLen, height, thick);
    const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
    const mesh = new THREE.Mesh(geo, mat);
    // Segment center in wall-local x
    const localMidX = (seg.start + seg.end) / 2;
    // Convert to world position: rotate local offset then add to wall center
    const worldX = cx + localMidX * Math.cos(-angle);
    const worldZ = cy - localMidX * Math.sin(-angle); // sin(-angle) = -sin(angle)
    mesh.position.set(worldX, baseElev + height / 2, worldZ);
    mesh.rotation.y = -angle;

    const edges = new THREE.EdgesGeometry(geo);
    mesh.add(new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: lineColor })));
    mesh.userData = { id: el.id, type: 'element' };
    pickMap.set(mesh.uuid, { id: el.id, type: 'element' });
    meshes.push(mesh);
  }

  return meshes;
}

// ─── Phase 3.2: Floor slab mesh builder ─────────────────────────────────────
// Renders a horizontal slab (floor) at base_level elevation with multi-layer
// construction. Each layer gets a separate mesh with material-appropriate color.
function buildFloorMesh(floor, isSelected) {
  const params = typeof floor.parameters === 'string'
    ? JSON.parse(floor.parameters)
    : (floor.parameters || {});
  const layers = floor.layers || [];

  const baseElev = floor.base_level_id ? levelElevation(floor.base_level_id) : parseFloat(floor.elevation || 0);
  const thickness = parseFloat(floor.thickness || 0.3);
  const color = isSelected ? COLORS.selected : 0x7a5c3a; // concrete tan-brown

  const group = new THREE.Group();

  // Single-layer fallback
  if (layers.length === 0) {
    const boundary = params.boundary;
    if (boundary && Array.isArray(boundary) && boundary.length >= 3) {
      const cx = boundary.reduce((s, p) => s + parseFloat(p.x), 0) / boundary.length;
      const cz = boundary.reduce((s, p) => s + parseFloat(p.z || p.y), 0) / boundary.length;
      const shape = new THREE.Shape();
      const pts = boundary.map(p => new THREE.Vector2(
        parseFloat(p.x) - cx, parseFloat(p.z || p.y) - cz
      ));
      shape.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i].x, pts[i].y);
      shape.closePath();
      const geo = new THREE.ExtrudeGeometry(shape, { depth: thickness, bevelEnabled: false });
      const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.rotation.x = -Math.PI / 2;
      mesh.position.set(cx, baseElev, cz);
      group.add(mesh);
    } else {
      const w = parseFloat(params.width || 5);
      const d = parseFloat(params.depth || 5);
      const geo = new THREE.BoxGeometry(w, thickness, d);
      const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(parseFloat(floor.position_x || 0) + w / 2, baseElev + thickness / 2, parseFloat(floor.position_y || 0) + d / 2);
      group.add(mesh);
    }
  } else {
    // Multi-layer: render each layer from bottom up
    let cumulative = baseElev;
    const layerColors = {
      structure: 0x7a5c3a,
      finish: 0x9a7a5a,
      insulation: 0x5a8a9a,
      air_gap: 0x3a5a6a,
      membrane: 0x4a4a4a,
      wearing: 0x8a6a4a,
    };
    for (const layer of layers) {
      const lt = parseFloat(layer.thickness || 0.1);
      const lc = layerColors[layer.function] || 0x7a5c3a;
      const isFinish = layer.function === 'finish' || layer.function === 'wearing';

      // Render each layer as a flat slab using ExtrudeGeometry or BoxGeometry
      const boundary = params.boundary;
      let mesh;
      if (boundary && Array.isArray(boundary) && boundary.length >= 3) {
        const cx = boundary.reduce((s, p) => s + parseFloat(p.x), 0) / boundary.length;
        const cz = boundary.reduce((s, p) => s + parseFloat(p.z || p.y), 0) / boundary.length;
        const shape = new THREE.Shape();
        const pts = boundary.map(p => new THREE.Vector2(
          parseFloat(p.x) - cx, parseFloat(p.z || p.y) - cz
        ));
        shape.moveTo(pts[0].x, pts[0].y);
        for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i].x, pts[i].y);
        shape.closePath();
        const geo = new THREE.ExtrudeGeometry(shape, { depth: lt, bevelEnabled: false });
        const mat = new THREE.MeshLambertMaterial({ color: isSelected ? COLORS.selected : lc, transparent: true, opacity: isSelected ? 0.85 : 0.8 });
        mesh = new THREE.Mesh(geo, mat);
        mesh.rotation.x = -Math.PI / 2;
        mesh.position.set(cx, cumulative, cz);
      } else {
        const w = parseFloat(params.width || 5);
        const d = parseFloat(params.depth || 5);
        const geo = new THREE.BoxGeometry(w, lt, d);
        const mat = new THREE.MeshLambertMaterial({ color: isSelected ? COLORS.selected : lc, transparent: true, opacity: isSelected ? 0.85 : 0.8 });
        mesh = new THREE.Mesh(geo, mat);
        mesh.position.set(parseFloat(floor.position_x || 0) + w / 2, cumulative + lt / 2, parseFloat(floor.position_y || 0) + d / 2);
      }
      mesh.userData = { id: floor.id, type: 'floor' };
      pickMap.set(mesh.uuid, { id: floor.id, type: 'floor' });
      group.add(mesh);
      cumulative += lt;
    }
  }

  // Add edges
  for (const mesh of group.children) {
    const edges = new THREE.EdgesGeometry(mesh.geometry);
    mesh.add(new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: isSelected ? 0x7aaff0 : 0x5a5a6a })));
  }

  return group.children.length > 0 ? group.children : [group];
}

// 2D plan view: floor boundary polygon outline
function buildFloorPlan2D(floor) {
  const params = typeof floor.parameters === 'string'
    ? JSON.parse(floor.parameters)
    : (floor.parameters || {});
  const boundary = params.boundary;
  const baseElev = floor.base_level_id ? levelElevation(floor.base_level_id) : parseFloat(floor.elevation || 0);

  if (!boundary || !Array.isArray(boundary) || boundary.length < 3) return [];

  const pts = boundary.map(p => new THREE.Vector3(parseFloat(p.x), baseElev, parseFloat(p.z || p.y)));
  // Close the polygon
  if (pts[0].distanceTo(pts[pts.length - 1]) > 0.01) pts.push(pts[0].clone());

  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineBasicMaterial({ color: 0x5a4a3a, linewidth: 2 });
  const line = new THREE.Line(geo, mat);
  return [line];
}

// ─── Phase 3.2: Ceiling mesh builder ─────────────────────────────────────────
// Renders a horizontal plane at ceiling elevation (host_level.elevation + offset).
// Multi-layer: each layer renders as a flat mesh. Types: flat, sloped, coffered, exposed.
function buildCeilingMesh(ceiling, isSelected) {
  const params = typeof ceiling.parameters === 'string'
    ? JSON.parse(ceiling.parameters)
    : (ceiling.parameters || {});
  const layers = ceiling.layers || [];

  const hostElev = ceiling.host_level_id ? levelElevation(ceiling.host_level_id) : 3;
  const elevationOffset = parseFloat(ceiling.elevation_offset || 2.7);
  const baseY = hostElev + elevationOffset;
  const ceilingType = ceiling.ceiling_type || 'flat';
  const color = isSelected ? COLORS.selected : 0xd4c4b4; // light plaster

  const group = new THREE.Group();

  if (ceilingType === 'exposed_structure') {
    // Exposed deck: metal deck pattern (coarse grid lines)
    const w = parseFloat(params.width || 8);
    const d = parseFloat(params.depth || 6);
    const geo = new THREE.BoxGeometry(w, 0.003, d);
    const mat = new THREE.MeshLambertMaterial({ color: isSelected ? COLORS.selected : 0x888888, transparent: true, opacity: isSelected ? 0.85 : 0.6 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(parseFloat(ceiling.position_x || 0) + w / 2, baseY, parseFloat(ceiling.position_y || 0) + d / 2);
    mesh.userData = { id: ceiling.id, type: 'ceiling' };
    pickMap.set(mesh.uuid, { id: ceiling.id, type: 'ceiling' });
    group.add(mesh);

    // Deck ribs (cross pattern)
    const ribMat = new THREE.MeshLambertMaterial({ color: isSelected ? COLORS.selected : 0x666666, transparent: true, opacity: 0.5 });
    const ribW = 0.03;
    const ribH = 0.05;
    const ribSpacing = 0.3;
    for (let x = 0; x < w; x += ribSpacing) {
      const ribGeo = new THREE.BoxGeometry(ribW, ribH, d);
      const rib = new THREE.Mesh(ribGeo, ribMat);
      rib.position.set(x + ribW / 2, baseY - ribH / 2, parseFloat(ceiling.position_y || 0) + d / 2);
      group.add(rib);
    }

  } else if (ceilingType === 'flat' || ceilingType === 'sloped' || ceilingType === 'coffered') {
    const boundary = params.boundary;
    if (boundary && Array.isArray(boundary) && boundary.length >= 3) {
      const cx = boundary.reduce((s, p) => s + parseFloat(p.x), 0) / boundary.length;
      const cz = boundary.reduce((s, p) => s + parseFloat(p.z || p.y), 0) / boundary.length;
      const shape = new THREE.Shape();
      const pts = boundary.map(p => new THREE.Vector2(
        parseFloat(p.x) - cx, parseFloat(p.z || p.y) - cz
      ));
      shape.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i].x, pts[i].y);
      shape.closePath();

      const totalThick = layers.length > 0
        ? parseFloat(layers.reduce((s, l) => s + parseFloat(l.thickness || 0.013), 0).toFixed(4))
        : 0.013;

      const geo = new THREE.ExtrudeGeometry(shape, { depth: totalThick, bevelEnabled: false });
      const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.rotation.x = -Math.PI / 2;
      mesh.position.set(cx, baseY, cz);
      mesh.userData = { id: ceiling.id, type: 'ceiling' };
      pickMap.set(mesh.uuid, { id: ceiling.id, type: 'ceiling' });
      group.add(mesh);
    } else {
      const w = parseFloat(params.width || 5);
      const d = parseFloat(params.depth || 5);
      const totalThick = layers.length > 0
        ? parseFloat(layers.reduce((s, l) => s + parseFloat(l.thickness || 0.013), 0).toFixed(4))
        : 0.013;
      const geo = new THREE.BoxGeometry(w, totalThick, d);
      const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(parseFloat(ceiling.position_x || 0) + w / 2, baseY + totalThick / 2, parseFloat(ceiling.position_y || 0) + d / 2);
      mesh.userData = { id: ceiling.id, type: 'ceiling' };
      pickMap.set(mesh.uuid, { id: ceiling.id, type: 'ceiling' });
      group.add(mesh);
    }
  }

  return group.children.length > 0 ? group.children : [group];
}

function buildColumnMesh(el, isSelected) {
  const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : (el.parameters || {});
  const computed = typeof el.computed === 'string' ? JSON.parse(el.computed) : (el.computed || {});

  const height = parseFloat(computed.height || 3);
  const baseElev = levelElevation(el.base_level_id);
  const section = params.section || 'W12x26';

  // W-section: approximate as slightly non-square box
  const w = section.includes('W') ? 0.31 : 0.3;
  const d = 0.15;

  const geo = new THREE.BoxGeometry(w, height, d);
  const color = isSelected ? COLORS.selected : COLORS.column;
  const mat = new THREE.MeshLambertMaterial({ color });
  const mesh = new THREE.Mesh(geo, mat);

  // Parse grid intersection for position (e.g., A-1 → x=0,z=0)
  // rotatedX/rotatedZ override when a group rotation has moved the column off-grid
  const grid = params.gridIntersection || 'A-1';
  const colLetter = grid.split('-')[0] || 'A';
  const colNum = parseInt(grid.split('-')[1] || '1', 10);
  const x = params.rotatedX !== undefined ? params.rotatedX : (colLetter.charCodeAt(0) - 65) * 5;
  const z = params.rotatedZ !== undefined ? params.rotatedZ : (colNum - 1) * 5;

  mesh.position.set(x, baseElev + height / 2, z);

  const edges = new THREE.EdgesGeometry(geo);
  const lines = new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: 0x888866 }));
  mesh.add(lines);

  mesh.userData = { id: el.id, type: 'element' };
  pickMap.set(mesh.uuid, { id: el.id, type: 'element' });

  return [mesh];
}

// ─── Structural Member 3D Mesh (Phase 33) ───────────────────────────────────
/**
 * Build Three.js geometry for a structural member (column or beam).
 * Columns: vertical cylinders from start_node to end_node.
 * Beams: horizontal boxes.
 * Color is driven by DCR stress value from pre-computed analysis run.
 * Green (< 0.5) → Yellow (0.5–0.7) → Orange (0.7–0.9) → Red (> 0.9).
 */
function buildStructuralMemberMesh(member, isSelected) {
  const startNode = typeof member.start_node === 'string'
    ? JSON.parse(member.start_node) : (member.start_node || {});
  const endNode = typeof member.end_node === 'string'
    ? JSON.parse(member.end_node) : (member.end_node || {});

  const x1 = parseFloat(startNode.x) || 0;
  const y1 = parseFloat(startNode.y) || 0;
  const z1 = parseFloat(startNode.z) || 0;
  const x2 = parseFloat(endNode.x) || 0;
  const y2 = parseFloat(endNode.y) || 0;
  const z2 = parseFloat(endNode.z) || 0;

  const isColumn = member.member_type === 'column' || Math.abs(y2 - y1) > Math.abs(x2 - x1) + Math.abs(z2 - z1);
  const sectionName = member.section_name || 'W14x48';
  const dcr = parseFloat(state.structuralStressMap[member.name]?.dcr || 0);
  const color = stressToColor(dcr);

  let geo, mat, mesh;
  if (isColumn) {
    // Cylinder for columns
    const radius = getMemberRadius(sectionName);
    geo = new THREE.CylinderGeometry(radius, radius, y2 - y1, 12);
    mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: 0.9 });
    mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(x1, y1 + (y2 - y1) / 2, z1);
  } else {
    // Box for beams
    const len = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2) + Math.pow(z2 - z1, 2));
    const beamH = 0.3; // beam depth
    const beamW = getMemberWidth(sectionName);
    geo = new THREE.BoxGeometry(x2 - x1 || len, beamH, beamW);
    mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: 0.9 });
    mesh = new THREE.Mesh(geo, mat);
    mesh.position.set((x1 + x2) / 2, y1, (z1 + z2) / 2);
  }

  if (isSelected) {
    mesh.material = new THREE.MeshLambertMaterial({ color: 0x00aaff, transparent: true, opacity: 0.9 });
  }

  // Add edges
  const edges = new THREE.EdgesGeometry(geo);
  const lines = new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: 0x888888, transparent: true, opacity: 0.5 }));
  mesh.add(lines);

  mesh.userData = { id: member.id, type: 'structural_member', member_type: member.member_type, member_name: member.name };
  pickMap.set(mesh.uuid, { id: member.id, type: 'structural_member' });

  return [mesh];
}

function getMemberRadius(sectionName) {
  // W14x48 → 0.15m radius (~6" flange)
  if (sectionName.includes('W14')) return 0.15;
  if (sectionName.includes('W18')) return 0.18;
  if (sectionName.includes('W21')) return 0.21;
  return 0.12;
}

function getMemberWidth(sectionName) {
  if (sectionName.includes('W14')) return 0.30;
  if (sectionName.includes('W18')) return 0.36;
  if (sectionName.includes('W21')) return 0.40;
  return 0.25;
}

/**
 * Map DCR (0–1) to a color using the green→yellow→orange→red gradient
 * matching the structural engineer's viz_data color scheme.
 */
function stressToColor(dcr) {
  const gradient = [
    { t: 0.0, c: 0x22c55e }, // green — no stress
    { t: 0.4, c: 0x84cc16 }, // lime
    { t: 0.6, c: 0xfacc15 }, // yellow
    { t: 0.8, c: 0xf97316 }, // orange
    { t: 0.9, c: 0xef4444 }, // red
    { t: 1.0, c: 0x9333ea }, // purple — failure
  ];
  let lower = gradient[0], upper = gradient[gradient.length - 1];
  for (let i = 0; i < gradient.length - 1; i++) {
    if (dcr >= gradient[i].t && dcr <= gradient[i + 1].t) {
      lower = gradient[i]; upper = gradient[i + 1]; break;
    }
  }
  const t = upper.t === lower.t ? 0 : (dcr - lower.t) / (upper.t - lower.t);
  const r = Math.round(((upper.c >> 16) & 0xff) * t + ((lower.c >> 16) & 0xff) * (1 - t));
  const g = Math.round(((upper.c >> 8) & 0xff) * t + ((lower.c >> 8) & 0xff) * (1 - t));
  const b = Math.round((upper.c & 0xff) * t + (lower.c & 0xff) * (1 - t));
  return (r << 16) | (g << 8) | b;
}

// ─── Stair Mesh Builder (Phase 3.4) ─────────────────────────────────────────

/**
 * Build Three.js geometry for a stair element.
 * Parametric: riser_height computed from total_rise / number_of_risers.
 * Supports: straight, l_shaped, u_shaped, spiral, circular.
 * Each step = tread depth (horizontal) + riser height (vertical).
 */
function buildStairMesh(stair, isSelected) {
  const stairType   = stair.stair_type || stair.configuration || 'straight';
  const width       = parseFloat(stair.width || 1.0);
  const risers      = parseInt(stair.number_of_risers, 10) || 16;
  const treads      = parseInt(stair.number_of_treads, 10)  || (risers - 1);
  const treadDepth  = parseFloat(stair.tread_depth || 0.275);
  const riserH      = parseFloat(stair.riser_height || 0.1875);
  const totalRise   = parseFloat(stair.total_rise || 3.0);
  const posX        = parseFloat(stair.position_x || 0);
  const posY        = parseFloat(stair.position_y || 0);
  const rotation    = (parseFloat(stair.rotation_degrees) || 0) * Math.PI / 180;
  const baseElev    = parseFloat(stair.base_level_elevation || 0);

  const color = isSelected ? COLORS.selected : 0x7a7a7a; // concrete grey
  const lineColor = isSelected ? 0x7aaff0 : 0x555555;

  const group = new THREE.Group();
  group.position.set(posX, baseElev, posY);
  group.rotation.y = rotation;

  if (stairType === 'straight') {
    buildStraightStair(group, width, risers, treads, treadDepth, riserH, color, lineColor, isSelected);
  } else if (stairType === 'l_shaped') {
    // L-shape: first flight up, 90° turn, second flight up
    const flights = 2;
    const risersPerFlight = Math.floor(risers / flights);
    const treadsPerFlight = Math.floor(treads / flights);
    buildStraightStair(group, width, risersPerFlight, treadsPerFlight, treadDepth, riserH, color, lineColor, isSelected);
    // Landing platform at top of first flight
    const landingGeo = new THREE.BoxGeometry(width, 0.12, 1.2);
    const landingMat = new THREE.MeshLambertMaterial({ color: 0x6a6a6a, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
    const landing = new THREE.Mesh(landingGeo, landingMat);
    landing.position.set(0, risersPerFlight * riserH, treadsPerFlight * treadDepth + 0.6);
    group.add(landing);
    // Second flight, offset by landing
    buildStraightStair(group, width, risers - risersPerFlight, treads - treadsPerFlight, treadDepth, riserH, color, lineColor, isSelected,
      treadsPerFlight * treadDepth + 1.2,  // X offset for second flight
      risersPerFlight * riserH              // Y offset for second flight
    );
  } else if (stairType === 'u_shaped') {
    const flights = 3;
    const rpFlight = Math.floor(risers / flights);
    const tpFlight = Math.floor(treads / flights);
    buildStraightStair(group, width, rpFlight, tpFlight, treadDepth, riserH, color, lineColor, isSelected);
    const midY = rpFlight * riserH;
    const midX = tpFlight * treadDepth + 1.2;
    // Landing
    const landingGeo = new THREE.BoxGeometry(width, 0.12, 1.2);
    const landingMat = new THREE.MeshLambertMaterial({ color: 0x6a6a6a, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
    group.add(new THREE.Mesh(landingGeo, landingMat));
    // Second flight
    buildStraightStair(group, width, rpFlight, tpFlight, treadDepth, riserH, color, lineColor, isSelected, midX, midY);
    // Third flight
    buildStraightStair(group, width, rpFlight, tpFlight, treadDepth, riserH, color, lineColor, isSelected, 0, midY * 2);
  } else if (stairType === 'spiral') {
    buildSpiralStair(group, width, risers, treadDepth, riserH, baseElev, color, lineColor, isSelected);
  } else if (stairType === 'circular') {
    buildSpiralStair(group, width, risers, treadDepth, riserH, baseElev, color, lineColor, isSelected);
  }

  // Edges for selection
  if (isSelected) {
    group.traverse(obj => {
      if (obj.isMesh && obj.geometry) {
        const edges = new THREE.EdgesGeometry(obj.geometry);
        obj.add(new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: lineColor })));
      }
    });
  }

  group.userData = { id: stair.id, type: 'stair' };
  pickMap.set(group.uuid, { id: stair.id, type: 'stair' });
  return [group];
}

function buildStraightStair(group, width, risers, treads, treadDepth, riserH, color, lineColor, isSelected, offsetX = 0, offsetY = 0) {
  // Each step: tread (horizontal box) + riser (vertical face)
  for (let i = 0; i < risers; i++) {
    // Tread: horizontal slab
    const treadGeo = new THREE.BoxGeometry(width, 0.04, treadDepth);
    const treadMat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.9 : 0.8 });
    const tread = new THREE.Mesh(treadGeo, treadMat);
    tread.position.set(offsetX + width / 2, offsetY + i * riserH + 0.02, i * treadDepth);
    group.add(tread);

    // Riser: vertical face
    const riserGeo = new THREE.BoxGeometry(width, riserH, 0.02);
    const riserMat = new THREE.MeshLambertMaterial({ color: 0x8a8a8a, transparent: true, opacity: isSelected ? 0.9 : 0.75 });
    const riser = new THREE.Mesh(riserGeo, riserMat);
    riser.position.set(offsetX + width / 2, offsetY + i * riserH + riserH / 2, i * treadDepth + treadDepth);
    group.add(riser);
  }
}

function buildSpiralStair(group, width, risers, treadDepth, riserH, baseElev, color, lineColor, isSelected) {
  const innerR = width * 0.4;
  const outerR = width;
  const stepsPerTurn = 12;
  for (let i = 0; i < risers; i++) {
    const angle = (i / stepsPerTurn) * 2 * Math.PI;
    const y = i * riserH;
    const cx = Math.cos(angle) * (innerR + (outerR - innerR) / 2);
    const cz = Math.sin(angle) * (innerR + (outerR - innerR) / 2);

    // Step wedge
    const stepGeo = new THREE.BoxGeometry(outerR - innerR, 0.04, treadDepth);
    const stepMat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.9 : 0.8 });
    const step = new THREE.Mesh(stepGeo, stepMat);
    step.position.set(cx, y + 0.02, cz);
    step.rotation.y = -angle;
    group.add(step);
  }
}

// ─── Railing Mesh Builder (Phase 3.4) ──────────────────────────────────────

/**
 * Build Three.js geometry for a railing element.
 * Follows the host stair boundary — left, right, or both sides.
 * Types: baluster (vertical posts), glass (transparent panel), handrail, monolithic.
 */
function buildRailingMesh(railing, isSelected) {
  const stair = state.stairs.find(s => s.id === railing.host_stair_id);
  if (!stair) return [];

  const height       = parseFloat(railing.height || 0.9);
  const topRailW     = parseFloat(railing.top_rail_width || 0.05);
  const balusterSpc  = parseFloat(railing.baluster_spacing || 0.11);
  const railType     = railing.railing_type || 'baluster';
  const side         = railing.side || 'left';
  const material     = railing.material || 'Aluminum';
  const glassFinish  = railing.glass_finish || 'clear';

  const width      = parseFloat(stair.width || 1.0);
  const risers     = parseInt(stair.number_of_risers, 10) || 16;
  const treads      = parseInt(stair.number_of_treads, 10) || (risers - 1);
  const treadDepth = parseFloat(stair.tread_depth || 0.275);
  const riserH     = parseFloat(stair.riser_height || 0.1875);
  const posX       = parseFloat(stair.position_x || 0);
  const posY       = parseFloat(stair.position_y || 0);
  const rotation   = (parseFloat(stair.rotation_degrees) || 0) * Math.PI / 180;
  const baseElev   = parseFloat(stair.base_level_elevation || 0);

  const group = new THREE.Group();
  group.position.set(posX, baseElev, posY);
  group.rotation.y = rotation;

  const drawSide = (side === 'both') ? ['left', 'right'] : [side];
  const leftX  = 0;
  const rightX = width;

  for (const s of drawSide) {
    const x = s === 'left' ? leftX - 0.05 : rightX - width + 0.05;

    if (railType === 'baluster') {
      // Top rail (horizontal bar)
      const railGeo = new THREE.BoxGeometry(0.05, height, treads * treadDepth);
      const railColor = material === 'Wood' ? 0x8B6914 : 0xaaaaaa;
      const railMat = new THREE.MeshLambertMaterial({ color: railColor });
      const topRail = new THREE.Mesh(railGeo, railMat);
      topRail.position.set(x + 0.025, height / 2, 0);
      group.add(topRail);

      // Balusters (vertical posts at regular intervals)
      const balCount = Math.ceil((treads * treadDepth) / balusterSpc);
      for (let i = 0; i <= balCount; i++) {
        const balGeo = new THREE.BoxGeometry(0.03, height, 0.03);
        const balMat = new THREE.MeshLambertMaterial({ color: railColor });
        const bal = new THREE.Mesh(balGeo, balMat);
        bal.position.set(x + 0.025, height / 2, i * balusterSpc);
        group.add(bal);
      }

    } else if (railType === 'glass') {
      // Glass panel with top rail
      const glassColor = glassFinish === 'frosted' ? 0xdddddd : glassFinish === 'tinted' ? 0x6688aa : 0xaaddff;
      const glassGeo = new THREE.BoxGeometry(0.015, height - 0.1, treads * treadDepth);
      const glassMat = new THREE.MeshLambertMaterial({ color: glassColor, transparent: true, opacity: 0.35, side: THREE.DoubleSide });
      const panel = new THREE.Mesh(glassGeo, glassMat);
      panel.position.set(x + 0.025, height / 2, 0);
      group.add(panel);

      // Top rail
      const railGeo = new THREE.BoxGeometry(0.06, 0.06, treads * treadDepth);
      const railMat = new THREE.MeshLambertMaterial({ color: 0xaaaaaa });
      const topRail = new THREE.Mesh(railGeo, railMat);
      topRail.position.set(x + 0.03, height - 0.03, 0);
      group.add(topRail);

    } else if (railType === 'handrail') {
      // Wall-mounted handrail: single horizontal tube
      const tubeGeo = new THREE.CylinderGeometry(0.025, 0.025, treads * treadDepth, 8);
      const tubeColor = material === 'Wood' ? 0x8B6914 : 0xaaaaaa;
      const tubeMat = new THREE.MeshLambertMaterial({ color: tubeColor });
      const tube = new THREE.Mesh(tubeGeo, tubeMat);
      tube.rotation.x = Math.PI / 2;
      tube.position.set(x + 0.025, height - 0.05, treads * treadDepth / 2);
      group.add(tube);

    } else if (railType === 'monolithic') {
      // Solid concrete/metal wall
      const wallGeo = new THREE.BoxGeometry(0.1, height, treads * treadDepth);
      const wallColor = material === 'Concrete' ? 0x999999 : 0x888888;
      const wallMat = new THREE.MeshLambertMaterial({ color: wallColor, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
      const wall = new THREE.Mesh(wallGeo, wallMat);
      wall.position.set(x, height / 2, treads * treadDepth / 2);
      group.add(wall);
    }
  }

  // Edges for selection
  if (isSelected) {
    group.traverse(obj => {
      if (obj.isMesh && obj.geometry) {
        const edges = new THREE.EdgesGeometry(obj.geometry);
        obj.add(new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: 0x7aaff0 })));
      }
    });
  }

  group.userData = { id: railing.id, type: 'railing' };
  pickMap.set(group.uuid, { id: railing.id, type: 'railing' });
  return [group];
}

// ─── Phase 3.3: Structural Grid Mesh Builder ─────────────────────────────────
/**
 * Build Three.js geometry for a structural grid.
 * Renders all grid lines as line segments with bubble labels.
 * X-axis lines: horizontal lines (fixed z, varying x)
 * Z-axis lines: vertical lines (fixed x, varying z)
 */
function buildGridMesh(grid) {
  const lines = grid.lines || [];
  const xLines = lines.filter(l => l.axis === 'x');
  const zLines = lines.filter(l => l.axis === 'z');
  const originX = parseFloat(grid.origin_x || 0);
  const originZ = parseFloat(grid.origin_z || 0);
  const spacingX = parseFloat(grid.spacing_x || 5);
  const spacingZ = parseFloat(grid.spacing_z || 5);

  const group = new THREE.Group();
  const lineMat = new THREE.LineBasicMaterial({ color: 0x888899, transparent: true, opacity: 0.7 });

  // Render grid extents based on line coordinates or generate from labels
  const xCoords = xLines.length > 0 ? xLines.map(l => parseFloat(l.coordinate)) : [0, 5, 10, 15, 20];
  const zCoords = zLines.length > 0 ? zLines.map(l => parseFloat(l.coordinate)) : [0, 5, 10, 15, 20];

  const minX = xCoords.length ? Math.min(...xCoords) : 0;
  const maxX = xCoords.length ? Math.max(...xCoords) : 20;
  const minZ = zCoords.length ? Math.min(...zCoords) : 0;
  const maxZ = zCoords.length ? Math.max(...zCoords) : 20;

  // X-axis lines (horizontal, run along X)
  if (xLines.length > 0) {
    for (const line of xLines) {
      const cx = parseFloat(line.coordinate);
      const z0 = minZ - 2, z1 = maxZ + 2;
      const pts = [new THREE.Vector3(minX - 2, 0, cx), new THREE.Vector3(maxX + 2, 0, cx)];
      const geo = new THREE.BufferGeometry().setFromPoints(pts);
      group.add(new THREE.Line(geo, lineMat));

      // Bubble at start (circle + label)
      addGridBubble(group, minX - 2, cx, line.label, 'start');
      // Bubble at end
      addGridBubble(group, maxX + 2, cx, line.label, 'end');
    }
  } else {
    // Auto-generate x lines from spacing
    const numX = Math.ceil((maxX - minX) / spacingX) + 1;
    for (let i = 0; i < numX; i++) {
      const cx = minX + i * spacingX;
      const label = String.fromCharCode(65 + i); // A, B, C...
      const pts = [new THREE.Vector3(minX - 2, 0, cx), new THREE.Vector3(maxX + 2, 0, cx)];
      const geo = new THREE.BufferGeometry().setFromPoints(pts);
      group.add(new THREE.Line(geo, lineMat));
      addGridBubble(group, minX - 2, cx, label, 'start');
      addGridBubble(group, maxX + 2, cx, label, 'end');
    }
  }

  // Z-axis lines (vertical, run along Z)
  if (zLines.length > 0) {
    for (const line of zLines) {
      const cx = parseFloat(line.coordinate);
      const x0 = minX - 2, x1 = maxX + 2;
      const pts = [new THREE.Vector3(cx, 0, minZ - 2), new THREE.Vector3(cx, 0, maxZ + 2)];
      const geo = new THREE.BufferGeometry().setFromPoints(pts);
      group.add(new THREE.Line(geo, lineMat));
      addGridBubble(group, cx, minZ - 2, line.label, 'start');
      addGridBubble(group, cx, maxZ + 2, line.label, 'end');
    }
  } else {
    const numZ = Math.ceil((maxZ - minZ) / spacingZ) + 1;
    for (let i = 0; i < numZ; i++) {
      const cx = minZ + i * spacingZ;
      const label = String(i + 1); // 1, 2, 3...
      const pts = [new THREE.Vector3(minX - 2, 0, cx), new THREE.Vector3(maxX + 2, 0, cx)];
      const geo = new THREE.BufferGeometry().setFromPoints(pts);
      group.add(new THREE.Line(geo, lineMat));
      addGridBubble(group, cx, minZ - 2, label, 'start');
      addGridBubble(group, cx, maxZ + 2, label, 'end');
    }
  }

  // Grid intersection dots (snap indicators)
  const dotGeo = new THREE.SphereGeometry(0.08, 6, 6);
  const dotMat = new THREE.MeshBasicMaterial({ color: 0xaaaacc });
  if (xLines.length > 0 && zLines.length > 0) {
    for (const xl of xLines) {
      for (const zl of zLines) {
        const dot = new THREE.Mesh(dotGeo, dotMat);
        dot.position.set(parseFloat(zl.coordinate), 0.01, parseFloat(xl.coordinate));
        group.add(dot);
      }
    }
  }

  group.userData = { id: grid.id, type: 'grid' };
  pickMap.set(group.uuid, { id: grid.id, type: 'grid' });
  return [group];
}

function addGridBubble(group, x, z, label, end) {
  // Bubble: small circle at line end
  const circleGeo = new THREE.CircleGeometry(0.12, 16);
  const circleMat = new THREE.MeshBasicMaterial({ color: 0x888899, side: THREE.DoubleSide });
  const circle = new THREE.Mesh(circleGeo, circleMat);
  circle.position.set(x, 0.02, z);
  group.add(circle);

  // Label sprite using CanvasTexture
  const labelSprite = makeTextSprite(label, {
    fontSize: 10, color: '#aaaacc', bgColor: null,
    width: 24, height: 16,
  });
  labelSprite.position.set(x, 0.05, z);
  group.add(labelSprite);
}

// ─── Phase 3.3: Room boundary rendering ──────────────────────────────────────
let roomBoundaryGroup = null;

function renderRoomBoundaries() {
  // Remove previous room boundary lines
  if (roomBoundaryGroup) {
    if (roomBoundaryGroup.parent) roomBoundaryGroup.parent.remove(roomBoundaryGroup);
    roomBoundaryGroup = null;
  }

  const group = new THREE.Group();
  group.name = 'room_boundaries';
  const lineMat = new THREE.LineBasicMaterial({ color: 0x34d399, transparent: true, opacity: 0.5 });

  for (const room of state.rooms) {
    if (!room.area_sqm) continue;
    // Compute boundary from walls on this room's level
    const levelId = room.level_id;
    const walls = state.elements.filter(e =>
      e.type === 'wall' && e.base_level_id === levelId
    );

    if (walls.length >= 3) {
      const points = getWallPolygon(walls);
      if (points.length >= 3) {
        const geo = new THREE.BufferGeometry().setFromPoints([...points, points[0]]);
        group.add(new THREE.Line(geo, lineMat));

        // Room area tag in plan
        const cx = points.reduce((s, p) => s + p.x, 0) / points.length;
        const cz = points.reduce((s, p) => s + p.z, 0) / points.length;
        const tag = makeRoomTagSprite(room.name || room.number || 'Room', room.area_sqm);
        tag.position.set(cx, 0.05, cz);
        group.add(tag);
      }
    }
  }

  scenePlan.add(group);
  roomBoundaryGroup = group;
}

function getWallPolygon(walls) {
  // Collect wall endpoints and compute convex hull
  const pts = [];
  for (const w of walls) {
    const params = typeof w.parameters === 'string' ? JSON.parse(w.parameters) : (w.parameters || {});
    const start = params.startCoord || {};
    const end = params.endCoord || {};
    if (start.x != null) pts.push({ x: start.x, z: start.y || 0 });
    if (end.x != null) pts.push({ x: end.x, z: end.y || 0 });
  }
  if (pts.length < 3) return pts;
  return convexHull(pts);
}

// Graham scan convex hull
function convexHull(points) {
  if (points.length < 3) return points;
  const sorted = [...points].sort((a, b) => a.x - b.x || a.y - b.y);
  const cross = (o, a, b) => (a.x - o.x) * (b.z - o.z) - (a.z - o.z) * (b.x - o.x);
  const lower = [];
  for (const p of sorted) {
    while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], p) <= 0) lower.pop();
    lower.push(p);
  }
  const upper = [];
  for (let i = sorted.length - 1; i >= 0; i--) {
    const p = sorted[i];
    while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], p) <= 0) upper.pop();
    upper.push(p);
  }
  lower.pop(); upper.pop();
  return [...lower, ...upper];
}

function makeRoomTagSprite(name, areaM2) {
  const canvas = document.createElement('canvas');
  canvas.width = 128; canvas.height = 48;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'rgba(52,211,153,0.85)';
  ctx.roundRect(0, 0, 128, 48, 6);
  ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 12px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(name || 'Room', 64, 18);
  ctx.font = '11px sans-serif';
  ctx.fillText(`${areaM2.toFixed(1)} m²`, 64, 38);
  const tex = new THREE.CanvasTexture(canvas);
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(2, 0.75, 1);
  return sprite;
}

// ─── 2D Stair Symbol (plan view) ─────────────────────────────────────────────

/**
 * Build a simplified 2D footprint symbol for a stair in the plan view.
 * Shows flight paths, landings, and up-arrow direction.
 */
function buildStairSymbol2D(stair) {
  const stairType   = stair.stair_type || 'straight';
  const width       = parseFloat(stair.width || 1.0);
  const risers      = parseInt(stair.number_of_risers, 10) || 16;
  const treads      = parseInt(stair.number_of_treads, 10) || (risers - 1);
  const treadDepth  = parseFloat(stair.tread_depth || 0.275);
  const posX        = parseFloat(stair.position_x || 0);
  const posY        = parseFloat(stair.position_y || 0);
  const rotation    = (parseFloat(stair.rotation_degrees) || 0) * Math.PI / 180;
  const totalLen    = treads * treadDepth;

  const group = new THREE.Group();
  group.position.set(posX, 0, posY);
  group.rotation.y = rotation;

  // Main footprint
  const fillColor = 0x555555;
  const lineColor = 0x888888;

  if (stairType === 'straight') {
    const geo = new THREE.PlaneGeometry(width, totalLen);
    const mat = new THREE.MeshBasicMaterial({ color: fillColor, transparent: true, opacity: 0.4, side: THREE.DoubleSide });
    const plane = new THREE.Mesh(geo, mat);
    plane.rotation.x = -Math.PI / 2;
    plane.position.set(width / 2, 0.01, totalLen / 2);
    group.add(plane);

    // Step lines
    for (let i = 0; i <= treads; i++) {
      const lineGeo = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(0, 0.01, i * treadDepth),
        new THREE.Vector3(width, 0.01, i * treadDepth),
      ]);
      group.add(new THREE.Line(lineGeo, new THREE.LineBasicMaterial({ color: lineColor })));
    }

    // Up arrow
    const arrowGeo = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(width / 2, 0.02, totalLen * 0.3),
      new THREE.Vector3(width / 2 - 0.15, 0.02, totalLen * 0.5),
      new THREE.Vector3(width / 2, 0.02, totalLen * 0.5),
      new THREE.Vector3(width / 2 + 0.15, 0.02, totalLen * 0.5),
      new THREE.Vector3(width / 2, 0.02, totalLen * 0.3),
    ]);
    group.add(new THREE.Line(arrowGeo, new THREE.LineBasicMaterial({ color: 0xffffff })));

  } else if (stairType === 'l_shaped') {
    const halfTreads = Math.floor(treads / 2);
    // First flight
    const f1Geo = new THREE.PlaneGeometry(width, halfTreads * treadDepth);
    const f1Mat = new THREE.MeshBasicMaterial({ color: fillColor, transparent: true, opacity: 0.4, side: THREE.DoubleSide });
    const f1 = new THREE.Mesh(f1Geo, f1Mat);
    f1.rotation.x = -Math.PI / 2;
    f1.position.set(width / 2, 0.01, halfTreads * treadDepth / 2);
    group.add(f1);
    // Landing
    const lGeo = new THREE.PlaneGeometry(width, 1.2);
    const lMat = new THREE.MeshBasicMaterial({ color: 0x666666, transparent: true, opacity: 0.5, side: THREE.DoubleSide });
    const landing = new THREE.Mesh(lGeo, lMat);
    landing.rotation.x = -Math.PI / 2;
    landing.position.set(width / 2, 0.01, halfTreads * treadDepth + 0.6);
    group.add(landing);
    // Second flight
    const f2Geo = new THREE.PlaneGeometry(totalLen - halfTreads * treadDepth - 1.2, width);
    const f2Mat = new THREE.MeshBasicMaterial({ color: fillColor, transparent: true, opacity: 0.4, side: THREE.DoubleSide });
    const f2 = new THREE.Mesh(f2Geo, f2Mat);
    f2.rotation.x = -Math.PI / 2;
    f2.rotation.z = Math.PI / 2;
    f2.position.set(halfTreads * treadDepth + 0.6 + (totalLen - halfTreads * treadDepth - 1.2) / 2, 0.01, width / 2);
    group.add(f2);
  }

  group.userData = { id: stair.id, type: 'stair' };
  pickMap.set(group.uuid, { id: stair.id, type: 'stair' });
  return [group];
}

/**
 * Build Three.js meshes for a roof element.
 * Handles flat (horizontal slab), gable, shed, hip, gambrel, and curtain styles.
 */
function buildRoofMesh(el, isSelected) {
  const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : (el.parameters || {});
  const computed = typeof el.computed === 'string' ? JSON.parse(el.computed) : (el.computed || {});
  const layers = el.layers || [];

  const roofStyle = params.roof_style || 'flat';
  const baseLevel = levelElevation(el.base_level_id);
  const height = parseFloat(computed.height || params.ridge_height || 0.3);
  const baseElev = baseLevel;

  const color = isSelected ? COLORS.selected : 0x6a3a1a; // warm dark brown
  const lineColor = isSelected ? 0x7aaff0 : 0x8a5a3a;
  const thickness = layers.length > 0
    ? parseFloat(layers.reduce((s, l) => s + parseFloat(l.thickness), 0))
    : parseFloat(params.thickness || 0.2);

  const group = new THREE.Group();

  if (roofStyle === 'flat') {
    // Flat roof: horizontal slab with slight taper or uniform thickness
    const footprint = params.footprint || [];
    if (footprint.length >= 3) {
      // Polygon footprint — use ExtrudeGeometry from center
      const cx = footprint.reduce((s, p) => s + parseFloat(p.x), 0) / footprint.length;
      const cy = footprint.reduce((s, p) => s + parseFloat(p.y), 0) / footprint.length;
      // Build shape from polygon points centered at origin
      const shape = new THREE.Shape();
      const pts = footprint.map(p => new THREE.Vector2(
        parseFloat(p.x) - cx, parseFloat(p.y) - cy
      ));
      shape.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i].x, pts[i].y);
      shape.closePath();
      const geo = new THREE.ExtrudeGeometry(shape, { depth: thickness, bevelEnabled: false });
      const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.rotation.x = -Math.PI / 2;
      mesh.position.set(cx, baseElev, cy);
      group.add(mesh);
    } else {
      // Default rectangular slab 10x8 m
      const w = parseFloat(params.width || 10);
      const d = parseFloat(params.depth || 8);
      const geo = new THREE.BoxGeometry(w, thickness, d);
      const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(w / 2, baseElev + thickness / 2, d / 2);
      group.add(mesh);
    }
  } else if (roofStyle === 'gable') {
    // Gable roof: two sloping triangular planes
    const pitch = parseFloat(params.pitch_ratio || '7:12');
    const [rise, run] = pitch.split(':').map(Number);
    const angle = Math.atan2(rise, run);
    const span = parseFloat(params.span || 10); // total width
    const halfSpan = span / 2;

    // Eave height = base, ridge at halfSpan * tan(angle) above
    const ridgeRise = halfSpan * Math.tan(angle);
    const eaveY = baseElev;
    const ridgeY = eaveY + ridgeRise;

    // Front face: left slope
    const frontLeft = buildGableSlope(span, ridgeRise, baseElev, eaveY, ridgeY, halfSpan, color, lineColor, isSelected, 'left');
    group.add(...frontLeft);
    // Back face: right slope
    const frontRight = buildGableSlope(span, ridgeRise, baseElev, eaveY, ridgeY, halfSpan, color, lineColor, isSelected, 'right');
    group.add(...frontRight);

    // Ridge line
    const ridgeGeo = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(0, ridgeY, -halfSpan),
      new THREE.Vector3(0, ridgeY, halfSpan),
    ]);
    const ridgeMat = new THREE.LineBasicMaterial({ color: lineColor });
    group.add(new THREE.Line(ridgeGeo, ridgeMat));

    // Gable ends (triangular walls)
    const frontGeo = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(0, eaveY, halfSpan),
      new THREE.Vector3(0, ridgeY, 0),
      new THREE.Vector3(0, eaveY, -halfSpan),
    ]);
    const endMat = new THREE.MeshBasicMaterial({ color: 0x5a3a2a, side: THREE.DoubleSide, transparent: true, opacity: 0.6 });
    const frontTri = new THREE.Mesh(frontGeo, endMat);
    group.add(frontTri);

  } else if (roofStyle === 'shed') {
    // Shed: single sloping plane
    const pitch = parseFloat(params.pitch_ratio || '4:12');
    const [rise, run] = pitch.split(':').map(Number);
    const angle = Math.atan2(rise, run);
    const span = parseFloat(params.span || 8);
    const rise_amt = span * Math.tan(angle);
    const eaveY = baseElev;
    const ridgeY = eaveY + rise_amt;

    const w = parseFloat(params.width || 10);
    const geo = new THREE.BoxGeometry(w, thickness, span);
    const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
    const mesh = new THREE.Mesh(geo, mat);
    const midZ = 0; // centered on Z
    const midY = (eaveY + ridgeY) / 2;
    mesh.position.set(w / 2, midY, midZ);
    mesh.rotation.x = angle;
    group.add(mesh);

  } else if (roofStyle === 'hip') {
    // Hip roof: 4 planes sloping to a ridge center
    const span = parseFloat(params.span || 10);
    const halfSpan = span / 2;
    const pitch = parseFloat(params.pitch_ratio || '7:12');
    const [rise, run] = [7, 12]; // default 30°
    const rise_amt = halfSpan * (rise / run);
    const eaveY = baseElev;
    const ridgeY = eaveY + rise_amt;

    const w = parseFloat(params.width || 8);
    const halfW = w / 2;
    // 4 triangular/quad planes
    const planes = [
      { pts: [[0, halfW, halfSpan], [halfW, 0, halfSpan], [halfW, 0, -halfSpan], [0, halfW, -halfSpan]], top: ridgeY, eave: eaveY },
      { pts: [[halfW, halfW, halfSpan], [0, halfW, halfSpan], [0, halfW, -halfSpan], [halfW, halfW, -halfSpan]], top: ridgeY, eave: eaveY },
    ];
    // Simple approximation: pyramid shape
    const apexGeo = new THREE.ConeGeometry(Math.max(halfSpan, halfW) * 1.2, rise_amt, 4);
    const apexMat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.75 });
    const apex = new THREE.Mesh(apexGeo, apexMat);
    apex.position.set(halfW / 2, eaveY + rise_amt / 2, 0);
    apex.rotation.y = Math.PI / 4;
    group.add(apex);

    // Floor base slab
    const baseGeo = new THREE.BoxGeometry(w, thickness, span);
    const baseMat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.7 });
    const base = new THREE.Mesh(baseGeo, baseMat);
    base.position.set(w / 2, eaveY + thickness / 2, 0);
    group.add(base);

  } else if (roofStyle === 'curtain') {
    // Curtain wall: grid of mullions + glass panels
    const gridU = parseInt(params.grid_u_count || 4, 10);
    const gridV = parseInt(params.grid_v_count || 3, 10);
    const w = parseFloat(params.width || 12);
    const h = parseFloat(params.height || 4);
    const span = parseFloat(params.span || 8);
    const cellW = w / gridU;
    const cellH = h / gridV;
    const mullW = 0.04;
    const mullColor = isSelected ? COLORS.selected : 0x888888;
    const glassColor = isSelected ? COLORS.selected : 0x4a7a8a;

    // Horizontal mullions (runners)
    for (let i = 0; i <= gridV; i++) {
      const geo = new THREE.BoxGeometry(w, mullW, mullW);
      const mat = new THREE.MeshLambertMaterial({ color: mullColor });
      const m = new THREE.Mesh(geo, mat);
      m.position.set(w / 2, baseElev + i * cellH, span / 2);
      group.add(m);
    }
    // Vertical mullions (stiles)
    for (let j = 0; j <= gridU; j++) {
      const geo = new THREE.BoxGeometry(mullW, h, mullW);
      const mat = new THREE.MeshLambertMaterial({ color: mullColor });
      const m = new THREE.Mesh(geo, mat);
      m.position.set(j * cellW, baseElev + h / 2, span / 2);
      group.add(m);
    }
    // Glass panels
    for (let i = 0; i < gridV; i++) {
      for (let j = 0; j < gridU; j++) {
        const geo = new THREE.PlaneGeometry(cellW - mullW * 2, cellH - mullW * 2);
        const mat = new THREE.MeshLambertMaterial({ color: glassColor, transparent: true, opacity: 0.45, side: THREE.DoubleSide });
        const panel = new THREE.Mesh(geo, mat);
        panel.position.set(j * cellW + cellW / 2, baseElev + i * cellH + cellH / 2, span / 2);
        group.add(panel);
      }
    }
  }

  // Edges overlay for selected state
  if (isSelected) {
    group.traverse(obj => {
      if (obj.isMesh && obj.geometry) {
        const edges = new THREE.EdgesGeometry(obj.geometry);
        obj.add(new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: lineColor })));
      }
    });
  }

  group.userData = { id: el.id, type: 'element' };
  pickMap.set(group.uuid, { id: el.id, type: 'element' });
  return [group];
}

/**
 * Build one slope of a gable roof as a plane mesh.
 */
function buildGableSlope(span, rise, baseElev, eaveY, ridgeY, halfSpan, color, lineColor, isSelected, side) {
  const meshes = [];
  const w = parseFloat(state.elements.find(e => e.id === state.selectedId)?.parameters?.width || 8);
  const midX = w / 2;

  // Slope plane: angled box
  const slopeAngle = Math.atan2(rise, halfSpan);
  const slopeLen = Math.sqrt(rise * rise + halfSpan * halfSpan);
  const geo = new THREE.BoxGeometry(midX * 2, 0.05, slopeLen);
  const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: isSelected ? 0.85 : 0.72 });
  const mesh = new THREE.Mesh(geo, mat);

  // Position: bottom edge at eave height, ridge at top
  const centerY = eaveY + rise / 2;
  mesh.position.set(midX, centerY, side === 'left' ? 0 : 0);
  mesh.rotation.x = -slopeAngle;

  // Tilt perpendicular to span direction (Z)
  mesh.rotation.z = side === 'left' ? 0 : 0;

  const edges = new THREE.EdgesGeometry(geo);
  mesh.add(new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: lineColor })));

  mesh.userData = { id: state.elements.find(e => e.type === 'roof')?.id || '', type: 'element' };
  pickMap.set(mesh.uuid, { id: state.elements.find(e => e.type === 'roof')?.id || '', type: 'element' });
  meshes.push(mesh);
  return meshes;
}

// ─── Family Mesh Builders (Doors + Windows) ────────────────────────────────

/**
 * Compute the world-space position and rotation of a family instance
 * hosted on a wall element.
 */
function getFamilyWorldTransform(fam) {
  const wallEl = state.elements.find(e => e.id === fam.host_wall_id);
  if (!wallEl) return null;

  const wParams = typeof wallEl.parameters === 'string' ? JSON.parse(wallEl.parameters) : (wallEl.parameters || {});
  const wComputed = typeof wallEl.computed === 'string' ? JSON.parse(wallEl.computed) : (wallEl.computed || {});

  const sx = parseFloat(wParams.startCoord?.x || 0);
  const sy = parseFloat(wParams.startCoord?.y || 0);
  const ex = parseFloat(wParams.endCoord?.x || sx + 5);
  const ey = parseFloat(wParams.endCoord?.y || sy);
  const wallLength = Math.sqrt((ex - sx) ** 2 + (ey - sy) ** 2) || 1;
  const wallHeight = parseFloat(wComputed.height || 3);
  const wallThick = parseFloat(wComputed.thickness || wParams.thickness || 0.2);
  const baseElev = levelElevation(wallEl.base_level_id);
  const wallAngle = Math.atan2(ey - sy, ex - sx);

  const u = parseFloat(fam.host_face_u || 0.5);
  const localX = u * wallLength;
  const wallCx = (sx + ex) / 2;
  const wallCy = (sy + ey) / 2;

  const worldX = wallCx + localX * Math.cos(-wallAngle);
  const worldZ = wallCy + localX * Math.sin(-wallAngle);

  return {
    position: { x: worldX, y: baseElev, z: worldZ },
    wallAngle,
    wallLength, wallHeight, wallThick,
    baseElev,
    localX,
  };
}

function buildDoorMesh(fam, isSelected) {
  const params = typeof fam.parameters === 'string' ? JSON.parse(fam.parameters) : (fam.parameters || {});
  const transform = getFamilyWorldTransform(fam);
  if (!transform) return [];

  const { position, wallAngle, baseElev, localX, wallLength, wallHeight, wallThick } = transform;
  const doorW = parseFloat(params.width || 0.914);
  const doorH = parseFloat(params.height || 2.032);
  const hand = params.hand || 'left';
  const baseY = baseElev; // door sits at base of wall (bottom)

  const group = new THREE.Group();
  group.position.set(position.x, baseY, position.z);
  group.rotation.y = -wallAngle;

  // Door panel (vertical plane in wall local space)
  const panelGeo = new THREE.PlaneGeometry(doorW, doorH);
  const panelColor = isSelected ? COLORS.selected : 0x6b4c3d;
  const panelMat = new THREE.MeshLambertMaterial({ color: panelColor, side: THREE.DoubleSide, transparent: true, opacity: 0.85 });
  const panel = new THREE.Mesh(panelGeo, panelMat);
  // Place panel at wall front face (Z offset = thick/2 + tiny)
  panel.position.set(localX, doorH / 2, wallThick / 2 + 0.001);
  group.add(panel);

  // Door frame lines
  const frameMat = new THREE.LineBasicMaterial({ color: isSelected ? 0x7aaff0 : 0x4a3a2a, linewidth: 1 });
  const framePoints = [
    new THREE.Vector3(localX - doorW / 2, 0, wallThick / 2),
    new THREE.Vector3(localX - doorW / 2, doorH, wallThick / 2),
    new THREE.Vector3(localX + doorW / 2, doorH, wallThick / 2),
    new THREE.Vector3(localX + doorW / 2, 0, wallThick / 2),
    new THREE.Vector3(localX - doorW / 2, 0, wallThick / 2),
  ];
  const frameGeo = new THREE.BufferGeometry().setFromPoints(framePoints);
  group.add(new THREE.Line(frameGeo, frameMat));

  // Door swing arc (90° arc showing swing path)
  // Hinge at bottom-left of door (localX - doorW/2, 0) — opening direction
  const hingeX = localX - doorW / 2;
  const swingRadius = doorW;
  const arcPoints = [];
  const steps = 12;
  for (let i = 0; i <= steps; i++) {
    const t = (i / steps) * Math.PI / 2; // 0 to 90°
    const ax = hingeX + swingRadius * Math.cos(t);
    const ay = doorH * Math.sin(t);
    arcPoints.push(new THREE.Vector3(ax, ay, wallThick / 2 + 0.005));
  }
  if (arcPoints.length >= 2) {
    const arcGeo = new THREE.BufferGeometry().setFromPoints(arcPoints);
    const arcMat = new THREE.LineBasicMaterial({ color: isSelected ? 0x7aaff0 : 0x8a6a5a, transparent: true, opacity: 0.5 });
    group.add(new THREE.Line(arcGeo, arcMat));
  }

  // Hinge dot
  const hingeGeo = new THREE.SphereGeometry(0.03, 8, 8);
  const hingeMat = new THREE.MeshBasicMaterial({ color: isSelected ? COLORS.selected : 0xaaa });
  const hinge = new THREE.Mesh(hingeGeo, hingeMat);
  hinge.position.set(hingeX, 0.03, wallThick / 2);
  group.add(hinge);

  group.userData = { id: fam.id, type: 'family', familyType: 'door' };
  pickMap.set(group.uuid, { id: fam.id, type: 'family' });

  return [group];
}

function buildWindowMesh(fam, isSelected) {
  const params = typeof fam.parameters === 'string' ? JSON.parse(fam.parameters) : (fam.parameters || {});
  const transform = getFamilyWorldTransform(fam);
  if (!transform) return [];

  const { position, wallAngle, baseElev, localX, wallLength, wallHeight, wallThick } = transform;
  const winW = parseFloat(params.width || 1.219);
  const winH = parseFloat(params.height || 1.219);
  const sillH = parseFloat(params.sillHeight || 0.9);

  const group = new THREE.Group();
  group.position.set(position.x, baseElev, position.z);
  group.rotation.y = -wallAngle;

  // Window glass (transparent rectangle at wall front)
  const glassGeo = new THREE.PlaneGeometry(winW, winH);
  const glassColor = isSelected ? COLORS.selected : 0x4a7a8a;
  const glassMat = new THREE.MeshLambertMaterial({ color: glassColor, transparent: true, opacity: 0.55, side: THREE.DoubleSide });
  const glass = new THREE.Mesh(glassGeo, glassMat);
  glass.position.set(localX, sillH + winH / 2, wallThick / 2 + 0.001);
  group.add(glass);

  // Window frame (outline in wall front face)
  const frameMat = new THREE.LineBasicMaterial({ color: isSelected ? 0x7aaff0 : 0x5a7a8a });
  const framePoints = [
    new THREE.Vector3(localX - winW / 2, sillH, wallThick / 2),
    new THREE.Vector3(localX - winW / 2, sillH + winH, wallThick / 2),
    new THREE.Vector3(localX + winW / 2, sillH + winH, wallThick / 2),
    new THREE.Vector3(localX + winW / 2, sillH, wallThick / 2),
    new THREE.Vector3(localX - winW / 2, sillH, wallThick / 2),
  ];
  const frameGeo = new THREE.BufferGeometry().setFromPoints(framePoints);
  group.add(new THREE.Line(frameGeo, frameMat));

  // Muntins (cross dividers for sash look)
  const muntinMat = new THREE.LineBasicMaterial({ color: isSelected ? 0x7aaff0 : 0x5a7a8a });
  const centerX = localX;
  const centerY = sillH + winH / 2;
  const muntinH = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(localX - winW / 2, centerY, wallThick / 2 + 0.005),
    new THREE.Vector3(localX + winW / 2, centerY, wallThick / 2 + 0.005),
  ]);
  const muntinV = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(centerX, sillH, wallThick / 2 + 0.005),
    new THREE.Vector3(centerX, sillH + winH, wallThick / 2 + 0.005),
  ]);
  group.add(new THREE.Line(muntinH, muntinMat));
  group.add(new THREE.Line(muntinV, muntinMat));

  group.userData = { id: fam.id, type: 'family', familyType: 'window' };
  pickMap.set(group.uuid, { id: fam.id, type: 'family' });

  return [group];
}

function buildLevelPlane(level) {
  const elevation = parseFloat(level.elevation);
  const geo = new THREE.PlaneGeometry(30, 30);
  const mat = new THREE.MeshBasicMaterial({ color: 0x2a2a40, transparent: true, opacity: 0.25, side: THREE.DoubleSide });
  const plane = new THREE.Mesh(geo, mat);
  plane.rotation.x = -Math.PI / 2;
  plane.position.set(5, elevation, 5);

  // Level label sprite-like using a line ring
  const ringGeo = new THREE.RingGeometry(0.3, 0.35, 16);
  const ringMat = new THREE.MeshBasicMaterial({ color: 0x5b9bd5, side: THREE.DoubleSide });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.rotation.x = -Math.PI / 2;
  ring.position.set(-5, elevation + 0.01, -5);
  plane.add(ring);

  return [plane];
}

// ─── MEP Element Mesh Builders (Phase 6) ─────────────────────────────────────

const MEP_COLORS = {
  duct: { supply: 0xc0392b, return: 0x2980b9, exhaust: 0x27ae60 },
  pipe: { domestic_water: 0x1a6fc4, c_waste: 0x7d6608, vent: 0x1e8449, fire_protection: 0xe74c3c },
  cable_tray: { ladder: 0x8e44ad, trough: 0x6c3483, solid: 0x9b59b6, conduit: 0x7d3c98 },
};

function buildMEPMesh(el, isSelected) {
  const { type, subtype, start_x: sx, start_y: sy, end_x: ex, end_y: ey, elevation: el_elev = 2.4 } = el;
  const dx = ex - sx, dy = ey - sy;
  const length = Math.sqrt(dx * dx + dy * dy) || 0.001;
  const midX = (sx + ex) / 2, midY = (sy + ey) / 2;
  const angle = Math.atan2(dy, dx);

  const color = isSelected ? COLORS.selected : (MEP_COLORS[type]?.[subtype] || 0xaaaaaa);
  const group = new THREE.Group();
  group.userData = { id: el.id, type: 'mep', mepType: type, mepSubtype: subtype, systemType: el.system_type };

  if (type === 'duct') {
    const width = parseFloat(el.width) || 0.3;
    const height = parseFloat(el.height) || 0.2;
    const diam = parseFloat(el.diameter) || 0;
    let geo, mat;
    if (diam > 0) {
      geo = new THREE.CylinderGeometry(diam / 2, diam / 2, length, 12);
      mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: 0.8 });
    } else {
      geo = new THREE.BoxGeometry(length, height, width);
      mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: 0.8 });
    }
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(midX, el_elev, midY);
    mesh.rotation.y = -angle;
    mesh.rotation.x = Math.PI / 2;
    group.add(mesh);
    if (isSelected) {
      const edges = new THREE.EdgesGeometry(geo);
      group.add(new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: 0x7aaff0 })));
    }
  } else if (type === 'pipe') {
    const diam = parseFloat(el.diameter) || 0.025;
    const geo = new THREE.CylinderGeometry(diam / 2, diam / 2, length, 8);
    const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: 0.85 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(midX, el_elev, midY);
    mesh.rotation.y = -angle;
    mesh.rotation.x = Math.PI / 2;
    group.add(mesh);
    if (isSelected) {
      const edges = new THREE.EdgesGeometry(geo);
      group.add(new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: 0x7aaff0 })));
    }
  } else if (type === 'cable_tray') {
    const w = parseFloat(el.width) || 0.15;
    const h = parseFloat(el.height) || 0.05;
    const geo = new THREE.BoxGeometry(length, h, w);
    const mat = new THREE.MeshLambertMaterial({ color, transparent: true, opacity: 0.75 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(midX, el_elev, midY);
    mesh.rotation.y = -angle;
    mesh.rotation.x = Math.PI / 2;
    group.add(mesh);
    // Ladder rungs
    if (subtype === 'ladder') {
      const rungCount = Math.max(1, Math.floor(length / 0.3));
      for (let i = 0; i <= rungCount; i++) {
        const t = i / rungCount;
        const rx = sx + dx * t, ry = sy + dy * t;
        const rungGeo = new THREE.CylinderGeometry(0.005, 0.005, w, 6);
        const rungMat = new THREE.MeshLambertMaterial({ color: 0x666666 });
        const rung = new THREE.Mesh(rungGeo, rungMat);
        rung.position.set(rx, el_elev, ry);
        rung.rotation.z = Math.PI / 2;
        group.add(rung);
      }
    }
  }

  // Fittings (elbow dots at endpoints)
  const fitColor = isSelected ? COLORS.selected : 0x888888;
  for (const [px, py] of [[sx, sy], [ex, ey]]) {
    const dotGeo = new THREE.SphereGeometry(0.04, 8, 8);
    const dotMat = new THREE.MeshBasicMaterial({ color: fitColor });
    const dot = new THREE.Mesh(dotGeo, dotMat);
    dot.position.set(px, el_elev, py);
    group.add(dot);
  }

  // Hangers — vertical drops
  try {
    const hangers = typeof el.hangers === 'string' ? JSON.parse(el.hangers) : (el.hangers || []);
    for (const h of hangers) {
      const hx = h.x ?? hx, hy = h.y ?? hy;
      const hangerGeo = new THREE.CylinderGeometry(0.005, 0.005, el_elev, 4);
      const hangerMat = new THREE.MeshLambertMaterial({ color: 0x555555, transparent: true, opacity: 0.6 });
      const hangerMesh = new THREE.Mesh(hangerGeo, hangerMat);
      hangerMesh.position.set(h.x, el_elev / 2, h.y);
      group.add(hangerMesh);
    }
  } catch (_) {}

  pickMap.set(group.uuid, { id: el.id, type: 'mep' });
  return [group];
}

// ── Phase 4.2: Render annotation overlays from state.annotations ─────────────
// currentView: the active Three.js scene ('3d'|'plan'|'section'|null).
// Driven by viewport-manager when user switches views; defaults to '3d'.
let currentView = '3d';
function renderAnnotations() {
  if (!state.annotations || !Array.isArray(state.annotations)) return;
  if (!currentView) return;
  try {
    syncAnnotationOverlays(state.annotations, scene3d, scenePlan, sceneSection, currentView);
  } catch (e) {
    console.warn('[rebuildScene] renderAnnotations sync failed:', e.message);
  }
}

function rebuildScene() {
  const t0 = performance.now();
  // Guard: skip if a rebuild is already in progress — prevents double-fire from
  // rapid state changes and cascading recursive calls.
  if (rebuildScene._busy) return;
  rebuildScene._busy = true;
  // Outer try-catch ensures a single bad subsystem (bad geometry, bad parameters,
  // bad build function) never leaves the scene blank — the previous render
  // persists until a clean rebuild completes.
  try {
    clearMeshes();
    // Per-subsystem perf markers — log subsystems taking >16ms (one frame at 60fps)
    let _t = performance.now();
    const _note = (name) => {
      const d = performance.now() - _t;
      if (d > 16) console.debug(`[rebuild:perf] ${name}: ${d.toFixed(1)}ms (target <16ms)`);
      _t = performance.now();
    };

  // Build element meshes (3d scene + plan scene copy)
  for (const el of state.elements) {
    const isSelected = el.id === state.selectedId || state.multiSelection.some(s => s.id === el.id);
    let objs = [];
    if (el.type === 'wall') {
      const wallFamilies = state.familyInstances.filter(f => f.host_wall_id === el.id);
      objs = buildWallMesh(el, isSelected, wallFamilies);
    } else if (el.type === 'column') {
      objs = buildColumnMesh(el, isSelected);
    } else if (el.type === 'roof') {
      objs = buildRoofMesh(el, isSelected);
    }

    for (const obj of objs) {
      scene3d.add(obj);
      const clonePlan = obj.clone();
      clonePlan.userData = obj.userData;
      if (clonePlan.uuid !== obj.uuid) pickMap.set(clonePlan.uuid, { id: el.id, type: 'element' });
      scenePlan.add(clonePlan);
      const cloneSection = obj.clone();
      sceneSection.add(cloneSection);
    }
    objectMap.set(el.id, objs);
  }
  _note('elements');

  // Build family instance meshes (doors + windows)
  for (const fam of state.familyInstances) {
    const isSelected = fam.id === state.selectedId;
    let objs = [];
    if (fam.family_type === 'door') objs = buildDoorMesh(fam, isSelected);
    else if (fam.family_type === 'window') objs = buildWindowMesh(fam, isSelected);

    for (const obj of objs) {
      scene3d.add(obj);
      const clonePlan = obj.clone();
      scenePlan.add(clonePlan);
      const cloneSection = obj.clone();
      sceneSection.add(cloneSection);
    }
    objectMap.set(fam.id, objs);
  }
  _note('families');

  // Level planes (3d view only)
  for (const level of state.levels) {
    const isSelected = level.id === state.selectedId;
    const objs = buildLevelPlane(level);
    for (const obj of objs) {
      scene3d.add(obj);
      if (isSelected) {
        obj.material = new THREE.MeshBasicMaterial({ color: 0x4a7dbd, transparent: true, opacity: 0.35, side: THREE.DoubleSide });
      }
      obj.userData = { id: level.id, type: 'level' };
      pickMap.set(obj.uuid, { id: level.id, type: 'level' });
    }
    objectMap.set(level.id, objs);
  }
  _note('levels');

  // MEP elements — wrapped so a broken duct/pipe/cable tray never kills the viewport
  try {
    if (state.mepLayerVisible) {
      for (const mepEl of state.mepElements) {
        const isSelected = mepEl.id === state.selectedId;
        const objs = buildMEPMesh(mepEl, isSelected);
        for (const obj of objs) {
          scene3d.add(obj);
          const clonePlan = obj.clone();
          scenePlan.add(clonePlan);
        }
        objectMap.set(mepEl.id, objs);
      }
    }
  } catch (e) {
    console.warn(`[rebuildScene] MEP elements failed: ${e.message}`);
  }
  _note('mep');

  // ── Phase 3.4: Stairs + Railings ──────────────────────────────────────────
  try {
    for (const stair of state.stairs) {
      const isSelected = stair.id === state.selectedId;
      const objs = buildStairMesh(stair, isSelected);
      for (const obj of objs) {
        scene3d.add(obj);
        const planObjs = buildStairSymbol2D(stair);
        for (const p of planObjs) {
          scenePlan.add(p);
          sceneSection.add(p.clone());
        }
      }
      objectMap.set(stair.id, objs);
    }
    for (const railing of state.railings) {
      const isSelected = railing.id === state.selectedId;
      const objs = buildRailingMesh(railing, isSelected);
      for (const obj of objs) {
        scene3d.add(obj);
        scenePlan.add(obj.clone());
      }
      objectMap.set(railing.id, objs);
    }
  } catch (e) {
    console.warn(`[rebuildScene] stairs/railings failed: ${e.message}`);
  }
  _note('stairs/railings');

  // ── Phase 3.3: Structural Grids ─────────────────────────────────────────────
  try {
    for (const grid of state.grids) {
      const objs = buildGridMesh(grid);
      for (const obj of objs) {
        scene3d.add(obj);
        scenePlan.add(obj.clone());
      }
    }
  } catch (e) {
    console.warn(`[rebuildScene] grids failed: ${e.message}`);
  }
  _note('grids');

  // ── Phase 33: Structural Members ────────────────────────────────────────────
  try {
    for (const member of (Array.isArray(state.structuralMembers) ? state.structuralMembers : [])) {
      const isSelected = member.id === state.selectedId || state.multiSelection.some(s => s.id === member.id);
      let objs = [];
      try { objs = buildStructuralMemberMesh(member, isSelected); }
      catch (e) { console.warn(`[rebuildScene] buildStructuralMemberMesh(${member.id}) failed: ${e.message}`); continue; }
      for (const obj of objs) {
        scene3d.add(obj);
        scenePlan.add(obj.clone());
      }
      objectMap.set(member.id, objs);
    }
  } catch (e) {
    console.warn(`[rebuildScene] structural members failed: ${e.message}`);
  }
  _note('structural');

  // ── Phase 3.3: Rooms (2D boundary lines in plan view) ──────────────────────
  try { renderRoomBoundaries(); } catch (e) { console.warn(`[rebuildScene] renderRoomBoundaries failed: ${e.message}`); }
  _note('rooms');

  // ── Phase 3.2: Floors ───────────────────────────────────────────────────────
  try {
    for (const floor of state.floors) {
      const isSelected = floor.id === state.selectedId;
      const objs = buildFloorMesh(floor, isSelected);
      for (const obj of objs) {
        scene3d.add(obj);
        const planObjs = buildFloorPlan2D(floor);
        for (const p of planObjs) {
          scenePlan.add(p);
          sceneSection.add(p.clone());
        }
      }
      objectMap.set(floor.id, objs);
    }
  } catch (e) {
    console.warn(`[rebuildScene] floors failed: ${e.message}`);
  }
  _note('floors');

  // ── Phase 3.2: Ceilings ─────────────────────────────────────────────────────
  try {
    for (const ceiling of state.ceilings) {
      const isSelected = ceiling.id === state.selectedId;
      const objs = buildCeilingMesh(ceiling, isSelected);
      for (const obj of objs) {
        scene3d.add(obj);
        scenePlan.add(obj.clone());
        sceneSection.add(obj.clone());
      }
      objectMap.set(ceiling.id, objs);
    }
  } catch (e) {
    console.warn(`[rebuildScene] ceilings failed: ${e.message}`);
  }
  _note('ceilings');

  // ── Phase 22: Curved Surfaces ──────────────────────────────────────────────
  try {
    for (const surface of state.curvedSurfaces) {
      const isSelected = surface.id === state.selectedId;
      const objs = buildCurvedSurfaceMesh(surface, isSelected);
      for (const obj of objs) {
        scene3d.add(obj);
        const plan2D = buildCurvedSurface2DLine(surface);
        scenePlan.add(plan2D.clone());
        sceneSection.add(plan2D.clone());
      }
      objectMap.set(surface.id, objs);
    }
  } catch (e) {
    console.warn(`[rebuildScene] curved surfaces failed: ${e.message}`);
  }
  _note('curved');

  // ── Phase 4.2: Annotations overlay ─────────────────────────────────────────
  try { renderAnnotations(); } catch (e) { console.warn(`[rebuildScene] renderAnnotations failed: ${e.message}`); }
  _note('annotations');

  // IM-D: render gold highlight outline on IM-selected element
  try { renderIMHighlight(); } catch (e) { console.warn(`[rebuildScene] renderIMHighlight failed: ${e.message}`); }

  renderAllViews();

  const ms = performance.now() - t0;
  if (ms > 20) console.debug(`[rebuildScene] ${ms.toFixed(1)}ms — slow (>20ms, monitor for optimization targets)`);

  } catch (e) {
    console.warn(`[rebuildScene] scene build failed: ${e.message}`);
  } finally {
    rebuildScene._busy = false;
  }
}

// ─── IM-D: Gold outline highlight for IM-selected element ───────────────────
function renderIMHighlight() {
  // Clear previous IM highlight
  while (imHighlightGroup.children.length) imHighlightGroup.remove(imHighlightGroup.children[0]);

  const targetId = _imCurrentElementId;
  if (!targetId) return;

  // Find all meshes belonging to this element
  const objs = objectMap.get(targetId) || [];
  if (!objs.length) return;

  for (const obj of objs) {
    // Compute bounding box for this mesh + descendants
    const box = new THREE.Box3().setFromObject(obj);
    if (box.isEmpty()) continue;
    const size = new THREE.Vector3();
    box.getSize(size);
    const center = new THREE.Vector3();
    box.getCenter(center);

    // Wireframe box around the element
    const edges = new THREE.EdgesGeometry(new THREE.BoxGeometry(size.x + 0.02, size.y + 0.02, size.z + 0.02));
    const line = new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: COLORS.im_selected, linewidth: 2 }));
    line.position.copy(center);
    imHighlightGroup.add(line);
  }

  // Dim other elements slightly
  scene3d.traverse(child => {
    if (child.isMesh && child !== imHighlightGroup) {
      const ud = child.userData;
      if (ud && ud.id !== targetId && !child._originalOpacity) {
        child._originalOpacity = child.material?.opacity ?? 1;
        if (child.material) {
          child.material = child.material.clone();
          child.material.opacity = Math.max(0.3, (child._originalOpacity - 0.25));
        }
      }
    }
  });
}

// ─── Render loop ──────────────────────────────────────────────────────────────
function renderAllViews() {
  syncRendererSizes();
  // After watchForVPReady fires, use the VP renderers (bound to actual visible canvases).
  // Before VP is ready, _vpRenderer3d is null and the dummy/bootstrap renderers are used.
  (_vpRenderer3d   || renderer3d).render(scene3d,    cam3d);
  (_vpRendererPlan || rendererPlan).render(scenePlan, camPlan);
  (_vpRendererSect || rendererSection).render(sceneSection, camSection);
}

function syncRendererSizes() {
  function resize(renderer, camera) {
    if (!renderer || !renderer.domElement) return;
    const canvas = renderer.domElement;
    // clientWidth is 0 when the canvas is in a hidden/collapsed pane — use a
    // minimum of 1 so the renderer doesn't initialize at 0×0 and stay blank
    // when the pane becomes visible. The actual resize happens again on the next
    // frame once clientWidth reports the real dimension.
    const w = Math.max(canvas.clientWidth,  1);
    const h = Math.max(canvas.clientHeight, 1);
    const pw = Math.round(w * window.devicePixelRatio);
    const ph = Math.round(h * window.devicePixelRatio);
    if (renderer.domElement.width !== pw || renderer.domElement.height !== ph) {
      renderer.setSize(w, h, false);
      if (camera.isPerspectiveCamera) {
        camera.aspect = w / h;
        camera.updateProjectionMatrix();
      } else {
        const aspect = w / h;
        const frust = 15;
        camera.left = -frust * aspect; camera.right = frust * aspect;
        camera.top = frust; camera.bottom = -frust;
        camera.updateProjectionMatrix();
      }
    }
  }
  resize(_vpRenderer3d   || renderer3d,    cam3d);
  resize(_vpRendererPlan || rendererPlan,   camPlan);
  resize(_vpRendererSect || rendererSection, camSection);
  // Debounced RCP redraw — avoids layout thrashing from rapid resize events.
  // RAF loop sets this flag; setTimeout fires once after the batch settles.
  if (typeof drawRCPCanvas === 'function' && state.rcpVisible) {
    if (syncRendererSizes._rcpTimer) clearTimeout(syncRendererSizes._rcpTimer);
    syncRendererSizes._rcpTimer = setTimeout(drawRCPCanvas, 150);
  }
}

// ─── Viewport grid layout ─────────────────────────────────────────────────────
// Supports 2x2 grid, 2-col, 2-row, and single-pane layouts.
// Grid state persisted in localStorage. Long-press (400ms) enters edit mode.

// BUG-UI-6: applyViewportGrid() is a legacy stub. viewport-manager.js owns all layout logic.
// Kept as a no-op so any stale call sites don’t throw. resetLayout() is the real function.
let vpLayout = '2x2'; // read-only legacy shim; viewport-manager reads its own localStorage key

function applyViewportGrid() {
  // No-op: viewport-manager.js builds and owns all viewport DOM + dividers.
  // Call resetLayout() from viewport-manager if you need to reset the grid.
  return;
} /* applyViewportGrid stub end */
