// ── Viewport layout menu toggle
document.getElementById('btn-vp-layout')?.addEventListener('click', (e) => {
  e.stopPropagation();
  const menu = document.getElementById('vp-layout-menu');
  const wasOpen = menu?.classList.contains('open');
  document.querySelectorAll('#vp-layout-menu').forEach(m => m.classList.remove('open'));
  if (!wasOpen) menu?.classList.add('open');
});

document.addEventListener('click', (e) => {
  if (!e.target.closest('#vp-layout-controls')) {
    document.querySelectorAll('#vp-layout-menu').forEach(m => m.classList.remove('open'));
  }
});

// BUG-UI-6 fix: layout buttons delegate to viewport-manager resetLayout().
// applyViewportGrid() is a no-op stub kept only for call-site safety.
document.querySelectorAll('.vp-layout-opt').forEach(btn => {
  btn?.addEventListener('click', () => {
    resetLayout(); // viewport-manager owns layout state
    document.querySelectorAll('#vp-layout-menu').forEach(m => m.classList.remove('open'));
  });
});

document.getElementById('vp-reset-layout')?.addEventListener('click', () => {
  resetLayout();
  document.querySelectorAll('#vp-layout-menu').forEach(m => m.classList.remove('open'));
});

// viewport-manager initialises its own grid DOM — do not call applyViewportGrid() here.

// ── Draggable divider bars (for 2x2 grid resize)
function setupDividers() {
  const area = document.getElementById('viewport-area');
  if (!area) return;

  // Remove existing dividers
  area.querySelectorAll('.vp-grid-divider').forEach(d => d.remove());

  const layout = vpLayout;
  if (layout !== '2x2') return;

  // Vertical divider between col 1 and 2
  const vDivider = document.createElement('div');
  vDivider.className = 'vp-grid-divider vp-divider-col';
  vDivider.style.cssText = `
    position: absolute; top: 0; left: 50%; width: 5px; height: 50%;
    background: rgba(255,255,255,0.08); cursor: col-resize;
    z-index: 20; transition: background 0.15s;
    transform: translateX(-50%);
  `;
  vDivider?.addEventListener('mouseenter', () => { vDivider.style.background = 'rgba(74,141,245,0.5)'; });
  vDivider?.addEventListener('mouseleave', () => { if (!vDivider.dragging) vDivider.style.background = 'rgba(255,255,255,0.08)'; });
  vDivider?.addEventListener('dblclick', () => { vpLayout = '2x2'; localStorage.setItem('atlantist-vp-layout', '2x2'); applyViewportGrid(); });

  let dragging = false;
  let startX = 0;

  vDivider?.addEventListener('mousedown', (e) => {
    dragging = true;
    vDivider.dragging = true;
    startX = e.clientX;
    vDivider.style.background = 'rgba(74,141,245,0.7)';
    document.body.style.cursor = 'col-resize';
    e.preventDefault();
  });

  document.addEventListener('mousemove', (e) => {
    if (!dragging) return;
    const areaRect = area.getBoundingClientRect();
    const relX = (e.clientX - areaRect.left) / areaRect.width;
    const newRel = Math.max(0.15, Math.min(0.85, relX));
    const wrap3d = document.getElementById('canvas-3d-wrap');
    const wrapPlan = document.getElementById('canvas-plan-wrap');
    if (wrap3d) wrap3d.style.width = `${newRel * 100}%`;
    if (wrapPlan) wrapPlan.style.width = `${(1 - newRel) * 100}%`;
  });

  document.addEventListener('mouseup', () => {
    if (dragging) {
      dragging = false;
      vDivider.dragging = false;
      vDivider.style.background = 'rgba(255,255,255,0.08)';
      document.body.style.cursor = '';
    }
  });

  // Horizontal divider between top and bottom row
  const hDivider = document.createElement('div');
  hDivider.className = 'vp-grid-divider vp-divider-row';
  hDivider.style.cssText = `
    position: absolute; top: 50%; left: 0; width: 100%; height: 5px;
    background: rgba(255,255,255,0.08); cursor: row-resize;
    z-index: 20; transition: background 0.15s;
    transform: translateY(-50%);
  `;
  hDivider?.addEventListener('mouseenter', () => { hDivider.style.background = 'rgba(74,141,245,0.5)'; });
  hDivider?.addEventListener('mouseleave', () => { if (!hDivider.dragging) hDivider.style.background = 'rgba(255,255,255,0.08)'; });
  hDivider?.addEventListener('dblclick', () => { vpLayout = '2x2'; localStorage.setItem('atlantist-vp-layout', '2x2'); applyViewportGrid(); });

  let hDragging = false;
  hDivider?.addEventListener('mousedown', (e) => {
    hDragging = true;
    hDivider.dragging = true;
    hDivider.style.background = 'rgba(74,141,245,0.7)';
    document.body.style.cursor = 'row-resize';
    e.preventDefault();
  });

  document.addEventListener('mousemove', (e) => {
    if (!hDragging) return;
    const areaRect = area.getBoundingClientRect();
    const relY = (e.clientY - areaRect.top) / areaRect.height;
    const newRel = Math.max(0.15, Math.min(0.85, relY));
    const wrap3d = document.getElementById('canvas-3d-wrap');
    const wrapSect = document.getElementById('canvas-section-wrap');
    if (wrap3d)  wrap3d.style.height = `${newRel * 100}%`;
    if (wrapSect) wrapSect.style.height = `${(1 - newRel) * 100}%`;
  });

  document.addEventListener('mouseup', () => {
    if (hDragging) {
      hDragging = false;
      hDivider.dragging = false;
      hDivider.style.background = 'rgba(255,255,255,0.08)';
      document.body.style.cursor = '';
    }
  });

  area.style.position = 'relative';
  area.appendChild(vDivider);
  area.appendChild(hDivider);
}

// BUG-UI-6: setupDividers() removed — viewport-manager.js builds all dividers.
// setupViewportEditMode() still runs; setupDividers() is a no-op stub.
if (document.readyState === 'loading') {
  window.addEventListener('DOMContentLoaded', () => setTimeout(() => { setupViewportEditMode(); }, 0));
} else {
  setTimeout(() => { setupViewportEditMode(); }, 0);
}

// ── Long-press on viewport wrap to enter edit mode (hide/swap)
// Attach to canvas wraps — long-press 400ms shows hide button + enables drag-swap
function setupViewportEditMode() {
  const wraps = document.querySelectorAll('#canvas-3d-wrap, #canvas-plan-wrap, #canvas-section-wrap');
  // Guard: wraps may be empty if elements don't exist yet
  if (!wraps.length) return;
  let holdTimers = {};

  wraps.forEach(wrap => {
    let moved = false;
    let timer = null;

    wrap?.addEventListener('pointerdown', (e) => {
      if (e.pointerType !== 'mouse' || e.button !== 0) return;
      moved = false;
      timer = setTimeout(() => {
        if (!moved) enterViewportEdit(wrap);
      }, 400);
    });

    wrap?.addEventListener('pointermove', () => { moved = true; if (timer) { clearTimeout(timer); timer = null; } });
    wrap?.addEventListener('pointerup', () => { if (timer) { clearTimeout(timer); timer = null; } });
    wrap?.addEventListener('pointerleave', () => { if (timer) { clearTimeout(timer); timer = null; } });
  });

  // Exit edit mode on outside click
  document.addEventListener('pointerdown', (e) => {
    if (!window._vpEditMode) return;
    const wraps = document.querySelectorAll('#canvas-3d-wrap, #canvas-plan-wrap, #canvas-section-wrap');
    const inside = [...wraps].some(w => w.contains(e.target));
    if (!inside) exitViewportEdit();
  });
}

function enterViewportEdit(wrap) {
  window._vpEditMode = true;
  wrap.style.outline = '2px solid rgba(74,141,245,0.8)';
  wrap.style.outlineOffset = '-2px';

  // Show hide button
  const hideBtn = document.createElement('button');
  hideBtn.className = 'vp-hide-overlay';
  hideBtn.textContent = '×';
  hideBtn.style.cssText = `
    position: absolute; top: 8px; right: 8px; z-index: 30;
    width: 24px; height: 24px;
    background: rgba(240,90,90,0.85);
    border: none; border-radius: 50%;
    color: white; font-size: 14px; line-height: 1; cursor: pointer;
    display: flex; align-items: center; justify-content: center;
  `;
  hideBtn?.addEventListener('click', (e) => {
    e.stopPropagation();
    wrap.style.display = 'none';
    exitViewportEdit();
  });

  // If plan or section, hide it and reduce to fewer-pane
  const id = wrap.id;
  if (id === 'canvas-plan-wrap') {
    const planHidden = true;
  }
  if (id === 'canvas-section-wrap') {
    const sectHidden = true;
  }

  wrap._vpHideBtn = hideBtn;
  wrap.appendChild(hideBtn);

  // Dim other wraps
  document.querySelectorAll('#canvas-3d-wrap, #canvas-plan-wrap, #canvas-section-wrap').forEach(w => {
    if (w !== wrap) w.style.opacity = '0.5';
  });
}

function exitViewportEdit() {
  window._vpEditMode = false;
  document.querySelectorAll('#canvas-3d-wrap, #canvas-plan-wrap, #canvas-section-wrap').forEach(w => {
    w.style.outline = '';
    w.style.outlineOffset = '';
    w.style.opacity = '';
    if (w._vpHideBtn) {
      w._vpHideBtn.remove();
      w._vpHideBtn = null;
    }
  });
}

// Ctrl+Shift+V to reset viewport layout
document.addEventListener('keydown', (e) => {
  if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key.toLowerCase() === 'v') {
    e.preventDefault();
    vpLayout = '2x2';
    localStorage.setItem('atlantist-vp-layout', '2x2');
    applyViewportGrid();
  }
});

// SP-B: Grid density cycling — G key cycles density, Shift+G toggles global grid
document.addEventListener('keydown', (e) => {
  if (e.target.matches('input,textarea,select')) return;
  if (!window.AdaptiveGrid) return;
  if (e.key === 'g' || e.key === 'G') {
    if (e.shiftKey) {
      window.AdaptiveGrid.toggleGlobalGrid();
      const toastFn = window._atlantist_toast || console.log.bind(console);
      toastFn(`Global grid: ${window.AdaptiveGrid.showGlobalGrid ? 'ON' : 'OFF'}`, 'info', 1400);
    } else {
      window.AdaptiveGrid.cycleDensity();
      const label = window.AdaptiveGrid.getDensityLabel();
      const toastFn = window._atlantist_toast || console.log.bind(console);
      toastFn(`Grid: ${label}`, 'info', 1400);
    }
  }
});


// Animation loop
let animId;
let _frameCount = 0;
let _frameLogTime = 0;
// Throttle issue pin DOM updates to ~10fps — avoids DOM thrash during orbit
let _pinFrameThrottle = 0;
// Throttle: capture camera state for active viewport tabs every 800ms
let _lastCamCapture = 0;
const CAM_CAPTURE_INTERVAL = 800;

export function animate() {
  animId = requestAnimationFrame(animate);
  if (!_vpWired) return;
  try {
    const t0 = performance.now();
    // BULK-LIBS: stats.js FPS counter (enabled via ?debugStats or window.__atlForceStats)
    statsBegin();
    (_vpControls3d || controls3d).update();

    // Render all viewports — syncRendererSizes removed from RAF to eliminate
    // layout thrash. Canvas resizes are handled by ResizeObserver (see below).
    (_vpRenderer3d   || renderer3d).render(scene3d,    cam3d);
    (_vpRendererPlan || rendererPlan).render(scenePlan, camPlan);
    (_vpRendererSect || rendererSection).render(sceneSection, camSection);
    applyViewportCameras();

    // Render floating viewports
    try { renderFloatingViewports(); } catch (_) {}

    // Throttle camera state capture for active tabs (every 800ms)
    const now = performance.now();
    if (now - _lastCamCapture > CAM_CAPTURE_INTERVAL) {
      _lastCamCapture = now;
      try {
        const m = window.__vpManager;
        if (m?.vpState?.panes) {
          m.vpState.panes.forEach(p => {
            if (p.visible && typeof m.captureViewportCameraState === 'function') {
              m.captureViewportCameraState(p.id);
            }
          });
        }
      } catch (_) {}
    }

    // Throttle pin updates to ~10fps (every 100ms)
    const pinNow = performance.now();
    if (pinNow - _pinFrameThrottle > 100) {
      _pinFrameThrottle = pinNow;
      try { renderIssuePins(); } catch (e) { /* non-critical — don't block render */ }
    }

    // SP-C: Update 3D overlay badge positions on every frame
    try { if (window.__updateOverlayBadges) window.__updateOverlayBadges(); } catch (_) {}

    const ms = performance.now() - t0;
    _frameCount++;
    if (ms > 16 && performance.now() - _frameLogTime > 5000) {
      console.warn(`[animate] slow frame: ${ms.toFixed(1)}ms (${Math.round(1000 / ms)} fps — target 60fps)`);
      _frameLogTime = performance.now();
    }
  } catch (e) {
    console.warn(`[animate] render frame error: ${e.message}`);
  } finally {
    // BULK-LIBS: stats.js FPS counter end marker
    statsEnd();
  }
}
animate();

// ─── Selection ────────────────────────────────────────────────────────────────
function selectEntity(id, type) {
  if (state.selectedId === id) return;
  state.selectedId = id;
  state.selectedType = type;
  rebuildScene();
  if (id) {
    // Handle MEP + curved-surface types inline (avoids duplicate function declaration)
    if (type === 'mep') {
      showMEPPropertiesPanel(id);
    } else if (type === 'curved') {
      showCurvedSurfacePropertiesPanel(id);
    } else {
      showPropertiesPanel(id, type);
    }
    // IM Panel: notify of selection change
    window.dispatchEvent(new CustomEvent('atl-element-selected', { detail: { id, type } }));
  } else {
    clearPropertiesPanel();
    window.dispatchEvent(new CustomEvent('atl-selection-cleared'));
  }
  // Broadcast selection to other clients
  wsClient.sendSelectionChange(id);
  // Phase 35: broadcast to live session participants
  if (liveSession?.session && id) {
    liveSession.ws.sendLiveSelection(id);
  }
}
window.selectEntity = selectEntity;

// ─── Multi-select status toast ────────────────────────────────────────────────
function updateMultiSelectStatus() {
  const n = state.multiSelection.length;
  if (n >= 2) {
    toast(`${n} objects selected — press Space or click ↻ Rotate 45° to group-rotate`, 'info', 2500);
  }
}

// ─── Group Rotation (Rodrigues via applyAxisAngle) ────────────────────────────
// Single undo entry per group-rotate: stores pre-rotation params for all targets.
const groupRotateUndoStack = [];

// Get world-space center of an entity (the XZ plane, Y irrelevant for pivot on ground plane)
function getEntityCenter(id, type) {
  const v = new THREE.Vector3();
  if (type === 'element') {
    const el = state.elements.find(e => e.id === id);
    if (!el) return v;
    const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : (el.parameters || {});
    if (el.type === 'wall') {
      const sx = parseFloat(params.startCoord?.x || 0);
      const sy = parseFloat(params.startCoord?.y || 0);
      const ex = parseFloat(params.endCoord?.x || sx + 5);
      const ey = parseFloat(params.endCoord?.y || sy);
      v.set((sx + ex) / 2, 0, (sy + ey) / 2);
    } else if (el.type === 'column') {
      if (params.rotatedX !== undefined) {
        v.set(params.rotatedX, 0, params.rotatedZ);
      } else {
        const grid = params.gridIntersection || 'A-1';
        const colLetter = grid.split('-')[0] || 'A';
        const colNum = parseInt(grid.split('-')[1] || '1', 10);
        v.set((colLetter.charCodeAt(0) - 65) * 5, 0, (colNum - 1) * 5);
      }
    }
  } else if (type === 'stair') {
    const stair = state.elements.find(e => e.id === id) ||
      (state.stairs && state.stairs.find(s => s.id === id));
    if (stair) v.set(parseFloat(stair.position_x || 0), 0, parseFloat(stair.position_y || 0));
  } else if (type === 'floor') {
    const floor = state.floors.find(f => f.id === id);
    if (floor) v.set(parseFloat(floor.position_x || 0), 0, parseFloat(floor.position_y || 0));
  } else if (type === 'ceiling') {
    const ceil = state.ceilings.find(c => c.id === id);
    if (ceil) v.set(parseFloat(ceil.position_x || 0), 0, parseFloat(ceil.position_y || 0));
  }
  return v;
}

// Rotate a single XZ point around a pivot by angle radians (Y-up axis = plan rotation)
function rotateXZAroundPivot(px, pz, pivotX, pivotZ, angleRad) {
  const dx = px - pivotX;
  const dz = pz - pivotZ;
  return {
    x: pivotX + dx * Math.cos(angleRad) - dz * Math.sin(angleRad),
    z: pivotZ + dx * Math.sin(angleRad) + dz * Math.cos(angleRad),
  };
}

/**
 * Rotate selected objects as a unified group around their common barycenter.
 * @param {number} degrees - Angle in degrees (default 45). Negative = CW from above.
 */
async function rotateSelectionGroup(degrees = 45) {
  const targets = state.multiSelection.length >= 1
    ? state.multiSelection
    : (state.selectedId ? [{ id: state.selectedId, type: state.selectedType }] : []);

  if (targets.length === 0) return;

  const angleRad = THREE.MathUtils.degToRad(-degrees);

  const centers = targets.map(t => getEntityCenter(t.id, t.type));
  const pivot = centers.reduce(
    (acc, c) => ({ x: acc.x + c.x / targets.length, z: acc.z + c.z / targets.length }),
    { x: 0, z: 0 }
  );

  const undoSnapshot = targets.map(({ id, type }) => {
    const snap = { id, type, before: {} };
    if (type === 'element') {
      const el = state.elements.find(e => e.id === id);
      if (el) snap.before.parameters = JSON.parse(JSON.stringify(
        typeof el.parameters === 'string' ? JSON.parse(el.parameters) : el.parameters
      ));
    } else if (type === 'stair') {
      const s = state.stairs && state.stairs.find(s => s.id === id);
      if (s) snap.before = { position_x: s.position_x, position_y: s.position_y, rotation_degrees: s.rotation_degrees };
    } else if (type === 'floor') {
      const f = state.floors.find(f => f.id === id);
      if (f) snap.before = { position_x: f.position_x, position_y: f.position_y };
    } else if (type === 'ceiling') {
      const c = state.ceilings.find(c => c.id === id);
      if (c) snap.before = { position_x: c.position_x, position_y: c.position_y };
    }
    return snap;
  });
  groupRotateUndoStack.push({ targets: undoSnapshot, pivot });

  const patchPromises = [];
  const eventPromises = [];
  const currentUser = window.currentUserId || 'user';

  for (const { id, type } of targets) {
    if (type === 'element') {
      const el = state.elements.find(e => e.id === id);
      if (!el) continue;
      const params = JSON.parse(JSON.stringify(
        typeof el.parameters === 'string' ? JSON.parse(el.parameters) : el.parameters
      ));
      if (el.type === 'wall') {
        const beforeParams = JSON.parse(JSON.stringify(params));
        const sx = parseFloat(params.startCoord?.x || 0);
        const sy = parseFloat(params.startCoord?.y || 0);
        const ex = parseFloat(params.endCoord?.x || sx + 5);
        const ey = parseFloat(params.endCoord?.y || sy);
        const ns = rotateXZAroundPivot(sx, sy, pivot.x, pivot.z, angleRad);
        const ne = rotateXZAroundPivot(ex, ey, pivot.x, pivot.z, angleRad);
        params.startCoord = { x: ns.x, y: ns.z };
        params.endCoord   = { x: ne.x, y: ne.z };
        el.parameters = params;
        patchPromises.push(
          api('PATCH', `/api/elements/${id}`, { parameters: params })
            .then(() => api('POST', '/api/events', {
              entity_type: 'element', entity_id: id, event_type: 'group_rotate',
              before_data: { parameters: beforeParams },
              after_data: { parameters },
              triggered_by: currentUser
            }))
            .catch(() => {})
        );
      } else if (el.type === 'column') {
        let cx, cz;
        if (params.rotatedX !== undefined) {
          cx = params.rotatedX; cz = params.rotatedZ;
        } else {
          const grid = params.gridIntersection || 'A-1';
          const colLetter = grid.split('-')[0] || 'A';
          const colNum = parseInt(grid.split('-')[1] || '1', 10);
          cx = (colLetter.charCodeAt(0) - 65) * 5;
          cz = (colNum - 1) * 5;
        }
        const nr = rotateXZAroundPivot(cx, cz, pivot.x, pivot.z, angleRad);
        const beforeParams = JSON.parse(JSON.stringify(params));
        params.rotatedX = nr.x;
        params.rotatedZ = nr.z;
        el.parameters = params;
        patchPromises.push(
          api('PATCH', `/api/elements/${id}`, { parameters: params })
            .then(() => api('POST', '/api/events', {
              entity_type: 'element', entity_id: id, event_type: 'group_rotate',
              before_data: { parameters: beforeParams },
              after_data: { parameters },
              triggered_by: currentUser
            }))
            .catch(() => {})
        );
      }
    } else if (type === 'stair') {
      const stairArr = state.stairs || [];
      const s = stairArr.find(st => st.id === id);
      if (!s) continue;
      const beforeState = { position_x: s.position_x, position_y: s.position_y, rotation_degrees: s.rotation_degrees };
      const nr = rotateXZAroundPivot(parseFloat(s.position_x || 0), parseFloat(s.position_y || 0), pivot.x, pivot.z, angleRad);
      const newRot = ((parseFloat(s.rotation_degrees || 0) - degrees) % 360 + 360) % 360;
      s.position_x = nr.x; s.position_y = nr.z; s.rotation_degrees = newRot;
      patchPromises.push(
        api('PATCH', `/api/stairs/${id}`, { position_x: nr.x, position_y: nr.z, rotation_degrees: newRot })
          .then(() => api('POST', '/api/events', {
            entity_type: 'stair', entity_id: id, event_type: 'group_rotate',
            before_data: beforeState,
            after_data: { position_x: nr.x, position_y: nr.z, rotation_degrees: newRot },
            triggered_by: currentUser
          }))
          .catch(() => {})
      );
    } else if (type === 'floor') {
      const f = state.floors.find(f => f.id === id);
      if (!f) continue;
      const beforeState = { position_x: f.position_x, position_y: f.position_y };
      const nr = rotateXZAroundPivot(parseFloat(f.position_x || 0), parseFloat(f.position_y || 0), pivot.x, pivot.z, angleRad);
      f.position_x = nr.x; f.position_y = nr.z;
      patchPromises.push(
        api('PATCH', `/api/floors/${id}`, { position_x: nr.x, position_y: nr.z })
          .then(() => api('POST', '/api/events', {
            entity_type: 'floor', entity_id: id, event_type: 'group_rotate',
            before_data: beforeState,
            after_data: { position_x: nr.x, position_y: nr.z },
            triggered_by: currentUser
          }))
          .catch(() => {})
      );
    } else if (type === 'ceiling') {
      const c = state.ceilings.find(c => c.id === id);
      if (!c) continue;
      const beforeState = { position_x: c.position_x, position_y: c.position_y };
      const nr = rotateXZAroundPivot(parseFloat(c.position_x || 0), parseFloat(c.position_y || 0), pivot.x, pivot.z, angleRad);
      c.position_x = nr.x; c.position_y = nr.z;
      patchPromises.push(
        api('PATCH', `/api/ceilings/${id}`, { position_x: nr.x, position_y: nr.z })
          .then(() => api('POST', '/api/events', {
            entity_type: 'ceiling', entity_id: id, event_type: 'group_rotate',
            before_data: beforeState,
            after_data: { position_x: nr.x, position_y: nr.z },
            triggered_by: currentUser
          }))
          .catch(() => {})
      );
    }
  }

  rebuildScene();
  toast(`Rotated ${targets.length} object${targets.length > 1 ? 's' : ''} ${degrees}° CW`, 'success', 2000);
  wsClient.sendGroupRotation(targets.map(t => t.id), pivot, angleRad);
  await Promise.allSettled(patchPromises);
}
window.rotateSelectionGroup = rotateSelectionGroup;

async function undoGroupRotate() {
  if (groupRotateUndoStack.length === 0) {
    toast('Nothing to undo', 'info', 1500);
    return;
  }
  const { targets } = groupRotateUndoStack.pop();
  const patchPromises = [];
  for (const { id, type, before } of targets) {
    if (type === 'element') {
      const el = state.elements.find(e => e.id === id);
      if (el) {
        el.parameters = before.parameters;
        patchPromises.push(
          api('PATCH', `/api/elements/${id}`, { parameters: before.parameters })
            .then(updated => { const i = state.elements.findIndex(e => e.id === id); if (i !== -1) state.elements[i] = { ...updated, layers: updated.layers || [] }; })
            .catch(() => {})
        );
      }
    } else if (type === 'stair') {
      const s = (state.stairs || []).find(st => st.id === id);
      if (s) {
        Object.assign(s, before);
        patchPromises.push(api('PATCH', `/api/stairs/${id}`, before).catch(() => {}));
      }
    } else if (type === 'floor') {
      const f = state.floors.find(f => f.id === id);
      if (f) { Object.assign(f, before); patchPromises.push(api('PATCH', `/api/floors/${id}`, before).catch(() => {})); }
    } else if (type === 'ceiling') {
      const c = state.ceilings.find(c => c.id === id);
      if (c) { Object.assign(c, before); patchPromises.push(api('PATCH', `/api/ceilings/${id}`, before).catch(() => {})); }
    }
  }
  rebuildScene();
  toast('Group rotation undone', 'success', 2000);
  await Promise.allSettled(patchPromises);
}

// ─── Level list panel ─────────────────────────────────────────────────────────
function renderLevelList() {
  const list = document.getElementById('level-list');
  list.innerHTML = '';
  const sorted = [...state.levels].sort((a, b) => parseFloat(b.elevation) - parseFloat(a.elevation));
  for (const level of sorted) {
    const item = document.createElement('div');
    item.className = `level-item${level.id === state.selectedId ? ' active' : ''}`;
    item.innerHTML = `
      <span class="level-name">${level.name}</span>
      <span class="level-elev">${parseFloat(level.elevation).toFixed(3)}m</span>
    `;
    item?.addEventListener('click', () => selectEntity(level.id, 'level'));
    list.appendChild(item);
  }
}

// ─── Properties Panel ─────────────────────────────────────────────────────────
function clearPropertiesPanel() {
  document.getElementById('props-title').textContent = 'PROPERTIES';
  document.getElementById('properties-content').innerHTML = `
    <div class="props-empty">
      <p>Select an element in the viewport to view and edit its properties.</p>
      <p class="hint">Click a wall, column, or level.</p>
    </div>`;
}

function clearIMPanel() {
  _imCurrentElementId = null;
  _imCurrentElementType = null;
  _imDataCache = null;
  // Clear gold highlight
  while (imHighlightGroup.children.length) imHighlightGroup.remove(imHighlightGroup.children[0]);
  // Restore dimmed elements
  scene3d.traverse(child => {
    if (child.isMesh && child._originalOpacity !== undefined) {
      if (child.material) child.material.opacity = child._originalOpacity;
      child._originalOpacity = undefined;
    }
  });
}

function showPropertiesPanel(id, type) {
  if (type === 'level') {
    const level = state.levels.find(l => l.id === id);
    if (!level) return;
    renderLevelProperties(level);
  } else if (type === 'family') {
    const fam = state.familyInstances.find(f => f.id === id);
    if (!fam) return;
    renderFamilyProperties(fam);
  } else if (type === 'stair') {
    const stair = state.stairs.find(s => s.id === id);
    if (!stair) return;
    renderStairProperties(stair);
  } else if (type === 'railing') {
    const railing = state.railings.find(r => r.id === id);
    if (!railing) return;
    renderRailingProperties(railing);
  } else if (type === 'grid') {
    const grid = state.grids.find(g => g.id === id);
    if (!grid) return;
    renderGridProperties(grid);
  } else if (type === 'room') {
    const room = state.rooms.find(r => r.id === id);
    if (!room) return;
    renderRoomProperties(room);
  } else if (type === 'curved') {
    const surface = state.curvedSurfaces.find(s => s.id === id);
    if (!surface) return;
    renderCurvedSurfaceProperties(surface);
  } else {
    const el = state.elements.find(e => e.id === id);
    if (!el) return;
    if (el.type === 'wall') renderWallProperties(el);
    else if (el.type === 'column') renderColumnProperties(el);
    else if (el.type === 'roof') renderRoofProperties(el);
  }
}

function refreshPropertiesPanel() {
  if (!state.selectedId) return;
  showPropertiesPanel(state.selectedId, state.selectedType);
}

// ─── IM Panel (IM-D) ────────────────────────────────────────────────────────
let _imCurrentElementId = null;
let _imCurrentElementType = null;
let _imDataCache = null;

/** Toggle IM panel open/closed for current selection. */
function toggleIMPanel() {
  const imPanel = document.getElementById('im-content');
  if (!imPanel) return;
  const isVisible = !imPanel.classList.contains('hidden') && imPanel.style.display !== 'none';
  if (isVisible) {
    // Switch to props tab
    document.getElementById('btn-props')?.click();
  } else {
    document.getElementById('btn-im')?.click();
  }
}

/** Open the IM panel for the currently selected element. */
function openIMPanelForCurrentSelection() {
  if (!state.selectedId) {
    renderIMPanelEmpty();
    return;
  }
  _imCurrentElementId = state.selectedId;
  _imCurrentElementType = state.selectedType;
  fetchIMData(_imCurrentElementId, _imCurrentElementType);
}

/** Fetch IM data from API and render. Uses real IM API (im-elements.js) */
async function fetchIMData(elementId, elementType) {
  try {
    // GET /api/im/instances/:elementId — returns { instance, effective_properties }
    const res = await api('GET', `/api/im/instances/${elementId}`);
    _imDataCache = res; // { instance, effective_properties }
    // Also fetch type properties and constraints in parallel
    const typeId = res.instance?.type_id;
    const [typePropsRes, constraintsRes] = await Promise.all([
      typeId ? api('GET', `/api/im/types/${typeId}/properties`).catch(() => ({ properties: [], effective: {} })) : Promise.resolve({ properties: [], effective: {} }),
      api('GET', `/api/im/constraints/${elementId}`).catch(() => ({ constraints: [] })),
    ]);
    _imDataCache.typeProperties = typePropsRes.properties || [];
    _imDataCache.effective = typePropsRes.effective || {};
    _imDataCache.constraints = constraintsRes.constraints || [];
    renderIMPanel(_imDataCache);
  } catch (e) {
    if (e.status === 404) {
      renderIMPanelNoIMData(elementId, elementType);
    } else {
      console.error('IM panel load failed:', e);
      renderIMPanelError();
    }
  }
}

/** Render the IM panel from fetched data. */
function renderIMPanel(data) {
  const body = document.getElementById('im-panel-body');
  if (!body) return;

  const inst = data.instance || {};
  const typeName = inst.type_name || `Type #${inst.type_id}`;
  document.getElementById('im-type-name').textContent = typeName;

  const hasOverrides = inst.overridden_keys && inst.overridden_keys.length > 0;
  const badge = document.getElementById('im-override-badge');
  if (hasOverrides) badge?.classList.remove('hidden');
  else badge?.classList.add('hidden');

  if (imActiveTab === 'type') renderIMTypeTab(data, body);
  else if (imActiveTab === 'instance') renderIMInstanceTab(data, body);
  else renderIMConstraintsTab(data, body);
}

function renderIMTypeTab(data, body) {
  const typeProps = data.typeProperties || [];
  const effective = data.effective || {};
  if (!typeProps.length) {
    // Fallback: show effective properties
    const ep = Object.entries(effective);
    if (!ep.length) {
      body.innerHTML = `<div style="color:var(--text-muted);font-size:12px;text-align:center;padding:20px">No type properties defined.</div>`;
      return;
    }
    body.innerHTML = `<div style="display:flex;flex-direction:column;gap:4px">
      ${ep.map(([k, v]) => `
        <div style="display:flex;align-items:center;gap:8px;padding:6px 8px;background:var(--bg-viewport);border-radius:6px;border:1px solid var(--border)">
          <span style="font-size:11px;color:var(--text-muted);min-width:100px;flex-shrink:0">${escHtml(k)}</span>
          <span style="font-size:12px;font-weight:600;color:var(--text);flex:1;text-align:right">${escHtml(String(v ?? '—'))}</span>
        </div>`).join('')}
    </div>`;
    return;
  }
  body.innerHTML = `<div style="display:flex;flex-direction:column;gap:6px">
    ${typeProps.map(p => `
      <div style="display:flex;align-items:center;gap:8px;padding:6px 8px;background:var(--bg-viewport);border-radius:6px;border:1px solid var(--border)">
        <span style="font-size:11px;color:var(--text-muted);min-width:100px;flex-shrink:0">${escHtml(p.property_key || p.property_name || '')}</span>
        <span style="font-size:12px;font-weight:600;color:var(--text);flex:1;text-align:right">${escHtml(String(p.property_value ?? '—'))}${p.unit ? ' <span style="font-size:10px;color:var(--text-muted)">'+escHtml(p.unit)+'</span>' : ''}</span>
        ${p.override_flag ? '<span style="color:#f39c12;font-size:10px">E</span>' : ''}
      </div>
    `).join('')}
  </div>`;
}

function renderIMInstanceTab(data, body) {
  const inst = data.instance || {};
  const overrides = inst.override_values || {};
  const overriddenKeys = inst.overridden_keys || [];
  const effective = data.effective || {};
  const entries = Object.entries(effective);
  if (!entries.length) {
    body.innerHTML = `<div style="color:var(--text-muted);font-size:12px;text-align:center;padding:20px">No instance properties.</div>`;
    return;
  }
  body.innerHTML = `<div style="display:flex;flex-direction:column;gap:6px">
    ${entries.map(([k, v]) => {
      const isOverridden = overriddenKeys.includes(k);
      return `
      <div style="display:flex;align-items:center;gap:6px;padding:6px 8px;background:var(--bg-viewport);border-radius:6px;border:1px solid ${isOverridden ? 'rgba(243,156,18,0.4)' : 'var(--border)'}">
        <span style="font-size:11px;color:var(--text-muted);min-width:100px;flex-shrink:0">${escHtml(k)}</span>
        <input class="im-override-input" data-prop="${escHtml(k)}"
          value="${escHtml(String(isOverridden ? (overrides[k] ?? v) : v))}"
          style="flex:1;background:transparent;border:none;color:var(--text);font-size:12px;text-align:right;outline:none;padding:0"
          placeholder="${escHtml(String(v))}"/>
        ${isOverridden ? `<button class="im-reset-btn" data-prop="${escHtml(k)}" title="Reset to type default" style="background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:10px;padding:2px 4px">↩</button>` : '<span style="width:22px"></span>'}
      </div>`;
    }).join('')}
    <button id="im-reset-all-overrides" style="margin-top:8px;padding:8px;background:rgba(243,156,18,0.1);border:1px solid rgba(243,156,18,0.3);border-radius:6px;color:#f39c12;font-size:11px;cursor:pointer">Reset All to Type Defaults</button>
  </div>`;

  body.querySelectorAll('.im-override-input').forEach(inp => {
    inp.addEventListener('change', async (e) => {
      await saveIMOverride(e.target.dataset.prop, e.target.value);
    });
    inp.addEventListener('keydown', (e) => { if (e.key === 'Enter') e.target.blur(); });
  });
  body.querySelectorAll('.im-reset-btn').forEach(btn => {
    btn.addEventListener('click', async () => { await resetSingleIMOverride(btn.dataset.prop); });
  });
  body.getElementById('im-reset-all-overrides')?.addEventListener('click', resetAllIMOverrides);
}

function renderIMConstraintsTab(data, body) {
  const constraints = data.constraints || [];
  if (!constraints.length) {
    body.innerHTML = `<div style="color:var(--text-muted);font-size:12px;text-align:center;padding:20px">No active constraints.</div>`;
    return;
  }
  body.innerHTML = `<div style="display:flex;flex-direction:column;gap:6px">
    ${constraints.map(c => `
      <div style="padding:8px 10px;background:var(--bg-viewport);border-radius:6px;border:1px solid var(--border)">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">
          <span style="font-size:11px;font-weight:600;color:var(--text)">${escHtml(c.constraint_key)}</span>
          ${c.constraint_category ? `<span style="font-size:10px;padding:2px 5px;border-radius:3px;background:rgba(100,100,255,0.15);color:#8888ff">${escHtml(c.constraint_category)}</span>` : ''}
        </div>
        <div style="font-size:11px;color:var(--accent);font-family:monospace">${escHtml(c.formula_expression)}</div>
        ${c.bound_value !== null ? `<div style="font-size:10px;color:var(--text-muted);margin-top:2px">Bound: ${escHtml(String(c.bound_value))}${c.unit ? ' '+escHtml(c.unit) : ''}</div>` : ''}
      </div>
    `).join('')}
  </div>`;
}

function renderIMPanelNoIMData(elementId, elementType) {
  const body = document.getElementById('im-panel-body');
  if (!body) return;
  document.getElementById('im-type-name').textContent = 'No IM Data';
  body.innerHTML = `<div style="text-align:center;padding:20px;color:var(--text-muted);font-size:12px">
    <div style="margin-bottom:8px;font-size:20px">📋</div>
    <div>Element has no IM instance record.</div>
    <div style="margin-top:8px;font-size:11px">Use <strong>Ctrl+Shift+T</strong> to assign an IM type.</div>
    <button id="im-assign-type-btn" style="margin-top:12px;padding:8px 16px;background:var(--accent);border:none;border-radius:6px;color:white;cursor:pointer;font-size:12px;font-weight:600">Assign Type…</button>
  </div>`;
  document.getElementById('im-assign-type-btn')?.addEventListener('click', openIMChangeTypeModal);
  document.getElementById('im-override-badge')?.classList.add('hidden');
}

function renderIMPanelEmpty() {
  const body = document.getElementById('im-panel-body');
  if (!body) return;
  document.getElementById('im-type-name').textContent = 'IM Panel';
  body.innerHTML = `<div style="text-align:center;padding:20px;color:var(--text-muted);font-size:12px">
    <div style="margin-bottom:8px;font-size:20px">🔍</div>
    <div>Select an element in the 3D viewport to inspect its IM data.</div>
  </div>`;
  document.getElementById('im-override-badge')?.classList.add('hidden');
}

function renderIMPanelError() {
  const body = document.getElementById('im-panel-body');
  if (!body) return;
  body.innerHTML = `<div style="text-align:center;padding:20px;color:#e74c3c;font-size:12px">Failed to load IM data. Check the console for errors.</div>`;
}

/** Save an individual override via PUT /api/im/instances/:id/overrides/:key */
async function saveIMOverride(propertyName, value) {
  if (!_imCurrentElementId) return;
  try {
    await api('PUT', `/api/im/instances/${_imCurrentElementId}/overrides/${encodeURIComponent(propertyName)}`, { value });
    openIMPanelForCurrentSelection();
    toast('Override saved', 'success');
  } catch (e) {
    toast('Failed to save override: ' + e.message, 'error');
  }
}

/** Reset a single property override via DELETE /api/im/instances/:id/overrides/:key */
async function resetSingleIMOverride(propertyName) {
  if (!_imCurrentElementId) return;
  try {
    await api('DELETE', `/api/im/instances/${_imCurrentElementId}/overrides/${encodeURIComponent(propertyName)}`);
    openIMPanelForCurrentSelection();
    toast('Override reset', 'info');
  } catch (e) {
    toast('Failed to reset: ' + e.message, 'error');
  }
}

/** Reset all overrides by clearing each one */
async function resetAllIMOverrides() {
  if (!_imCurrentElementId || !_imDataCache?.instance) return;
  const keys = _imDataCache.instance.overridden_keys || [];
  try {
    for (const k of keys) {
      await api('DELETE', `/api/im/instances/${_imCurrentElementId}/overrides/${encodeURIComponent(k)}`).catch(() => {});
    }
    openIMPanelForCurrentSelection();
    toast('All overrides reset', 'info');
  } catch (e) {
    toast('Failed to reset overrides: ' + e.message, 'error');
  }
}

async function resetIMOverridesForCurrent() {
  await resetAllIMOverrides();
}

/** Open the Change Type modal for the current element. */
async function openIMChangeTypeModal() {
  if (!state.selectedId || !state.selectedType) { toast('Select an element first', 'warn'); return; }
  const projectId = window.currentProjectId || 1;
  try {
    const res = await api('GET', `/api/im/types?project_id=${projectId}`);
    openIMChangeTypeDialog(res.types || []);
  } catch (e) {
    toast('Failed to load type catalog: ' + e.message, 'error');
  }
}

function openIMChangeTypeDialog(types) {
  let overlay = document.getElementById('im-change-type-modal');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'im-change-type-modal';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:600;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.6)';
    document.body.appendChild(overlay);
  }
  const cats = ['wall','column','door','window','floor','ceiling','stair','railing'];
  const byCategory = {};
  for (const t of types) {
    if (!byCategory[t.element_category]) byCategory[t.element_category] = [];
    byCategory[t.element_category].push(t);
  }
  overlay.innerHTML = `<div style="background:var(--bg-panel);border:1px solid var(--border);border-radius:16px;padding:24px;min-width:400px;max-width:500px;max-height:70vh;overflow-y:auto;display:flex;flex-direction:column;gap:12px">
    <div style="display:flex;align-items:center;justify-content:space-between">
      <h3 style="font-size:16px;font-weight:700;margin:0">Change Type</h3>
      <button id="im-ct-close" style="background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:20px;line-height:1">×</button>
    </div>
    ${cats.map(cat => byCategory[cat] ? `
      <div>
        <div style="font-size:11px;font-weight:600;color:var(--text-muted);text-transform:uppercase;margin-bottom:4px;padding-top:8px">${cat}</div>
        <div style="display:flex;flex-direction:column;gap:4px">
          ${byCategory[cat].map(t => `
            <button class="im-ct-option" data-type-id="${t.id}" style="padding:8px 12px;text-align:left;background:var(--bg-viewport);border:1px solid var(--border);border-radius:6px;color:var(--text);cursor:pointer;font-size:12px">${escHtml(t.type_name)}</button>
          `).join('')}
        </div>
      </div>` : '').join('')}
  </div>`;
  overlay.style.display = 'flex';
  overlay.querySelector('#im-ct-close').onclick = () => { overlay.style.display = 'none'; };
  overlay.onclick = (e) => { if (e.target === overlay) overlay.style.display = 'none'; };
  overlay.querySelectorAll('.im-ct-option').forEach(btn => {
    btn.onclick = async () => {
      const typeId = btn.dataset.typeId;
      await assignIMType(typeId);
      overlay.style.display = 'none';
    };
  });
}

async function assignIMType(typeId) {
  if (!_imCurrentElementId) return;
  try {
    // POST /api/im/instances to create the IM instance with the chosen type
    await api('POST', '/api/im/instances', { element_id: _imCurrentElementId, type_id: parseInt(typeId, 10), override_values: {}, status: 'design' });
    openIMPanelForCurrentSelection();
    toast('Type assigned', 'success');
  } catch (e) {
    if (e.status === 409) {
      // Instance already exists — update type via PUT
      try {
        await api('PUT', `/api/im/instances/${_imCurrentElementId}`, { type_id: parseInt(typeId, 10) });
        openIMPanelForCurrentSelection();
        toast('Type changed', 'success');
      } catch (e2) { toast('Failed to change type: ' + e2.message, 'error'); }
    } else {
      toast('Failed to assign type: ' + e.message, 'error');
    }
  }
}

// ─── Debounced PATCH ──────────────────────────────────────────────────────────
const debouncers = {};
function debouncedPatch(id, patchFn, delay = 300) {
  clearTimeout(debouncers[id]);
  debouncers[id] = setTimeout(patchFn, delay);
}

/**
 * Loop 17.4: Offline-aware element save with performance timer.
 * Attempts the HTTP save; if we're offline the edit gets queued for replay.
 * Marks the sync timer so Tab B sees the update within <2s target.
 */
async function saveElementOfflineSafe(elementId, patchData, entityType = 'element') {
  // Start performance timer (Tab B will measure this as the round-trip)
  window.__recordEditStart(elementId, entityType);

  const isOffline = !wsClient.socket || wsClient.socket.readyState !== WebSocket.OPEN;
  if (isOffline) {
    // Queue for replay; optimistically update local state
    await wsClient.queueEdit({
      _editType: 'element_update',
      _entityType: entityType,
      _entityId: elementId,
      id: elementId,
      entity_type: entityType,
      parameters: patchData.parameters || patchData,
    });
    window.__recordEditDone(elementId);
    return;
  }

  try {
    const updated = await api('PATCH', `/api/elements/${elementId}`, patchData);
    window.__recordEditDone(elementId);
    return updated;
  } catch (e) {
    window.__recordEditDone(elementId);
    // Network error — queue it
    await wsClient.queueEdit({
      _editType: 'element_update',
      _entityType: entityType,
      _entityId: elementId,
      id: elementId,
      entity_type: entityType,
      parameters: patchData.parameters || patchData,
    });
    throw e;
  }
}

function setDagStatus(state) {
  const el = document.getElementById('dag-status');
  el.className = `dag-status ${state}`;
  el.title = state === 'recalculating' ? 'DAG recalculating...' : state === 'done' ? 'Up to date' : '';
}

// ─── Optimistic update helper ─────────────────────────────────────────────────
function optimisticElementUpdate(id, patchParams) {
  const idx = state.elements.findIndex(e => e.id === id);
  if (idx === -1) return;
  const el = state.elements[idx];
  const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : { ...el.parameters };
  Object.assign(params, patchParams);
  state.elements[idx] = { ...el, parameters: params };
  rebuildScene();
}

// ─── WALL PROPERTIES ─────────────────────────────────────────────────────────
function renderWallProperties(el) {
  const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : (el.parameters || {});
  const computed = typeof el.computed === 'string' ? JSON.parse(el.computed) : (el.computed || {});
  const layers = el.layers || [];
  const title = `WALL: ${el.type_name || 'Wall'}`;
  document.getElementById('props-title').textContent = title;

  const levelsOptions = state.levels.map(l =>
    `<option value="${l.id}">${l.name} (${parseFloat(l.elevation).toFixed(3)}m)</option>`
  ).join('');

  const layersHtml = layers.map((l, i) => `
    <div class="layer-row">
      <span style="color:var(--text-muted);min-width:16px">${i + 1}</span>
      <span style="flex:1">${l.material}</span>
      <span style="color:var(--text-muted);font-family:var(--font-mono)">${(l.thickness * 1000).toFixed(0)}mm</span>
      <span class="layer-fn-badge ${l.function}">${l.function}</span>
    </div>
  `).join('');

  const totalThick = layers.length > 0
    ? layers.reduce((s, l) => s + parseFloat(l.thickness), 0)
    : parseFloat(computed.thickness || params.thickness || 0.2);

  document.getElementById('properties-content').innerHTML = `
    <div class="props-section">
      <div class="props-section-header" data-section="location">
        Location <span class="chevron">▼</span>
      </div>
      <div class="props-section-body" data-body="location">
        ${coordRow('startX', 'Start X', params.startCoord?.x ?? 0, el.id)}
        ${coordRow('startY', 'Start Y', params.startCoord?.y ?? 0, el.id)}
        ${coordRow('endX', 'End X', params.endCoord?.x ?? 10, el.id)}
        ${coordRow('endY', 'End Y', params.endCoord?.y ?? 0, el.id)}
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="levels">
        Levels <span class="chevron">▼</span>
      </div>
      <div class="props-section-body" data-body="levels">
        <div class="prop-row">
          <span class="prop-label">Base Level</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-base-level" data-id="${el.id}">
              ${state.levels.map(l => `<option value="${l.id}" ${l.id === el.base_level_id ? 'selected' : ''}>${l.name}</option>`).join('')}
            </select>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Top Level</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-top-level" data-id="${el.id}">
              ${state.levels.map(l => `<option value="${l.id}" ${l.id === el.top_level_id ? 'selected' : ''}>${l.name}</option>`).join('')}
            </select>
          </span>
        </div>
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="dims">
        Dimensions (computed) <span class="chevron">▼</span>
      </div>
      <div class="props-section-body" data-body="dims">
        <div class="prop-row">
          <span class="prop-label">Height</span>
          <span class="prop-value"><span class="prop-readonly" id="computed-height">${fmtM(computed.height)}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Length</span>
          <span class="prop-value"><span class="prop-readonly" id="computed-length">${fmtM(computed.length)}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Thickness</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-thickness" type="number" step="0.001" min="0.01" value="${fmtMVal(params.thickness || 0.2)}" data-id="${el.id}">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Area</span>
          <span class="prop-value"><span class="prop-readonly" id="computed-area">${fmtM2(computed.area)}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Volume</span>
          <span class="prop-value"><span class="prop-readonly" id="computed-volume">${fmtM3(computed.volume)}</span></span>
        </div>
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="layers">
        Layers <span class="chevron">▼</span>
      </div>
      <div class="props-section-body" data-body="layers">
        <div class="layers-list" id="layers-list">
          ${layersHtml || '<div style="padding:8px 0;color:var(--text-muted);font-size:11px">No layers defined</div>'}
        </div>
        <div style="padding:4px 12px 4px;font-size:11px;color:var(--text-muted)">
          Total: ${(totalThick * 1000).toFixed(0)}mm
        </div>
        <button class="layer-add-btn" id="btn-add-layer" data-id="${el.id}">+ Add Layer</button>
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="struct">
        Structural <span class="chevron">▼</span>
      </div>
      <div class="props-section-body" data-body="struct">
        <div class="prop-row">
          <span class="prop-label">Load Bearing</span>
          <span class="prop-value">
            <input type="checkbox" class="prop-checkbox" id="prop-load-bearing" ${params.loadBearing ? 'checked' : ''} data-id="${el.id}">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Phase</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-phase" data-id="${el.id}">
              <option ${params.phase === 'New Construction' ? 'selected' : ''}>New Construction</option>
              <option ${params.phase === 'Existing' ? 'selected' : ''}>Existing</option>
              <option ${params.phase === 'Demolition' ? 'selected' : ''}>Demolition</option>
            </select>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Type Name</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-type-name" data-id="${el.id}">
              ${state.wallTypes.map(t => `<option ${el.type_name === t.name ? 'selected' : ''}>${t.name}</option>`).join('')}
            </select>
          </span>
        </div>
      </div>
    </div>
    <div class="props-footer">
      <button class="btn-undo" id="btn-undo-el" data-id="${el.id}">↩ Undo</button>
      <button class="btn-delete" id="btn-delete-el" data-id="${el.id}">Delete</button>
    </div>
  `;

  bindWallPropertyEvents(el);
  bindSectionCollapse();
}

function coordRow(key, label, val, elId) {
  return `
    <div class="prop-row">
      <span class="prop-label">${label}</span>
      <span class="prop-value">
        <input class="prop-input" type="number" step="0.001" value="${parseFloat(val).toFixed(3)}"
          data-coord="${key}" data-id="${elId}" id="prop-${key}">
      </span>
    </div>`;
}

function fmtM(v) { return v != null ? `${parseFloat(v).toFixed(3)} m` : '—'; }
function fmtM2(v) { return v != null ? `${parseFloat(v).toFixed(3)} m²` : '—'; }
function fmtM3(v) { return v != null ? `${parseFloat(v).toFixed(3)} m³` : '—'; }
function fmtMVal(v) { return v != null ? parseFloat(v).toFixed(4) : '0.2000'; }

function bindWallPropertyEvents(el) {
  // Coordinate inputs
  const coordInputs = document.querySelectorAll('[data-coord]');
  coordInputs.forEach(input => {
    input?.addEventListener('input', () => {
      const key = input.dataset.coord;
      const val = parseFloat(input.value);
      if (isNaN(val)) { input.classList.add('error'); return; }
      input.classList.remove('error');

      // Optimistic update
      const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : { ...el.parameters };
      if (key === 'startX') params.startCoord = { ...params.startCoord, x: val };
      else if (key === 'startY') params.startCoord = { ...params.startCoord, y: val };
      else if (key === 'endX') params.endCoord = { ...params.endCoord, x: val };
      else if (key === 'endY') params.endCoord = { ...params.endCoord, y: val };

      const idx = state.elements.findIndex(e => e.id === el.id);
      if (idx !== -1) { state.elements[idx] = { ...state.elements[idx], parameters: params }; scheduleRebuild(); }

      debouncedPatch(el.id + key, async () => {
        try {
          setDagStatus('recalculating');
          // Loop 17.4: use offline-safe save so edits queue when disconnected
          const updated = await saveElementOfflineSafe(el.id, { parameters: params });
          const i = state.elements.findIndex(e => e.id === el.id);
          if (i !== -1) state.elements[i] = { ...updated, layers: updated.layers || [] };
          updateComputedDisplay(updated.computed);
          setDagStatus('done');
          scheduleRebuild();
        } catch (e) {
          // Offline-safe save throws only on unexpected errors; edits are queued silently
          if (!e.message?.includes('demo_readonly')) toast(e.message, 'error');
          setDagStatus('');
        }
      });
    });
  });

  // Thickness
  const thickInput = document.getElementById('prop-thickness');
  if (thickInput) {
    thickInput?.addEventListener('input', () => {
      const val = parseFloat(thickInput.value);
      if (isNaN(val) || val < 0.001) { thickInput.classList.add('error'); return; }
      thickInput.classList.remove('error');
      debouncedPatch(el.id + 'thick', async () => {
        try {
          setDagStatus('recalculating');
          const updated = await saveElementOfflineSafe(el.id, { parameters: { thickness: val } });
          const i = state.elements.findIndex(e => e.id === el.id);
          if (i !== -1) state.elements[i] = { ...updated, layers: updated.layers || [] };
          updateComputedDisplay(updated.computed);
          setDagStatus('done'); scheduleRebuild();
        } catch (e) {
          if (!e.message?.includes('demo_readonly')) toast(e.message, 'error');
          setDagStatus('');
        }
      });
    });
  }

  // Level selects
  ['prop-base-level', 'prop-top-level'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    sel?.addEventListener('change', async () => {
      const field = id === 'prop-base-level' ? 'base_level_id' : 'top_level_id';
      try {
        setDagStatus('recalculating');
        const updated = await api('PATCH', `/api/elements/${el.id}`, { [field]: sel.value });
        const i = state.elements.findIndex(e => e.id === el.id);
        if (i !== -1) state.elements[i] = { ...updated, layers: updated.layers || [] };
        updateComputedDisplay(updated.computed);
        setDagStatus('done'); scheduleRebuild();
        toast('Level binding updated', 'success');
      } catch (e) { toast(e.message, 'error'); setDagStatus(''); }
    });
  });

  // Load bearing
  const lbCheck = document.getElementById('prop-load-bearing');
  if (lbCheck) {
    lbCheck?.addEventListener('change', async () => {
      try {
        await api('PATCH', `/api/elements/${el.id}`, { parameters: { loadBearing: lbCheck.checked } });
        const i = state.elements.findIndex(e => e.id === el.id);
        if (i !== -1) { const params = { ...state.elements[i].parameters, loadBearing: lbCheck.checked }; state.elements[i] = { ...state.elements[i], parameters: params }; }
        scheduleRebuild();
      } catch (e) { toast(e.message, 'error'); }
    });
  }

  // Phase
  const phaseSel = document.getElementById('prop-phase');
  if (phaseSel) {
    phaseSel?.addEventListener('change', async () => {
      try {
        await api('PATCH', `/api/elements/${el.id}`, { parameters: { phase: phaseSel.value } });
      } catch (e) { toast(e.message, 'error'); }
    });
  }

  // Type name
  const typeNameSel = document.getElementById('prop-type-name');
  if (typeNameSel) {
    typeNameSel?.addEventListener('change', async () => {
      try {
        const wt = state.wallTypes.find(t => t.name === typeNameSel.value);
        const patchData = { type_name: typeNameSel.value };
        if (wt?.layers) patchData.layers = typeof wt.layers === 'string' ? JSON.parse(wt.layers) : wt.layers;
        const updated = await api('PATCH', `/api/elements/${el.id}`, patchData);
        const i = state.elements.findIndex(e => e.id === el.id);
        if (i !== -1) state.elements[i] = { ...updated, layers: updated.layers || [] };
        scheduleRebuild(); renderWallProperties({ ...updated, layers: updated.layers || [] });
        toast(`Type changed to ${typeNameSel.value}`, 'success');
      } catch (e) { toast(e.message, 'error'); }
    });
  }

  // Delete
  document.getElementById('btn-delete-el')?.addEventListener('click', async () => {
    if (!confirm('Delete this element?')) return;
    try {
      await api('DELETE', `/api/elements/${el.id}`);
      state.elements = state.elements.filter(e => e.id !== el.id);
      selectEntity(null, null);
      rebuildScene(); renderLevelList();
      toast('Element deleted', 'success');
    } catch (e) { toast(e.message, 'error'); }
  });

  // Undo
  document.getElementById('btn-undo-el')?.addEventListener('click', async () => {
    try {
      const updated = await api('POST', `/api/elements/${el.id}/undo`, {});
      const i = state.elements.findIndex(e => e.id === el.id);
      if (i !== -1) state.elements[i] = updated;
      rebuildScene(); renderWallProperties({ ...updated, layers: [] });
      toast('Undone', 'success');
    } catch (e) { toast(e.message, 'error'); }
  });

  // Add Layer
  document.getElementById('btn-add-layer')?.addEventListener('click', () => showAddLayerModal(el));
}

function updateComputedDisplay(computed) {
  if (!computed) return;
  const c = typeof computed === 'string' ? JSON.parse(computed) : computed;
  const setVal = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
  setVal('computed-height', fmtM(c.height));
  setVal('computed-length', fmtM(c.length));
  setVal('computed-area', fmtM2(c.area));
  setVal('computed-volume', fmtM3(c.volume));
}

// ─── COLUMN PROPERTIES ────────────────────────────────────────────────────────
function renderColumnProperties(el) {
  const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : (el.parameters || {});
  const computed = typeof el.computed === 'string' ? JSON.parse(el.computed) : (el.computed || {});
  document.getElementById('props-title').textContent = `COLUMN: ${el.type_name || 'Column'}`;

  document.getElementById('properties-content').innerHTML = `
    <div class="props-section">
      <div class="props-section-header" data-section="grid">Grid Location <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="grid">
        <div class="prop-row">
          <span class="prop-label">Host Intersect.</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-grid" type="text" value="${params.gridIntersection || 'A-1'}" data-id="${el.id}">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Base Level</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-base-level" data-id="${el.id}">
              ${state.levels.map(l => `<option value="${l.id}" ${l.id === el.base_level_id ? 'selected' : ''}>${l.name}</option>`).join('')}
            </select>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Top Level</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-top-level" data-id="${el.id}">
              ${state.levels.map(l => `<option value="${l.id}" ${l.id === el.top_level_id ? 'selected' : ''}>${l.name}</option>`).join('')}
            </select>
          </span>
        </div>
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="dims">Dimensions (computed) <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="dims">
        <div class="prop-row">
          <span class="prop-label">Height</span>
          <span class="prop-value"><span class="prop-readonly" id="computed-height">${fmtM(computed.height)}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Section</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-section" data-id="${el.id}">
              ${state.columnTypes.map(t => `<option ${el.type_name === t.name ? 'selected' : ''}>${t.name}</option>`).join('')}
            </select>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Material</span>
          <span class="prop-value"><span class="prop-readonly">${params.material || 'Structural Steel'}</span></span>
        </div>
      </div>
    </div>
    <div class="props-footer">
      <button class="btn-undo" id="btn-undo-el" data-id="${el.id}">↩ Undo</button>
      <button class="btn-delete" id="btn-delete-el" data-id="${el.id}">Delete</button>
    </div>
  `;

  // Grid intersection
  const gridInput = document.getElementById('prop-grid');
  gridInput?.addEventListener('input', () => {
    debouncedPatch(el.id + 'grid', async () => {
      try {
        const updated = await api('PATCH', `/api/elements/${el.id}`, { parameters: { gridIntersection: gridInput.value } });
        const i = state.elements.findIndex(e => e.id === el.id);
        if (i !== -1) state.elements[i] = updated;
        scheduleRebuild();
      } catch (e) { toast(e.message, 'error'); }
    });
  });

  // Level selects
  ['prop-base-level', 'prop-top-level'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    sel?.addEventListener('change', async () => {
      const field = id === 'prop-base-level' ? 'base_level_id' : 'top_level_id';
      try {
        setDagStatus('recalculating');
        const updated = await api('PATCH', `/api/elements/${el.id}`, { [field]: sel.value });
        const i = state.elements.findIndex(e => e.id === el.id);
        if (i !== -1) state.elements[i] = updated;
        document.getElementById('computed-height').textContent = fmtM(updated.computed?.height);
        setDagStatus('done'); scheduleRebuild();
      } catch (e) { toast(e.message, 'error'); setDagStatus(''); }
    });
  });

  // Section / type
  document.getElementById('prop-section')?.addEventListener('change', async (e) => {
    try {
      const ct = state.columnTypes.find(t => t.name === e.target.value);
      await api('PATCH', `/api/elements/${el.id}`, {
        type_name: e.target.value,
        parameters: { section: ct?.section || e.target.value, material: ct?.material || 'Structural Steel' }
      });
      toast('Section updated', 'success');
    } catch (err) { toast(err.message, 'error'); }
  });

  // Delete & Undo
  document.getElementById('btn-delete-el')?.addEventListener('click', async () => {
    if (!confirm('Delete this element?')) return;
    try {
      await api('DELETE', `/api/elements/${el.id}`);
      state.elements = state.elements.filter(e => e.id !== el.id);
      selectEntity(null, null); rebuildScene();
      toast('Element deleted', 'success');
    } catch (e) { toast(e.message, 'error'); }
  });
  document.getElementById('btn-undo-el')?.addEventListener('click', async () => {
    try {
      const updated = await api('POST', `/api/elements/${el.id}/undo`, {});
      const i = state.elements.findIndex(e => e.id === el.id);
      if (i !== -1) state.elements[i] = updated;
      rebuildScene(); renderColumnProperties(updated);
      toast('Undone', 'success');
    } catch (e) { toast(e.message, 'error'); }
  });

  bindSectionCollapse();
}

// ─── FAMILY PROPERTIES (Doors + Windows) ────────────────────────────────────
function renderFamilyProperties(fam) {
  const params = typeof fam.parameters === 'string' ? JSON.parse(fam.parameters) : (fam.parameters || {});
  const isDoor = fam.family_type === 'door';
  const title = `${isDoor ? 'DOOR' : 'WINDOW'}: ${fam.type_name || (isDoor ? 'Door' : 'Window')}`;
  document.getElementById('props-title').textContent = title;

  // Find host wall
  const hostWall = state.elements.find(e => e.id === fam.host_wall_id);
  const hostWallName = hostWall ? hostWall.type_name : 'Unknown';
  const hostWallId = fam.host_wall_id;

  // Position display
  const posInfo = getFamilyWorldTransform(fam);
  const posStr = posInfo
    ? `X: ${posInfo.position.x.toFixed(2)}, Z: ${posInfo.position.z.toFixed(2)}`
    : 'N/A';

  // Type selector
  const typeOptions = isDoor
    ? state.doorTypes.map(t => `<option value="${t.id}" ${fam.type_name === t.name ? 'selected' : ''}>${t.name}</option>`).join('')
    : state.windowTypes.map(t => `<option value="${t.id}" ${fam.type_name === t.name ? 'selected' : ''}>${t.name}</option>`).join('');

  document.getElementById('properties-content').innerHTML = `
    <div class="props-section">
      <div class="props-section-header" data-section="fam-host">Host Wall <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="fam-host">
        <div class="prop-row">
          <span class="prop-label">Host Wall</span>
          <span class="prop-value"><span class="prop-readonly">${escHtml(hostWallName)}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Position U</span>
          <span class="prop-value">
            <input class="prop-input" type="number" step="0.01" min="0.01" max="0.99"
              value="${parseFloat(fam.host_face_u || 0.5).toFixed(2)}"
              id="prop-fam-u" data-id="${fam.id}">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">World Pos</span>
          <span class="prop-value"><span class="prop-readonly">${posStr}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Mark</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-fam-mark" type="text" value="${escHtml(fam.mark || '')}" data-id="${fam.id}">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Type</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-fam-type" data-id="${fam.id}">
              ${typeOptions}
            </select>
          </span>
        </div>
      </div>
    </div>
    ${isDoor ? `
    <div class="props-section">
      <div class="props-section-header" data-section="fam-door">Door Properties <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="fam-door">
        <div class="prop-row">
          <span class="prop-label">Width</span>
          <span class="prop-value"><span class="prop-readonly">${parseFloat(params.width || 0.914).toFixed(3)} m</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Height</span>
          <span class="prop-value"><span class="prop-readonly">${parseFloat(params.height || 2.032).toFixed(3)} m</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Hand</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-fam-hand" data-id="${fam.id}">
              <option value="left" ${params.hand === 'left' ? 'selected' : ''}>Left Swing</option>
              <option value="right" ${params.hand === 'right' ? 'selected' : ''}>Right Swing</option>
            </select>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Material</span>
          <span class="prop-value"><span class="prop-readonly">${escHtml(params.material || 'Wood Flush')}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Fire Rating</span>
          <span class="prop-value"><span class="prop-readonly">${escHtml(params.fireRating || 'None')}</span></span>
        </div>
      </div>
    </div>
    ` : `
    <div class="props-section">
      <div class="props-section-header" data-section="fam-win">Window Properties <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="fam-win">
        <div class="prop-row">
          <span class="prop-label">Width</span>
          <span class="prop-value"><span class="prop-readonly">${parseFloat(params.width || 1.219).toFixed(3)} m</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Height</span>
          <span class="prop-value"><span class="prop-readonly">${parseFloat(params.height || 1.219).toFixed(3)} m</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Sill Height</span>
          <span class="prop-value"><span class="prop-readonly">${parseFloat(params.sillHeight || 0.9).toFixed(3)} m</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Type</span>
          <span class="prop-value"><span class="prop-readonly">${escHtml(params.type || 'double_hung')}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Glazing</span>
          <span class="prop-value"><span class="prop-readonly">${escHtml(params.glazing || 'double')}</span></span>
        </div>
      </div>
    </div>
    `}
    <div class="props-footer">
      <button class="btn-undo" id="btn-undo-fam" data-id="${fam.id}">↩ Undo</button>
      <button class="btn-delete" id="btn-delete-fam" data-id="${fam.id}">Delete</button>
    </div>
  `;

  // Bind family property events
  document.getElementById('prop-fam-u')?.addEventListener('input', () => {
    const val = parseFloat(document.getElementById('prop-fam-u').value);
    if (isNaN(val) || val < 0.01 || val > 0.99) return;
    debouncedPatch(fam.id + 'u', async () => {
      try {
        const updated = await api('PATCH', `/api/families/${fam.id}`, { host_face_u: val });
        const idx = state.familyInstances.findIndex(f => f.id === fam.id);
        if (idx !== -1) state.familyInstances[idx] = updated;
        scheduleRebuild();
      } catch (e) { toast(e.message, 'error'); }
    });
  });

  document.getElementById('prop-fam-mark')?.addEventListener('input', () => {
    debouncedPatch(fam.id + 'mark', async () => {
      try {
        const updated = await api('PATCH', `/api/families/${fam.id}`, { mark: document.getElementById('prop-fam-mark').value });
        const idx = state.familyInstances.findIndex(f => f.id === fam.id);
        if (idx !== -1) state.familyInstances[idx] = updated;
      } catch (e) { toast(e.message, 'error'); }
    });
  });

  document.getElementById('prop-fam-type')?.addEventListener('change', async (e) => {
    try {
      const isDoor2 = fam.family_type === 'door';
      const types = isDoor2 ? state.doorTypes : state.windowTypes;
      const selectedType = types.find(t => t.id === e.target.value);
      if (!selectedType) return;

      const patchData = {
        type_name: selectedType.name,
        parameters: isDoor2
          ? { width: parseFloat(selectedType.width), height: parseFloat(selectedType.height), sillHeight: 0, hand: 'left', type: selectedType.type, material: selectedType.material, fireRating: selectedType.fire_rating || '' }
          : { width: parseFloat(selectedType.width), height: parseFloat(selectedType.height), sillHeight: parseFloat(selectedType.sill_height), type: selectedType.type, glazing: selectedType.glazing, material: selectedType.material, headHeight: parseFloat(selectedType.sill_height) + parseFloat(selectedType.height) }
      };
      const updated = await api('PATCH', `/api/families/${fam.id}`, patchData);
      const idx = state.familyInstances.findIndex(f => f.id === fam.id);
      if (idx !== -1) state.familyInstances[idx] = updated;
      scheduleRebuild();
      renderFamilyProperties(updated);
      toast(`${isDoor2 ? 'Door' : 'Window'} type changed`, 'success');
    } catch (err) { toast(err.message, 'error'); }
  });

  if (isDoor) {
    document.getElementById('prop-fam-hand')?.addEventListener('change', async (e) => {
      try {
        const mergedParams = { ...params, hand: e.target.value };
        const updated = await api('PATCH', `/api/families/${fam.id}`, { parameters: mergedParams });
        const idx = state.familyInstances.findIndex(f => f.id === fam.id);
        if (idx !== -1) state.familyInstances[idx] = updated;
        rebuildScene();
      } catch (err) { toast(err.message, 'error'); }
    });
  }

  document.getElementById('btn-delete-fam')?.addEventListener('click', async () => {
    if (!confirm('Delete this ' + fam.family_type + '?')) return;
    try {
      await api('DELETE', `/api/families/${fam.id}`);
      state.familyInstances = state.familyInstances.filter(f => f.id !== fam.id);
      selectEntity(null, null);
      rebuildScene();
      toast(escHtml(fam.family_type) + ' deleted', 'success');
    } catch (e) { toast(e.message, 'error'); }
  });

  document.getElementById('btn-undo-fam')?.addEventListener('click', async () => {
    toast('Undo not available for family instances', 'info');
  });

  bindSectionCollapse();
}

// ─── ROOF PROPERTIES (Phase 3.5) ─────────────────────────────────────────────
function renderRoofProperties(el) {
  const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : (el.parameters || {});
  const computed = typeof el.computed === 'string' ? JSON.parse(el.computed) : (el.computed || {});
  const layers = el.layers || [];
  const roofStyle = params.roof_style || 'flat';
  const title = `ROOF: ${el.type_name || roofStyle.charAt(0).toUpperCase() + roofStyle.slice(1) + ' Roof'}`;
  document.getElementById('props-title').textContent = title;

  const totalThick = layers.length > 0
    ? layers.reduce((s, l) => s + parseFloat(l.thickness), 0)
    : parseFloat(params.thickness || 0.2);

  const layersHtml = layers.map((l, i) => `
    <div class="layer-row">
      <span style="color:var(--text-muted);min-width:16px">${i + 1}</span>
      <span style="flex:1">${l.material}</span>
      <span style="color:var(--text-muted);font-family:var(--font-mono)">${(parseFloat(l.thickness) * 1000).toFixed(0)}mm</span>
      <span class="layer-fn-badge ${l.function}">${l.function}</span>
    </div>
  `).join('');

  document.getElementById('properties-content').innerHTML = `
    <div class="props-section">
      <div class="props-section-header" data-section="type">Type <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="type">
        <div class="prop-row">
          <span class="prop-label">Style</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-roof-style" data-id="${el.id}">
              ${state.roofTypes.map(t => `<option value="${t.roof_style}" ${t.roof_style === roofStyle ? 'selected' : ''}>${t.name}</option>`).join('')}
              <option value="flat" ${roofStyle === 'flat' && !state.roofTypes.find(t => t.roof_style === 'flat') ? 'selected' : ''}>Flat</option>
              <option value="gable" ${roofStyle === 'gable' ? 'selected' : ''}>Gable</option>
              <option value="shed" ${roofStyle === 'shed' ? 'selected' : ''}>Shed</option>
              <option value="hip" ${roofStyle === 'hip' ? 'selected' : ''}>Hip</option>
              <option value="curtain" ${roofStyle === 'curtain' ? 'selected' : ''}>Curtain Wall</option>
            </select>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Type Name</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-roof-type-name" data-id="${el.id}">
              ${state.roofTypes.map(t => `<option ${el.type_name === t.name ? 'selected' : ''}>${t.name}</option>`).join('')}
            </select>
          </span>
        </div>
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="level">Level <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="level">
        <div class="prop-row">
          <span class="prop-label">Base Level</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-base-level" data-id="${el.id}">
              ${state.levels.map(l => `<option value="${l.id}" ${l.id === el.base_level_id ? 'selected' : ''}>${l.name} (${parseFloat(l.elevation).toFixed(3)}m)</option>`).join('')}
            </select>
          </span>
        </div>
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="dims">Dimensions (computed) <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="dims">
        <div class="prop-row">
          <span class="prop-label">Height / Rise</span>
          <span class="prop-value"><span class="prop-readonly">${fmtM(computed.height)}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Area</span>
          <span class="prop-value"><span class="prop-readonly" id="computed-area">${fmtM2(computed.area)}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Thickness</span>
          <span class="prop-value"><span class="prop-readonly">${(totalThick * 1000).toFixed(0)}mm</span></span>
        </div>
        ${['gable', 'shed', 'hip'].includes(roofStyle) ? `
        <div class="prop-row">
          <span class="prop-label">Pitch (rise:run)</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-pitch" type="text" value="${params.pitch_ratio || '7:12'}" data-id="${el.id}">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Span (m)</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-span" type="number" step="0.1" value="${params.span || 10}" data-id="${el.id}">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Eave Height (m)</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-eave-height" type="number" step="0.01" value="${params.eave_height || 0}" data-id="${el.id}">
          </span>
        </div>` : ''}
        ${roofStyle === 'flat' ? `
        <div class="prop-row">
          <span class="prop-label">Width (m)</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-width" type="number" step="0.1" value="${params.width || 10}" data-id="${el.id}">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Depth (m)</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-depth" type="number" step="0.1" value="${params.depth || 8}" data-id="${el.id}">
          </span>
        </div>` : ''}
        ${roofStyle === 'curtain' ? `
        <div class="prop-row">
          <span class="prop-label">Grid U</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-grid-u" type="number" min="1" max="20" value="${params.grid_u_count || 4}" data-id="${el.id}">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Grid V</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-grid-v" type="number" min="1" max="20" value="${params.grid_v_count || 3}" data-id="${el.id}">
          </span>
        </div>` : ''}
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="layers">Layers <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="layers">
        <div class="layers-list" id="layers-list">
          ${layersHtml || '<div style="padding:8px 0;color:var(--text-muted);font-size:11px">No layers defined</div>'}
        </div>
        <div style="padding:4px 12px 4px;font-size:11px;color:var(--text-muted)">
          Total: ${(totalThick * 1000).toFixed(0)}mm
        </div>
        <button class="layer-add-btn" id="btn-add-layer" data-id="${el.id}">+ Add Layer</button>
      </div>
    </div>
    <div class="props-footer">
      <button class="btn-undo" id="btn-undo-el" data-id="${el.id}">↩ Undo</button>
      <button class="btn-delete" id="btn-delete-el" data-id="${el.id}">Delete</button>
    </div>
  `;

  bindRoofPropertyEvents(el);
  bindSectionCollapse();
}

function bindRoofPropertyEvents(el) {
  // Style change
  const styleSel = document.getElementById('prop-roof-style');
  styleSel?.addEventListener('change', async () => {
    try {
      const patchParams = { roof_style: styleSel.value };
      const updated = await api('PATCH', `/api/elements/${el.id}`, { parameters: patchParams });
      const i = state.elements.findIndex(e => e.id === el.id);
      if (i !== -1) state.elements[i] = { ...updated, layers: updated.layers || [] };
      rebuildScene();
      renderRoofProperties({ ...updated, layers: updated.layers || [] });
      toast('Roof style updated', 'success');
    } catch (e) { toast(e.message, 'error'); }
  });

  // Level select
  const baseSel = document.getElementById('prop-base-level');
  baseSel?.addEventListener('change', async () => {
    try {
      setDagStatus('recalculating');
      const updated = await api('PATCH', `/api/elements/${el.id}`, { base_level_id: baseSel.value });
      const i = state.elements.findIndex(e => e.id === el.id);
      if (i !== -1) state.elements[i] = { ...updated, layers: updated.layers || [] };
      document.getElementById('computed-area') && (document.getElementById('computed-area').textContent = fmtM2(updated.computed?.area));
      setDagStatus('done'); scheduleRebuild();
    } catch (e) { toast(e.message, 'error'); setDagStatus(''); }
  });

  // Type name
  const typeNameSel = document.getElementById('prop-roof-type-name');
  typeNameSel?.addEventListener('change', async () => {
    try {
      const rt = state.roofTypes.find(t => t.name === typeNameSel.value);
      const patchParams = { roof_style: rt?.roof_style || 'flat', pitch_ratio: rt?.pitch_ratio || '0' };
      const patchData = { type_name: typeNameSel.value, parameters: patchParams };
      if (rt?.layers) patchData.layers = typeof rt.layers === 'string' ? JSON.parse(rt.layers) : rt.layers;
      const updated = await api('PATCH', `/api/elements/${el.id}`, patchData);
      const i = state.elements.findIndex(e => e.id === el.id);
      if (i !== -1) state.elements[i] = { ...updated, layers: updated.layers || [] };
      scheduleRebuild();
      renderRoofProperties({ ...updated, layers: updated.layers || [] });
      toast(`Type changed to ${typeNameSel.value}`, 'success');
    } catch (e) { toast(e.message, 'error'); }
  });

  // Numeric params: pitch, span, eave_height, width, depth, grid_u/v
  ['pitch', 'span', 'eave_height', 'width', 'depth', 'grid_u', 'grid_v'].forEach(key => {
    const el_ = document.getElementById(`prop-${key.replace('_', '-')}`);
    if (!el_) return;
    el_?.addEventListener('input', () => {
      const paramMap = { 'prop-pitch': 'pitch_ratio', 'prop-span': 'span', 'prop-eave-height': 'eave_height', 'prop-width': 'width', 'prop-depth': 'depth', 'prop-grid-u': 'grid_u_count', 'prop-grid-v': 'grid_v_count' };
      const paramKey = paramMap[el_.id] || key;
      const val = isNaN(parseFloat(el_.value)) ? el_.value : parseFloat(el_.value);
      const params = { ...(typeof el.parameters === 'string' ? JSON.parse(el.parameters) : el.parameters || {}), [paramKey]: val };
      debouncedPatch(el.id + key, async () => {
        try {
          const updated = await api('PATCH', `/api/elements/${el.id}`, { parameters: params });
          const i = state.elements.findIndex(e => e.id === el.id);
          if (i !== -1) state.elements[i] = { ...updated, layers: updated.layers || [] };
          scheduleRebuild();
        } catch (e) { toast(e.message, 'error'); }
      });
    });
  });

  // Delete
  document.getElementById('btn-delete-el')?.addEventListener('click', async () => {
    if (!confirm('Delete this roof?')) return;
    try {
      await api('DELETE', `/api/elements/${el.id}`);
      state.elements = state.elements.filter(e => e.id !== el.id);
      selectEntity(null, null);
      rebuildScene(); renderLevelList();
      toast('Roof deleted', 'success');
    } catch (e) { toast(e.message, 'error'); }
  });

  // Undo
  document.getElementById('btn-undo-el')?.addEventListener('click', async () => {
    try {
      const updated = await api('POST', `/api/elements/${el.id}/undo`, {});
      const i = state.elements.findIndex(e => e.id === el.id);
      if (i !== -1) state.elements[i] = updated;
      rebuildScene(); renderRoofProperties({ ...updated, layers: [] });
      toast('Undone', 'success');
    } catch (e) { toast(e.message, 'error'); }
  });

  // Add Layer
  document.getElementById('btn-add-layer')?.addEventListener('click', () => showAddLayerModal(el));
}

// ─── STAIR PROPERTIES (Phase 3.4) ─────────────────────────────────────────────
function renderStairProperties(stair) {
  const stairTypes = state.stairTypes || [];
  const levels = state.levels || [];
  document.getElementById('props-title').textContent = `STAIR: ${stair.name || 'Main Stair'}`;

  const totalRise = parseFloat(stair.total_rise || 3.0);
  const risers = parseInt(stair.number_of_risers, 10) || 16;
  const treads = parseInt(stair.number_of_treads, 10) || (risers - 1);
  const riserH = parseFloat(stair.riser_height || 0.1875);
  const treadD = parseFloat(stair.tread_depth || 0.275);
  const going = parseFloat(stair.going || 0);
  const slope = parseFloat(stair.slope_degrees || 30);
  const width = parseFloat(stair.width || 1.0);
  const config = stair.stair_type || stair.configuration || 'straight';
  const material = stair.material || 'Concrete';

  document.getElementById('properties-content').innerHTML = `
    <div class="props-section">
      <div class="props-section-header" data-section="stair-info">Identity <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="stair-info">
        <div class="prop-row">
          <span class="prop-label">Name</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-stair-name" data-id="${stair.id}" value="${stair.name || ''}" placeholder="Main Stair">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Configuration</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-stair-config" data-id="${stair.id}">
              <option value="straight"  ${config==='straight'  ?'selected':''}>Straight</option>
              <option value="l_shaped"  ${config==='l_shaped'  ?'selected':''}>L-Shaped</option>
              <option value="u_shaped"  ${config==='u_shaped'  ?'selected':''}>U-Shaped</option>
              <option value="spiral"    ${config==='spiral'    ?'selected':''}>Spiral</option>
              <option value="circular"  ${config==='circular'  ?'selected':''}>Circular</option>
            </select>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Material</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-stair-material" data-id="${stair.id}">
              <option value="Concrete"    ${material==='Concrete'   ?'selected':''}>Concrete</option>
              <option value="Steel"      ${material==='Steel'     ?'selected':''}>Steel</option>
              <option value="Wood"       ${material==='Wood'      ?'selected':''}>Wood</option>
              <option value="Stone"      ${material==='Stone'     ?'selected':''}>Stone</option>
            </select>
          </span>
        </div>
      </div>
    </div>

    <div class="props-section">
      <div class="props-section-header" data-section="stair-levels">Level Binding <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="stair-levels">
        <div class="prop-row">
          <span class="prop-label">Base Level</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-stair-base" data-id="${stair.id}">
              ${levels.map(l => `<option value="${l.id}" ${stair.base_level_id == l.id ? 'selected' : ''}>${l.name} (${parseFloat(l.elevation).toFixed(3)}m)</option>`).join('')}
            </select>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Top Level</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-stair-top" data-id="${stair.id}">
              ${levels.map(l => `<option value="${l.id}" ${stair.top_level_id == l.id ? 'selected' : ''}>${l.name} (${parseFloat(l.elevation).toFixed(3)}m)</option>`).join('')}
            </select>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Total Rise</span>
          <span class="prop-value"><span class="prop-readonly">${(totalRise * 1000).toFixed(0)} mm</span></span>
        </div>
      </div>
    </div>

    <div class="props-section">
      <div class="props-section-header" data-section="stair-dims">Dimensions <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="stair-dims">
        <div class="prop-row">
          <span class="prop-label">Number of Risers</span>
          <span class="prop-value">
            <input class="prop-input" type="number" id="prop-stair-risers" data-id="${stair.id}"
              value="${risers}" min="2" max="50">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Riser Height</span>
          <span class="prop-value"><span class="prop-readonly" id="prop-stair-riser-h">${(riserH * 1000).toFixed(1)} mm</span>
            <span style="color:var(--text-muted);font-size:10px;margin-left:4px">(auto)</span>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Number of Treads</span>
          <span class="prop-value"><span class="prop-readonly">${treads}</span>
            <span style="color:var(--text-muted);font-size:10px;margin-left:4px">(auto: risers - 1)</span>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Tread Depth (m)</span>
          <span class="prop-value">
            <input class="prop-input" type="number" id="prop-stair-tread" data-id="${stair.id}"
              value="${treadD}" step="0.01" min="0.15" max="0.4">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Width (m)</span>
          <span class="prop-value">
            <input class="prop-input" type="number" id="prop-stair-width" data-id="${stair.id}"
              value="${width}" step="0.05" min="0.6" max="2.0">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Going</span>
          <span class="prop-value"><span class="prop-readonly">${(going * 1000).toFixed(0)} mm</span>
            <span style="color:var(--text-muted);font-size:10px;margin-left:4px">(auto)</span>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Slope</span>
          <span class="prop-value"><span class="prop-readonly">${slope.toFixed(1)}°</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">IBC Limit</span>
          <span class="prop-value"><span class="prop-readonly" style="color:${riserH > 0.198 ? '#e74c3c' : '#2ecc71'}">Riser ≤ 198mm · Tread ≥ 254mm</span></span>
        </div>
      </div>
    </div>

    <div class="props-section">
      <div class="props-section-header" data-section="stair-geo">Position <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="stair-geo">
        <div class="prop-row">
          <span class="prop-label">X (m)</span>
          <span class="prop-value">
            <input class="prop-input" type="number" id="prop-stair-pos-x" data-id="${stair.id}"
              value="${parseFloat(stair.position_x || 0)}" step="0.1">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Y (m)</span>
          <span class="prop-value">
            <input class="prop-input" type="number" id="prop-stair-pos-y" data-id="${stair.id}"
              value="${parseFloat(stair.position_y || 0)}" step="0.1">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Rotation (°)</span>
          <span class="prop-value">
            <input class="prop-input" type="number" id="prop-stair-rot" data-id="${stair.id}"
              value="${parseFloat(stair.rotation_degrees || 0)}" step="15">
          </span>
        </div>
      </div>
    </div>

    <div class="props-section">
      <div class="props-section-header" data-section="stair-railings">Railings <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="stair-railings">
        <div class="prop-row">
          <span class="prop-label">Attached</span>
          <span class="prop-value">
            <span class="prop-readonly">${state.railings.filter(r => r.host_stair_id === stair.id).length} railings</span>
            <button class="prop-btn" id="prop-add-railing" data-id="${stair.id}"
              style="margin-left:8px;font-size:11px;padding:2px 8px;background:var(--accent);color:#fff;border:none;border-radius:4px;cursor:pointer">
              + Add Railing
            </button>
          </span>
        </div>
        <div id="stair-railings-list">
          ${state.railings.filter(r => r.host_stair_id === stair.id).map(r => `
            <div class="prop-row" style="cursor:pointer" onclick="selectEntity(${r.id},'railing')">
              <span style="color:var(--text-muted);font-size:11px">${r.railing_type || 'baluster'}</span>
              <span class="prop-value">${r.name || 'Handrail'}</span>
            </div>
          `).join('')}
        </div>
      </div>
    </div>

    <div class="props-section">
      <div class="prop-row">
        <button class="prop-btn" id="prop-delete-stair" data-id="${stair.id}"
          style="background:#e74c3c;color:#fff;border:none;padding:6px 12px;border-radius:4px;cursor:pointer;width:100%;font-size:12px">
          Delete Stair
        </button>
      </div>
    </div>
  `;

  // Wire up live editing
  const patch = (field, val) => {
    debouncedPatch(`stair-${stair.id}`, async () => {
      const res = await api('PATCH', `/api/stairs/${stair.id}`, { [field]: val });
      const idx = state.stairs.findIndex(s => s.id === stair.id);
      if (idx !== -1) state.stairs[idx] = res;
      scheduleRebuild();
    });
  };

  document.getElementById('prop-stair-name')?.addEventListener('input', e => patch('name', e.target.value));
  document.getElementById('prop-stair-config')?.addEventListener('change', e => patch('stair_type', e.target.value));
  document.getElementById('prop-stair-material')?.addEventListener('change', e => patch('material', e.target.value));
  document.getElementById('prop-stair-base')?.addEventListener('change', e => patch('base_level_id', parseInt(e.target.value, 10)));
  document.getElementById('prop-stair-top')?.addEventListener('change', e => patch('top_level_id', parseInt(e.target.value, 10)));
  document.getElementById('prop-stair-risers')?.addEventListener('change', e => {
    patch('number_of_risers', parseInt(e.target.value, 10));
    document.getElementById('prop-stair-riser-h').textContent = ((totalRise / parseInt(e.target.value, 10)) * 1000).toFixed(1) + ' mm';
  });
  document.getElementById('prop-stair-tread')?.addEventListener('change', e => patch('tread_depth', parseFloat(e.target.value)));
  document.getElementById('prop-stair-width')?.addEventListener('change', e => patch('width', parseFloat(e.target.value)));
  document.getElementById('prop-stair-pos-x')?.addEventListener('change', e => patch('position_x', parseFloat(e.target.value)));
  document.getElementById('prop-stair-pos-y')?.addEventListener('change', e => patch('position_y', parseFloat(e.target.value)));
  document.getElementById('prop-stair-rot')?.addEventListener('change', e => patch('rotation_degrees', parseFloat(e.target.value)));

  document.getElementById('prop-delete-stair')?.addEventListener('click', async () => {
    if (!confirm(`Delete "${stair.name || 'Main Stair'}"?`)) return;
    await api('DELETE', `/api/stairs/${stair.id}`);
    state.stairs = state.stairs.filter(s => s.id !== stair.id);
    state.railings = state.railings.filter(r => r.host_stair_id !== stair.id);
    selectEntity(null, null);
    rebuildScene();
    toast('Stair deleted', 'info');
  });

  document.getElementById('prop-add-railing')?.addEventListener('click', async () => {
    const railing = await api('POST', '/api/railings', {
      project_id: window.currentProjectId || 1,
      host_stair_id: stair.id,
      name: 'Handrail',
      railing_type: 'baluster',
      height: 0.9,
      side: 'left',
      material: 'Aluminum',
    });
    state.railings.push(railing);
    renderStairProperties(stair);
    selectEntity(railing.id, 'railing');
    rebuildScene();
    toast('Railing added', 'success');
  });
}

// ─── RAILING PROPERTIES (Phase 3.4) ────────────────────────────────────────────
function renderRailingProperties(railing) {
  const stair = state.stairs.find(s => s.id === railing.host_stair_id);
  document.getElementById('props-title').textContent = `RAILING: ${railing.name || 'Handrail'}`;

  const height = parseFloat(railing.height || 0.9);
  const railType = railing.railing_type || 'baluster';
  const side = railing.side || 'left';
  const material = railing.material || 'Aluminum';
  const glassFinish = railing.glass_finish || 'clear';

  document.getElementById('properties-content').innerHTML = `
    <div class="props-section">
      <div class="props-section-header" data-section="rail-info">Identity <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="rail-info">
        <div class="prop-row">
          <span class="prop-label">Name</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-rail-name" data-id="${railing.id}" value="${railing.name || ''}">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Host Stair</span>
          <span class="prop-value"><span class="prop-readonly">${stair?.name || '—'}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Type</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-rail-type" data-id="${railing.id}">
              <option value="baluster"   ${railType==='baluster'  ?'selected':''}>Baluster (Posts)</option>
              <option value="glass"      ${railType==='glass'     ?'selected':''}>Glass Panel</option>
              <option value="handrail"  ${railType==='handrail'  ?'selected':''}>Wall Handrail</option>
              <option value="monolithic" ${railType==='monolithic'?'selected':''}>Monolithic Wall</option>
            </select>
          </span>
        </div>
      </div>
    </div>

    <div class="props-section">
      <div class="props-section-header" data-section="rail-dims">Geometry <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="rail-dims">
        <div class="prop-row">
          <span class="prop-label">Height (m)</span>
          <span class="prop-value">
            <input class="prop-input" type="number" id="prop-rail-height" data-id="${railing.id}"
              value="${height}" step="0.01" min="0.5" max="1.5">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">IBC Height</span>
          <span class="prop-value">
            <span class="prop-readonly" style="color:${height >= 0.86 ? '#2ecc71' : '#e74c3c'}">
              IBC 1011.5 requires ≥ 0.86m
            </span>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Side</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-rail-side" data-id="${railing.id}">
              <option value="left"  ${side==='left'  ?'selected':''}>Left</option>
              <option value="right" ${side==='right' ?'selected':''}>Right</option>
              <option value="both"  ${side==='both'  ?'selected':''}>Both</option>
            </select>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Baluster Spacing</span>
          <span class="prop-value">
            <input class="prop-input" type="number" id="prop-rail-bs" data-id="${railing.id}"
              value="${parseFloat(railing.baluster_spacing || 0.11)}" step="0.005" min="0.05" max="0.2">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Glass Finish</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-rail-glass" data-id="${railing.id}" ${railType !== 'glass' ? 'disabled' : ''}>
              <option value="clear"   ${glassFinish==='clear'  ?'selected':''}>Clear</option>
              <option value="frosted" ${glassFinish==='frosted'?'selected':''}>Frosted</option>
              <option value="tinted"  ${glassFinish==='tinted' ?'selected':''}>Tinted</option>
            </select>
          </span>
        </div>
      </div>
    </div>

    <div class="props-section">
      <div class="props-section-header" data-section="rail-mat">Material <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="rail-mat">
        <div class="prop-row">
          <span class="prop-label">Material</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-rail-material" data-id="${railing.id}">
              <option value="Aluminum"      ${material==='Aluminum'     ?'selected':''}>Aluminum</option>
              <option value="Stainless"     ${material==='Stainless'    ?'selected':''}>Stainless Steel</option>
              <option value="Wood"          ${material==='Wood'         ?'selected':''}>Wood</option>
              <option value="Glass"         ${material==='Glass'        ?'selected':''}>Tempered Glass</option>
              <option value="Concrete"      ${material==='Concrete'     ?'selected':''}>Concrete</option>
            </select>
          </span>
        </div>
      </div>
    </div>

    <div class="props-section">
      <div class="prop-row">
        <button class="prop-btn" id="prop-delete-railing" data-id="${railing.id}"
          style="background:#e74c3c;color:#fff;border:none;padding:6px 12px;border-radius:4px;cursor:pointer;width:100%;font-size:12px">
          Delete Railing
        </button>
      </div>
    </div>
  `;

  const patch = (field, val) => {
    debouncedPatch(`railing-${railing.id}`, async () => {
      const res = await api('PATCH', `/api/railings/${railing.id}`, { [field]: val });
      const idx = state.railings.findIndex(r => r.id === railing.id);
      if (idx !== -1) state.railings[idx] = res;
      scheduleRebuild();
    });
  };

  document.getElementById('prop-rail-name')?.addEventListener('input', e => patch('name', e.target.value));
  document.getElementById('prop-rail-type')?.addEventListener('change', e => patch('railing_type', e.target.value));
  document.getElementById('prop-rail-height')?.addEventListener('change', e => patch('height', parseFloat(e.target.value)));
  document.getElementById('prop-rail-side')?.addEventListener('change', e => patch('side', e.target.value));
  document.getElementById('prop-rail-bs')?.addEventListener('change', e => patch('baluster_spacing', parseFloat(e.target.value)));
  document.getElementById('prop-rail-glass')?.addEventListener('change', e => patch('glass_finish', e.target.value));
  document.getElementById('prop-rail-material')?.addEventListener('change', e => patch('material', e.target.value));

  document.getElementById('prop-delete-railing')?.addEventListener('click', async () => {
    await api('DELETE', `/api/railings/${railing.id}`);
    state.railings = state.railings.filter(r => r.id !== railing.id);
    selectEntity(null, null);
    rebuildScene();
    toast('Railing deleted', 'info');
  });
}

// ─── Phase 3.3: Grid Properties ──────────────────────────────────────────────
function renderGridProperties(grid) {
  document.getElementById('props-title').textContent = `GRID: ${grid.name || 'Structural Grid'}`;
  const lines = grid.lines || [];
  const xLines = lines.filter(l => l.axis === 'x');
  const zLines = lines.filter(l => l.axis === 'z');

  document.getElementById('properties-content').innerHTML = `
    <div class="props-section">
      <div class="props-section-header" data-section="grid-info">Identity <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="grid-info">
        <div class="prop-row">
          <span class="prop-label">Name</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-grid-name" data-id="${grid.id}" value="${grid.name || ''}">
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Type</span>
          <span class="prop-value">
            <select class="prop-select" id="prop-grid-type" data-id="${grid.id}">
              <option value="structural" ${grid.system_type==='structural'?'selected':''}>Structural</option>
              <option value="architectural" ${grid.system_type==='architectural'?'selected':''}>Architectural</option>
            </select>
          </span>
        </div>
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="grid-geom">Geometry <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="grid-geom">
        <div class="prop-row">
          <span class="prop-label">Origin X</span>
          <span class="prop-value"><span class="prop-readonly">${parseFloat(grid.origin_x || 0).toFixed(2)} m</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Origin Z</span>
          <span class="prop-value"><span class="prop-readonly">${parseFloat(grid.origin_z || 0).toFixed(2)} m</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">X Spacing</span>
          <span class="prop-value"><span class="prop-readonly">${parseFloat(grid.spacing_x || 5).toFixed(2)} m</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Z Spacing</span>
          <span class="prop-value"><span class="prop-readonly">${parseFloat(grid.spacing_z || 5).toFixed(2)} m</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">X Lines</span>
          <span class="prop-value"><span class="prop-readonly">${xLines.map(l=>l.label).join(', ') || '—'}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Z Lines</span>
          <span class="prop-value"><span class="prop-readonly">${zLines.map(l=>l.label).join(', ') || '—'}</span></span>
        </div>
      </div>
    </div>
    <div class="props-section">
      <div class="prop-row">
        <button class="prop-btn" id="prop-delete-grid" data-id="${grid.id}"
          style="background:#e74c3c;color:#fff;border:none;padding:6px 12px;border-radius:4px;cursor:pointer;width:100%;font-size:12px">
          Delete Grid
        </button>
      </div>
    </div>
  `;

  const patch = (field, val) => {
    debouncedPatch(`grid-${grid.id}`, async () => {
      const res = await api('PATCH', `/api/grids/${grid.id}`, { [field]: val });
      const idx = state.grids.findIndex(g => g.id === grid.id);
      if (idx !== -1) state.grids[idx] = res;
      scheduleRebuild();
    });
  };

  document.getElementById('prop-grid-name')?.addEventListener('input', e => patch('name', e.target.value));
  document.getElementById('prop-grid-type')?.addEventListener('change', e => patch('system_type', e.target.value));
  document.getElementById('prop-grid-ox')?.addEventListener('change', e => patch('origin_x', parseFloat(e.target.value)));
  document.getElementById('prop-grid-oz')?.addEventListener('change', e => patch('origin_z', parseFloat(e.target.value)));
  document.getElementById('prop-grid-sp-x')?.addEventListener('change', e => patch('spacing_x', parseFloat(e.target.value)));
  document.getElementById('prop-grid-sp-z')?.addEventListener('change', e => patch('spacing_z', parseFloat(e.target.value)));

  document.getElementById('prop-delete-grid')?.addEventListener('click', async () => {
    await api('DELETE', `/api/grids/${grid.id}`);
    state.grids = state.grids.filter(g => g.id !== grid.id);
    selectEntity(null, null);
    rebuildScene();
    toast('Grid deleted', 'info');
  });
}

// ─── Phase 3.3: Room Properties ───────────────────────────────────────────────
function renderRoomProperties(room) {
  document.getElementById('props-title').textContent = `ROOM: ${room.name || room.number || 'Room'}`;
  const level = state.levels.find(l => l.id === room.level_id);

  document.getElementById('properties-content').innerHTML = `
    <div class="props-section">
      <div class="props-section-header" data-section="room-info">Identity <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="room-info">
        <div class="prop-row"><span class="prop-label">Number</span><span class="prop-value"><input class="prop-input" id="prop-room-number" data-id="${room.id}" value="${room.number || ''}"></span></div>
        <div class="prop-row"><span class="prop-label">Name</span><span class="prop-value"><input class="prop-input" id="prop-room-name" data-id="${room.id}" value="${room.name || ''}"></span></div>
        <div class="prop-row">
          <span class="prop-label">Level</span>
          <span class="prop-value"><span class="prop-readonly">${level?.name || '—'}</span></span>
        </div>
        <div class="prop-row">
          <span class="prop-label">Department</span>
          <span class="prop-value">
            <input class="prop-input" id="prop-room-dept" data-id="${room.id}" value="${room.department || ''}">
          </span>
        </div>
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="room-area" style="color:#34d399">Computed <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="room-area">
        <div class="prop-row">
          <span class="prop-label" style="color:#34d399">Area</span>
          <span class="prop-value" style="font-size:15px;font-weight:600">
            ${room.area_sqm ? `${parseFloat(room.area_sqm).toFixed(2)} m²` : '—'}
            <span style="color:var(--text-muted);font-size:12px;margin-left:8px">
              (${room.area_sqm ? (parseFloat(room.area_sqm) * 10.764).toFixed(1) : '—'} ft²)
            </span>
          </span>
        </div>
        <div class="prop-row">
          <span class="prop-label" style="color:#34d399">Volume</span>
          <span class="prop-value" style="font-size:15px;font-weight:600">
            ${room.volume_cum ? `${parseFloat(room.volume_cum).toFixed(2)} m³` : '—'}
          </span>
        </div>
        <div class="prop-row">
          <button class="prop-btn" id="prop-recompute-room" data-id="${room.id}"
            style="background:#34d399;color:#000;border:none;padding:6px 12px;border-radius:4px;cursor:pointer;width:100%;font-size:12px;font-weight:600">
            ↻ Recompute from Walls
          </button>
        </div>
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="room-finish">Finishes <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="room-finish">
        <div class="prop-row"><span class="prop-label">Floor</span><span class="prop-value"><input class="prop-input" id="prop-room-floor" data-id="${room.id}" value="${room.floor_finish || ''}"></span></div>
        <div class="prop-row"><span class="prop-label">Wall</span><span class="prop-value"><input class="prop-input" id="prop-room-wall" data-id="${room.id}" value="${room.wall_finish || ''}"></span></div>
        <div class="prop-row"><span class="prop-label">Ceiling</span><span class="prop-value"><input class="prop-input" id="prop-room-ceiling" data-id="${room.id}" value="${room.ceiling_finish || ''}"></span></div>
        <div class="prop-row"><span class="prop-label">Base</span><span class="prop-value"><input class="prop-input" id="prop-room-base" data-id="${room.id}" value="${room.base_finish || ''}"></span></div>
      </div>
    </div>
    <div class="props-section">
      <div class="prop-row">
        <button class="prop-btn" id="prop-delete-room" data-id="${room.id}"
          style="background:#e74c3c;color:#fff;border:none;padding:6px 12px;border-radius:4px;cursor:pointer;width:100%;font-size:12px">
          Delete Room
        </button>
      </div>
    </div>
  `;

  const patch = (field, val) => {
    debouncedPatch(`room-${room.id}-${field}`, async () => {
      const res = await api('PATCH', `/api/rooms/${room.id}`, { [field]: val });
      const idx = state.rooms.findIndex(r => r.id === room.id);
      if (idx !== -1) state.rooms[idx] = res;
      scheduleRebuild();
    });
  };

  document.getElementById('prop-room-number')?.addEventListener('input', e => patch('number', e.target.value));
  document.getElementById('prop-room-name')?.addEventListener('input', e => patch('name', e.target.value));
  document.getElementById('prop-room-dept')?.addEventListener('input', e => patch('department', e.target.value));
  document.getElementById('prop-room-floor')?.addEventListener('input', e => patch('floor_finish', e.target.value));
  document.getElementById('prop-room-wall')?.addEventListener('input', e => patch('wall_finish', e.target.value));
  document.getElementById('prop-room-ceiling')?.addEventListener('input', e => patch('ceiling_finish', e.target.value));
  document.getElementById('prop-room-base')?.addEventListener('input', e => patch('base_finish', e.target.value));

  document.getElementById('prop-recompute-room')?.addEventListener('click', async () => {
    try {
      const res = await api('PATCH', `/api/rooms/${room.id}`, { recompute: true });
      const idx = state.rooms.findIndex(r => r.id === room.id);
      if (idx !== -1) state.rooms[idx] = res;
      rebuildScene();
      refreshPropertiesPanel();
      toast(`Area: ${res.area_sqm?.toFixed(2)} m², Volume: ${res.volume_cum?.toFixed(2)} m³`, 'success');
    } catch (e) { toast(e.message, 'error'); }
  });

  document.getElementById('prop-delete-room')?.addEventListener('click', async () => {
    await api('DELETE', `/api/rooms/${room.id}`);
    state.rooms = state.rooms.filter(r => r.id !== room.id);
    selectEntity(null, null);
    rebuildScene();
    toast('Room deleted', 'info');
  });
}

// ─── Phase 22: Curved Surface Properties ────────────────────────────────
function renderCurvedSurfaceProperties(surface) {
  const typeLabel = getSurfaceTypeLabel(surface.surface_type);
  document.getElementById('props-title').textContent = `CURVED: ${surface.name || typeLabel}`;

  const params = typeof surface.parameters === 'string'
    ? JSON.parse(surface.parameters) : (surface.parameters || {});

  document.getElementById('properties-content').innerHTML = `
    <div class="props-section">
      <div class="props-section-header" data-section="cs-identity">Identity <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="cs-identity">
        <div class="prop-row"><span class="prop-label">Name</span>
          <span class="prop-value"><input class="prop-input" id="prop-cs-name" data-id="${surface.id}" value="${surface.name || ''}"></span></div>
        <div class="prop-row"><span class="prop-label">Type</span>
          <span class="prop-value"><span class="prop-readonly">${typeLabel}</span></span></div>
        <div class="prop-row"><span class="prop-label">Material</span>
          <span class="prop-value">
            <select class="prop-input" id="prop-cs-material" data-id="${surface.id}">
              <option value="concrete"${surface.material === 'concrete' ? ' selected' : ''}>Concrete</option>
              <option value="steel"${surface.material === 'steel' ? ' selected' : ''}>Steel</option>
              <option value="glass"${surface.material === 'glass' ? ' selected' : ''}>Glass</option>
              <option value="timber"${surface.material === 'timber' ? ' selected' : ''}>Timber</option>
              <option value="composite"${surface.material === 'composite' ? ' selected' : ''}>Composite</option>
            </select>
          </span></div>
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="cs-geometry">Geometry <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="cs-geometry">
        <div class="prop-row"><span class="prop-label">Base Level</span>
          <span class="prop-value"><span class="prop-readonly">${surface.base_level_name || '—'}</span></span></div>
        <div class="prop-row"><span class="prop-label">Top Level</span>
          <span class="prop-value"><span class="prop-readonly">${surface.top_level_name || '—'}</span></span></div>
        <div class="prop-row"><span class="prop-label">Thickness (m)</span>
          <span class="prop-value"><input class="prop-input" id="prop-cs-thickness" data-id="${surface.id}" type="number" step="0.01" value="${surface.thickness || 0.15}"></span></div>
        <div class="prop-row"><span class="prop-label">Color</span>
          <span class="prop-value"><input class="prop-input" id="prop-cs-color" data-id="${surface.id}" type="color" value="${surface.color || '#7a9cbf'}"></span></div>
      </div>
    </div>
    <div class="props-section">
      <div class="props-section-header" data-section="cs-params">Parameters <span class="chevron">▼</span></div>
      <div class="props-section-body" data-body="cs-params">
        <div class="prop-row"><span class="prop-label">Segments U</span>
          <span class="prop-value"><input class="prop-input" id="prop-cs-seg-u" data-id="${surface.id}" type="number" value="${params.segments_u || 32}"></span></div>
        <div class="prop-row"><span class="prop-label">Segments V</span>
          <span class="prop-value"><input class="prop-input" id="prop-cs-seg-v" data-id="${surface.id}" type="number" value="${params.segments_v || 16}"></span></div>
        ${params.radius_a ? `<div class="prop-row"><span class="prop-label">Radius A</span><span class="prop-value"><input class="prop-input" id="prop-cs-rad-a" data-id="${surface.id}" type="number" step="0.1" value="${params.radius_a}"></span></div>` : ''}
        ${params.half_height ? `<div class="prop-row"><span class="prop-label">Half Height</span><span class="prop-value"><input class="prop-input" id="prop-cs-half-h" data-id="${surface.id}" type="number" step="0.1" value="${params.half_height}"></span></div>` : ''}
      </div>
    </div>
    <div style="margin-top:16px">
      <button class="btn-dangerous" id="prop-delete-curved" style="width:100%">Delete Surface</button>
    </div>
  `;

  const patch = (field, value) => debouncedPatch(`cs_${surface.id}_${field}`, async () => {
    const res = await api('PATCH', `/api/curved-surfaces/${surface.id}`, { [field]: value });
    const idx = state.curvedSurfaces.findIndex(s => s.id === surface.id);
    if (idx !== -1) state.curvedSurfaces[idx] = res;
    scheduleRebuild();
  });

  document.getElementById('prop-cs-name')?.addEventListener('input', e => patch('name', e.target.value));
  document.getElementById('prop-cs-material')?.addEventListener('change', e => patch('material', e.target.value));
  document.getElementById('prop-cs-thickness')?.addEventListener('input', e => patch('thickness', parseFloat(e.target.value)));
  document.getElementById('prop-cs-color')?.addEventListener('input', e => patch('color', e.target.value));
  document.getElementById('prop-cs-seg-u')?.addEventListener('input', e => {
    const p = { ...params, segments_u: parseInt(e.target.value) };
    patch('parameters', p);
  });
  document.getElementById('prop-cs-seg-v')?.addEventListener('input', e => {
    const p = { ...params, segments_v: parseInt(e.target.value) };
    patch('parameters', p);
  });

  document.getElementById('prop-delete-curved')?.addEventListener('click', async () => {
    await api('DELETE', `/api/curved-surfaces/${surface.id}`);
    state.curvedSurfaces = state.curvedSurfaces.filter(s => s.id !== surface.id);
    selectEntity(null, null);
    rebuildScene();
    toast('Curved surface deleted', 'info');
  });
}

// ─── Phase 22: Curved Surface Creation Modal ─────────────────────────────
