document.getElementById('cancel-add-roof')?.addEventListener('click', () => {
  document.getElementById('modal-add-roof').classList.add('hidden');
});

document.getElementById('confirm-add-roof')?.addEventListener('click', async () => {
  const roofStyle = document.getElementById('new-roof-style')?.value || 'flat';
  const typeName = document.getElementById('new-roof-type-name')?.value || 'Flat Roof TPO';
  const baseId = document.getElementById('nr-base')?.value;
  const width = parseFloat(document.getElementById('nr-width')?.value || 10);
  const depth = parseFloat(document.getElementById('nr-depth')?.value || 8);
  const pitch = document.getElementById('nr-pitch')?.value || '7:12';
  const rt = state.roofTypes.find(t => t.name === typeName);
  const span = depth;

  // Flat roof default layers: deck 150mm + membrane 10mm + insulation 50mm
  const defaultLayers = [
    { material: 'Concrete Deck 150mm', thickness: 0.15, function: 'structure' },
    { material: 'TPO Membrane 10mm', thickness: 0.01, function: 'waterproofing' },
    { material: 'XPS Insulation 50mm', thickness: 0.05, function: 'insulation' },
  ];
  // Gable gets lighter: sheathing + shingles
  const gableLayers = [
    { material: 'Plywood Sheathing 12mm', thickness: 0.012, function: 'structure' },
    { material: 'Asphalt Shingles', thickness: 0.004, function: 'finish' },
    { material: 'Felt Underlayment', thickness: 0.003, function: 'waterproofing' },
  ];
  const layers = ['gable', 'shed', 'hip'].includes(roofStyle) ? gableLayers : defaultLayers;

  try {
    const el = await api('POST', '/api/elements', {
      type: 'roof', type_name: typeName,
      parameters: {
        roof_style: roofStyle,
        width, depth, span,
        pitch_ratio: roofStyle === 'flat' ? '0' : pitch,
        phase: 'New Construction',
        footprint: roofStyle === 'flat' ? [
          { x: 0, y: 0 }, { x: width, y: 0 }, { x: width, y: depth }, { x: 0, y: depth }
        ] : [],
      },
      base_level_id: baseId,
      layers,
    });
    state.elements.push({ ...el, layers: el.layers || layers });
    rebuildScene();
    document.getElementById('modal-add-roof').classList.add('hidden');
    selectEntity(el.id, 'element');
    toast(`${roofStyle.charAt(0).toUpperCase() + roofStyle.slice(1)} roof added`, 'success');
  } catch (e) { toast(e.message, 'error'); }
});

// ─── Door / Window Placement Mode ─────────────────────────────────────────────

function populateDoorWindowModals() {
  const doorSel = document.getElementById('new-door-type');
  if (doorSel && state.doorTypes.length > 0) {
    doorSel.innerHTML = state.doorTypes.map(t =>
      `<option value="${t.id}">${t.name} (${(parseFloat(t.width)*1000).toFixed(0)}x${(parseFloat(t.height)*1000).toFixed(0)}mm)</option>`
    ).join('');
  }
  const winSel = document.getElementById('new-window-type');
  if (winSel && state.windowTypes.length > 0) {
    winSel.innerHTML = state.windowTypes.map(t =>
      `<option value="${t.id}">${t.name} (${(parseFloat(t.width)*1000).toFixed(0)}x${(parseFloat(t.height)*1000).toFixed(0)}mm)</option>`
    ).join('');
  }
}

