// ─── Wall-click raycasting for door/window placement ─────────────────────────
// canvas3dEl imported from canvas-bootstrap.js (single source of truth)
if (canvas3dEl) {
  canvas3dEl?.addEventListener('click', (e) => {
    if (!state.placementMode || !state.pendingPlacement) return;
    if (e.button !== 0) return;

    const rect = canvas3dEl.getBoundingClientRect();
    const mx = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    const my = -((e.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(new THREE.Vector2(mx, my), cam3d);

  const wallMeshes = [];
  for (const el of state.elements) {
    if (el.type !== 'wall') continue;
    const objs = objectMap.get(el.id);
    if (objs) wallMeshes.push(...objs.filter(Boolean));
  }
  const hits = raycaster.intersectObjects(wallMeshes, false);
  if (!hits.length) { toast('Click on a wall face', 'info'); return; }

  let wallId = null;
  let obj = hits[0].object;
  while (obj && !wallId) {
    if (obj.userData?.type === 'element') wallId = obj.userData.id;
    obj = obj.parent;
  }
  if (!wallId) { const meta = pickMap.get(hits[0].object.uuid); if (meta?.type === 'element') wallId = meta.id; }
  if (!wallId) { toast('Could not determine wall', 'error'); return; }

  const wallEl = state.elements.find(we => we.id === wallId);
  if (!wallEl) return;
  const wParams = typeof wallEl.parameters === 'string' ? JSON.parse(wallEl.parameters) : (wallEl.parameters || {});
  const sx = parseFloat(wParams.startCoord?.x || 0);
  const sy = parseFloat(wParams.startCoord?.y || 0);
  const ex = parseFloat(wParams.endCoord?.x || sx + 5);
  const ey = parseFloat(wParams.endCoord?.y || sy);
  const hitPt = hits[0].point;

  const wallVecX = ex - sx;
  const wallVecY = ey - sy;
  const wallLen = Math.sqrt(wallVecX ** 2 + wallVecY ** 2) || 1;
  const dx = hitPt.x - sx;
  const dy = hitPt.z - sy;
  const proj = (dx * wallVecX + dy * wallVecY) / (wallLen ** 2);
  const u = Math.max(0.02, Math.min(0.98, proj));

  placeFamily(wallId, u);
  });
}

// ─── SP-D: Cross-viewport click for placement (ortho → 3D sync) ─────────────
// Ortho viewports (Plan / El. X / El. Y) can also place doors/windows.
// On click: unproject → intersect with wall → call placeFamily().
// Secondary pane click listeners are attached after VP init (watchForVPReady).
function _setupOrthoPlacementListeners() {
  // Plan viewport (p1) — top-down view
  const planCanvas = document.getElementById('vp-canvas-p1');
  if (planCanvas) {
    planCanvas.addEventListener('click', (e) => _handleOrthoPlacementClick(e, 'plan'));
  }
  // Section / El. X viewport (p2)
  const sectCanvas = document.getElementById('vp-canvas-p2');
  if (sectCanvas) {
    sectCanvas.addEventListener('click', (e) => _handleOrthoPlacementClick(e, 'section'));
  }
  // El. Y viewport (p3)
  const elevCanvas = document.getElementById('vp-canvas-p3');
  if (elevCanvas) {
    elevCanvas.addEventListener('click', (e) => _handleOrthoPlacementClick(e, 'elevation-y'));
  }
}

/**
 * Handle click on an ortho viewport during placement mode.
 * Unprojects click to world ray, intersects walls, triggers placeFamily.
 */
function _handleOrthoPlacementClick(e, viewType) {
  if (!state.placementMode || !state.pendingPlacement) return;
  if (e.button !== 0) return;

  // Get the target canvas and camera for this view
  let targetCanvas, cam;
  if (viewType === 'plan') {
    targetCanvas = document.getElementById('vp-canvas-p1');
    cam = window._atlantist_cameras?.plan;
  } else {
    targetCanvas = document.getElementById('vp-canvas-p2');
    cam = window._atlantist_cameras?.section;
  }
  if (!targetCanvas || !cam) return;

  const rect = targetCanvas.getBoundingClientRect();
  const mx = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  const my = -((e.clientY - rect.top) / rect.height) * 2 + 1;

  // Ortho camera: unproject to world space along camera forward direction
  const ray = new THREE.Raycaster();
  ray.setFromCamera(new THREE.Vector2(mx, my), cam);

  // Find wall hits in the correct plane:
  // Plan view: look for walls in XZ plane at any Y
  // Section view: look for walls in XY plane (using camera's right axis)
  const wallMeshes = [];
  for (const el of state.elements) {
    if (el.type !== 'wall') continue;
    const objs = objectMap.get(el.id);
    if (objs) wallMeshes.push(...objs.filter(Boolean));
  }

  const hits = ray.intersectObjects(wallMeshes, false);
  if (!hits.length) { toast('Click on a wall in the viewport', 'info'); return; }

  // Find the wall element from hit
  let wallId = null;
  let obj = hits[0].object;
  while (obj && !wallId) {
    if (obj.userData?.type === 'element') wallId = obj.userData.id;
    obj = obj.parent;
  }
  if (!wallId) { const meta = pickMap.get(hits[0].object.uuid); if (meta?.type === 'element') wallId = meta.id; }
  if (!wallId) { toast('Could not determine wall', 'error'); return; }

  const wallEl = state.elements.find(we => we.id === wallId);
  if (!wallEl) return;
  const wParams = typeof wallEl.parameters === 'string' ? JSON.parse(wallEl.parameters) : (wallEl.parameters || {});
  const sx = parseFloat(wParams.startCoord?.x || 0);
  const sy = parseFloat(wParams.startCoord?.y || 0);
  const ex = parseFloat(wParams.endCoord?.x || sx + 5);
  const ey = parseFloat(wParams.endCoord?.y || sy);
  const hitPt = hits[0].point;

  // Compute U along wall in the appropriate plane
  // Plan view: hitPt is world (x, y, z), wall goes (x, y) in XZ plane
  // Section view: hitPt gives (x, z) → use x component
  const wallVecX = ex - sx;
  const wallVecY = ey - sy;
  const wallLen = Math.sqrt(wallVecX ** 2 + wallVecY ** 2) || 1;

  let dx, dy;
  if (viewType === 'plan') {
    // XZ plane projection for plan view
    dx = hitPt.x - sx;
    dy = hitPt.z - sy;
  } else {
    // For section/elevation: use the coordinate that changes along the wall
    // Section camera (front): sees X-Y plane, wall goes X-Y
    // Elevation Y camera: sees Z-Y plane, wall goes Z-Y
    // Fallback: use the dominant direction of the wall in world
    if (Math.abs(wallVecX) >= Math.abs(wallVecY)) {
      dx = hitPt.x - sx;
      dy = 0;
    } else {
      dx = 0;
      dy = hitPt.z - sy;
    }
  }

  const proj = (dx * wallVecX + dy * wallVecY) / (wallLen ** 2);
  const u = Math.max(0.02, Math.min(0.98, proj));

  placeFamily(wallId, u);
}

// ─── SP-D: Close-up zoom during placement ───────────────────────────────────
// On scroll during placement: zoom 3D camera to M×4 zone around cursor.
// Also update ortho camera to frame the zone.
function _setupPlacementScrollZoom() {
  if (!canvas3dEl) return;
  canvas3dEl.addEventListener('wheel', (e) => {
    if (!state.placementMode || !state.pendingPlacement) return;
    // Prevent page scroll
    e.preventDefault();
    e.stopPropagation();

    // Get cursor position in world space (approximate from raycaster)
    const rect = canvas3dEl.getBoundingClientRect();
    const mx = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    const my = -((e.clientY - rect.top) / rect.height) * 2 + 1;

    raycaster.setFromCamera(new THREE.Vector2(mx, my), cam3d);
    const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); // horizontal plane at y=0
    const target = new THREE.Vector3();
    raycaster.ray.intersectPlane(plane, target);
    if (!target) return;

    // Update placement service with current position (for ortho framing)
    updatePlacementPosition(target);

    // Zoom 3D camera toward cursor: shrink orbit target + zoom in
    const zoomFactor = e.deltaY > 0 ? 0.85 : 1.15; // scroll-in = zoom-in
    const maxZoom = 0.2; // minimum orbit distance (don't zoom into nothing)

    // Move camera target toward cursor position (lerp)
    const currentTgt = controls3d.target;
    currentTgt.lerp(target, 0.15);

    // Also zoom camera in/out
    const newDist = Math.max(maxZoom, cam3d.position.distanceTo(currentTgt) * zoomFactor);
    const dir = cam3d.position.clone().sub(currentTgt).normalize();
    cam3d.position.copy(currentTgt).addScaledVector(dir, newDist);
    controls3d.target.copy(currentTgt);
    controls3d.update();

    // Update ortho camera to frame M×4 zone around target
    _frameOrthoZone(target);

    // Re-render all viewports
    requestAnimationFrame(() => applyViewportCameras());
  }, { passive: false });
}

function _frameOrthoZone(target) {
  const derived = getModuleDerivedLocal();
  const zoneSize = derived.orthoZone_mm / 1000; // convert mm → meters
  const half = zoneSize / 2;

  // Get the secondary camera (p1 = plan, p2 = section)
  const secondaryCam = window._atlantist_cameras?.plan || window._atlantist_cameras?.section;
  if (!secondaryCam || !secondaryCam.isOrthographicCamera) return;

  // Zoom ortho to show M×4 zone centered on target
  const aspect = secondaryCam.right / (secondaryCam.top - secondaryCam.bottom);
  secondaryCam.left   = -half * aspect;
  secondaryCam.right  =  half * aspect;
  secondaryCam.top    =  half;
  secondaryCam.bottom = -half;
  // Keep camera looking at the target
  secondaryCam.updateProjectionMatrix();
}

async function placeFamily(hostWallId, u) {
  const { type, typeName, mark, parameters } = state.pendingPlacement;
  try {
    const fam = await api('POST', '/api/families', {
      family_type: type, type_name: typeName, host_wall_id: hostWallId,
      host_face_u: u, mark, parameters,
      computed: { openingWidth: parseFloat(parameters.width), openingHeight: parseFloat(parameters.height), frameDepth: 0.05 },
    });
    state.familyInstances.push(fam);
    rebuildScene();
    selectEntity(fam.id, 'family');
    toast((type === 'door' ? 'Door' : 'Window') + ' placed', 'success');
    state.placementMode = null;
    state.pendingPlacement = null;
    document.body.classList.remove('placing-door');
    document.body.classList.remove('placing-window');
    // SP-D: end placement context (secondary viewport restore, close-up reset)
    endPlacement();
  } catch (e) { toast('Failed to place: ' + e.message, 'error'); }
}

// Keyboard shortcuts
document.addEventListener('keydown', (e) => {
  // Ctrl/Cmd+K → open Command Palette (Ctrl+Shift+K → Node Editor)
  if ((e.ctrlKey || e.metaKey) && e.key === 'k' && !e.shiftKey) {
    e.preventDefault();
    openCommandPalette();
    return;
  }
  if ((e.ctrlKey || e.metaKey) && e.key === 'k' && e.shiftKey) {
    e.preventDefault();
    if (window._ne) window._ne.open();
    return;
  }
  if (e.key === 'Escape') {
    if (state.placementMode) {
      state.placementMode = null;
      state.pendingPlacement = null;
      document.body.classList.remove('placing-door');
      document.body.classList.remove('placing-window');
      // SP-D: end placement context (secondary viewport restore, close-up reset)
      endPlacement();
      toast('Placement cancelled', 'info');
    } else {
      state.multiSelection = [];
      selectEntity(null, null);
    }
  }
  if (e.key === 'Delete' && state.selectedId && state.selectedType === 'element') {
    const elBtn = document.getElementById('btn-delete-el');
    if (elBtn) elBtn.click();
  }
  // Space → group rotate (works for single or multi select, not in text inputs, not when FDS player is active)
  if (e.code === 'Space' && !e.target.matches('input,textarea,select')) {
    // Don't intercept if FDS fire sim panel is open (it already owns Space for play/pause)
    const fdsPanel = document.getElementById('fire-panel');
    if (fdsPanel && !fdsPanel.classList.contains('hidden')) return;
    if (!state.selectedId && state.multiSelection.length === 0) return;
    e.preventDefault();
    rotateSelectionGroup(45);
  }
  // Ctrl+Z → undo last group rotation
  if ((e.ctrlKey || e.metaKey) && e.key === 'z' && !e.shiftKey && !e.target.matches('input,textarea')) {
    if (groupRotateUndoStack.length > 0) {
      e.preventDefault();
      undoGroupRotate();
    }
  }
});

// ─── GOAL 4: Complete toolbar wiring ──────────────────────────────────────────
// Modify group (ArchiCAD-style: Move, Copy, Mirror, Array, Delete, Group)
document.getElementById('btn-mod-move')?.addEventListener('click', () => {
  if (!state.selectedId && state.multiSelection.length === 0) {
    toast('Select an element first, then Move', 'warn'); return;
  }
  const prompt = document.createElement('div');
  prompt.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:9999;background:#1a1a2e;border:1px solid #4a7dbd;border-radius:12px;padding:20px;color:white;font-family:var(--font-mono,"Courier New"),monospace;min-width:280px;box-shadow:0 20px 60px rgba(0,0,0,0.5)';
  prompt.innerHTML = `<div style="font-size:14px;font-weight:600;margin-bottom:12px;color:#5b9bd5">Move Element(s)</div>
    <div style="display:flex;flex-direction:column;gap:8px">
      <label style="font-size:12px;color:#888">Offset X (m)<input id="mv-x" type="number" step="0.1" value="0" style="width:100%;padding:6px 8px;background:#111;border:1px solid #333;border-radius:6px;color:white;margin-top:2px"></label>
      <label style="font-size:12px;color:#888">Offset Y (m)<input id="mv-y" type="number" step="0.1" value="0" style="width:100%;padding:6px 8px;background:#111;border:1px solid #333;border-radius:6px;color:white;margin-top:2px"></label>
      <label style="font-size:12px;color:#888">Offset Z (m)<input id="mv-z" type="number" step="0.1" value="0" style="width:100%;padding:6px 8px;background:#111;border:1px solid #333;border-radius:6px;color:white;margin-top:2px"></label>
    </div>
    <div style="display:flex;gap:8px;margin-top:14px">
      <button id="mv-do" style="flex:1;padding:8px;background:#1d4e89;color:white;border:none;border-radius:6px;cursor:pointer;font-size:13px;font-weight:600">Move</button>
      <button id="mv-cancel" style="padding:8px 16px;background:#222;color:#888;border:1px solid #333;border-radius:6px;cursor:pointer;font-size:13px">Cancel</button>
    </div>`;
  document.body.appendChild(prompt);
  document.getElementById('mv-cancel').onclick = () => document.body.removeChild(prompt);
  document.getElementById('mv-do').onclick = async () => {
    const dx = parseFloat(document.getElementById('mv-x').value) || 0;
    const dy = parseFloat(document.getElementById('mv-y').value) || 0;
    const dz = parseFloat(document.getElementById('mv-z').value) || 0;
    document.body.removeChild(prompt);
    if (dx === 0 && dy === 0 && dz === 0) return;
    const ids = state.multiSelection.length > 0 ? state.multiSelection : (state.selectedId ? [state.selectedId] : []);
    for (const id of ids) {
      const el = state.elements.find(e => e.id === id);
      if (!el || el.type === 'wall') {
        const params = typeof el?.parameters === 'string' ? JSON.parse(el.parameters) : (el.parameters || {});
        const newParams = {
          ...params,
          startCoord: params.startCoord ? { x: params.startCoord.x + dx, y: params.startCoord.y + dy } : undefined,
          endCoord: params.endCoord ? { x: params.endCoord.x + dx, y: params.endCoord.y + dy } : undefined,
          rotatedX: (params.rotatedX || 0) + dx,
          rotatedZ: (params.rotatedZ || 0) + dz,
        };
        await api('PATCH', `/api/elements/${id}`, { parameters: newParams });
        if (el) el.parameters = newParams;
      } else {
        await api('PATCH', `/api/elements/${id}`, { position_x: (el.position_x || 0) + dx, position_y: (el.position_y || 0) + dy });
        if (el) { el.position_x = (el.position_x || 0) + dx; el.position_y = (el.position_y || 0) + dy; }
      }
    }
    rebuildScene();
    toast(`Moved ${ids.length} element(s)`, 'success');
  };
  document.getElementById('mv-x').focus();
});

document.getElementById('btn-mod-copy')?.addEventListener('click', () => {
  if (!state.selectedId && state.multiSelection.length === 0) {
    toast('Select an element first, then Copy', 'warn'); return;
  }
  const ids = state.multiSelection.length > 0 ? state.multiSelection : [state.selectedId];
  (async () => {
    let count = 0;
    for (const id of ids) {
      const el = state.elements.find(e => e.id === id);
      if (!el) continue;
      const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : (el.parameters || {});
      const copyParams = { ...params };
      if (el.type === 'wall') {
        copyParams.startCoord = { x: (params.startCoord?.x || 0) + 2, y: (params.startCoord?.y || 0) + 2 };
        copyParams.endCoord = { x: (params.endCoord?.x || 5) + 2, y: (params.endCoord?.y || 0) + 2 };
      }
      const created = await api('POST', '/api/elements', { ...el, id: undefined, type: el.type, type_name: el.type_name, parameters: copyParams });
      state.elements.push(created);
      count++;
    }
    rebuildScene();
    toast(`Copied ${count} element(s) (+2m offset)`, 'success');
  })();
});

document.getElementById('btn-mod-mirror')?.addEventListener('click', () => {
  if (!state.selectedId && state.multiSelection.length === 0) {
    toast('Select an element first, then Mirror', 'warn'); return;
  }
  const ids = state.multiSelection.length > 0 ? state.multiSelection : [state.selectedId];
  (async () => {
    let count = 0;
    for (const id of ids) {
      const el = state.elements.find(e => e.id === id);
      if (!el || el.type !== 'wall') continue;
      const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : (el.parameters || {});
      const sx = params.startCoord?.x || 0, sy = params.startCoord?.y || 0;
      const ex = params.endCoord?.x || 5, ey = params.endCoord?.y || 0;
      // Flip X
      const mirroredParams = {
        ...params,
        startCoord: { x: -sx, y: sy },
        endCoord: { x: -ex, y: ey },
      };
      await api('PATCH', `/api/elements/${id}`, { parameters: mirroredParams });
      el.parameters = mirroredParams;
      count++;
    }
    rebuildScene();
    toast(`Mirrored ${count} wall(s) across X=0 axis`, 'success');
  })();
});

document.getElementById('btn-mod-array')?.addEventListener('click', () => {
  if (!state.selectedId && state.multiSelection.length === 0) {
    toast('Select an element first, then Array', 'warn'); return;
  }
  const ids = state.multiSelection.length > 0 ? state.multiSelection : [state.selectedId];
  const prompt = document.createElement('div');
  prompt.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:9999;background:#1a1a2e;border:1px solid #4a7dbd;border-radius:12px;padding:20px;color:white;font-family:var(--font-mono,"Courier New"),monospace;min-width:300px;box-shadow:0 20px 60px rgba(0,0,0,0.5)';
  prompt.innerHTML = `<div style="font-size:14px;font-weight:600;margin-bottom:12px;color:#5b9bd5">Linear Array</div>
    <div style="display:flex;flex-direction:column;gap:8px">
      <label style="font-size:12px;color:#888">Count <input id="ar-count" type="number" min="2" max="20" value="3" style="width:100%;padding:6px 8px;background:#111;border:1px solid #333;border-radius:6px;color:white;margin-top:2px"></label>
      <label style="font-size:12px;color:#888">Offset X (m)<input id="ar-dx" type="number" step="0.1" value="2" style="width:100%;padding:6px 8px;background:#111;border:1px solid #333;border-radius:6px;color:white;margin-top:2px"></label>
      <label style="font-size:12px;color:#888">Offset Y (m)<input id="ar-dy" type="number" step="0.1" value="0" style="width:100%;padding:6px 8px;background:#111;border:1px solid #333;border-radius:6px;color:white;margin-top:2px"></label>
    </div>
    <div style="display:flex;gap:8px;margin-top:14px">
      <button id="ar-do" style="flex:1;padding:8px;background:#1d4e89;color:white;border:none;border-radius:6px;cursor:pointer;font-size:13px;font-weight:600">Create Array</button>
      <button id="ar-cancel" style="padding:8px 16px;background:#222;color:#888;border:1px solid #333;border-radius:6px;cursor:pointer;font-size:13px">Cancel</button>
    </div>`;
  document.body.appendChild(prompt);
  document.getElementById('ar-cancel').onclick = () => document.body.removeChild(prompt);
  document.getElementById('ar-do').onclick = async () => {
    const count = parseInt(document.getElementById('ar-count').value) || 3;
    const dx = parseFloat(document.getElementById('ar-dx').value) || 2;
    const dy = parseFloat(document.getElementById('ar-dy').value) || 0;
    document.body.removeChild(prompt);
    let total = 0;
    for (const id of ids) {
      const el = state.elements.find(e => e.id === id);
      if (!el) continue;
      const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : (el.parameters || {});
      for (let i = 1; i < count; i++) {
        const offset = i;
        let newParams = { ...params };
        if (el.type === 'wall') {
          newParams = {
            ...params,
            startCoord: { x: (params.startCoord?.x || 0) + dx * offset, y: (params.startCoord?.y || 0) + dy * offset },
            endCoord: { x: (params.endCoord?.x || 5) + dx * offset, y: (params.endCoord?.y || 0) + dy * offset },
          };
        }
        const created = await api('POST', '/api/elements', { ...el, id: undefined, type: el.type, type_name: el.type_name, parameters: newParams });
        state.elements.push(created);
        total++;
      }
    }
    rebuildScene();
    toast(`Arrayed ${total} copies of ${ids.length} element(s)`, 'success');
  };
  document.getElementById('ar-count').focus();
});

document.getElementById('btn-mod-delete')?.addEventListener('click', () => {
  const ids = state.multiSelection.length > 0 ? state.multiSelection : (state.selectedId ? [state.selectedId] : []);
  if (ids.length === 0) { toast('Nothing selected to delete', 'warn'); return; }
  if (!confirm(`Delete ${ids.length} element(s)?`)) return;
  (async () => {
    for (const id of ids) {
      await api('DELETE', `/api/elements/${id}`).catch(() => {});
      state.elements = state.elements.filter(e => e.id !== id);
    }
    state.selectedId = null;
    state.multiSelection = [];
    clearPropertiesPanel();
    rebuildScene();
    toast(`Deleted ${ids.length} element(s)`, 'info');
  })();
});

document.getElementById('btn-mod-group')?.addEventListener('click', () => {
  if (state.multiSelection.length === 0 && !state.selectedId) {
    toast('Select 2+ elements to group (Ctrl+click each)', 'warn'); return;
  }
  const ids = state.multiSelection.length > 0 ? state.multiSelection : [state.selectedId];
  if (ids.length < 2) { toast('Select 2+ elements to group', 'warn'); return; }
  toast(`${ids.length} elements grouped — press Ctrl+G to ungroup`, 'success', 3000);
});

