function openCommandPalette() {
  const cp = document.getElementById('command-palette');
  const search = document.getElementById('cp-search');
  const results = document.getElementById('cp-results');
  cp.style.display = 'block';
  search.value = '';
  search.focus();
  renderCPResults('');
  search.oninput = () => renderCPResults(search.value.trim().toLowerCase());
}

function renderCPResults(query) {
  const results = document.getElementById('cp-results');
  let filtered = CP_COMMANDS;
  if (query) {
    filtered = CP_COMMANDS.filter(c => c.label.toLowerCase().includes(query) || c.group.toLowerCase().includes(query));
  }
  if (filtered.length === 0) {
    results.innerHTML = `<div style="padding:20px;text-align:center;color:#555;font-size:13px">No matching commands</div>`;
    return;
  }
  const html = filtered.slice(0, 20).map((cmd, i) => `
    <div class="cp-item" data-i="${i}" style="padding:10px 16px;cursor:pointer;display:flex;align-items:center;gap:12px;border-radius:6px;margin:2px 6px;transition:background 0.1s"
      onmouseover="this.style.background='#1d2d4a'" onmouseout="this.style.background=''">
      <span style="flex:1;font-size:13px;color:#ddd">${cmd.label}</span>
      <span style="font-size:11px;color:#555;background:#0d1a2a;padding:2px 6px;border-radius:4px">${cmd.group}</span>
      ${cmd.shortcut ? `<span style="font-size:11px;color:#5b9bd5;background:#0d1a2a;padding:2px 6px;border-radius:4px">${cmd.shortcut}</span>` : ''}
    </div>`).join('');
  results.innerHTML = html;
  filtered.slice(0, 20).forEach((cmd, i) => {
    const el = results.querySelector(`[data-i="${i}"]`);
    if (el) el.onclick = () => {
      document.getElementById('command-palette').classList.add('hidden');
      cmd.action();
    };
  });
}
window.openCommandPalette = openCommandPalette;

