  // Temporarily redirect the section renderer to show the elevation
  // We use the section canvas for elevation (it shares the orthographic camera layout)
  // Reset section camera to elevation position
  camSection.position.set(...def.pos);
  camSection.lookAt(...def.look);
  camSection.left = -25; camSection.right = 25; camSection.top = 10; camSection.bottom = -2;
  camSection.updateProjectionMatrix();

  state.activeView = 'elevation-' + btnId.split('-')[1];
