document.getElementById('ctx-add-issue')?.addEventListener('click', async () => {
  const anchorId = _ctxRightClickTarget?.type === 'element' ? _ctxRightClickTarget.id : null;
  issueState.pendingAnchorId = anchorId;
  issueState.pendingCamera = captureViewportState();

  // Capture PNG snapshot
  try {
    issueState.pendingPng = await captureViewportPng();
    const preview = document.getElementById('issue-snapshot-preview');
    const img = document.getElementById('issue-snapshot-img');
    if (issueState.pendingPng) {
      img.src = issueState.pendingPng;
      preview.classList.remove('hidden');
    }
  } catch(_) { issueState.pendingPng = null; }

  // Reset form
  document.getElementById('new-issue-title').value = '';
  document.getElementById('new-issue-body').value = '';
  document.getElementById('new-issue-priority').value = 'normal';
  document.getElementById('modal-add-issue').classList.remove('hidden');
  setTimeout(() => document.getElementById('new-issue-title').focus(), 50);
});

document.getElementById('cancel-add-issue')?.addEventListener('click', () => {
  document.getElementById('modal-add-issue').classList.add('hidden');
  document.getElementById('issue-snapshot-preview').classList.add('hidden');
});

document.getElementById('confirm-add-issue')?.addEventListener('click', async () => {
  const title = document.getElementById('new-issue-title').value.trim();
  if (!title) { toast('Title is required', 'error'); return; }
  const priority = document.getElementById('new-issue-priority').value;
  const body = document.getElementById('new-issue-body').value;

  try {
    const payload = {
      title, body, priority,
      anchor_element_id: issueState.pendingAnchorId,
      author_user_id: wsClient.myUserId || 'anonymous',
      camera_position: issueState.pendingCamera,
      view_mode: '3d',
      visible_layers: [],
      snapshot_png: issueState.pendingPng || null,
    };
    const issue = await api('POST', '/api/issues', payload);
    issueState.issues.unshift({ ...issue, comment_count: 0 });
    applyIssueFilters();
    renderIssuePins();
    document.getElementById('modal-add-issue').classList.add('hidden');
    document.getElementById('issue-snapshot-preview').classList.add('hidden');
    toast('Issue created', 'success');

    // Switch to issues tab to show it
    document.getElementById('btn-issues')?.click();
  } catch (e) { toast(e.message, 'error'); }
});

// ─── Issue detail modal ───────────────────────────────────────
async function openIssueDetail(issueId) {
  issueState.openIssueId = issueId;
  renderIssuesList();
  try {
    const issue = await api('GET', `/api/issues/${issueId}`);
    const titleEl = document.getElementById('issue-detail-title');
    const bodyEl = document.getElementById('issue-detail-body');
    const resolveBtn = document.getElementById('resolve-issue-btn');

    titleEl.textContent = issue.title;

    // Snapshot
    const snapshotHtml = issue.snapshot_png
      ? `<div class="issue-detail-snapshot"><img src="${issue.snapshot_png}" alt="Snapshot"></div>`
      : '';

    // Comments
    const commentsHtml = (issue.comments || []).map(c => `
      <div class="issue-comment" data-cid="${c.id}">
        <span class="issue-comment-author">${escHtml(c.author_user_id)}</span>
        <span class="issue-comment-time">${relativeTime(c.created_at)}</span>
        <div class="issue-comment-text">${escHtml(c.body)}</div>
      </div>
    `).join('') || '<div style="font-size:11px;color:var(--text-muted);padding:4px 0">No comments yet.</div>';

    const statusBadgeStyle = `background:${statusColor(issue.status)};color:#fff;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;margin-left:8px`;

    bodyEl.innerHTML = `
      ${snapshotHtml}
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
        <span class="issue-priority-badge ${issue.priority}">${priorityLabel(issue.priority)}</span>
        <span style="${statusBadgeStyle}">${issue.status.replace('_', ' ').toUpperCase()}</span>
        ${issue.anchor_element_id ? `<span style="font-size:10px;color:var(--text-muted)">📍 Element: ${issue.anchor_element_id.slice(-8)}</span>` : ''}
      </div>
      ${issue.body ? `<div class="issue-detail-body-text" style="margin-bottom:12px">${escHtml(issue.body)}</div>` : ''}
      <div class="issue-comments-section">
        <div style="font-size:10px;font-weight:600;text-transform:uppercase;color:var(--text-muted);margin-bottom:8px;letter-spacing:.08em">Comments</div>
        <div id="comments-list-inner">${commentsHtml}</div>
        <div class="issue-comment-form">
          <textarea id="new-comment-text" placeholder="Add a comment… @mention others by userId"></textarea>
          <button id="submit-comment-btn">Post</button>
        </div>
      </div>
    `;

    // Resolve / Reopen button state
    if (issue.status === 'open') {
      resolveBtn.textContent = '✓ Resolve';
      resolveBtn.onclick = () => changeIssueStatus(issue.id, 'resolved');
    } else if (issue.status === 'resolved') {
      resolveBtn.textContent = '↩ Reopen';
      resolveBtn.onclick = () => changeIssueStatus(issue.id, 'open');
    } else {
      resolveBtn.textContent = '↩ Reopen';
      resolveBtn.onclick = () => changeIssueStatus(issue.id, 'open');
    }

    // Post comment
    document.getElementById('submit-comment-btn')?.addEventListener('click', async () => {
      const commentBody = document.getElementById('new-comment-text').value.trim();
      if (!commentBody) return;
      try {
        await api('POST', `/api/issues/${issueId}/comments`, {
          body: commentBody,
          author_user_id: wsClient.myUserId || 'anonymous'
        });
        document.getElementById('new-comment-text').value = '';
        openIssueDetail(issueId); // refresh
        toast('Comment added', 'success');
      } catch (e) { toast(e.message, 'error'); }
    });

    // Jump camera if anchor
    if (issue.camera_position) {
      jumpCameraToSnapshot(issue);
    }

    document.getElementById('modal-issue-detail').classList.remove('hidden');
  } catch (e) {
    toast('Could not load issue: ' + e.message, 'error');
  }
}

document.getElementById('close-issue-detail')?.addEventListener('click', () => {
  document.getElementById('modal-issue-detail').classList.add('hidden');
  issueState.openIssueId = null;
  renderIssuesList();
});

async function changeIssueStatus(issueId, newStatus) {
  try {
    const updated = await api('PATCH', `/api/issues/${issueId}/status`, {
      status: newStatus, user_id: wsClient.myUserId || 'anonymous'
    });
    const idx = issueState.issues.findIndex(i => i.id === issueId);
    if (idx !== -1) issueState.issues[idx] = { ...issueState.issues[idx], ...updated };
    applyIssueFilters();
    renderIssuePins();
    document.getElementById('modal-issue-detail').classList.add('hidden');
    issueState.openIssueId = null;
    toast(`Issue ${newStatus.replace('_', ' ')}`, 'success');
  } catch (e) { toast(e.message, 'error'); }
}

// ─── Wire up WS callbacks for real-time issue events ─────────
wsClient.onIssueCreated = (payload) => {
  const exists = issueState.issues.findIndex(i => i.id === payload.id);
  if (exists === -1) {
    issueState.issues.unshift({ ...payload, comment_count: 0 });
    applyIssueFilters();
    renderIssuePins();
    toast(`New issue: "${payload.title}"`, 'info', 3000);
  }
};

wsClient.onIssueStatusChanged = (payload) => {
  const idx = issueState.issues.findIndex(i => i.id === payload.id);
  if (idx !== -1) {
    issueState.issues[idx] = { ...issueState.issues[idx], status: payload.status, resolved_at: payload.resolved_at };
    applyIssueFilters();
    renderIssuePins();
  }
};

wsClient.onIssueComment = (payload) => {
  const idx = issueState.issues.findIndex(i => i.id === payload.issue_id);
  if (idx !== -1) {
    issueState.issues[idx].comment_count = (issueState.issues[idx].comment_count || 0) + 1;
    applyIssueFilters();
    // If detail modal is open for this issue, refresh it
    if (issueState.openIssueId === payload.issue_id) openIssueDetail(payload.issue_id);
  }
};

wsClient.onIssueDeleted = (issueId) => {
  issueState.issues = issueState.issues.filter(i => i.id !== issueId);
  applyIssueFilters();
  renderIssuePins();
  if (issueState.openIssueId === issueId) document.getElementById('modal-issue-detail').classList.add('hidden');
};

