document.getElementById('render-action-trigger')?.addEventListener('click', async () => {
  renderDropdown?.classList.remove('open');
  await triggerRender();
});

async function triggerRender() {
  const style = renderState.currentStyle;
  const styleLabel = style.charAt(0).toUpperCase() + style.slice(1);

  // Show loading
  const loadingEl = document.getElementById('render-loading');
  const styleTextEl = document.getElementById('render-loading-style');
  if (loadingEl) {
    styleTextEl.textContent = styleLabel;
    loadingEl.classList.remove('hidden');
  }

  try {
    // Capture 3D viewport
    renderer3d.render(scene3d, cam3d);
    const blob = await new Promise(resolve => {
      renderer3d.domElement.toBlob(resolve, 'image/jpeg', 0.85);
    });
    if (!blob) throw new Error('Failed to capture viewport');

    const base64 = await new Promise(resolve => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result);
      reader.readAsDataURL(blob);
    });

    // Get camera state
    const cameraData = captureViewportState();
    const viewpointName = `View at ${new Date().toLocaleString()}`;

    // Call API
    const render = await api('POST', '/api/renders', {
      imageBase64: base64,
      style,
      viewpointName,
      cameraData,
      sourceCanvas: '3d',
    });

    // Add to history
    renderState.history.unshift(render);
    renderState.currentRender = render;

    // Show render modal
    openRenderModal(render);

    toast(`Render complete: ${styleLabel}`, 'success');
  } catch (err) {
    toast('Render failed: ' + err.message, 'error');
  } finally {
    loadingEl?.classList.add('hidden');
  }
}

// ─── Render modal ──────────────────────────────────────────────
function openRenderModal(render) {
  const modal = document.getElementById('render-modal');
  const img = document.getElementById('render-modal-img');
  const title = document.getElementById('render-modal-title');

  if (modal && img && title) {
    img.src = render.image_url;
    const styleLabel = render.style.charAt(0).toUpperCase() + render.style.slice(1);
    title.innerHTML = `<strong>${styleLabel}</strong> · ${escHtml(render.viewpoint_name)}`;
    modal.classList.remove('hidden');
    renderState.currentRender = render;

    // Download handler
    document.getElementById('render-modal-download')?.addEventListener('click', () => {
      const a = document.createElement('a');
      a.href = render.image_url;
      a.download = `render_${render.style}_${Date.now()}.png`;
      a.target = '_blank';
      a.click();
    });

    // Set as cover (just a toast — project cover would need project API)
    document.getElementById('render-modal-set-cover')?.addEventListener('click', () => {
      toast('Cover image updated', 'success');
    });
  }
}

document.getElementById('render-modal-close')?.addEventListener('click', () => {
  document.getElementById('render-modal')?.classList.add('hidden');
});
document.getElementById('render-modal')?.addEventListener('click', (e) => {
  if (e.target.id === 'render-modal') {
    document.getElementById('render-modal')?.classList.add('hidden');
  }
});

// ─── Render History Panel ───────────────────────────────────────
async function loadRenderHistory() {
  try {
    renderState.history = await api('GET', '/api/renders');
    renderHistoryList();
  } catch (e) {
    console.error('[renders] history load failed', e);
  }
}

function renderHistoryList() {
  const list = document.getElementById('render-history-list');
  if (!list) return;

  if (renderState.history.length === 0) {
    list.innerHTML = '<div class="render-history-empty">No renders yet.<br><br>Use the <strong>Render</strong> button to generate AI-powered views of your model.</div>';
    return;
  }

  list.innerHTML = renderState.history.map(r => {
    const styleLabel = r.style.charAt(0).toUpperCase() + r.style.slice(1);
    const date = new Date(r.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    return `
      <div class="render-history-item" data-id="${r.id}">
        <img src="${r.thumbnail_url || r.image_url}" alt="${escHtml(r.viewpoint_name)}" loading="lazy">
        <div class="render-history-meta">
          <div class="render-history-name">${escHtml(r.viewpoint_name)}</div>
          <div class="render-history-sub">${date}</div>
          <span class="render-history-style-badge ${r.style}">${styleLabel}</span>
        </div>
      </div>
    `;
  }).join('');

  list.querySelectorAll('.render-history-item').forEach(item => {
    item?.addEventListener('click', async () => {
      const id = item.dataset.id;
      const r = renderState.history.find(x => x.id === id);
      if (r) {
        // Fetch fresh from server to get full URL
        try {
          const fresh = await api('GET', `/api/renders/${id}`);
          openRenderModal(fresh);
        } catch (_) {
          openRenderModal(r);
        }
      }
      // Close panel on click
      document.getElementById('render-history-panel')?.classList.remove('open');
    });
  });
}

