// ─── FBX Export ────────────────────────────────────────────────
async function exportFBX({ includeMaterials = true }) {
  const FBXExporter = window.__FBXExporter;
  if (!FBXExporter) {
    toast('FBX exporter not loaded — try refreshing the page', 'error');
    return;
  }

  // Build a Three.js Group with all scene geometry
  const exportGroup = new THREE.Group();
  exportGroup.name = 'Atlantist_BIM_Export';

  // Add all element meshes (walls, columns, families)
  for (const el of state.elements) {
    const objs = objectMap.get(el.id);
    if (!objs) continue;
    for (const obj of objs) {
      const clone = obj.clone();
      clone.userData.elementId = el.id;
      clone.userData.elementType = el.type;
      exportGroup.add(clone);
    }
  }

  // Add level planes (geometric representation)
  for (const level of state.levels) {
    const plane = new THREE.Mesh(
      new THREE.PlaneGeometry(60, 60),
      new THREE.MeshLambertMaterial({ color: 0x888888, side: THREE.DoubleSide, transparent: true, opacity: 0.1 })
    );
    plane.rotation.x = -Math.PI / 2;
    plane.position.y = parseFloat(level.elevation);
    plane.name = `Level_${level.name}`;
    exportGroup.add(plane);
  }

  const exporter = new FBXExporter();
  const result = await new Promise((resolve, reject) => {
    exporter.parse(exportGroup, (fbxBuffer) => resolve(fbxBuffer), (err) => reject(err), { binary: true });
  });

  const blob = new Blob([result], { type: 'application/octet-stream' });
  triggerDownload(blob, `atlantist_${Date.now()}.fbx`);

  // Count exported objects
  const count = state.elements.length + state.levels.length;
  toast(`FBX exported (${count} objects) — open in Twinmotion`, 'success');
}

// ─── OBJ Export (fallback) ─────────────────────────────────────
async function exportOBJ() {
  let objContent = `# Atlantist BIM Export — ${new Date().toISOString()}\n`;
  let vertexOffset = 1;

  function writeMesh(geo, matrix, materialName) {
    let out = `# ${materialName}\n`;
    const pos = geo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      const v = new THREE.Vector3(pos.getX(i), pos.getY(i), pos.getZ(i)).applyMatrix4(matrix);
      out += `v ${v.x.toFixed(4)} ${v.y.toFixed(4)} ${v.z.toFixed(4)}\n`;
    }
    if (geo.attributes.normal) {
      for (let i = 0; i < geo.attributes.normal.count; i++) {
        const n = new THREE.Vector3(geo.attributes.normal.getX(i), geo.attributes.normal.getY(i), geo.attributes.normal.getZ(i)).transformDirection(matrix);
        out += `vn ${n.x.toFixed(4)} ${n.y.toFixed(4)} ${n.z.toFixed(4)}\n`;
      }
    }
    const index = geo.index;
    if (index) {
      for (let i = 0; i < index.count; i += 3) {
        const a = index.getX(i) + vertexOffset;
        const b = index.getX(i + 1) + vertexOffset;
        const c = index.getX(i + 2) + vertexOffset;
        out += `f ${a} ${b} ${c}\n`;
      }
    }
    vertexOffset += pos.count;
    return out;
  }

  for (const el of state.elements) {
    const objs = objectMap.get(el.id);
    if (!objs) continue;
    for (const obj of objs) {
      obj.traverse(child => {
        if (child.isMesh && child.geometry) {
          objContent += writeMesh(child.geometry, child.matrixWorld, el.type_name || el.type);
        }
      });
    }
  }

  const blob = new Blob([objContent], { type: 'text/plain' });
  triggerDownload(blob, `atlantist_${Date.now()}.obj`);
  toast('OBJ exported — open in Twinmotion', 'success');
}

function triggerDownload(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.style.display = 'none';
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 100);
}

