// Populate level selector in DXF modal
async function populateDxfLevelSelector() {
  const sel = document.getElementById('dxf-level-select');
  if (!sel) return;
  try {
    const res = await fetch('/api/levels');
    if (!res.ok) return;
    let levels;
    try {
      levels = await res.json();
    } catch {
      const body = await res.text().catch(() => '');
      console.warn(`[app] GET /api/levels returned non-JSON (${res.status}): ${body.slice(0, 200)}`);
      levels = [];
    }
    sel.innerHTML = '<option value="">All Levels</option>';
    levels.forEach(l => {
      const opt = document.createElement('option');
      opt.value = l.id;
      opt.textContent = `${l.name} (${l.elevation}')`;
      sel.appendChild(opt);
    });
  } catch {
    // Levels unavailable — selector stays empty
  }
}

