// ════════════════════════════════════════════════════════════════
// PHASE 8 — Collaboration (Motif WebRTC), DOB Filing, Materials Schedule
// ════════════════════════════════════════════════════════════════

// ─── Phase 8.1: WebRTC Collaboration (Motif-style shared viewport) ───────────

// PeerJS peer management — one peer connection per remote user
const peers = new Map(); // peerId → { peer: PeerJS instance, conn: DataConnection }
let collaborationActive = false;
let localCameraFollowing = null; // peerId being followed — their camera controls ours

// Register wsClient callbacks for collaboration room events
wsClient.onRoomCreated = (roomCode) => {
  collaborationActive = true;
  updateCollabSessionUI(roomCode, true, []);
  toast(`Room ${roomCode} created — share this code`, 'success', 4000);
  // Host: listen for incoming peer connections via PeerJS
  setupPeerJSHostListener(roomCode);
};

wsClient.onRoomJoined = (roomCode) => {
  collaborationActive = true;
  updateCollabSessionUI(roomCode, false, []);
  toast(`Joined room ${roomCode}`, 'success', 3000);
  wsClient.requestRoomSync();
};

wsClient.onRoomError = (error) => {
  toast('Room error: ' + error, 'error');
};

wsClient.onRoomPeerJoined = (peerId, peerColor, peerCount) => {
  // Establish PeerJS connection to new peer
  establishPeerConnection(peerId, peerColor);
  updateCollabSessionPeers(peerCount);
};

wsClient.onRoomPeerLeft = (peerId, peerCount) => {
  const p = peers.get(peerId);
  if (p?.conn) p.conn.close();
  if (p?.peer) p.peer.destroy();
  peers.delete(peerId);
  if (localCameraFollowing === peerId) localCameraFollowing = null;
  updateCollabSessionPeers(peerCount);
  // Remove ghost cursors for this peer
  removePeerGhostCursor(peerId);
};

wsClient.onRoomClosed = (reason) => {
  collaborationActive = false;
  closeAllPeerConnections();
  hideCollabSession();
  if (reason !== 'Host disconnected') toast('Room closed: ' + reason, 'error');
};

wsClient.onRoomState = ({ roomCode, peers: peerList }) => {
  // Called when we join a room — connect to all existing peers via PeerJS
  for (const { userId: peerId, color: peerColor } of peerList) {
    establishPeerConnection(peerId, peerColor);
  }
};

wsClient.onCameraSync = (peerId, peerColor, cameraData) => {
  // Apply remote peer's camera to our viewport (follow mode or live indicator)
  if (localCameraFollowing === peerId) {
    applyRemoteCamera(cameraData);
  }
};

wsClient.onWebRTCSignal = (fromPeerId, signal) => {
  // Handle incoming PeerJS signaling via WebSocket relay
  const p = peers.get(fromPeerId);
  if (p?.conn && signal.type === 'offer') {
    // We're the new peer receiving an offer — auto-accept
    p.peer.signal(signal);
  } else if (p?.conn) {
    // ICE candidate or answer
    p.peer.signal(signal);
  }
};

function establishPeerConnection(peerId, peerColor) {
  if (peers.has(peerId)) return; // already connected
  if (typeof Peer === 'undefined') return; // PeerJS not loaded

  const isHost = wsClient.currentRoom?.isHost;
  const roomCode = wsClient.currentRoom?.code;

  const peer = new Peer(`atlantist-${roomCode}-${wsClient.myUserId}-${peerId}`, {
    debug: 0
  });

  peer.on('open', () => {
    // We're the initiator — connect to the remote peer
    const conn = peer.connect(`atlantist-${roomCode}-${peerId}-${wsClient.myUserId}`, {
      reliable: true,
      metadata: { userId: wsClient.myUserId, color: wsClient.myColor }
    });
    setupDataConnection(peerId, peerColor, peer, conn);
  });

  peer.on('connection', (conn) => {
    // We're the host — accept incoming connection
    setupDataConnection(peerId, peerColor, peer, conn);
  });

  peer.on('error', (err) => {
    console.warn('[collab] PeerJS error:', err.message);
  });
}

function setupDataConnection(peerId, peerColor, peer, conn) {
  conn.on('open', () => {
    peers.set(peerId, { peer, conn });
    console.log('[collab] DataChannel open with', peerId);
  });

  conn.on('data', (data) => {
    handlePeerDataMessage(peerId, peerColor, data);
  });

  conn.on('close', () => {
    peers.delete(peerId);
    console.log('[collab] DataChannel closed with', peerId);
  });

  // Relay signals through WebSocket (PeerJS needs signaling server; using WS relay)
  peer.on('signal', (signal) => {
    wsClient.sendWebRTCSignal(peerId, signal);
  });

  // If we're receiving signals from remote, forward them to our peer
  wsClient.onWebRTCSignal = (fromPeerId, signal) => {
    if (fromPeerId === peerId) {
      try { peer.signal(signal); } catch (_) { /* may not be connected yet */ }
    }
  };
}

function setupPeerJSHostListener(roomCode) {
  // Host waits for incoming PeerJS connections from peers
  if (typeof Peer === 'undefined') return;
  // Already handled via conn.on('connection') in establishPeerConnection
}

function handlePeerDataMessage(peerId, peerColor, data) {
  if (data.type === 'camera_update') {
    // Low-latency camera sync via DataChannel (~3 Hz)
    applyRemoteCamera(data.camera);
    // Also update ghost cursor if selection present
    if (data.selectedId) {
      updateRemoteSelection(peerId, peerColor, data.selectedId);
    }
  } else if (data.type === 'selection_update') {
    updateRemoteSelection(peerId, peerColor, data.selectedId);
  } else if (data.type === 'cursor_update') {
    showGhostCursor(peerId, peerColor, data.position, data.screenPos);
  }
}

// Apply remote camera to local Three.js cameras (for follow mode)
function applyRemoteCamera(cameraData) {
  if (!cameraData) return;
  // Smoothly interpolate camera position (avoid jarring jumps)
  const targetPos = cameraData.position;
  const targetLook = cameraData.target;
  if (!targetPos || !targetLook) return;

  // Animate: for now, set directly (could use lerp for smoothness)
  if (cameraData.position) {
    cam3d.position.set(
      cameraData.position.x || cam3d.position.x,
      cameraData.position.y || cam3d.position.y,
      cameraData.position.z || cam3d.position.z
    );
  }
  if (cameraData.target) {
    controls3d.target.set(
      cameraData.target.x || controls3d.target.x,
      cameraData.target.y || controls3d.target.y,
      cameraData.target.z || controls3d.target.z
    );
  }
  controls3d.update();
}

function closeAllPeerConnections() {
  for (const [peerId, p] of peers) {
    try { p.conn?.close(); } catch (_) { /* ignore */ }
    try { p.peer?.destroy(); } catch (_) { /* ignore */ }
  }
  peers.clear();
}

// Send camera update to all connected peers via DataChannel (throttled)
let _lastCameraDataChannelSend = 0;
function sendCameraToPeers() {
  if (!collaborationActive) return;
  const now = Date.now();
  if (now - _lastCameraDataChannelSend < 333) return;
  _lastCameraDataChannelSend = now;

  const data = {
    type: 'camera_update',
    camera: captureCameraState(),
    selectedId: state.selectedId
  };

  for (const [, p] of peers) {
    try {
      if (p.conn?.open) p.conn.send(data);
    } catch (_) { /* ignore */ }
  }
  // Also send via WebSocket as fallback/reliability
  wsClient.sendCameraSync(captureCameraState());
}

function captureCameraState() {
  return {
    position: {
      x: cam3d.position.x, y: cam3d.position.y, z: cam3d.position.z
    },
    target: {
      x: controls3d.target.x, y: controls3d.target.y, z: controls3d.target.z
    },
    up: { x: cam3d.up.x, y: cam3d.up.y, z: cam3d.up.z }
  };
}

// ── Collaboration UI ───────────────────────────────────────────────────────────

function updateCollabSessionUI(roomCode, isHost, peerList) {
  const el = document.getElementById('collab-session');
  if (!el) return;
  el.classList.remove('hidden');
  const codeEl = document.getElementById('collab-room-code');
  if (codeEl) codeEl.textContent = roomCode;
  updateCollabSessionPeers(peerList?.length ?? 1);
}

function updateCollabSessionPeers(count) {
  const peersEl = document.getElementById('collab-peers');
  if (!peersEl) return;
  const room = wsClient.currentRoom;
  const totalPeers = (room?.peers?.size ?? 0) + 1; // +1 for self
  peersEl.innerHTML = '';
  // Show self first
  const selfDot = document.createElement('div');
  selfDot.className = 'collab-peer-avatar';
  selfDot.style.background = wsClient.myColor;
  selfDot.textContent = 'ME';
  selfDot.title = 'You';
  peersEl.appendChild(selfDot);
  // Show room peers
  if (room?.peers) {
    for (const [pid, meta] of room.peers) {
      const dot = document.createElement('div');
      dot.className = 'collab-peer-avatar';
      dot.style.background = meta.color;
      dot.textContent = pid.slice(0, 3).toUpperCase();
      dot.title = pid;
      peersEl.appendChild(dot);
    }
  }
}

function hideCollabSession() {
  const el = document.getElementById('collab-session');
  if (el) el.classList.add('hidden');
  collaborationActive = false;
}

// Ghost cursor management for collaboration — reuses ghostCursors Map declared above

function showGhostCursor(peerId, peerColor, position, screenPos) {
  if (!screenPos) return;
  let el = ghostCursors.get(peerId);
  if (!el) {
    const overlay = document.getElementById('cursor-overlay-3d');
    if (!overlay) return;
    el = document.createElement('div');
    el.className = 'ghost-cursor';
    el.innerHTML = `
      <div class="ghost-cursor-dot" style="background:${peerColor}"></div>
      <div class="ghost-cursor-label" style="background:${peerColor}">${peerId.slice(0,6)}</div>
    `;
    overlay.appendChild(el);
    ghostCursors.set(peerId, el);
  }
  el.style.left = screenPos.x + 'px';
  el.style.top = screenPos.y + 'px';
  el.style.display = 'flex';
}

function removePeerGhostCursor(peerId) {
  const el = ghostCursors.get(peerId);
  if (el) { el.remove(); ghostCursors.delete(peerId); }
}

