// ── Arcol validation modal ─────────────────────────────────────────────────────

document.getElementById('ctx-validate-arcol')?.addEventListener('click', () => {
  document.getElementById('modal-validate-arcol')?.classList.remove('hidden');
  runArcolValidation();
});

document.getElementById('cancel-validate-arcol')?.addEventListener('click', () => {
  document.getElementById('modal-validate-arcol')?.classList.add('hidden');
});

function runArcolValidation() {
  const checks = [
    { id: 'arcol-check-count', label: 'Element count', validate: () => state.elements.length > 0 },
    { id: 'arcol-check-types', label: 'Type distribution', validate: () => state.elements.some(e => e.type_name) },
    { id: 'arcol-check-materials', label: 'Material assignments', validate: () => state.elements.length > 0 },
    { id: 'arcol-check-levels', label: 'Level data', validate: () => state.levels.length > 0 },
  ];

  let passed = 0;
  for (const check of checks) {
    const el = document.getElementById(check.id);
    if (!el) continue;
    setTimeout(() => {
      const result = check.validate();
      if (result) {
        el.className = 'arcol-check-item pass';
        el.innerHTML = `<span class="arcol-check-icon">✓</span> ${check.label}: PASS (${result ? state.elements.length + ' elements' : 'check'})`;
        passed++;
      } else {
        el.className = 'arcol-check-item fail';
        el.innerHTML = `<span class="arcol-check-icon">✗</span> ${check.label}: FAIL`;
      }
      // Enable confirm button when all done
      if (passed === checks.length) {
        document.getElementById('confirm-validate-arcol').disabled = false;
        document.getElementById('confirm-validate-arcol').textContent = '→ Open Arcol';
      }
    }, 300 + checks.indexOf(check) * 250);
  }
}

document.getElementById('btn-run-arcol-validation')?.addEventListener('click', runArcolValidation);

document.getElementById('confirm-validate-arcol')?.addEventListener('click', () => {
  document.getElementById('modal-validate-arcol')?.classList.add('hidden');
  toast('Exporting IFC for Arcol…', 'info');
  const ifcContent = generateIFC();
  const blob = new Blob([ifcContent], { type: 'application/step' });
  triggerDownload(blob, `atlantist_arcol_${Date.now()}.ifc`);
  window.open('https://arcol.io', '_blank');
  toast('IFC exported — Arcol validation ready', 'success', 3000);
});

