function renderDOBChecklist() {
  const checklist = document.getElementById('dob-drawing-checklist');
  if (!checklist) return;

  const sheets = [
    { id: 'A-100', name: 'Cover Sheet & Index', required: true },
    { id: 'A-101', name: 'Floor Plans', required: true },
    { id: 'A-200', name: 'Building Elevations', required: true },
    { id: 'A-300', name: 'Building Sections', required: true },
    { id: 'A-400', name: 'Door & Window Schedule', required: false },
    { id: 'A-500', name: 'Finish Schedule', required: false },
    { id: 'EN-001', name: 'Energy Compliance', required: true },
    { id: 'EN-1', name: 'EN-1 Energy Analysis Form', required: true },
    { id: 'ZD-1', name: 'Zoning Diagram', required: true },
    { id: 'P-100', name: 'Plumbing Plans', required: false },
    { id: 'M-100', name: 'Mechanical Plans', required: false },
    { id: 'E-100', name: 'Electrical Plans', required: false },
  ];

  checklist.innerHTML = sheets.map(sheet => {
    const hasData = sheet.id.startsWith('A-') ? state.elements.length > 0 :
                   sheet.id === 'EN-1' ? document.getElementById('dob-project-name')?.value :
                   sheet.id === 'ZD-1' ? true :
                   sheet.id === 'EN-001' ? state.levels.length > 0 : false;
    const status = hasData ? 'pass' : 'pending';
    const icon = status === 'pass' ? '✓' : '○';
    return `
      <div class="dob-check-item ${status}">
        <span class="dob-check-icon">${icon}</span>
        <span class="dob-check-sheet">${sheet.id}</span>
        <span class="dob-check-label">${sheet.name}</span>
        ${sheet.required ? '<span style="font-size:9px;color:var(--text-muted);margin-left:auto">REQ</span>' : ''}
      </div>
    `;
  }).join('');
}

function loadDOBProjectSettings() {
  // Load from localStorage or use defaults
  const saved = localStorage.getItem('atlantist_dob_settings');
  if (saved) {
    const s = JSON.parse(saved);
    document.getElementById('dob-project-name').value = s.projectName || '';
    document.getElementById('dob-address').value = s.address || '';
    document.getElementById('dob-bin').value = s.bin || '';
    document.getElementById('dob-zoning-district').value = s.zoningDistrict || '';
    document.getElementById('dob-occupancy-type').value = s.occupancyType || '';
  }
  updateEN1Preview();
}

// Auto-fill EN-1 from model
document.getElementById('btn-autofill-en1')?.addEventListener('click', () => {
  // Extract model data for EN-1
  const projectName = 'Atlantist BIM Project';
  const elementCount = state.elements.length;
  const levelCount = state.levels.length;
  const wallArea = calculateTotalWallArea();
  const floorArea = calculateTotalFloorArea();
  const doorCount = state.familyInstances.filter(f => f.family_type === 'door').length;
  const windowCount = state.familyInstances.filter(f => f.family_type === 'window').length;

  // Estimate from model bounding box
  const bounds = getModelBounds();
  const lotArea = bounds ? (bounds.maxX - bounds.minX) * (bounds.maxZ - bounds.minZ) : 1000;
  const buildingArea = state.elements.length * 20; // rough estimate
  const far = lotArea > 0 ? (buildingArea / lotArea).toFixed(2) : '0.00';

  document.getElementById('dob-lot-area').textContent = lotArea.toFixed(0) + ' m²';
  document.getElementById('dob-building-coverage').textContent = (buildingArea / lotArea * 100).toFixed(1) + '%';
  document.getElementById('dob-far').textContent = far;
  document.getElementById('dob-front-yard').textContent = '5.0 m';
  document.getElementById('dob-rear-yard').textContent = '5.0 m';
  document.getElementById('dob-side-yard-l').textContent = '3.0 m';
  document.getElementById('dob-side-yard-r').textContent = '3.0 m';

  toast(`EN-1 auto-filled: ${elementCount} elements, ${levelCount} levels, FAR ${far}`, 'success', 3000);
  updateEN1Preview();
  renderDOBChecklist();
});

