function getModelBounds() {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const el of state.elements) {
    const params = typeof el.parameters === 'string' ? JSON.parse(el.parameters) : {};
    const sx = parseFloat(params.startCoord?.x || 0);
    const sy = parseFloat(params.startCoord?.y || 0);
    const ex = parseFloat(params.endCoord?.x || sx + 5);
    const ey = parseFloat(params.endCoord?.y || sy);
    const length = Math.sqrt((ex - sx) ** 2 + (ey - sy) ** 2) || 5;
    minX = Math.min(minX, sx, sx + length);
    maxX = Math.max(maxX, sx, sx + length);
    minZ = Math.min(minZ, sy, sy + length);
    maxZ = Math.max(maxZ, sy, sy + length);
  }
  if (!isFinite(minX)) return null;
  return { minX, maxX, minZ, maxZ };
}

// ─── Phase 8.4: Materials Procurement Schedule ───────────────────────────────

document.getElementById('btn-materials-schedule')?.addEventListener('click', () => {
  document.getElementById('materials-panel')?.classList.add('open');
  renderMaterialsSchedule();
});

document.getElementById('materials-panel-close')?.addEventListener('click', () => {
  document.getElementById('materials-panel')?.classList.remove('open');
});

function renderMaterialsSchedule() {
  const walls = state.elements.filter(e => e.type === 'wall');
  const columns = state.elements.filter(e => e.type === 'column');
  const doors = state.familyInstances.filter(f => f.family_type === 'door');
  const windows = state.familyInstances.filter(f => f.family_type === 'window');

  // Wall area by material
  const wallByType = {};
  for (const wall of walls) {
    const typeName = wall.type_name || 'Generic';
    if (!wallByType[typeName]) wallByType[typeName] = { count: 0, area: 0, length: 0 };
    wallByType[typeName].count++;
    const params = typeof wall.parameters === 'string' ? JSON.parse(wall.parameters) : {};
    const computed = typeof wall.computed === 'string' ? JSON.parse(wall.computed) : {};
    const sx = parseFloat(params.startCoord?.x || 0);
    const sy = parseFloat(params.startCoord?.y || 0);
    const ex = parseFloat(params.endCoord?.x || sx + 5);
    const ey = parseFloat(params.endCoord?.y || sy);
    const length = Math.sqrt((ex - sx) ** 2 + (ey - sy) ** 2) || 5;
    const height = parseFloat(computed.height || 3);
    wallByType[typeName].area += length * height;
    wallByType[typeName].length += length;
  }

  // Door types
  const doorsByType = {};
  for (const door of doors) {
    const t = door.type_name || 'Generic';
    if (!doorsByType[t]) doorsByType[t] = { count: 0, width: 0, height: 0 };
    doorsByType[t].count++;
    const params = typeof door.parameters === 'string' ? JSON.parse(door.parameters) : {};
    doorsByType[t].width = parseFloat(params.width || 0.9);
    doorsByType[t].height = parseFloat(params.height || 2.1);
  }

  // Window types
  const windowsByType = {};
  for (const win of windows) {
    const t = win.type_name || 'Generic';
    if (!windowsByType[t]) windowsByType[t] = { count: 0, width: 0, height: 0 };
    windowsByType[t].count++;
    const params = typeof win.parameters === 'string' ? JSON.parse(win.parameters) : {};
    windowsByType[t].width = parseFloat(params.width || 1.2);
    windowsByType[t].height = parseFloat(params.height || 1.5);
  }

  // Summary
  const totalWallArea = Object.values(wallByType).reduce((s, v) => s + v.area, 0);
  const totalWallLength = Object.values(wallByType).reduce((s, v) => s + v.length, 0);

  document.getElementById('materials-summary').innerHTML = `
    <div class="materials-summary-item">
      <span class="materials-summary-label">Walls</span>
      <span class="materials-summary-value">${walls.length}</span>
    </div>
    <div class="materials-summary-item">
      <span class="materials-summary-label">Area m²</span>
      <span class="materials-summary-value">${totalWallArea.toFixed(0)}</span>
    </div>
    <div class="materials-summary-item">
      <span class="materials-summary-label">Doors+Windows</span>
      <span class="materials-summary-value">${doors.length + windows.length}</span>
    </div>
  `;

  // Walls section
  const wallsEl = document.getElementById('materials-walls');
  if (wallsEl) {
    if (walls.length === 0) {
      wallsEl.innerHTML = '<div class="materials-empty">No walls in model yet.</div>';
    } else {
      wallsEl.innerHTML = Object.entries(wallByType).map(([type, data]) => `
        <div class="materials-row">
          <div>
            <div class="materials-row-label">${escHtml(type)}</div>
            <div class="materials-row-sub">${data.count} wall${data.count > 1 ? 's' : ''} · ${data.length.toFixed(1)}m total</div>
          </div>
          <div>
            <div class="materials-row-value">${data.area.toFixed(1)} m²</div>
            <div class="materials-row-sub">${(data.area * 1.2).toFixed(0)} bricks est.</div>
          </div>
        </div>
      `).join('') + `
        <div class="materials-row" style="border-top:1px solid var(--border);margin-top:4px;padding-top:8px">
          <div class="materials-row-label" style="font-weight:700;color:var(--text-primary)">Total Wall Area</div>
          <div class="materials-row-value">${totalWallArea.toFixed(1)} m²</div>
        </div>
        <div class="materials-row">
          <div class="materials-row-label" style="font-weight:700;color:var(--text-primary)">Total Wall Length</div>
          <div class="materials-row-value">${totalWallLength.toFixed(1)} m</div>
        </div>
        <div class="materials-row">
          <div class="materials-row-label">Columns</div>
          <div class="materials-row-value">${columns.length} units</div>
        </div>
      `;
    }
  }

  // Doors section
  const doorsEl = document.getElementById('materials-doors');
  if (doorsEl) {
    if (doors.length === 0) {
      doorsEl.innerHTML = '<div class="materials-empty">No doors placed yet.</div>';
    } else {
      doorsEl.innerHTML = Object.entries(doorsByType).map(([type, data]) => `
        <div class="materials-row">
          <div>
            <div class="materials-row-label">${escHtml(type)}</div>
            <div class="materials-row-sub">${data.width}×${data.height}m</div>
          </div>
          <div class="materials-row-value">${data.count} units</div>
        </div>
      `).join('') + `<div class="materials-row" style="border-top:1px solid var(--border);margin-top:4px;padding-top:8px"><div class="materials-row-label" style="font-weight:700;color:var(--text-primary)">Total Doors</div><div class="materials-row-value">${doors.length} units</div></div>`;
    }
  }

  // Windows section
  const winsEl = document.getElementById('materials-windows');
  if (winsEl) {
    if (windows.length === 0) {
      winsEl.innerHTML = '<div class="materials-empty">No windows placed yet.</div>';
    } else {
      winsEl.innerHTML = Object.entries(windowsByType).map(([type, data]) => `
        <div class="materials-row">
          <div>
            <div class="materials-row-label">${escHtml(type)}</div>
            <div class="materials-row-sub">${data.width}×${data.height}m</div>
          </div>
          <div class="materials-row-value">${data.count} units</div>
        </div>
      `).join('') + `<div class="materials-row" style="border-top:1px solid var(--border);margin-top:4px;padding-top:8px"><div class="materials-row-label" style="font-weight:700;color:var(--text-primary)">Total Windows</div><div class="materials-row-value">${windows.length} units</div></div>`;
    }
  }
}

// CSV export for materials
document.getElementById('btn-export-materials-csv')?.addEventListener('click', () => {
  const rows = [];

  // Headers
  rows.push('Category,Type,Count,Dimensions,Area m²,Notes');

  // Walls
  const walls = state.elements.filter(e => e.type === 'wall');
  for (const wall of walls) {
    const params = typeof wall.parameters === 'string' ? JSON.parse(wall.parameters) : {};
    const computed = typeof wall.computed === 'string' ? JSON.parse(wall.computed) : {};
    const sx = parseFloat(params.startCoord?.x || 0);
    const sy = parseFloat(params.startCoord?.y || 0);
    const ex = parseFloat(params.endCoord?.x || sx + 5);
    const ey = parseFloat(params.endCoord?.y || sy);
    const length = Math.sqrt((ex - sx) ** 2 + (ey - sy) ** 2) || 5;
    const height = parseFloat(computed.height || 3);
    const thick = parseFloat(computed.thickness || params.thickness || 0.2);
    rows.push(`Wall,${wall.type_name || 'Generic'},1,${length.toFixed(2)}m × ${height.toFixed(2)}m × ${thick}m,${(length * height).toFixed(2)},ID: ${wall.id}`);
  }

  // Columns
  const columns = state.elements.filter(e => e.type === 'column');
  for (const col of columns) {
    rows.push(`Column,${col.type_name || 'Generic'},1,—,—,ID: ${col.id}`);
  }

  // Doors
  const doors = state.familyInstances.filter(f => f.family_type === 'door');
  for (const door of doors) {
    const params = typeof door.parameters === 'string' ? JSON.parse(door.parameters) : {};
    rows.push(`Door,${door.type_name || 'Generic'},1,${params.width || 0.9}m × ${params.height || 2.1}m,—,Mark: ${door.mark || door.id}`);
  }

  // Windows
  const windows = state.familyInstances.filter(f => f.family_type === 'window');
  for (const win of windows) {
    const params = typeof win.parameters === 'string' ? JSON.parse(win.parameters) : {};
    rows.push(`Window,${win.type_name || 'Generic'},1,${params.width || 1.2}m × ${params.height || 1.5}m,—,Mark: ${win.mark || win.id}`);
  }

  const csv = rows.join('\n');
  const blob = new Blob([csv], { type: 'text/csv' });
  triggerDownload(blob, `atlantist_materials_${Date.now()}.csv`);
  toast(`Materials exported: ${walls.length} walls, ${columns.length} columns, ${doors.length} doors, ${windows.length} windows`, 'success');
});

// Utility helpers for Phase 8
function calculateTotalWallArea() {
  let total = 0;
  for (const wall of state.elements.filter(e => e.type === 'wall')) {
    const params = typeof wall.parameters === 'string' ? JSON.parse(wall.parameters) : {};
    const computed = typeof wall.computed === 'string' ? JSON.parse(wall.computed) : {};
    const sx = parseFloat(params.startCoord?.x || 0);
    const sy = parseFloat(params.startCoord?.y || 0);
    const ex = parseFloat(params.endCoord?.x || sx + 5);
    const ey = parseFloat(params.endCoord?.y || sy);
    const length = Math.sqrt((ex - sx) ** 2 + (ey - sy) ** 2) || 5;
    const height = parseFloat(computed.height || 3);
    total += length * height;
  }
  return total;
}

function calculateTotalFloorArea() {
  const bounds = getModelBounds();
  if (!bounds) return 0;
  return (bounds.maxX - bounds.minX) * (bounds.maxZ - bounds.minZ) * (state.levels.length || 1);
}

