// Progress simulation steps
async function animateEnergyProgress() {
  const steps = ['step-model', 'step-gbxml', 'step-idf', 'step-sim', 'step-compliance'];
  const labels = [
    'Loading model data…',
    'Generating gbXML export…',
    'Generating EnergyPlus IDF…',
    'Running ASHRAE 90.1 thermal simulation…',
    'Checking NYECC compliance (EN-001 to EN-008)…',
  ];
  const fill = document.getElementById('energy-progress-fill');
  const labelEl = document.getElementById('energy-progress-label');

  for (let i = 0; i < steps.length; i++) {
    const el = document.getElementById(steps[i]);
    if (el) {
      if (i > 0) document.getElementById(steps[i - 1])?.classList.replace('active', 'done');
      el.classList.add('active');
    }
    if (labelEl) labelEl.textContent = labels[i];
    if (fill) fill.style.width = `${Math.round((i + 0.5) / steps.length * 100)}%`;
    await new Promise(r => setTimeout(r, 350));
  }
  // Mark last step done
  document.getElementById(steps[steps.length - 1])?.classList.replace('active', 'done');
  if (fill) fill.style.width = '100%';
  if (labelEl) labelEl.textContent = 'Simulation complete.';
}

// Run energy analysis
document.getElementById('btn-run-energy')?.addEventListener('click', async () => {
  const projectName = document.getElementById('energy-project-name')?.value || 'Atlantist Building';

  // Reset steps
  ['step-model','step-gbxml','step-idf','step-sim','step-compliance'].forEach(id => {
    const el = document.getElementById(id);
    if (el) { el.className = 'energy-step pending'; }
  });

  setEnergyState('progress');

  // Start animation (runs in parallel with the actual API call)
  const animPromise = animateEnergyProgress();

  try {
    const sim = await api('POST', '/api/energy/run', { projectName });
    await animPromise; // ensure animation completes
    energyLastSim = sim;
    // Fetch year data for SimulationTimelineViewport
    try {
      const yearData = await api('GET', '/api/energy/year-data');
      sim.yearData = yearData;
    } catch (e) { /* year viz might not have run yet */ }
    setEnergyState('results');
    renderEnergyCompliance(sim);
    toast('Energy simulation complete', 'success');
  } catch (err) {
    await animPromise;
    setEnergyState('run');
    toast('Energy simulation failed: ' + err.message, 'error', 4000);
  }
});

