function renderEnergyCompliance(sim) {
  const compliance = typeof sim.compliance === 'string' ? JSON.parse(sim.compliance) : sim.compliance;
  const results = typeof sim.results === 'string' ? JSON.parse(sim.results) : sim.results;

  if (!compliance) return;

  // Update tab badges (skip EN-1 Workbook tab)
  document.querySelectorAll('.energy-tab').forEach(btn => {
    const form = btn.dataset.form;
    if (form === 'EN-1-WORKBOOK') return;
    const formData = compliance[form];
    if (formData) {
      btn.classList.toggle('pass', formData.pass);
      btn.classList.toggle('fail', !formData.pass);
    }
  });

  // Render current form
  renderEnergyForm(energyCurrentForm, sim);

  // Summary bar
  renderEnergySummaryBar(results, compliance);

  // Fetch and render guardrails compliance summary
  fetchGuardrailsSummary('energy');
}

function renderEnergyForm(formKey, sim) {
  const compliance = typeof sim.compliance === 'string' ? JSON.parse(sim.compliance) : sim.compliance;
  const formData = compliance?.[formKey];
  const el = document.getElementById('energy-compliance-content');
  if (!el || !formData) return;

  const passClass = formData.pass ? 'pass' : 'fail';
  const passLabel = formData.pass ? '✓ PASS' : '✗ FAIL';

  const itemRows = (formData.items || []).map(item => {
    let passIcon = '—';
    if (item.pass === true) passIcon = '<span style="color:var(--text-success)">✓</span>';
    else if (item.pass === false) passIcon = '<span style="color:var(--text-error)">✗</span>';
    const limitCell = item.limit !== undefined
      ? `<td class="en-limit">${item.limit}${item.unit ? ' ' + escHtml(item.unit) : ''}</td>`
      : `<td class="en-limit">—</td>`;
    return `<tr>
      <td>${escHtml(item.label)}</td>
      <td class="en-actual">${escHtml(String(item.actual))}${item.unit ? ' <span style="color:var(--text-muted);font-weight:400;font-family:var(--font)">${escHtml(item.unit)}</span>' : ''}</td>
      ${limitCell}
      <td class="en-pass-icon">${passIcon}</td>
    </tr>`;
  }).join('');

  el.innerHTML = `
    <div class="en-form-header">
      <div class="en-form-badge ${passClass}">${passLabel}</div>
      <div class="en-form-title">${escHtml(formKey)}: ${escHtml(formData.title)}</div>
    </div>
    <div class="en-form-desc">${escHtml(formData.description)}</div>
    <table class="en-items-table">
      <thead><tr>
        <th>Parameter</th>
        <th>Actual</th>
        <th>Code Limit</th>
        <th></th>
      </tr></thead>
      <tbody>${itemRows}</tbody>
    </table>`;
}

function renderEnergySummaryBar(results, compliance) {
  const el = document.getElementById('energy-summary-bar');
  if (!el || !results) return;

  const passCount = Object.values(compliance).filter(f => f.pass).length;
  const totalCount = Object.values(compliance).length;
  const allPass = passCount === totalCount;

  el.innerHTML = `
    <div class="energy-summary-item">
      <div class="energy-summary-label">EUI</div>
      <div class="energy-summary-value ${results.EUI <= 250 ? 'pass' : 'fail'}">${results.EUI?.toFixed(1)} <span style="font-size:10px;font-weight:400">kBtu/ft²/yr</span></div>
    </div>
    <div class="energy-summary-item">
      <div class="energy-summary-label">Peak Heating</div>
      <div class="energy-summary-value">${results.peakHeatingKW?.toFixed(1)} <span style="font-size:10px;font-weight:400">kW</span></div>
    </div>
    <div class="energy-summary-item">
      <div class="energy-summary-label">Peak Cooling</div>
      <div class="energy-summary-value">${results.peakCoolingKW?.toFixed(1)} <span style="font-size:10px;font-weight:400">kW</span></div>
    </div>
    <div class="energy-summary-item">
      <div class="energy-summary-label">Floor Area</div>
      <div class="energy-summary-value">${results.grossFloorAreaM2?.toFixed(0)} <span style="font-size:10px;font-weight:400">m²</span></div>
    </div>
    <div class="energy-summary-item">
      <div class="energy-summary-label">Compliance</div>
      <div class="energy-summary-value ${allPass ? 'pass' : 'fail'}">${passCount}/${totalCount} <span style="font-size:10px;font-weight:400">forms pass</span></div>
    </div>`;
}

// Fetch guardrails for geotech after analysis with actual soil parameters
async function fetchGuardrailsForGeo(params) {
  const panel = document.getElementById('geo-guardrails-panel');
  const htmlEl = document.getElementById('geo-guardrails-html');
  const designEl = document.getElementById('geo-guardrails-design');
  if (!panel || !htmlEl || !designEl) return;

  try {
    const resp = await api('POST', '/api/guardrails/validate', {
      simType: 'geotech',
      inputs: {
        cohesion: params.c || 0,
        frictionAngle: params.phi || 0,
        unitWeight: params.gamma || 0,
        elasticModulus: params.E || 0,
        foundationWidth: params.B || 0,
        foundationDepth: params.D || 0,
        groundwaterDepth: params.gwDepth || 0,
      },
    });
    panel.style.display = resp.valid ? 'none' : 'block';
    htmlEl.innerHTML = resp.validationHtml || '';
    designEl.innerHTML = resp.guidanceHtml || '';
  } catch (e) {
    panel.style.display = 'none';
  }
}

// Fetch and display guardrails compliance summary for a simulation type
async function fetchGuardrailsSummary(simType) {
  const panel = document.getElementById(simType + '-guardrails-panel');
  const htmlEl = document.getElementById(simType + '-guardrails-html');
  const designEl = document.getElementById(simType + '-guardrails-design');
  if (!panel || !htmlEl || !designEl) return;

  try {
    const resp = await api('GET', `/api/${simType}/compliance-summary`);
    if (!resp.hasResults) { panel.style.display = 'none'; return; }
    panel.style.display = 'block';
    htmlEl.innerHTML = resp.html || '';
    designEl.innerHTML = resp.designHtml || '';
  } catch (e) {
    console.warn('[guardrails] Could not load compliance summary for', simType, e.message);
    panel.style.display = 'none';
  }
}

