// ─── Updates Tab (What's New) ─────────────────────────────────────────

let _updatesState = { updates: [], unreadCount: 0 };

async function loadUpdatesForModal() {
  try {
    const res = await fetch('/api/updates/latest');
    const data = await res.json();
    _updatesState.updates = data.updates || [];
    _updatesState.unreadCount = data.unread_count || 0;
  } catch {
    _updatesState.updates = [];
    _updatesState.unreadCount = 0;
  }
}

async function refreshUpdatesUnreadCount() {
  try {
    const res = await fetch('/api/updates/latest');
    const data = await res.json();
    _updatesState.unreadCount = data.unread_count || 0;
    const btn = document.getElementById('btn-guide');
    if (!btn) return;
    // Remove existing badge
    const existing = btn.querySelector('.update-badge-dot');
    if (existing) existing.remove();
    // Add badge if unread
    if (_updatesState.unreadCount > 0) {
      const badge = document.createElement('span');
      badge.className = 'update-badge-dot';
      badge.textContent = _updatesState.unreadCount > 9 ? '9+' : _updatesState.unreadCount;
      btn.appendChild(badge);
    }
  } catch {
    // Non-blocking
  }
  // Also update the in-modal tab badge
  const modalBadge = document.getElementById('guide-updates-count-badge');
  if (modalBadge) {
    if (_updatesState.unreadCount > 0) {
      modalBadge.textContent = _updatesState.unreadCount > 9 ? '9+' : _updatesState.unreadCount;
      modalBadge.style.display = 'inline';
    } else {
      modalBadge.style.display = 'none';
    }
  }
}

function renderGuideUpdatesTab() {
  const content = document.getElementById('guide-content');
  if (!_updatesState.updates.length) {
    content.innerHTML = `
      <div style="text-align:center;padding:40px 20px;color:var(--text-muted)">
        <div style="font-size:28px;margin-bottom:12px">✨</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:6px">All caught up!</div>
        <div style="font-size:12px">No new updates. Check back after the next release.</div>
      </div>`;
    return;
  }

  const CATEGORY_LABELS = {
    feature: 'Feature',
    bugfix: 'Bug Fix',
    improvement: 'Improvement',
    breaking: 'Breaking'
  };
  const CATEGORY_COLORS = {
    feature: 'rgba(91,155,213,.2)',
    bugfix: 'rgba(239,68,68,.2)',
    improvement: 'rgba(249,115,22,.2)',
    breaking: 'rgba(239,68,68,.4)'
  };
  const CATEGORY_TEXT = {
    feature: '#5b9bd5',
    bugfix: '#f87171',
    improvement: '#fb923c',
    breaking: '#f87171'
  };

  const html = `
    <div style="padding:0 4px">
      <div style="font-size:11px;color:var(--text-muted);margin-bottom:12px;text-align:right">
        ${_updatesState.unreadCount > 0 ? `<strong>${_updatesState.unreadCount}</strong> unread` : 'All read'}
      </div>
    </div>
    <div class="guide-updates-list">
      ${_updatesState.updates.map(u => {
        const cat = u.category || 'feature';
        return `
        <div class="guide-update-card" data-id="${u.id}" style="border:1px solid var(--border);border-radius:8px;padding:14px;margin-bottom:10px;cursor:pointer;transition:border-color .15s" onclick="openGuideUpdateItem(${u.id})">
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
            ${u.badge ? `<span style="background:${CATEGORY_COLORS[cat]};color:${CATEGORY_TEXT[cat]};font-size:10px;font-weight:700;padding:2px 6px;border-radius:4px;text-transform:uppercase">${u.badge}</span>` : ''}
            <span style="background:${CATEGORY_COLORS[cat]}22;color:${CATEGORY_TEXT[cat]};font-size:10px;font-weight:600;padding:2px 6px;border-radius:4px">${CATEGORY_LABELS[cat] || cat}</span>
            ${u.version ? `<span style="font-size:10px;color:var(--text-muted)">v${u.version}</span>` : ''}
          </div>
          <div style="font-size:13px;font-weight:600;color:var(--text-primary);margin-bottom:4px">${_escapeHtml(u.title || '')}</div>
          <div style="font-size:12px;color:var(--text-secondary);line-height:1.5;margin-bottom:8px">${_escapeHtml(u.body || '')}</div>
          ${u.action_label ? `
            <button class="guide-update-action-btn" style="background:var(--accent);color:white;border:none;border-radius:5px;padding:5px 12px;font-size:11px;font-weight:600;cursor:pointer">
              ${u.action_label}
            </button>` : ''}
          <div style="font-size:10px;color:var(--text-muted);margin-top:8px">${_formatRelativeTime(u.created_at)}</div>
        </div>`;
      }).join('')}
    </div>`;
  content.innerHTML = html;
}

function _escapeHtml(str) {
  return String(str || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

async function openGuideUpdateItem(id) {
  const update = _updatesState.updates.find(u => u.id === id);
  if (!update) return;
  if (authState.authenticated) {
    fetch(`/api/updates/${id}/seen`, { method: 'POST', credentials: 'include' }).catch(() => {});
  }
  if (update.action_url) {
    closeGuideModal();
    document.getElementById('btn-guide').click();
    return;
  }
  _updatesState.updates = _updatesState.updates.filter(u => u.id !== id);
  refreshUpdatesUnreadCount();
  renderGuideUpdatesTab();
}

