let _submitStepCount = 1;
window.addSubmitStep = function() {
  _submitStepCount++;
  const list = document.getElementById('submit-steps-list');
  const row = document.createElement('div');
  row.className = 'guide-step-row';
  row.innerHTML = `<span class="guide-step-row-num">${_submitStepCount}</span><input type="text" placeholder="Step ${_submitStepCount} description…" class="submit-step-input" data-step="${_submitStepCount}">`;
  list.appendChild(row);
};

window.submitGuide = async function(e) {
  e.preventDefault();
  const successEl = document.getElementById('guide-submit-success');
  const errorEl = document.getElementById('guide-submit-error');
  successEl.classList.add('hidden');
  errorEl.classList.add('hidden');

  const steps = [];
  document.querySelectorAll('.submit-step-input').forEach((inp, i) => {
    if (inp.value.trim()) {
      steps.push({ order: i + 1, title: inp.value.trim(), content: '' });
    }
  });

  if (steps.length === 0) { errorEl.textContent = 'Add at least one step'; errorEl.classList.remove('hidden'); return; }

  try {
    const res = await fetch('/api/guides/submit', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        category_slug: document.getElementById('submit-category').value,
        title: document.getElementById('submit-title').value,
        difficulty: document.getElementById('submit-difficulty').value,
        time_estimate: document.getElementById('submit-time').value,
        steps,
        tags: []
      })
    });
    if (!res.ok) {
      let msg = 'Failed';
      try { msg = (await res.json()).error || res.statusText; } catch { msg = `HTTP ${res.status}`; }
      throw new Error(msg);
    }
    successEl.classList.remove('hidden');
    document.getElementById('guide-submit-form').reset();
    _submitStepCount = 1;
  } catch(err) {
    errorEl.textContent = err.message;
    errorEl.classList.remove('hidden');
  }
};

async function openGuide(slug) {
  try {
    const res = await fetch(`/api/guides/guide/${slug}`);
    if (!res.ok) return;
    const data = await res.json();
    _guideState.currentGuide = data.guide;
    renderGuideReader(data.guide);
  } catch (e) { console.error('[guides] open guide error', e); }
}

function renderGuideReader(guide) {
  const content = document.getElementById('guide-content');
  const tier = getUserTier();

  // Get existing progress
  const existingProgress = _guideState.userProgress.find(p => p.guide_id === guide.id);
  const completedSteps = existingProgress ? (existingProgress.completed_steps || []) : [];
  const allSteps = typeof guide.steps === 'string' ? JSON.parse(guide.steps) : (guide.steps || []);
  const completedCount = allSteps.filter((s, i) => completedSteps.includes(s.order)).length;
  const pct = allSteps.length > 0 ? Math.round((completedCount / allSteps.length) * 100) : 0;

  content.innerHTML = `
    <div class="guide-reader-header">
      <button class="guide-back-btn" onclick="switchGuideTab('browse')">← Guides</button>
      <div style="flex:1">
        <div style="font-size:15px;font-weight:600;color:var(--text-primary)">${guide.title}</div>
        <div style="font-size:11px;color:var(--text-muted);margin-top:2px">${guide.difficulty} · ${guide.time_estimate || ''}</div>
      </div>
    </div>
    ${guide.summary ? `<div style="font-size:12px;color:var(--text-secondary);padding:8px 10px;background:var(--bg-panel-hover);border:1px solid var(--border);border-radius:6px;margin-bottom:10px;line-height:1.5">${guide.summary}</div>` : ''}
    <div style="font-size:11px;color:var(--text-muted);margin-bottom:8px">${completedCount}/${allSteps.length} steps complete · ${pct}%</div>
    <div class="guide-reader-steps">
      ${allSteps.map((step, idx) => {
        const isDone = completedSteps.includes(step.order);
        return `
          <div class="guide-step-card">
            <div class="guide-step-header">
              <div class="guide-step-num">${step.order}</div>
              <div class="guide-step-title">${step.title}</div>
              <button class="guide-step-check${isDone ? ' checked' : ''}" onclick="toggleGuideStep(${guide.id}, ${step.order}, this)" title="${isDone ? 'Mark incomplete' : 'Mark complete'}">
                ${isDone ? '✓' : ''}
              </button>
            </div>
            ${step.content ? `<div class="guide-step-body">${step.content}</div>` : ''}
            ${step.action_url ? `<button class="guide-step-action" onclick="handleGuideStepAction('${step.action_url}')">▶ Try it now${step.action_label ? ' — ' + step.action_label : ''}</button>` : ''}
          </div>
        `;
      }).join('')}
    </div>
    <div class="guide-completion-row">
      <input type="checkbox" id="guide-complete-cb" ${completedCount === allSteps.length ? 'checked' : ''} onchange="markGuideComplete(${guide.id}, this.checked)">
      <label class="guide-completion-label" for="guide-complete-cb">Mark as complete</label>
      ${pct >= 100 ? `<button class="guide-complete-btn" onclick="switchGuideTab('progress')">View Progress →</button>` : ''}
    </div>
  `;
}

window.toggleGuideStep = async function(guideId, stepOrder, btn) {
  const guide = _guideState.currentGuide;
  if (!guide) return;
  const allSteps = typeof guide.steps === 'string' ? JSON.parse(guide.steps) : (guide.steps || []);
  const existingProgress = _guideState.userProgress.find(p => p.guide_id === guideId);
  let completedSteps = existingProgress ? [...(existingProgress.completed_steps || [])] : [];

  if (completedSteps.includes(stepOrder)) {
    completedSteps = completedSteps.filter(s => s !== stepOrder);
    btn.classList.remove('checked');
    btn.textContent = '';
  } else {
    completedSteps.push(stepOrder);
    btn.classList.add('checked');
    btn.textContent = '✓';
  }

  const completedCount = allSteps.filter(s => completedSteps.includes(s.order)).length;
  const pct = allSteps.length > 0 ? Math.round((completedCount / allSteps.length) * 100) : 0;

  try {
    const res = await fetch('/api/guides/progress', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ guide_id: guideId, completed_steps: completedSteps, progress_pct: pct })
    });
    if (res.ok) {
      const data = await res.json();
      // Update local state
      const existing = _guideState.userProgress.find(p => p.guide_id === guideId);
      if (existing) {
        existing.completed_steps = completedSteps;
        existing.progress_pct = pct;
        existing.completed = pct >= 100;
      } else {
        _guideState.userProgress.push(data.progress);
      }
      // Update completion row
      const cb = document.getElementById('guide-complete-cb');
      if (cb) cb.checked = completedCount === allSteps.length;
    }
  } catch (e) { console.error('[guides] step toggle error', e); }
};

window.markGuideComplete = async function(guideId, completed) {
  try {
    if (completed) {
      await fetch('/api/guides/progress/complete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ guide_id: guideId })
      });
    }
    // Update local progress state
    const existing = _guideState.userProgress.find(p => p.guide_id === guideId);
    if (existing) {
      existing.completed = completed;
      if (completed) existing.progress_pct = 100;
    }
  } catch (e) { console.error('[guides] mark complete error', e); }
};

