function _tierLabel(tier) {
  return tier;
}

// ─── Landing Modal (early access opt-in) ───────────────────────

function setupLandingModal() {
  // Check if this is a returning user (skip landing)
  if (localStorage.getItem('atlantist_landed')) return;

  // Show landing on first visit
  const urlParams = new URLSearchParams(window.location.search);
  if (!urlParams.has('magic_token') && !urlParams.has('lead_verify') && !urlParams.has('magic_error')) {
    // Small delay so the app can initialize first
    setTimeout(() => showModal('modal-landing'), 800);
  }

  document.getElementById('landing-submit')?.addEventListener('click', async () => {
    const email = document.getElementById('landing-email')?.value.trim();
    const consent = document.getElementById('landing-consent')?.checked;
    if (!email) { const e = document.getElementById('landing-error'); if (e) { e.textContent = 'Email required'; e.classList.remove('hidden'); } return; }
    if (!consent) { const e = document.getElementById('landing-error'); if (e) { e.textContent = 'Please agree to receive updates'; e.classList.remove('hidden'); } return; }

    try {
      const res = await fetch('/api/leads', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, source: 'landing_page', consent_given: true })
      });
      if (!res.ok) throw new Error((await res.json()).error || 'Failed');
      document.getElementById('landing-success')?.classList.remove('hidden');
      document.getElementById('landing-error')?.classList.add('hidden');
      setTimeout(() => {
        hideModal('modal-landing');
        localStorage.setItem('atlantist_landed', '1');
      }, 2000);
    } catch (err) {
      const e = document.getElementById('landing-error');
      if (e) { e.textContent = err.message; e.classList.remove('hidden'); }
    }
  });

  document.getElementById('landing-skip')?.addEventListener('click', e => {
    e.preventDefault();
    hideModal('modal-landing');
    localStorage.setItem('atlantist_landed', '1');
  });
}

// ─── Opt-in Toast Modal ────────────────────────────────────────

function showOptinModal(title = 'Get product updates', desc = 'Be the first to know about new features.', source = 'landing_page') {
  const titleEl = document.getElementById('optin-title');
  const descEl = document.getElementById('optin-desc');
  if (titleEl) titleEl.textContent = title;
  if (descEl) descEl.textContent = desc;
  showModal('modal-optin');
  document.getElementById('optin-email')?.focus();
  document.getElementById('optin-email')._optin_source = source;
}

function setupOptinModal() {
  document.getElementById('optin-submit')?.addEventListener('click', async () => {
    const email = document.getElementById('optin-email')?.value.trim();
    const consent = document.getElementById('optin-consent')?.checked;
    if (!email) { const e = document.getElementById('optin-error'); if (e) { e.textContent = 'Email required'; e.classList.remove('hidden'); } return; }
    if (!consent) { const e = document.getElementById('optin-error'); if (e) { e.textContent = 'Please agree to receive updates'; e.classList.remove('hidden'); } return; }

    const source = document.getElementById('optin-email')._optin_source || 'landing_page';
    try {
      const res = await fetch('/api/leads', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, source, consent_given: true })
      });
      if (!res.ok) throw new Error((await res.json()).error || 'Failed');
      document.getElementById('optin-success')?.classList.remove('hidden');
      document.getElementById('optin-error')?.classList.add('hidden');
      setTimeout(() => {
        hideModal('modal-optin');
        document.getElementById('optin-email').value = '';
        document.getElementById('optin-success')?.classList.add('hidden');
      }, 2500);
    } catch (err) {
      const e = document.getElementById('optin-error');
      if (e) { e.textContent = err.message; e.classList.remove('hidden'); }
    }
  });

  // Close on overlay click for opt-in
  document.getElementById('modal-optin')?.addEventListener('click', e => {
    if (e.target === document.getElementById('modal-optin')) hideModal('modal-optin');
  });
}

// ─── Lead Verification Feedback ─────────────────────────────────

function initLeadVerifyFeedback() {
  const params = new URLSearchParams(window.location.search);
  if (params.has('lead_verify') && params.get('lead_verify') === 'success') {
    setTimeout(() => toast('Email confirmed! You\u2019re subscribed.', 'success'), 500);
    history.replaceState({}, '', window.location.pathname);
  }
  if (params.has('lead_verify_error')) {
    const msgs = { invalid: 'Invalid verification link.', expired: 'Verification link expired.', server: 'Server error. Try again.' };
    const msg = msgs[params.get('lead_verify_error')] || 'Verification failed.';
    setTimeout(() => toast(msg, 'error'), 500);
    history.replaceState({}, '', window.location.pathname);
  }
}

// ─── Help Button (topbar) ───────────────────────────────────────

function addHelpButton() {
  const topbarRight = document.querySelector('.topbar-right');
  if (!topbarRight) return;
  // Check if already added
  if (document.getElementById('btn-help')) return;
  const helpBtn = document.createElement('button');
  helpBtn.className = 'tb-btn';
  helpBtn.id = 'btn-help';
  helpBtn.title = 'Help & Documentation';
  helpBtn.textContent = '❓ Help';
  helpBtn.style.marginLeft = '8px';
  helpBtn?.addEventListener('click', () => showModal('modal-help'));
  // Insert before presence bar
  const presence = document.getElementById('presence-bar');
  if (presence) topbarRight.insertBefore(helpBtn, presence);
  else topbarRight.appendChild(helpBtn);
}

// ─── Status Dot (topbar) — poll /status.json every 60s ─────────

let _statusDotInterval = null;

function initStatusDot() {
  const dot = document.getElementById('status-indicator');
  if (!dot) return;

  async function checkStatus() {
    try {
      const res = await fetch('/status.json');
      if (!res.ok) throw new Error('non-200');
      const ct = (res.headers.get('content-type') || '');
      if (!ct.includes('application/json')) {
        const text = await res.text().catch(() => '');
        throw new Error(`Expected JSON from /status.json but got Content-Type: ${ct}; body: ${text.slice(0, 200)}`);
      }
      const data = await res.json();
      if (data.status === 'operational') {
        dot.style.background = '#3bba6c';
        dot.title = 'All systems operational';
      } else if (data.status === 'degraded') {
        dot.style.background = '#f0a030';
        dot.title = 'Some services degraded';
      } else {
        dot.style.background = '#e84855';
        dot.title = 'Service disruption detected';
      }
    } catch {
      dot.style.background = '#e84855';
      dot.title = 'System status unavailable';
    }
  }

  checkStatus();
  _statusDotInterval = setInterval(checkStatus, 60000);
}

// ─── Version History Panel ──────────────────────────────────

// Active project id — read from authState on project open
function getHistoryProjectId() {
  // Use the project ID from the current project detail (set by showProjectDetail)
  if (window.atlantistActiveProjectId) return window.atlantistActiveProjectId;
  const stored = localStorage.getItem('atlantist_active_project_id');
  return stored || null;
}

// Show/hide the History button based on role (admin or project owner)
function updateHistoryButtonVisibility(projectId) {
  const btn = document.getElementById('btn-history');
  if (!btn) return;
  // Show if admin role (checked from authState which is set on session init)
  if (authState.app_role === 'admin') {
    btn.classList.remove('hidden');
  }
}

// Call this after session init resolves
function maybeShowHistoryButton() {
  if (authState.app_role === 'admin') {
    const btn = document.getElementById('btn-history');
    if (btn) btn.classList.remove('hidden');
  }
}

function setupHistoryButton() {
  const btn = document.getElementById('btn-history');
  if (!btn) return;

  btn?.addEventListener('click', () => {
    const projectId = getHistoryProjectId();
    if (!projectId) {
      toast('Open a project to view its history.', 'info');
      return;
    }
    openHistoryPanel(projectId);
  });
}

let _historyPage = 0;
let _historyHasMore = false;
let _historyProjectId = null;

async function openHistoryPanel(projectId) {
  _historyProjectId = projectId;
  _historyPage = 0;
  const modal = document.getElementById('modal-history');
  const subtitle = document.getElementById('history-subtitle');

  document.getElementById('history-loading').classList.remove('hidden');
  document.getElementById('history-events').classList.add('hidden');
  document.getElementById('history-empty').classList.add('hidden');
  document.getElementById('history-load-more').classList.add('hidden');

  modal.classList.remove('hidden');
  modal.style.display = 'flex';
  subtitle.textContent = `Model #${projectId} — loading…`;

  await loadHistoryEvents(projectId, 0);
}

async function loadHistoryEvents(projectId, offset) {
  const loading = document.getElementById('history-loading');
  const eventsEl = document.getElementById('history-events');
  const emptyEl = document.getElementById('history-empty');
  const loadMoreEl = document.getElementById('history-load-more');
  const loadMoreBtn = document.getElementById('history-load-more-btn');
  const subtitle = document.getElementById('history-subtitle');

  loading.classList.remove('hidden');
  emptyEl.classList.add('hidden');

  try {
    const limit = 50;
    const res = await authApi('GET', `/api/events/models/${projectId}/history?limit=${limit}&offset=${offset}`);
    loading.classList.add('hidden');

    const events = res.events || [];
    _historyHasMore = res.has_more;
    _historyPage = offset;

    if (offset === 0 && events.length === 0) {
      eventsEl.classList.add('hidden');
      emptyEl.classList.remove('hidden');
      subtitle.textContent = `Model #${projectId} — no events yet`;
      return;
    }

    eventsEl.classList.remove('hidden');

    // Group by 5-minute sessions
    const grouped = groupEventsBySession(events);

    if (offset === 0) {
      eventsEl.innerHTML = grouped.map(g => renderEventGroup(g, offset)).join('');
    } else {
      eventsEl.insertAdjacentHTML('beforeend', grouped.map(g => renderEventGroup(g, offset)).join(''));
    }

    subtitle.textContent = `Model #${projectId} — ${res.events.length} event${res.events.length !== 1 ? 's' : ''}`;

    loadMoreEl.classList.toggle('hidden', !_historyHasMore);
    bindEventGroupInteractions();
  } catch (err) {
    loading.classList.add('hidden');
    eventsEl.classList.remove('hidden');
    eventsEl.innerHTML = `<div style="padding:20px;color:#e84855;font-size:13px">Error loading history: ${err.message}</div>`;
  }
}

function groupEventsBySession(events) {
  // Returns array of session groups, each containing events within 5 minutes
  const groups = [];
  let currentGroup = null;
  const SESSION_GAP_MS = 5 * 60 * 1000; // 5 minutes

  for (const event of events) {
    const eventTime = new Date(event.created_at).getTime();
    if (!currentGroup || (eventTime - currentGroup.lastTime) > SESSION_GAP_MS) {
      currentGroup = { sessionStart: eventTime, lastTime: eventTime, events: [] };
      groups.push(currentGroup);
    }
    currentGroup.events.push(event);
    currentGroup.lastTime = Math.max(currentGroup.lastTime, eventTime);
  }
  return groups;
}

function renderEventGroup(group, baseOffset) {
  const sessionTime = new Date(group.sessionStart).toLocaleString();
  const hasMany = group.events.length > 1;
  return `
    <div class="history-session" style="border-bottom:1px solid var(--border)">
      <div class="history-session-header" style="padding:8px 20px;display:flex;align-items:center;gap:10px;background:rgba(255,255,255,.03);font-size:12px;color:var(--text-muted)">
        <span style="font-weight:600">${hasMany ? '◆' : '◇'}</span>
        <span class="history-session-time">${sessionTime}</span>
        <span class="history-session-count">${group.events.length} event${group.events.length !== 1 ? 's' : ''}</span>
      </div>
      ${group.events.map((e, i) => renderEventRow(e, baseOffset, i)).join('')}
    </div>
  `;
}

function renderEventRow(event, baseOffset, rowIdx) {
  const globalIdx = baseOffset + rowIdx;
  const userName = event.user_name || event.triggered_by || 'System';
  const userInitial = userName.charAt(0).toUpperCase();
  const time = new Date(event.created_at);
  const localTime = time.toLocaleTimeString();
  const utcTime = time.toUTCString();
  const summary = event.summary || event.event_type;
  const isRevert = event.event_type === 'model.reverted' || event.event_type === 'element.reverted';
  const canRevert = event.can_revert !== false;

  return `
    <div class="history-event-row" data-event-id="${event.id}" data-event-type="${event.event_type}" style="padding:10px 20px;display:flex;align-items:flex-start;gap:10px;cursor:pointer" title="${utcTime}">
      <div style="width:24px;height:24px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:#fff;flex-shrink:0;margin-top:2px">${userInitial}</div>
      <div style="flex:1;min-width:0">
        <div style="font-size:13px;font-weight:500;color:var(--text-primary);margin-bottom:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escHtml(summary)}</div>
        <div style="font-size:11px;color:var(--text-muted)">${escHtml(userName)} · ${localTime}</div>
      </div>
      ${isRevert ? `<span style="background:#92400e;color:#fef3c7;border-radius:4px;padding:2px 7px;font-size:10px;font-weight:600;flex-shrink:0">REVERT</span>` : ''}
      ${canRevert ? `<button class="btn-revert-point" data-event-id="${event.id}" style="background:rgba(217,119,6,.15);color:#d97706;border:1px solid #92400e;border-radius:5px;padding:4px 10px;font-size:11px;font-weight:600;cursor:pointer;flex-shrink:0;white-space:nowrap">Revert to this point</button>` : ''}
    </div>
    <div class="history-event-detail hidden" id="detail-${event.id}" style="padding:8px 20px 12px 54px;font-size:12px;color:var(--text-muted);background:rgba(255,255,255,.01);border-bottom:1px solid var(--border)">
      <div style="font-weight:600;color:var(--text-secondary);margin-bottom:4px">Event JSON</div>
      <pre style="background:#1a1a2e;border:1px solid #333;border-radius:4px;padding:8px;overflow:auto;font-size:11px;max-height:200px;margin:0">${JSON.stringify(event, null, 2)}</pre>
    </div>
  `;
}

function bindEventGroupInteractions() {
  document.querySelectorAll('.history-event-row').forEach(row => {
    row?.addEventListener('click', (e) => {
      if (e.target.closest('.btn-revert-point')) return;
      const detail = document.getElementById('detail-' + row.dataset.eventId);
      if (detail) detail.classList.toggle('hidden');
    });
  });

  document.querySelectorAll('.btn-revert-point').forEach(btn => {
    btn?.addEventListener('click', (e) => {
      e.stopPropagation();
      openConfirmRevert(btn.dataset.eventId);
    });
  });
}

async function openConfirmRevert(eventId) {
  const modal = document.getElementById('modal-confirm-revert');
  const body = document.getElementById('confirm-revert-body');
  const errorDiv = document.getElementById('confirm-revert-error');

  errorDiv.classList.add('hidden');
  modal.classList.remove('hidden');
  modal.style.display = 'flex';
  body.textContent = 'Loading diff summary…';

  try {
    const res = await authApi('GET', `/api/events/models/${_historyProjectId}/revert/diff?target_event_id=${eventId}`);
    const count = res.undone_event_count || 0;
    const users = res.undone_user_count || 0;
    const date = new Date(res.target_created_at).toLocaleString();
    body.innerHTML = `Reverting will undo <strong>${count} change${count !== 1 ? 's' : ''}</strong> from <strong>${users} user${users !== 1 ? 's' : ''}</strong> since <strong>${date}</strong>.<br><br>This creates a new checkpoint — no history is deleted and this action itself can be reverted later.`;

    document.getElementById('confirm-revert-confirm').onclick = () => executeRevert(eventId, 'model');
  } catch (err) {
    body.textContent = `Could not load diff summary. Proceed anyway? (Error: ${err.message})`;
    document.getElementById('confirm-revert-confirm').onclick = () => executeRevert(eventId, 'model');
  }
}

async function executeRevert(eventId, scope) {
  const errorDiv = document.getElementById('confirm-revert-error');
  const confirmBtn = document.getElementById('confirm-revert-confirm');
  errorDiv.classList.add('hidden');
  confirmBtn.disabled = true;
  confirmBtn.textContent = 'Reverting…';

  try {
    const res = await authApi('POST', `/api/events/models/${_historyProjectId}/revert`, {
      target_event_id: parseInt(eventId, 10),
      scope: scope || null
    });

    toast(`Model reverted — ${res.undone_event_count} changes undone`, 'success');

    // Close both modals
    document.getElementById('modal-confirm-revert').classList.add('hidden');
    document.getElementById('modal-history').classList.add('hidden');

    // Reload the scene
    await loadAll();

    // Notify WebSocket clients
    try {
      if (wsClient && wsClient.ws && wsClient.ws.readyState === 1) {
        wsClient.ws.send(JSON.stringify({ type: 'model.snapshot.replaced', project_id: _historyProjectId }));
      }
    } catch (_) {}
  } catch (err) {
    errorDiv.textContent = err.message;
    errorDiv.classList.remove('hidden');
    confirmBtn.disabled = false;
    confirmBtn.textContent = 'Revert to this point';
  }
}

function setupHistoryPanel() {
  document.getElementById('history-close')?.addEventListener('click', () => {
    const m = document.getElementById('modal-history');
    m.classList.add('hidden'); m.style.display = '';
  });

  document.getElementById('modal-history')?.addEventListener('click', (e) => {
    if (e.target.id === 'modal-history') {
      const m = document.getElementById('modal-history');
      m.classList.add('hidden'); m.style.display = '';
    }
  });

  document.getElementById('history-load-more-btn')?.addEventListener('click', () => {
    loadHistoryEvents(_historyProjectId, _historyPage + 50);
  });

  // Filter
  document.getElementById('history-filter-type')?.addEventListener('change', (e) => {
    const filter = e.target.value;
    document.querySelectorAll('.history-event-row').forEach(row => {
      if (!filter) { row.style.display = ''; return; }
      const type = row.dataset.eventType;
      row.style.display = type.includes(filter) ? '' : 'none';
    });
  });

  document.getElementById('confirm-revert-close')?.addEventListener('click', () => {
    const m = document.getElementById('modal-confirm-revert');
    m.classList.add('hidden'); m.style.display = '';
  });

  document.getElementById('confirm-revert-cancel')?.addEventListener('click', () => {
    const m = document.getElementById('modal-confirm-revert');
    m.classList.add('hidden'); m.style.display = '';
  });

  document.getElementById('modal-confirm-revert')?.addEventListener('click', (e) => {
    if (e.target.id === 'modal-confirm-revert') {
      const m = document.getElementById('modal-confirm-revert');
      m.classList.add('hidden'); m.style.display = '';
    }
  });

  setupHistoryButton();
}

