let currentProjectDetail = null;

async function showProjectsModal() {
  showModal('modal-projects');
  // Reset to list view
  document.getElementById('projects-list').classList.remove('hidden');
  document.getElementById('projects-toolbar').classList.remove('hidden');
  document.getElementById('create-project-form').classList.add('hidden');
  document.getElementById('project-detail').classList.add('hidden');
  await loadProjects();
}

async function loadProjects() {
  const listEl = document.getElementById('projects-list');
  listEl.innerHTML = '<div class="projects-loading">Loading projects…</div>';

  try {
    const projects = await authApi('GET', '/api/projects');
    renderProjectsList(projects);
  } catch (err) {
    listEl.innerHTML = `<div class="projects-loading" style="color:var(--text-error)">Error: ${err.message}</div>`;
  }
}

function renderProjectsList(projects) {
  const listEl = document.getElementById('projects-list');
  const countEl = document.getElementById('projects-count');
  countEl.textContent = `${projects.length} project${projects.length !== 1 ? 's' : ''}`;

  if (projects.length === 0) {
    listEl.innerHTML = '<div class="projects-loading">No projects yet. Create your first project!</div>';
    return;
  }

  listEl.innerHTML = projects.map(p => `
    <div class="project-card" data-id="${p.id}">
      <div class="project-card-icon">📁</div>
      <div class="project-card-info">
        <div class="project-card-name">${escapeHtml(p.name)}</div>
        <div class="project-card-meta">${p.member_count || 1} member${(p.member_count || 1) !== 1 ? 's' : ''} · ${p.type || 'Mixed'}</div>
      </div>
      <span class="project-card-type">${p.type || 'Mixed'}</span>
    </div>
  `).join('');

  // Click to show detail
  listEl.querySelectorAll('.project-card').forEach(card => {
    card?.addEventListener('click', () => showProjectDetail(card.dataset.id));
  });
}

async function showProjectDetail(projectId) {
  // Project IDs are UUIDs (VARCHAR) — never parseInt
  currentProjectId = String(projectId);
  window.currentProjectId = currentProjectId;
  window.atlantistActiveProjectId = currentProjectId;
  localStorage.setItem('atlantist_active_project_id', currentProjectId);
  document.getElementById('projects-list').classList.add('hidden');
  document.getElementById('projects-toolbar').classList.add('hidden');
  document.getElementById('project-detail').classList.remove('hidden');

  try {
    const project = await authApi('GET', `/api/projects/${projectId}`);
    currentProjectDetail = project;

    document.getElementById('detail-project-name').textContent = project.name;
    document.getElementById('detail-project-meta').textContent = `${project.type || 'Mixed'} · Created ${new Date(project.created_at).toLocaleDateString()}`;

    const membersEl = document.getElementById('detail-members-list');
    if (!project.members || project.members.length === 0) {
      membersEl.innerHTML = '<div style="font-size:11px;color:var(--text-muted);padding:8px 0">No members yet</div>';
    } else {
      membersEl.innerHTML = project.members.map(m => `
        <div class="member-row">
          <div class="user-avatar">${(m.first_name || 'U').charAt(0).toUpperCase()}</div>
          <div class="member-info">
            <div class="member-name">${escapeHtml(m.first_name || 'Member')}</div>
            <div class="member-email">${escapeHtml(m.email || '')}</div>
          </div>
          <span class="member-role-badge ${m.role}">${m.role}</span>
        </div>
      `).join('');
    }
  } catch (err) {
    toast('Error loading project: ' + err.message, 'error');
  }
}

// Fork the current demo project as a new project for the logged-in user
async function forkDemoProject() {
  if (!authState.authenticated || authState.user?.anonymous) {
    document.getElementById('account-login-prompt')?.click();
    return;
  }
  const btn = document.getElementById('btn-fork-demo');
  if (btn) { btn.disabled = true; btn.textContent = 'Forking…'; }
  try {
    const res = await authApi('POST', '/api/projects', {
      name: '220 W 23rd St — My Copy',
      type: 'Commercial',
      description: 'Forked from the NYC Mid-Rise demo project'
    });
    const demoId = window.currentProjectId;
    const newId = res.id;

    // 1. Copy levels — build old→new ID map
    const levelMap = {};
    const demoLevels = await authApi('GET', `/api/levels?project_id=${demoId}`);
    for (const lvl of demoLevels) {
      const created = await authApi('POST', '/api/levels', {
        name: lvl.name, elevation: lvl.elevation, project_id: newId,
        is_building_storey: lvl.is_building_storey
      });
      levelMap[lvl.id] = created.id;
    }

    // 2. Copy elements (walls + columns) with ID map
    const elementMap = {};
    const demoElements = await authApi('GET', `/api/elements?project_id=${demoId}`);
    for (const el of demoElements) {
      const newBaseId = levelMap[el.base_level_id] || null;
      const newTopId = levelMap[el.top_level_id] || null;
      const created = await authApi('POST', '/api/elements', {
        type: el.type,
        type_name: el.type_name,
        base_level_id: newBaseId,
        top_level_id: newTopId,
        project_id: newId,
        parameters: el.parameters,
        computed: el.computed
      });
      elementMap[el.id] = created.id;

      // Copy wall layers for wall elements
      if (el.type === 'wall' && el.layers?.length) {
        for (const layer of el.layers) {
          await fetch('/api/elements/' + created.id + '/layers', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ material: layer.material, thickness: layer.thickness, function: layer.function })
          });
        }
      }
    }

    // 3. Copy family instances (doors + windows)
    const demoFamilies = await authApi('GET', `/api/families?project_id=${demoId}`);
    for (const fam of demoFamilies) {
      const newWallId = elementMap[fam.host_wall_id];
      if (!newWallId) continue;
      await authApi('POST', '/api/families', {
        family_type: fam.family_type,
        type_name: fam.type_name,
        host_wall_id: newWallId,
        host_face_u: fam.host_face_u,
        mark: fam.mark,
        parameters: fam.parameters,
        computed: fam.computed,
        project_id: newId
      });
    }

    // 4. Copy structural grids
    const demoGrids = await authApi('GET', `/api/grids?project_id=${demoId}`);
    for (const grid of demoGrids) {
      const createdGrid = await authApi('POST', '/api/grids', {
        name: grid.name,
        system_type: grid.system_type,
        origin_x: grid.origin_x,
        origin_z: grid.origin_z,
        spacing_x: grid.spacing_x,
        spacing_z: grid.spacing_z,
        bubble_visible: grid.bubble_visible,
        project_id: newId
      });
      // Copy grid lines — DB uses bubble_end_a/bubble_end_b
      const lines = grid.lines || grid.grid_lines || [];
      for (const line of lines) {
        await authApi('POST', `/api/grids/${createdGrid.id}/lines`, {
          axis: line.axis,
          label: line.label,
          coordinate: line.coordinate,
          bubble_end_a: line.bubble_end_a ?? true,
          bubble_end_b: line.bubble_end_b ?? true
        });
      }
    }

    // 5. Copy rooms
    const demoRooms = await authApi('GET', `/api/rooms?project_id=${demoId}`);
    for (const rm of demoRooms) {
      const newLevelId = levelMap[rm.level_id] || null;
      if (!newLevelId) continue;
      await authApi('POST', '/api/rooms', {
        number: rm.number,
        name: rm.name,
        level_id: newLevelId,
        area_sqm: rm.area_sqm,
        volume_cum: rm.volume_cum,
        floor_finish: rm.floor_finish,
        wall_finish: rm.wall_finish,
        ceiling_finish: rm.ceiling_finish,
        base_finish: rm.base_finish,
        department: rm.department,
        parameters: rm.parameters,
        project_id: newId
      });
    }

    // 6. Copy floor plates (with layers)
    const demoFloors = await authApi('GET', `/api/floors?project_id=${demoId}`);
    for (const fl of demoFloors) {
      const newBaseId = levelMap[fl.base_level_id] || null;
      const newTopId = levelMap[fl.top_level_id] || null;
      await authApi('POST', '/api/floors', {
        project_id: newId,
        name: fl.name,
        base_level_id: newBaseId,
        top_level_id: newTopId,
        area_sqm: fl.area_sqm,
        thickness: fl.thickness,
        position_x: fl.position_x,
        position_y: fl.position_y,
        elevation: fl.elevation,
        parameters: fl.parameters,
        layers: fl.layers || []
      });
    }

    // 7. Copy stairs + railings
    const stairMap = {};
    const demoStairs = await authApi('GET', `/api/stairs?project_id=${demoId}`);
    for (const st of demoStairs) {
      const newBaseId = levelMap[st.base_level_id] || null;
      const newTopId = levelMap[st.top_level_id] || null;
      const created = await authApi('POST', '/api/stairs', {
        project_id: newId,
        name: st.name,
        stair_type: st.stair_type,
        base_level_id: newBaseId,
        top_level_id: newTopId,
        width: st.width,
        number_of_risers: st.number_of_risers,
        number_of_treads: st.number_of_treads,
        tread_depth: st.tread_depth,
        landing_width: st.landing_width,
        flight_count: st.flight_count,
        position_x: st.position_x,
        position_y: st.position_y,
        rotation_degrees: st.rotation_degrees,
        material: st.material,
        total_rise: st.total_rise,
        riser_height: st.riser_height,
        going: st.going,
        slope_degrees: st.slope_degrees
      });
      stairMap[st.id] = created.id;
    }
    const demoRailings = await authApi('GET', `/api/railings?project_id=${demoId}`);
    for (const rl of demoRailings) {
      const newStairId = stairMap[rl.host_stair_id];
      if (!newStairId) continue;
      await authApi('POST', '/api/railings', {
        project_id: newId,
        name: rl.name,
        host_stair_id: newStairId,
        railing_type: rl.railing_type,
        height: rl.height,
        top_rail_width: rl.top_rail_width,
        baluster_spacing: rl.baluster_spacing,
        glass_thickness: rl.glass_thickness,
        side: rl.side,
        material: rl.material,
        glass_finish: rl.glass_finish
      });
    }

    toast('Demo forked! Your copy is ready to edit.', 'success', 4000);
    localStorage.setItem('atlantist_active_project_id', newId);
    window.location.reload();
  } catch (err) {
    toast('Fork failed: ' + err.message, 'error');
    if (btn) { btn.disabled = false; btn.textContent = '✂ Fork Project'; }
  }
}

// Expose fork for demo badge button
window.forkDemoProject = forkDemoProject;

// ─── Type Library Modal ───────────────────────────────────────
let tlCatalog = {};
let tlActiveCat = 'wall';

function openTypeLibrary() {
  document.getElementById('type-library-modal').style.display = 'flex';
  if (Object.keys(tlCatalog).length === 0) loadTLCatalog();
  else renderTLGrid();
}

function closeTypeLibrary() {
  document.getElementById('type-library-modal').style.display = 'none';
}

window.openTypeLibrary = openTypeLibrary;
window.closeTypeLibrary = closeTypeLibrary;

async function loadTLCatalog() {
  try {
    const resp = await fetch('/api/templates/catalogs/element-types');
    tlCatalog = await resp.json();
    renderTLGrid();
  } catch {
    document.getElementById('tl-grid').innerHTML = '<div style="grid-column:1/-1;color:var(--text-error);padding:12px;font-size:12px">Failed to load type catalog</div>';
  }
}

function switchTLTab(btn) {
  document.querySelectorAll('.tl-tab').forEach(b => {
    b.classList.remove('active');
    b.style.background = 'var(--surface)';
    b.style.borderColor = 'var(--border)';
    b.style.color = 'var(--text-muted)';
  });
  btn.classList.add('active');
  btn.style.background = 'var(--accent-glow)';
  btn.style.borderColor = 'var(--accent)';
  btn.style.color = 'var(--accent)';
  tlActiveCat = btn.dataset.cat;
  renderTLGrid();
}

window.switchTLTab = switchTLTab;

function renderTLGrid() {
  const grid = document.getElementById('tl-grid');
  const search = document.getElementById('tl-search')?.value?.toLowerCase() || '';

  let items = [];
  switch (tlActiveCat) {
    case 'wall':       items = tlCatalog.wall_types || []; break;
    case 'door':       items = tlCatalog.door_types || []; break;
    case 'window':     items = tlCatalog.window_types || []; break;
    case 'column':     items = tlCatalog.column_types || []; break;
    case 'stair':      items = tlCatalog.stair_types || []; break;
    case 'floor':      items = tlCatalog.floor_types || []; break;
    case 'ceiling':    items = tlCatalog.ceiling_types || []; break;
    case 'roof':       items = tlCatalog.roof_types || []; break;
    case 'beam':       items = tlCatalog.beam_types || []; break;
    default:           items = [];
  }

  if (search) items = items.filter(i => (i.name || '').toLowerCase().includes(search));

  if (!items.length) {
    grid.innerHTML = `<div style="grid-column:1/-1;text-align:center;color:var(--text-muted);font-size:13px;padding:20px">No types in this category${search ? ' (try a different search)' : ''}</div>`;
    return;
  }

  grid.innerHTML = items.map(t => {
    const layers = t.layers ? (typeof t.layers === 'string' ? JSON.parse(t.layers) : t.layers) : [];
    const layerSummary = layers.length
      ? layers.map(l => `${l.material} ${l.thickness ? '(' + (l.thickness * 1000).toFixed(0) + 'mm)' : ''}`).join(' · ')
      : (t.description || t.notes || '');
    const specs = [];
    if (t.width)  specs.push(`W: ${(t.width * 1000).toFixed(0)}mm`);
    if (t.height) specs.push(`H: ${(t.height * 1000).toFixed(0)}mm`);
    if (t.default_thickness) specs.push(`Thk: ${(t.default_thickness * 1000).toFixed(0)}mm`);
    if (t.default_width) specs.push(`W: ${(t.default_width * 1000).toFixed(0)}mm`);
    if (t.fire_rating) specs.push(`Fire: ${t.fire_rating}`);
    if (t.glazing) specs.push(t.glazing + ' glazing');
    if (t.section) specs.push(t.section);
    const specStr = specs.length ? specs.join(' · ') : '';
    return `<div class="tl-type-card" data-name="${escapeHtml(t.name || '')}" style="background:var(--bg-viewport);border:1px solid var(--border);border-radius:8px;padding:12px;cursor:pointer;transition:all .15s"
      onmouseover="this.style.borderColor='var(--accent)'" onmouseout="this.style.borderColor='var(--border)'"
      onclick="selectTLType('${escapeHtml(t.id || '')}', '${escapeHtml(t.name || '')}', '${escapeHtml(tlActiveCat)}')">
      <div style="font-size:12px;font-weight:700;color:var(--text);margin-bottom:4px">${escapeHtml(t.name || '')}</div>
      <div style="font-size:11px;color:var(--text-muted);margin-bottom:4px;line-height:1.4">${escapeHtml(specStr)}</div>
      <div style="font-size:10px;color:var(--text-dim);line-height:1.4">${escapeHtml(layerSummary.slice(0, 80))}</div>
    </div>`;
  }).join('');
}

function selectTLType(typeId, typeName, category) {
  // Store selection in state for next placement
  window.atlSelectedTypeId = typeId;
  window.atlSelectedTypeName = typeName;
  window.atlSelectedTypeCategory = category;
  toast(`${typeName} selected — now click on the model to place`, 'info', 3000);
  closeTypeLibrary();

  // Auto-activate the right tool
  if (category === 'wall') {
    // Walls use the + Wall modal form (btn-add-wall) — stored via pendingPlacement
    state.pendingPlacement = { type: 'wall', typeId, mark: typeName };
  } else if (category === 'door') {
    state.placementMode = 'door'; state.pendingPlacement = { type: 'door', typeId, mark: typeName };
  } else if (category === 'window') {
    state.placementMode = 'window'; state.pendingPlacement = { type: 'window', typeId, mark: typeName };
  } else if (category === 'stair') {
    // activateStairTool() doesn't exist — trigger via pendingPlacement
    state.pendingPlacement = { type: 'stair', typeId, mark: typeName };
  } else if (category === 'floor') {
    state.pendingPlacement = { type: 'floor', typeId, mark: typeName };
  } else if (category === 'ceiling') {
    state.pendingPlacement = { type: 'ceiling', typeId, mark: typeName };
  } else if (category === 'column') {
    state.pendingPlacement = { type: 'column', typeId, mark: typeName };
  }
}

window.selectTLType = selectTLType;

// Search filter on Type Library input
document.getElementById('tl-search')?.addEventListener('input', () => renderTLGrid());

