function openDesignGuide() {
  const panel = document.getElementById('design-guide-panel');
  panel.style.display = 'block';
  const content = document.getElementById('dg-content');
  content.innerHTML = DG_STEPS.map((step, i) => `
    <div class="dg-step" style="margin-bottom:20px;padding-bottom:20px;border-bottom:1px solid var(--border)">
      <div style="display:flex;align-items:flex-start;gap:10px;margin-bottom:8px">
        <span style="font-size:20px;flex-shrink:0">${step.icon}</span>
        <div>
          <div style="font-size:13px;font-weight:700;color:var(--text)">${step.title}</div>
        </div>
      </div>
      <div style="font-size:12px;color:var(--text);line-height:1.6;margin-bottom:8px">${step.body}</div>
      ${step.cta ? `<button onclick="${step.cta.action}" style="background:var(--accent);border:none;color:#fff;cursor:pointer;font-size:12px;font-weight:600;padding:6px 14px;border-radius:6px;margin-bottom:8px;display:block">${step.cta.label}</button>` : ''}
      ${step.tip ? `<div style="font-size:11px;color:var(--text-muted);background:var(--bg-viewport);border:1px solid var(--border);border-radius:6px;padding:8px 10px"><strong style="color:var(--accent-dim)">💡 Tip:</strong> ${step.tip}</div>` : ''}
    </div>
  `).join('');
  content.innerHTML += `<div style="margin-top:16px;text-align:center;font-size:12px;color:var(--text-muted)">Complete design guide at <a href="/docs/features" target="_blank" style="color:var(--accent)">/docs/features</a></div>`;
}

function closeDesignGuide() {
  document.getElementById('design-guide-panel').style.display = 'none';
}

window.openDesignGuide = openDesignGuide;
window.closeDesignGuide = closeDesignGuide;

async function createNewProject() {
  const name = document.getElementById('new-project-name').value.trim();
  const type = document.getElementById('new-project-type').value;
  const description = document.getElementById('new-project-desc').value.trim();

  if (!name) {
    toast('Project name is required', 'error');
    return;
  }

  try {
    await authApi('POST', '/api/projects', { name, type, description });
    document.getElementById('create-project-form').classList.add('hidden');
    document.getElementById('new-project-name').value = '';
    document.getElementById('new-project-desc').value = '';
    await loadProjects();
    toast('Project created!', 'success');
  } catch (err) {
    toast('Failed to create project: ' + err.message, 'error');
  }
}

async function sendCollaboratorInvite() {
  if (!currentProjectDetail) return;
  const email = document.getElementById('invite-email').value.trim();
  const role = document.getElementById('invite-role').value;

  if (!email || !email.includes('@')) {
    document.getElementById('invite-error').textContent = 'Enter a valid email address';
    document.getElementById('invite-error').classList.remove('hidden');
    return;
  }

  document.getElementById('invite-error').classList.add('hidden');
  document.getElementById('invite-success').classList.add('hidden');

  try {
    await authApi('POST', `/api/projects/${currentProjectDetail.id}/members/invite`, { email, role });
    document.getElementById('invite-success').classList.remove('hidden');
    document.getElementById('invite-email').value = '';
  } catch (err) {
    document.getElementById('invite-error').textContent = err.message;
    document.getElementById('invite-error').classList.remove('hidden');
  }
}

function setupProjectsModal() {
  document.getElementById('close-projects')?.addEventListener('click', () => {
    hideModal('modal-projects');
    currentProjectDetail = null;
  });

  document.getElementById('btn-new-project')?.addEventListener('click', () => {
    const form = document.getElementById('create-project-form');
    form.classList.toggle('hidden');
    if (!form.classList.contains('hidden')) {
      document.getElementById('new-project-name').focus();
    }
  });

  document.getElementById('cancel-new-project')?.addEventListener('click', () => {
    document.getElementById('create-project-form').classList.add('hidden');
  });

  document.getElementById('confirm-new-project')?.addEventListener('click', createNewProject);

  document.getElementById('back-to-projects')?.addEventListener('click', () => {
    document.getElementById('project-detail').classList.add('hidden');
    document.getElementById('projects-list').classList.remove('hidden');
    document.getElementById('projects-toolbar').classList.remove('hidden');
    currentProjectDetail = null;
  });

  document.getElementById('send-invite-btn')?.addEventListener('click', sendCollaboratorInvite);

  document.getElementById('btn-open-project')?.addEventListener('click', () => {
    if (currentProjectDetail) {
      hideModal('modal-projects');
      localStorage.setItem('atlantist_active_project_id', currentProjectDetail.id);
      window.currentProjectId = currentProjectDetail.id;
      window.atlantistActiveProjectId = currentProjectDetail.id;
      loadAll().then(() => {
        const overlay = document.getElementById('app-loading-overlay');
        if (overlay) { overlay.classList.add('fade-out'); setTimeout(() => overlay.remove(), 450); }
      }).catch(err => toast('Failed to load: ' + err.message, 'error'));
    }
  });

  // ── Template tabs ────────────────────────────────────────────
  const sectionMy = document.getElementById('section-my-projects');
  const sectionTmpl = document.getElementById('section-templates');
  const tabMy = document.getElementById('tab-my-projects');
  const tabTmpl = document.getElementById('tab-templates');

  tabMy?.addEventListener('click', () => {
    tabMy.classList.add('active'); tabMy.style.color = 'var(--accent)';
    tabMy.style.borderBottomColor = 'var(--accent)';
    tabTmpl.classList.remove('active'); tabTmpl.style.color = 'var(--text-muted)';
    tabTmpl.style.borderBottomColor = 'transparent';
    sectionMy.classList.remove('hidden');
    sectionTmpl.classList.add('hidden');
    document.getElementById('project-detail').classList.add('hidden');
  });

  tabTmpl?.addEventListener('click', () => {
    tabTmpl.classList.add('active'); tabTmpl.style.color = 'var(--accent)';
    tabTmpl.style.borderBottomColor = 'var(--accent)';
    tabMy.classList.remove('active'); tabMy.style.color = 'var(--text-muted)';
    tabMy.style.borderBottomColor = 'transparent';
    sectionMy.classList.add('hidden');
    sectionTmpl.classList.remove('hidden');
    document.getElementById('project-detail').classList.add('hidden');
    document.getElementById('template-preview').classList.add('hidden');
    loadTemplates();
  });

  document.getElementById('back-to-templates')?.addEventListener('click', () => {
    document.getElementById('template-preview').classList.add('hidden');
    document.getElementById('templates-list').parentElement.classList.remove('hidden');
  });

  document.getElementById('btn-use-template')?.addEventListener('click', instantiateTemplate);

  document.getElementById('close-catalog')?.addEventListener('click', () => hideModal('modal-catalog'));
  document.getElementById('btn-browse-catalog')?.addEventListener('click', () => showCatalogModal('walls'));

  document.querySelectorAll('.catalog-tab').forEach(tab => {
    tab?.addEventListener('click', () => {
      document.querySelectorAll('.catalog-tab').forEach(t => {
        t.classList.remove('active');
        t.style.color = 'var(--text-muted)';
        t.style.borderBottomColor = 'transparent';
      });
      tab.classList.add('active');
      tab.style.color = 'var(--accent)';
      tab.style.borderBottomColor = 'var(--accent)';
      showCatalogModal(tab.dataset.cat);
    });
  });
}

async function showCatalogModal(category) {
  const content = document.getElementById('catalog-content');
  content.innerHTML = '<div style="text-align:center;padding:32px;color:var(--text-muted);font-size:13px">Loading catalog…</div>';
  showModal('modal-catalog');
  try {
    const resp = await fetch('/api/templates/catalogs/element-types');
    const cats = await resp.json();
    renderCatalogCategory(category, cats, content);
  } catch {
    content.innerHTML = '<div style="color:var(--text-error);font-size:13px;padding:16px">Failed to load catalog.</div>';
  }
}

function renderCatalogCategory(cat, cats, container) {
  let rows = [];
  if (cat === 'walls') rows = cats.wall_types || [];
  else if (cat === 'floors') rows = cats.floor_types || [];
  else if (cat === 'roofs') rows = cats.roof_types || [];
  else if (cat === 'ceilings') rows = cats.ceiling_types || [];
  else if (cat === 'doors') rows = cats.door_types || [];
  else if (cat === 'windows') rows = cats.window_types || [];
  else if (cat === 'stairs') rows = cats.stair_types || [];
  else if (cat === 'railings') rows = cats.railing_types || [];
  else if (cat === 'structural') rows = [...(cats.column_types||[]), ...(cats.beam_types||[])];
  else if (cat === 'mep') rows = cats.mep_fixture_types || [];

  if (!rows.length) {
    container.innerHTML = `<div style="text-align:center;padding:32px;color:var(--text-muted);font-size:13px">No ${cat} types available.</div>`;
    return;
  }

  container.innerHTML = rows.map(r => {
    // Build display name — handle all type shapes
    let name = r.name || '';
    if (!name && r.section) name = r.section;
    if (r.discipline && !name.includes(r.discipline)) name = `${name} (${r.discipline})`;
    if (!name) name = JSON.stringify(r).slice(0, 80);

    // Build meta line based on available fields
    let meta = '';
    if (r.layers && Array.isArray(r.layers)) meta = `${r.layers.length} layers · ${r.default_thickness || r.thickness || ''}m thick`;
    else if (r.default_width && r.default_height) meta = `${(r.default_width * 1000).toFixed(0)}mm × ${(r.default_height * 1000).toFixed(0)}mm`;
    else if (r.width && r.height) meta = `${r.width}mm × ${r.height}mm`;
    else if (r.section && r.material) meta = `${r.section} · ${r.material}`;
    else if (r.default_tread_depth) meta = `Tread ${(r.default_tread_depth * 1000).toFixed(0)}mm · ${r.default_riser_count || ''} risers · ${r.stair_type || ''}`;
    else if (r.railing_type) meta = `${r.railing_type} · Height ${r.default_height ? (r.default_height * 1000).toFixed(0) + 'mm' : ''} · ${r.material || ''}`;
    else if (r.roof_style) meta = `${r.roof_style} · Pitch ${r.pitch_ratio || 'flat'}`;
    else if (r.ceiling_type) meta = `${r.ceiling_type} · Offset ${r.default_elevation_offset || 0}m`;
    else if (r.glazing) meta = `${r.glazing} glazing · Sill ${r.sill_height || 0}mm · ${r.window_type || ''}`;
    else if (r.specs) meta = `${r.category || ''} · ${typeof r.specs === 'object' ? (r.specs.cfm ? r.specs.cfm + ' CFM' : r.specs.voltage ? r.specs.voltage : '') : ''}`;
    else if (r.notes) meta = r.notes;
    else if (r.material) meta = r.material;

    const badges = [];
    if (r.code_compliant) badges.push('<span style="font-size:10px;background:rgba(74,222,128,0.12);color:#4ade80;padding:2px 8px;border-radius:4px;font-weight:600">IBC ✓</span>');
    if (r.fire_rating) badges.push(`<span style="font-size:10px;background:var(--accent-dim);color:var(--accent);padding:2px 8px;border-radius:4px;font-weight:600">${r.fire_rating}</span>`);
    if (r.ada_compliant) badges.push('<span style="font-size:10px;background:rgba(96,165,250,0.12);color:#60a5fa;padding:2px 8px;border-radius:4px;font-weight:600">ADA ✓</span>');

    return `<div style="background:var(--bg-viewport);border:1px solid var(--border);border-radius:8px;padding:12px 14px;margin-bottom:8px;display:flex;align-items:flex-start;gap:12px">
      <div style="flex:1">
        <div style="font-size:13px;font-weight:600;color:var(--text)">${name}</div>
        <div style="font-size:11px;color:var(--text-muted);margin-top:3px">${meta}</div>
      </div>
      <div style="display:flex;gap:4px;flex-shrink:0">${badges.join('')}</div>
    </div>`;
  }).join('');
}

let selectedTemplateId = null;

async function loadTemplates() {
  const el = document.getElementById('templates-list');
  el.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--text-muted);font-size:13px">Loading templates…</div>';
  try {
    const resp = await fetch('/api/templates');
    const templates = await resp.json();
    if (!templates.length) {
      el.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--text-muted);font-size:13px">No templates available.</div>';
      return;
    }
    el.innerHTML = templates.map(t => {
      const settings = t.settings ? (typeof t.settings === 'string' ? JSON.parse(t.settings) : t.settings) : {};
      return `<div class="template-card" data-id="${t.id}" style="background:var(--bg-viewport);border:1px solid var(--border);border-radius:10px;padding:14px;cursor:pointer;transition:all .15s">
        <div style="font-size:22px;margin-bottom:8px">${typeIcon(t.type)}</div>
        <div style="font-size:13px;font-weight:600;color:var(--text);margin-bottom:4px">${escapeHtml(t.name)}</div>
        <div style="font-size:11px;color:var(--text-muted)">${settings.level_count || '—'} levels · ${settings.construction_type || '—'}</div>
        <div style="font-size:11px;color:var(--text-muted);margin-top:2px">${t.type || 'Mixed'}</div>
      </div>`;
    }).join('');
    el.querySelectorAll('.template-card').forEach(card => {
      card?.addEventListener('click', () => showTemplatePreview(card.dataset.id, templates));
    });
  } catch (err) {
    el.innerHTML = `<div style="grid-column:1/-1;color:var(--text-error);padding:12px;font-size:12px">Failed to load templates</div>`;
  }
}

async function showTemplatePreview(tmplId, allTemplates) {
  const t = allTemplates.find(x => x.id === tmplId);
  if (!t) return;
  selectedTemplateId = tmplId;
  const settings = t.settings ? (typeof t.settings === 'string' ? JSON.parse(t.settings) : t.settings) : {};
  const previewEl = document.getElementById('template-preview');
  document.getElementById('tmpl-preview-name').textContent = t.name;
  document.getElementById('tmpl-preview-meta').textContent = `Template · ${t.type || 'Mixed'}`;
  document.getElementById('tmpl-preview-description').textContent = t.description || '';
  document.getElementById('tmpl-preview-levels').textContent = settings.level_count || '—';
  document.getElementById('tmpl-preview-type').textContent = settings.construction_type || '—';
  document.getElementById('tmpl-preview-height').textContent = settings.typical_floor_height ? `${settings.typical_floor_height}m` : '—';
  document.getElementById('tmpl-instantiate-name').value = `${t.name} — My Project`;
  previewEl.classList.remove('hidden');
  previewEl.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

async function instantiateTemplate() {
  const name = document.getElementById('tmpl-instantiate-name')?.value?.trim();
  if (!name || !selectedTemplateId) { toast('Please enter a project name', 'error'); return; }
  try {
    const resp = await authApi('POST', `/api/templates/${selectedTemplateId}/instantiate`, { name });
    hideModal('modal-projects');
    toast('Project created from template!', 'success');
    // Open the new project
    localStorage.setItem('atlantist_active_project_id', resp.id);
    window.currentProjectId = resp.id;
    window.atlantistActiveProjectId = resp.id;
    loadAll().then(() => {
      const overlay = document.getElementById('app-loading-overlay');
      if (overlay) { overlay.classList.add('fade-out'); setTimeout(() => overlay.remove(), 450); }
    }).catch(err => toast('Failed to load: ' + err.message, 'error'));
  } catch (err) {
    toast('Failed to create project: ' + err.message, 'error');
  }
}

function typeIcon(type) {
  const map = { Commercial: '🏢', Residential: '🏠', Industrial: '🏭', 'Mixed-Use': '🏗️' };
  return map[type] || '📐';
}

function escapeHtml(str) {
  if (!str) return '';
  return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// ─── Modal Helpers ─────────────────────────────────────────

function showModal(id) {
  document.getElementById(id)?.classList.remove('hidden');
}

function hideModal(id) {
  document.getElementById(id)?.classList.add('hidden');
}

// ─── Initialize ─────────────────────────────────────────────

// Run after DOM is ready
function initAuth() {
  initSession();
  setupUserMenu();
  setupSignupModal();
  setupLoginModal();
  setupCollaboratorsModal();
  setupAdminMatching();
  setupContactModal();
  setupOnboardingModal();
  setupProjectsModal();
  setupHelpModal();
  setupLandingModal();
  setupOptinModal();
  initLeadVerifyFeedback();
  addHelpButton();
  initStatusDot();
  setupHistoryPanel();
  setupSettingsAdminsPanel();

  // Phase 29: Node Editor integration — listen for script-generated elements
  window.addEventListener('atlantist:nodegraph:elements-pushed', async (e) => {
    // Reload elements from server so script-created walls appear in the tree
    try {
      if (window.atlantistActiveProjectId) {
        const res = await api('GET', `/api/elements?project_id=${window.atlantistActiveProjectId}`);
        state.elements = res.elements || res || [];
        rebuildScene();
        toast(`Script: ${e.detail.count} element(s) added to model`, 'success');
      }
    } catch (err) {
      console.error('[node-editor] elements-pushed error:', err);
    }
  });

  // Execute button complete — reload levels + elements for immediate viewport update
  window.addEventListener('atlantist:nodegraph:execute-complete', async (e) => {
    try {
      const pid = e.detail?.projectId || window.atlantistActiveProjectId;
      if (!pid) return;
      const [elRes, lvRes] = await Promise.all([
        api('GET', `/api/elements?project_id=${pid}`),
        api('GET', `/api/levels?project_id=${pid}`),
      ]);
      state.elements = elRes.elements || elRes || [];
      if (lvRes.levels || Array.isArray(lvRes)) {
        state.levels = lvRes.levels || lvRes || [];
      }
      rebuildScene();
    } catch (err) {
      console.error('[node-editor] execute-complete reload error:', err);
    }
  });

  // Pre-fill contact email if user is authenticated
  authApi('GET', '/api/auth/me').then(me => {
    if (me.authenticated && me.user?.email) {
      document.getElementById('contact-email').value = me.user.email;
    }
  }).catch(() => {});

  // Handle magic link token from URL params (?magic_token=xxx) or cookie
  // The GET /api/auth/verify redirects here with ?magic_token=xxx and sets pending_magic_token cookie
  const urlParams = new URLSearchParams(window.location.search);
  const magicToken = urlParams.get('magic_token') || getCookie('pending_magic_token');
  const magicError = urlParams.get('magic_error');

  if (magicError === 'expired') {
    toast('Magic link expired. Please request a new one.', 'error');
  } else if (magicError === 'server_error') {
    toast('Something went wrong. Please try again.', 'error');
  }

  if (magicToken) {
    // Clear the URL param and cookie
    history.replaceState({}, '', window.location.pathname);
    document.cookie = 'pending_magic_token=; Max-Age=0; path=/';

    // Pre-fill signup modal with the magic token
    authState.magicToken = magicToken;

    // Show signup modal so user can complete profile
    showSignupModal();

    // Auto-advance to step 2 (profile form) since email was already sent
    document.getElementById('signup-step-1').classList.add('hidden');
    document.getElementById('signup-step-2').classList.remove('hidden');
    document.getElementById('signup-step-3').classList.add('hidden');
  }
}

function getCookie(name) {
  const match = document.cookie.match(new RegExp('(?:^|; )' + name.replace(/([.$?*|{}()[\\]\\+^])/g, '\\$1') + '=([^;]*)'));
  return match ? decodeURIComponent(match[1]) : null;
}

// Wait for DOM ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initAuth);
} else {
  initAuth();
}

// ─── Phase 15: Fire Protection Analysis ──────────────────────────────────────

let fireResults = null;     // last successful run data
let fireAnimFrame = null;   // animation frame handle

// Toolbar button
document.getElementById('btn-fire-protection')?.addEventListener('click', () => {
  if (!requireAdmin()) return;
  showModal('modal-fire-protection');
  resetFireModal();
});

document.getElementById('fire-modal-close')?.addEventListener('click', () => {
  cancelFireAnimation();
  hideModal('modal-fire-protection');
});

document.getElementById('btn-run-fire')?.addEventListener('click', runFireAnalysis);
document.getElementById('btn-fire-run-again')?.addEventListener('click', resetFireModal);

// Tab switching
document.getElementById('fire-tabs')?.addEventListener('click', e => {
  const btn = e.target.closest('.fire-tab');
  if (!btn) return;
  const section = btn.dataset.section;
  document.querySelectorAll('.fire-tab').forEach(t => t.classList.toggle('active', t === btn));
  document.querySelectorAll('.fire-section').forEach(s => {
    s.classList.toggle('active', s.id === `fire-section-${section}`);
    s.classList.toggle('hidden', s.id !== `fire-section-${section}`);
  });
  // Re-draw canvas for active section
  if (fireResults) drawFireCanvas(section, fireResults);
});

// Export buttons
document.getElementById('btn-fire-pdf-sprinkler')?.addEventListener('click', () => exportFirePDF('sprinkler'));
document.getElementById('btn-fire-pdf-egress')?.addEventListener('click', () => exportFirePDF('egress'));
document.getElementById('btn-fire-pdf-smoke')?.addEventListener('click', () => exportFirePDF('smoke'));
document.getElementById('btn-fire-pdf-full')?.addEventListener('click', () => exportFirePDF('full'));

function resetFireModal() {
  cancelFireAnimation();
  document.getElementById('fire-run-state').classList.remove('hidden');
  document.getElementById('fire-progress-state').classList.add('hidden');
  document.getElementById('fire-results-state').classList.add('hidden');
  ['fire-step-sprinkler','fire-step-egress','fire-step-smoke','fire-step-resistance','fire-step-fdny'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.className = 'energy-step pending';
  });
  document.getElementById('fire-progress-fill').style.width = '0%';
}

async function runFireAnalysis() {
  const occupancy = document.getElementById('fire-occupancy-type').value;
  document.getElementById('fire-run-state').classList.add('hidden');
  document.getElementById('fire-progress-state').classList.remove('hidden');
  document.getElementById('fire-progress-label').textContent = 'Analyzing building model…';

  const steps = [
    { id: 'fire-step-sprinkler',  label: '💧 NFPA 13 Sprinkler Analysis',  pct: 20 },
    { id: 'fire-step-egress',     label: '🚪 NFPA 101 Egress Analysis',     pct: 40 },
    { id: 'fire-step-smoke',      label: '💨 NFPA 92 Smoke Control',         pct: 60 },
    { id: 'fire-step-resistance', label: '🏗️ Fire Resistance Ratings',       pct: 80 },
    { id: 'fire-step-fdny',       label: '🚒 NYC FDNY Requirements',         pct: 95 },
  ];

  // Animate step progress
  async function advanceStep(idx) {
    if (idx > 0) {
      const prev = document.getElementById(steps[idx - 1].id);
      if (prev) prev.className = 'energy-step complete';
    }
    const cur = document.getElementById(steps[idx].id);
    if (cur) cur.className = 'energy-step active';
    document.getElementById('fire-progress-fill').style.width = steps[idx].pct + '%';
    document.getElementById('fire-progress-label').textContent = steps[idx].label;
    await new Promise(r => setTimeout(r, 300));
  }

  try {
    for (let i = 0; i < steps.length; i++) await advanceStep(i);

    const data = await api('POST', '/api/fire-protection/run', { occupancy_type: occupancy });

    // Mark all complete
    steps.forEach(s => {
      const el = document.getElementById(s.id);
      if (el) el.className = 'energy-step complete';
    });
    document.getElementById('fire-progress-fill').style.width = '100%';
    document.getElementById('fire-progress-label').textContent = '✓ Analysis complete';

    await new Promise(r => setTimeout(r, 400));

    // Parse JSON fields if they came back as strings
    const parse = v => (typeof v === 'string' ? JSON.parse(v) : v);
    fireResults = {
      sprinkler:  parse(data.sprinkler_results),
      egress:     parse(data.egress_results),
      smoke:      parse(data.smoke_results),
      resistance: parse(data.resistance_results),
      fdny:       parse(data.fdny_results),
    };

    showFireResults(fireResults);
  } catch (err) {
    toast('Fire analysis failed: ' + err.message, 'error');
    resetFireModal();
  }
}

function showFireResults(r) {
  document.getElementById('fire-progress-state').classList.add('hidden');
  document.getElementById('fire-results-state').classList.remove('hidden');

  // Activate first tab
  document.querySelectorAll('.fire-tab').forEach((t, i) => t.classList.toggle('active', i === 0));
  document.querySelectorAll('.fire-section').forEach((s, i) => {
    s.classList.toggle('active', i === 0);
    s.classList.toggle('hidden', i !== 0);
  });

  populateSprinklerPanel(r.sprinkler);
  populateEgressPanel(r.egress);
  populateSmokePanel(r.smoke);
  populateResistancePanel(r.resistance);
  populateFDNYPanel(r.fdny);

  // Draw canvas for first active tab (sprinkler)
  requestAnimationFrame(() => drawFireCanvas('sprinkler', r));

  // Fetch and display guardrails compliance summary
  fetchGuardrailsSummary('fire-protection');
}

// ─── Panel renderers ─────────────────────────────────────────────────────────

function fireMetricCards(metrics) {
  return metrics.map(m => `
    <div class="fire-metric-card">
      <div class="fire-metric-label">${m.label}</div>
      <div class="fire-metric-value">${m.value}</div>
      ${m.sub ? `<div class="fire-metric-sub">${m.sub}</div>` : ''}
    </div>
  `).join('');
}

function fireChecks(checks) {
  return checks.map(c => `
    <div class="fire-check-row">
      <span class="fire-check-badge ${c.status}">${c.status.toUpperCase()}</span>
      <span class="fire-check-label">${escapeHtml(c.label)}</span>
      <span class="fire-check-value">${escapeHtml(c.value || '')}</span>
    </div>
  `).join('');
}

function populateSprinklerPanel(s) {
  document.getElementById('fire-sprinkler-metrics').innerHTML = fireMetricCards([
    { label: 'Hazard Type',        value: s.hazard_label,                      sub: s.occupancy_type },
    { label: 'Total Sprinklers',   value: s.total_sprinklers,                  sub: `${s.sprinklers_per_level}/floor × ${s.num_levels} levels` },
    { label: 'Design Density',     value: `${s.design_density_gpm_sf} gpm/ft²`, sub: `Remote area: ${s.remote_area_sf} ft²` },
    { label: 'System Demand',      value: `${s.system_demand_gpm} gpm`,         sub: `incl. ${s.hose_stream_allowance_gpm} gpm hose stream` },
    { label: 'Pressure Required',  value: `${s.system_pressure_required_psi} psi`, sub: `Supply: ${s.supply_pressure_psi} psi` },
    { label: 'K-Factor',           value: `K=${s.k_factor}`,                   sub: `Pipe: ${s.pipe_diameter_in}" @ C=${s.pipe_c_factor}` },
  ]);
  document.getElementById('fire-sprinkler-checks').innerHTML = fireChecks(s.checks);
}

function populateEgressPanel(e) {
  document.getElementById('fire-egress-metrics').innerHTML = fireMetricCards([
    { label: 'Occupant Load',      value: `${e.occupant_load_per_floor}/floor`, sub: `Total: ${e.total_occupant_load}` },
    { label: 'OL Factor',          value: `${e.ol_factor_sf_per_person} ft²/person`, sub: e.occupancy_type },
    { label: 'Exits Required',     value: e.min_exits_required,                sub: `Provided: ${e.exits_provided}` },
    { label: 'Travel Distance',    value: `${e.travel_distance_ft} ft`,        sub: `Max: ${e.max_travel_distance_ft} ft` },
    { label: 'Common Path',        value: `${e.common_path_ft} ft`,             sub: `Max: ${e.common_path_max_ft} ft` },
    { label: 'Stair Width Req.',   value: `${e.req_stair_width_in} in`,        sub: `Corridor: ${e.req_corridor_width_in} in` },
  ]);
  document.getElementById('fire-egress-checks').innerHTML = fireChecks(e.checks);
}

function populateSmokePanel(sm) {
  document.getElementById('fire-smoke-metrics').innerHTML = fireMetricCards([
    { label: 'Building Height',    value: `${sm.total_building_height_ft} ft`,  sub: sm.is_high_rise ? 'HIGH-RISE' : 'Low-rise' },
    { label: 'Stairwell Fan',      value: `${sm.stairwell.fan_flow_cfm} cfm`,   sub: `ΔP ≥ ${sm.stairwell.min_delta_p_in_wg} in wg` },
    { label: 'Elevator Fan',       value: `${sm.elevator_shaft.fan_flow_cfm} cfm`, sub: 'Shaft pressurization' },
    { label: 'Zone Exhaust',       value: `${sm.zone_control.exhaust_cfm} cfm`, sub: `Makeup: ${sm.zone_control.makeup_air_cfm} cfm` },
  ]);
  document.getElementById('fire-smoke-checks').innerHTML = fireChecks(sm.checks);
}

function populateResistancePanel(r) {
  document.getElementById('fire-resistance-metrics').innerHTML = fireMetricCards([
    { label: 'Construction Type',  value: r.construction_type,                 sub: `${r.num_levels} levels` },
    { label: 'Structural Frame',   value: `${r.structural_frame_rating_hr}h`,   sub: r.column_fireproofing.split('—')[0].trim() },
    { label: 'Bearing Walls',      value: `${r.bearing_wall_rating_hr}h` },
    { label: 'Partitions',         value: `${r.non_bearing_partition_hr}h` },
    { label: 'Shaft Enclosures',   value: `${r.shaft_enclosure_hr}h` },
    { label: 'Corridors',          value: r.corridor_rating_hr > 0 ? `${r.corridor_rating_hr}h` : 'N/A' },
  ]);
  document.getElementById('fire-resistance-checks').innerHTML = fireChecks(r.checks);
}

function populateFDNYPanel(f) {
  document.getElementById('fire-fdny-metrics').innerHTML = fireMetricCards([
    { label: 'Standpipe Class',    value: f.standpipe_class,                   sub: `${f.total_height_ft} ft building` },
    { label: 'Fire Pump',          value: f.requires_fire_pump ? 'Required' : 'Not Required', sub: f.requires_fire_pump ? `${f.fire_pump_room_sf} ft² room` : '' },
    { label: 'Hydrants Required',  value: f.hydrants_required,                 sub: `≤ ${f.hydrant_spacing_ft} ft from entry` },
    { label: 'Apparatus Road',     value: `${f.apparatus_access_road_width_ft} ft wide`, sub: `${f.vertical_clearance_ft} ft clearance` },
  ]);
  document.getElementById('fire-fdny-checks').innerHTML = fireChecks(f.checks);

  // FP-1 form table
  const fp1 = f.fp1_data;
  if (fp1) {
    document.getElementById('fire-fp1-table').innerHTML = Object.entries(fp1).map(([k, v]) =>
      `<div class="fire-fp1-row"><span class="fire-fp1-key">${k.replace(/_/g,' ')}</span><span class="fire-fp1-val">${escapeHtml(String(v))}</span></div>`
    ).join('');
  }
}

// ─── Canvas Animations ───────────────────────────────────────────────────────

function cancelFireAnimation() {
  if (fireAnimFrame) { cancelAnimationFrame(fireAnimFrame); fireAnimFrame = null; }
}

function drawFireCanvas(section, r) {
  cancelFireAnimation();
  if (section === 'sprinkler' && r.sprinkler) drawSprinklerCanvas(r.sprinkler);
  else if (section === 'egress' && r.egress)   drawEgressCanvas(r.egress);
  else if (section === 'smoke' && r.smoke)     drawSmokeCanvas(r.smoke);
}

function setupCanvas(id) {
  const wrap = document.getElementById(id + '-wrap');
  const canvas = document.getElementById(id);
  if (!canvas || !wrap) return null;
  const W = wrap.clientWidth || 600;
  const H = wrap.clientHeight || 220;
  canvas.width  = W;
  canvas.height = H;
  return { canvas, ctx: canvas.getContext('2d'), W, H };
}

// NFPA 13 Sprinkler visualization — animated water spray particles
function drawSprinklerCanvas(s) {
  const setup = setupCanvas('fire-sprinkler-canvas');
  if (!setup) return;
  const { canvas, ctx, W, H } = setup;

  const cols       = Math.min(s.grid_cols || 5, 12);
  const rows       = Math.min(s.grid_rows || 4, 8);
  const total      = cols * rows;
  const spacingX   = W / (cols + 1);
  const spacingY   = H / (rows + 1);
  const remoteCount = s.remote_sprinkler_count || 4;

  // Sprinkler head positions
  const heads = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      heads.push({
        x: spacingX * (c + 1),
        y: spacingY * (r + 1),
        remote: r * cols + c < remoteCount,
      });
    }
  }

  // Particles per head
  const PARTICLES_PER_HEAD = 6;
  const particles = [];
  for (const h of heads) {
    for (let i = 0; i < PARTICLES_PER_HEAD; i++) {
      particles.push({
        hx: h.x, hy: h.y,
        remote: h.remote,
        angle: (Math.PI * 2 / PARTICLES_PER_HEAD) * i,
        speed: 0.8 + Math.random() * 1.2,
        dist:  Math.random() * (h.remote ? 28 : 18),
        maxDist: h.remote ? 28 : 18,
        opacity: Math.random(),
      });
    }
  }

  function animate() {
    ctx.clearRect(0, 0, W, H);

    // Draw pipe grid lines
    ctx.strokeStyle = '#1e40af';
    ctx.lineWidth   = 1;
    ctx.globalAlpha = 0.4;
    // Horizontal mains
    for (let r = 0; r < rows; r++) {
      ctx.beginPath();
      ctx.moveTo(spacingX, spacingY * (r + 1));
      ctx.lineTo(W - spacingX, spacingY * (r + 1));
      ctx.stroke();
    }
    // Vertical branches
    for (let c = 0; c < cols; c++) {
      ctx.beginPath();
      ctx.moveTo(spacingX * (c + 1), spacingY);
      ctx.lineTo(spacingX * (c + 1), H - spacingY);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // Draw coverage arcs + sprinkler heads
    for (const h of heads) {
      const isRemote = h.remote;
      const radius   = isRemote ? 26 : 18;

      // Coverage arc
      ctx.beginPath();
      ctx.arc(h.x, h.y, radius, 0, Math.PI * 2);
      ctx.fillStyle = isRemote ? 'rgba(239,68,68,0.08)' : 'rgba(59,130,246,0.06)';
      ctx.fill();
      ctx.strokeStyle = isRemote ? 'rgba(239,68,68,0.3)' : 'rgba(59,130,246,0.2)';
      ctx.lineWidth = 0.5;
      ctx.stroke();

      // Head marker
      ctx.beginPath();
      ctx.arc(h.x, h.y, 4, 0, Math.PI * 2);
      ctx.fillStyle = isRemote ? '#ef4444' : '#3b82f6';
      ctx.fill();
    }

    // Animate particles (water droplets)
    for (const p of particles) {
      p.dist += p.speed * 0.5;
      if (p.dist > p.maxDist) { p.dist = 0; p.opacity = 1; }
      p.opacity = Math.max(0, 1 - p.dist / p.maxDist);
      const px = p.hx + Math.cos(p.angle) * p.dist;
      const py = p.hy + Math.sin(p.angle) * p.dist;
      ctx.beginPath();
      ctx.arc(px, py, 1.5, 0, Math.PI * 2);
      ctx.fillStyle = p.remote ? `rgba(96,165,250,${p.opacity})` : `rgba(147,197,253,${p.opacity})`;
      ctx.fill();
    }

    fireAnimFrame = requestAnimationFrame(animate);
  }
  animate();
}

// NFPA 101 Egress visualization — animated occupant flow
function drawEgressCanvas(e) {
  const setup = setupCanvas('fire-egress-canvas');
  if (!setup) return;
  const { canvas, ctx, W, H } = setup;

  const paths     = e.egress_paths || [];
  const numPaths  = paths.length || 2;
  const exitX     = W - 30;
  const figures   = [];

  // Generate animated occupant figures per path
  const FIGS_PER_PATH = 8;
  for (let p = 0; p < numPaths; p++) {
    const startY  = H * (p + 1) / (numPaths + 1);
    const pathInfo = paths[p] || {};
    const status   = pathInfo.status || 'ok';
    for (let i = 0; i < FIGS_PER_PATH; i++) {
      figures.push({
        x:   Math.random() * (W * 0.4),
        y:   startY + (Math.random() - 0.5) * 30,
        vy:  (Math.random() - 0.5) * 0.3,
        speed: 0.8 + Math.random() * 1.2,
        pathY: startY,
        status,
      });
    }
  }

  function animate() {
    ctx.clearRect(0, 0, W, H);

    // Draw exit doors
    for (let p = 0; p < numPaths; p++) {
      const y = H * (p + 1) / (numPaths + 1);
      ctx.fillStyle = '#22c55e';
      ctx.fillRect(exitX - 6, y - 16, 12, 32);
      ctx.fillStyle = '#fff';
      ctx.font = '10px monospace';
      ctx.textAlign = 'center';
      ctx.fillText('EXIT', exitX, y + 4);
    }
    ctx.textAlign = 'left';

    // Travel distance arcs
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = 'rgba(234,179,8,0.3)';
    ctx.lineWidth = 1;
    for (let p = 0; p < numPaths; p++) {
      const y = H * (p + 1) / (numPaths + 1);
      const maxDist = e.max_travel_distance_ft;
      const actual  = e.travel_distance_ft;
      const arcW    = (W - 60) * Math.min(1, actual / maxDist);
      ctx.beginPath();
      ctx.arc(exitX, y, arcW, Math.PI * 0.75, Math.PI * 1.25);
      ctx.stroke();
    }
    ctx.setLineDash([]);

    // Animate figures
    for (const f of figures) {
      f.x  += f.speed;
      f.vy  += (f.pathY - f.y) * 0.05;
      f.y  += f.vy;
      if (f.x > exitX - 10) f.x = 0;

      // Color by crowding status
      const color = f.status === 'ok' ? '#4ade80' : f.status === 'warning' ? '#facc15' : '#f87171';
      // Draw simple stick figure
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      // Head
      ctx.arc(f.x, f.y - 6, 3, 0, Math.PI * 2);
      ctx.stroke();
      // Body
      ctx.beginPath();
      ctx.moveTo(f.x, f.y - 3);
      ctx.lineTo(f.x, f.y + 4);
      // Arms
      ctx.moveTo(f.x - 4, f.y);
      ctx.lineTo(f.x + 4, f.y);
      // Legs
      ctx.moveTo(f.x, f.y + 4);
      ctx.lineTo(f.x - 3, f.y + 9);
      ctx.moveTo(f.x, f.y + 4);
      ctx.lineTo(f.x + 3, f.y + 9);
      ctx.stroke();
    }

    fireAnimFrame = requestAnimationFrame(animate);
  }
  animate();
}

// NFPA 92 Smoke visualization — animated pressure arrows + smoke fill
function drawSmokeCanvas(sm) {
  const setup = setupCanvas('fire-smoke-canvas');
  if (!setup) return;
  const { canvas, ctx, W, H } = setup;

  const numFloors = sm.num_levels || 3;
  const floorH    = H / (numFloors + 1);
  let   smokeY    = H;  // smoke descends from top
  let   t         = 0;

  function animate() {
    ctx.clearRect(0, 0, W, H);
    t++;

    // Smoke fill (top-down gradient, animates downward)
    smokeY = Math.max(0, H - (t * 0.3) % H);
    const grad = ctx.createLinearGradient(0, 0, 0, H);
    grad.addColorStop(0,   'rgba(100,100,100,0.7)');
    grad.addColorStop(Math.min(1, (H - smokeY) / H + 0.2), 'rgba(80,80,80,0.4)');
    grad.addColorStop(1,   'rgba(50,50,50,0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W * 0.55, H);

    // Floor lines
    for (let f = 0; f < numFloors; f++) {
      const y = floorH * (f + 1);
      ctx.strokeStyle = '#334155';
      ctx.lineWidth   = 1;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(W * 0.55, y);
      ctx.stroke();

      // Floor label
      ctx.fillStyle = '#64748b';
      ctx.font = '9px monospace';
      ctx.fillText(`L${numFloors - f}`, 4, y - 4);
    }

    // Stairwell box (right side)
    const swX  = W * 0.62;
    const swW  = 60;
    ctx.strokeStyle = '#475569';
    ctx.lineWidth   = 2;
    ctx.strokeRect(swX, 10, swW, H - 20);
    ctx.fillStyle = '#1e3a5f';
    ctx.fillRect(swX + 1, 11, swW - 2, H - 22);
    ctx.fillStyle = '#60a5fa';
    ctx.font = '9px monospace';
    ctx.fillText('STAIR', swX + 8, H / 2);

    // Pressure arrows on stairwell doors
    for (let f = 0; f < numFloors; f++) {
      const y = floorH * (f + 1);
      const pulse = 0.6 + 0.4 * Math.sin(t * 0.05 + f);
      ctx.strokeStyle = `rgba(96,165,250,${pulse})`;
      ctx.lineWidth   = 2;
      // Arrow pointing from stairwell to corridor (positive pressure)
      const ax = swX - 2;
      ctx.beginPath();
      ctx.moveTo(ax, y);
      ctx.lineTo(ax - 20, y);
      ctx.stroke();
      // Arrowhead
      ctx.beginPath();
      ctx.moveTo(ax - 20, y);
      ctx.lineTo(ax - 14, y - 5);
      ctx.lineTo(ax - 14, y + 5);
      ctx.closePath();
      ctx.fillStyle = `rgba(96,165,250,${pulse})`;
      ctx.fill();
    }

    // Legend
    ctx.fillStyle = '#64748b';
    ctx.font      = '9px monospace';
    ctx.fillText('Smoke zone', W * 0.02, 14);
    ctx.fillStyle = '#60a5fa';
    ctx.fillText('Pressurized →', swX - 70, H - 8);

    fireAnimFrame = requestAnimationFrame(animate);
  }
  animate();
}

// ─── PDF Export (print-to-PDF via window.print) ──────────────────────────────
function exportFirePDF(section) {
  if (!fireResults) { toast('Run analysis first', 'error'); return; }

  const r   = fireResults;
  const now = new Date().toLocaleDateString('en-US');
  let content = '';

  const DISCLAIMER = `<p style="font-size:9px;color:#666;border:1px solid #f59e0b;padding:8px;border-radius:4px;margin-bottom:16px">
    ⚠️ PROFESSIONAL DISCLAIMER: Atlantist Fire Protection tools are professional design aids. Results are estimates.
    All fire protection designs must be reviewed and stamped by a licensed PE or registered architect.
    Atlantist does not guarantee code compliance or regulatory approval.</p>`;

  function checkTable(checks) {
    return `<table style="width:100%;border-collapse:collapse;font-size:11px;margin-top:8px">
      ${checks.map(c => `<tr style="border-bottom:1px solid #eee">
        <td style="padding:4px 8px;width:60px"><span style="background:${c.status==='pass'?'#d1fae5':c.status==='fail'?'#fee2e2':'#fef3c7'};color:${c.status==='pass'?'#065f46':c.status==='fail'?'#7f1d1d':'#78350f'};padding:2px 6px;border-radius:3px;font-size:10px">${c.status.toUpperCase()}</span></td>
        <td style="padding:4px 8px">${c.label}</td>
        <td style="padding:4px 8px;color:#666;text-align:right">${c.value||''}</td>
      </tr>`).join('')}
    </table>`;
  }

  if (section === 'sprinkler' || section === 'full') {
    const s = r.sprinkler;
    content += `<h2 style="color:#1e40af">NFPA 13 — Sprinkler System Hydraulic Calculation</h2>
      <p><strong>Hazard:</strong> ${s.hazard_label} &nbsp; <strong>Occupancy:</strong> ${s.occupancy_type}</p>
      <p><strong>Design Density:</strong> ${s.design_density_gpm_sf} gpm/ft² &nbsp; <strong>Remote Area:</strong> ${s.remote_area_sf} ft²</p>
      <p><strong>System Demand:</strong> ${s.system_demand_gpm} gpm @ ${s.system_pressure_required_psi} psi &nbsp; <strong>K-Factor:</strong> ${s.k_factor}</p>
      <p><strong>Friction Loss (H-W):</strong> ${s.friction_loss_psi} psi &nbsp; <strong>Pipe:</strong> ${s.pipe_diameter_in}" dia., C=${s.pipe_c_factor}</p>
      ${checkTable(s.checks)}`;
  }
  if (section === 'egress' || section === 'full') {
    const e = r.egress;
    content += `<h2 style="color:#1e40af;margin-top:24px">NFPA 101 — Life Safety / Egress Analysis</h2>
      <p><strong>Occupant Load:</strong> ${e.occupant_load_per_floor}/floor (${e.ol_factor_sf_per_person} ft²/person)</p>
      <p><strong>Exits Required:</strong> ${e.min_exits_required} &nbsp; <strong>Exits Provided:</strong> ${e.exits_provided}</p>
      <p><strong>Travel Distance:</strong> ${e.travel_distance_ft} ft (max ${e.max_travel_distance_ft} ft) &nbsp; <strong>Common Path:</strong> ${e.common_path_ft} ft</p>
      ${checkTable(e.checks)}`;
  }
  if (section === 'smoke' || section === 'full') {
    const sm = r.smoke;
    content += `<h2 style="color:#1e40af;margin-top:24px">NFPA 92 — Smoke Control</h2>
      <p><strong>Building Height:</strong> ${sm.total_building_height_ft} ft ${sm.is_high_rise ? '(HIGH-RISE)' : ''}</p>
      <p><strong>Stairwell Fan:</strong> ${sm.stairwell.fan_flow_cfm} cfm @ ΔP ≥ ${sm.stairwell.min_delta_p_in_wg} in wg</p>
      <p><strong>Zone Exhaust:</strong> ${sm.zone_control.exhaust_cfm} cfm &nbsp; <strong>Makeup Air:</strong> ${sm.zone_control.makeup_air_cfm} cfm</p>
      ${checkTable(sm.checks)}`;
  }
  if (section === 'full') {
    const fr = r.resistance;
    content += `<h2 style="color:#1e40af;margin-top:24px">IBC Fire Resistance Ratings</h2>
      <p><strong>Construction Type:</strong> ${fr.construction_type} &nbsp; <strong>Structural Frame:</strong> ${fr.structural_frame_rating_hr}h</p>
      ${checkTable(fr.checks)}`;
    const f = r.fdny;
    content += `<h2 style="color:#1e40af;margin-top:24px">NYC FDNY Requirements (FP-1)</h2>
      <p><strong>Standpipe:</strong> ${f.standpipe_class} &nbsp; <strong>Fire Pump:</strong> ${f.requires_fire_pump ? 'Required' : 'Not Required'}</p>
      ${checkTable(f.checks)}`;
  }

  const win = window.open('', '_blank');
  win.document.write(`<!DOCTYPE html><html><head><title>Atlantist Fire Protection — ${section.toUpperCase()}</title>
    <style>body{font-family:Arial,sans-serif;padding:32px;max-width:800px;margin:0 auto;color:#111}h1{color:#dc2626}h2{border-bottom:2px solid #1e40af;padding-bottom:4px}p{margin:4px 0}@media print{button{display:none}}</style>
    </head><body>
    <h1>🔥 Atlantist Fire Protection Analysis</h1>
    <p style="color:#666;font-size:11px">Generated: ${now} | Atlantist BIM 2.0</p>
    ${DISCLAIMER}
    ${content}
    <br><button onclick="window.print()" style="background:#dc2626;color:white;padding:8px 16px;border:none;border-radius:4px;cursor:pointer">Print / Save PDF</button>
    </body></html>`);
  win.document.close();
}

// ─── FDS Simulation Visualization (Three.js) ─────────────────────────────────
// Renders fire simulation results in 3D on the #fds-3d-canvas element.
// Uses NIST fire formula approximations from runFDSSimulation() — not full CFD.

let fdsRenderer = null;
let fdsScene    = null;
let fdsCamera   = null;
let fdsAnimId   = null;
let fdsSimData  = null;    // timeSeries from /api/fire-protection/fds/simulate
let fdsTimestep = 0;      // current time index
let fdsPlaying  = false;
let fdsClock     = null;

const FDS_PARTICLES     = [];
const FDS_SPRINKLERS    = [];
let FDS_TEMP_PLANE      = null;
let FDS_SMOKE_PLANE     = null;
let FDS_FIRE_SOURCE     = null;
let FDS_FLOOR_MESH      = null;
let FDS_GRID_HELPER     = null;
const FDS_VIS_CONTOURS  = [];

function initFDSView() {
  const canvas = document.getElementById('fds-3d-canvas');
  if (!canvas || fdsRenderer) return;

  fdsRenderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  fdsRenderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  fdsRenderer.setSize(canvas.clientWidth || 800, canvas.clientHeight || 260);
  fdsRenderer.shadowMap.enabled = true;

  fdsScene  = new THREE.Scene();
  fdsScene.background = new THREE.Color(0x050a15);
  fdsScene.fog = new THREE.Fog(0x050a15, 15, 40);

  const w = canvas.clientWidth  || 800;
  const h = canvas.clientHeight || 260;
  fdsCamera = new THREE.PerspectiveCamera(50, w / h, 0.1, 100);
  fdsCamera.position.set(10, 8, 12);
  fdsCamera.lookAt(5, 2, 5);

  // Lighting
  const ambient = new THREE.AmbientLight(0x334466, 1.2);
  fdsScene.add(ambient);
  const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
  dirLight.position.set(10, 15, 10);
  fdsScene.add(dirLight);

  fdsClock = new THREE.Clock();
  startFDSRenderLoop();

  // Resize observer
  const ro = new ResizeObserver(() => {
    const cw = canvas.clientWidth, ch = canvas.clientHeight;
    fdsRenderer.setSize(cw, ch);
    fdsCamera.aspect = cw / ch;
    fdsCamera.updateProjectionMatrix();
  });
  ro.observe(canvas.parentElement);
}

// ─── FDS Scene Building ───────────────────────────────────────────────────────

function buildFDSBuildingScene() {
  // Remove old objects
  clearFDSObjects();

  // Floor plane (from model dimensions)
  const floorGeo = new THREE.PlaneGeometry(20, 20);
  const floorMat = new THREE.MeshStandardMaterial({ color: 0x1a2030, roughness: 0.9, transparent: true, opacity: 0.8 });
  FDS_FLOOR_MESH = new THREE.Mesh(floorGeo, floorMat);
  FDS_FLOOR_MESH.rotation.x = -Math.PI / 2;
  FDS_FLOOR_MESH.position.set(10, 0, 10);
  fdsScene.add(FDS_FLOOR_MESH);

  // Grid helper (building footprint grid)
  FDS_GRID_HELPER = new THREE.GridHelper(20, 20, 0x1e293b, 0x0f172a);
  FDS_GRID_HELPER.position.set(10, 0.01, 10);
  fdsScene.add(FDS_GRID_HELPER);

  // Building walls (simplified box)
  const wallMat = new THREE.MeshStandardMaterial({ color: 0x334155, roughness: 0.7 });
  const boxGeo  = new THREE.BoxGeometry(20, 3, 20);
  const walls   = new THREE.Mesh(boxGeo, wallMat);
  walls.position.set(10, 1.5, 10);
  walls.material.transparent = true;
  walls.material.opacity     = 0.08;
  walls.material.side       = THREE.BackSide;
  fdsScene.add(walls);

  // Fire source (orange cone)
  const fireGeo = new THREE.ConeGeometry(0.3, 0.8, 8);
  const fireMat = new THREE.MeshBasicMaterial({ color: 0xff6b35, transparent: true, opacity: 0.9 });
  FDS_FIRE_SOURCE = new THREE.Mesh(fireGeo, fireMat);
  FDS_FIRE_SOURCE.position.set(10, 0.5, 10);
  fdsScene.add(FDS_FIRE_SOURCE);

  // Sprinkler grid (green spheres on ceiling)
  const ceilY   = 3;
  const spacing = 3;
  for (let x = 2; x < 18; x += spacing) {
    for (let z = 2; z < 18; z += spacing) {
      const geo  = new THREE.SphereGeometry(0.08, 8, 8);
      const mat  = new THREE.MeshBasicMaterial({ color: 0x22c55e });
      const head = new THREE.Mesh(geo, mat);
      head.position.set(x, ceilY, z);
      fdsScene.add(head);
      FDS_SPRINKLERS.push({ mesh: head, x, z, activated: false });
    }
  }

  // Smoke plane (semi-transparent gray, near ceiling)
  const smokeGeo = new THREE.PlaneGeometry(20, 20);
  const smokeMat = new THREE.MeshBasicMaterial({
    color: 0x9090b0, transparent: true, opacity: 0.0, side: THREE.DoubleSide, depthWrite: false,
  });
  FDS_SMOKE_PLANE = new THREE.Mesh(smokeGeo, smokeMat);
  FDS_SMOKE_PLANE.rotation.x = -Math.PI / 2;
  FDS_SMOKE_PLANE.position.set(10, 2.0, 10);
  fdsScene.add(FDS_SMOKE_PLANE);

  // Temperature plane (floor-level heatmap, alphaMap driven)
  const tempGeo = new THREE.PlaneGeometry(20, 20, 40, 40);
  const tempMat = new THREE.MeshBasicMaterial({
    color: 0x000000, transparent: true, opacity: 0.5, side: THREE.DoubleSide,
  });
  FDS_TEMP_PLANE = new THREE.Mesh(tempGeo, tempMat);
  FDS_TEMP_PLANE.rotation.x = -Math.PI / 2;
  FDS_TEMP_PLANE.position.set(10, 0.05, 10);
  fdsScene.add(FDS_TEMP_PLANE);

  // Smoke particles (instanced for performance)
  const MAX_PARTICLES = 800;
  const pGeo = new THREE.SphereGeometry(0.06, 4, 4);
  const pMat = new THREE.MeshBasicMaterial({ color: 0x8090a0, transparent: true, opacity: 0.5, depthWrite: false });
  for (let i = 0; i < MAX_PARTICLES; i++) {
    const p = new THREE.Mesh(pGeo, pMat.clone());
    p.visible = false;
    fdsScene.add(p);
    FDS_PARTICLES.push({ mesh: p, active: false, vx: 0, vy: 0, vz: 0, life: 0, maxLife: 1 });
  }
}

function clearFDSObjects() {
  FDS_PARTICLES.forEach(p => { fdsScene.remove(p.mesh); p.mesh.visible = false; p.active = false; });
  FDS_PARTICLES.length = 0;
  FDS_SPRINKLERS.forEach(s => { fdsScene.remove(s.mesh); });
  FDS_SPRINKLERS.length = 0;
  if (FDS_TEMP_PLANE)  { fdsScene.remove(FDS_TEMP_PLANE);  FDS_TEMP_PLANE  = null; }
  if (FDS_SMOKE_PLANE) { fdsScene.remove(FDS_SMOKE_PLANE); FDS_SMOKE_PLANE = null; }
  if (FDS_FIRE_SOURCE) { fdsScene.remove(FDS_FIRE_SOURCE); FDS_FIRE_SOURCE = null; }
  if (FDS_FLOOR_MESH)  { fdsScene.remove(FDS_FLOOR_MESH);  FDS_FLOOR_MESH  = null; }
  if (FDS_GRID_HELPER) { fdsScene.remove(FDS_GRID_HELPER); FDS_GRID_HELPER = null; }
}

// ─── FDS Color Utilities ──────────────────────────────────────────────────────

function tempToColor(tempC) {
  if (tempC > 120) return new THREE.Color(0xef4444); // red
  if (tempC > 60)  return new THREE.Color(0xf59e0b); // amber
  if (tempC > 30)  return new THREE.Color(0xfbbf24); // yellow
  return new THREE.Color(0x3b82f6); // blue (cool)
}

function smokeToColor(conc) {
  const alpha = Math.min(0.7, conc * 1.5);
  const r = Math.round(144 * (1 - conc) + 239 * conc);
  const g = Math.round(144 * (1 - conc) + 68  * conc);
  const b = Math.round(176 * (1 - conc) + 68  * conc);
  return { r, g, b, alpha };
}

// ─── FDS Render Loop ─────────────────────────────────────────────────────────

let fdsLastFrameTime = 0;
const FDS_FRAME_INTERVAL_MS = 80; // ~12fps playback for smooth animation

function startFDSRenderLoop() {
  if (fdsAnimId) cancelAnimationFrame(fdsAnimId);
  function loop() {
    fdsAnimId = requestAnimationFrame(loop);
    const now = performance.now();
    if (now - fdsLastFrameTime < FDS_FRAME_INTERVAL_MS) return;
    fdsLastFrameTime = now;

    if (fdsPlaying && fdsSimData && fdsSimData.length > 0) {
      // Advance time index
      fdsTimestep = Math.min(fdsTimestep + 1, fdsSimData.length - 1);
      const slider = document.getElementById('fds-time-slider');
      if (slider) slider.value = fdsTimestep;
      updateFDSAtTimestep(fdsTimestep);
      const realTime = fdsSimData[fdsTimestep]?.time_s ?? fdsTimestep;
      document.getElementById('fds-time-label').textContent = realTime + 's';
      if (fdsTimestep >= fdsSimData.length - 1) {
        fdsPlaying = false;
        document.getElementById('btn-fds-play').textContent = '▶ Run';
      }
    }

    // Gentle camera orbit when playing
    if (fdsPlaying && fdsCamera) {
      const t = fdsClock ? fdsClock.getElapsedTime() : 0;
      fdsCamera.position.x = 10 + Math.sin(t * 0.15) * 4;
      fdsCamera.position.z = 10 + Math.cos(t * 0.15) * 4;
      fdsCamera.lookAt(10, 1.5, 10);
    }

    if (fdsRenderer && fdsScene && fdsCamera) {
      fdsRenderer.render(fdsScene, fdsCamera);
    }
  }
  loop();
}

function updateFDSAtTimestep(idx) {
  if (!fdsSimData || idx >= fdsSimData.length) return;
  const step = fdsSimData[idx];
  if (!step) return;

  const smokeConc  = step.smoke_concentration_grid;
  const tempGrid   = step.temperature_grid;
  const gridSize    = 40;

  // Update fire source scale/brightness
  if (FDS_FIRE_SOURCE) {
    const hrrNorm   = step.hrr_kw / 3000;
    const scale     = 0.5 + hrrNorm * 1.5;
    FDS_FIRE_SOURCE.scale.setScalar(scale);
    FDS_FIRE_SOURCE.material.color.setHSL(0.06 - hrrNorm * 0.03, 1, 0.5 + hrrNorm * 0.3);
    FDS_FIRE_SOURCE.material.opacity = 0.6 + hrrNorm * 0.4;
    // Pulse based on flashover
    if (step.at_flashover) {
      FDS_FIRE_SOURCE.scale.setScalar(scale * (1 + 0.2 * Math.sin(performance.now() * 0.01)));
    }
  }

  // Update smoke plane (height = smoke layer, opacity = concentration)
  if (FDS_SMOKE_PLANE) {
    const layerH = Math.max(0.3, Math.min(2.8, step.layer_height_m || 2.0));
    FDS_SMOKE_PLANE.position.y = layerH;
    const avgConc = smokeConc ? smokeConc.flat().reduce((a, b) => a + b, 0) / (gridSize * gridSize) : 0;
    FDS_SMOKE_PLANE.material.opacity = Math.min(0.6, avgConc * 1.5);
    FDS_SMOKE_PLANE.material.color.setHSL(0.66, 0.3, 0.45 + avgConc * 0.1);
  }

  // Update temperature plane vertices from grid
  if (FDS_TEMP_PLANE && tempGrid && tempGrid.length > 0) {
    const pos   = FDS_TEMP_PLANE.geometry.attributes.position;
    const colors = [];
    for (let i = 0; i < gridSize; i++) {
      for (let j = 0; j < gridSize; j++) {
        const row = tempGrid[i];
        const temp = row ? (row[j] || 0) : 0;
        const color = tempToColor(temp);
        colors.push(color.r, color.g, color.b);
      }
    }
    // Color the floor plane based on avg temperature
    const avgTemp = tempGrid.flat().reduce((a, b) => a + b, 0) / (gridSize * gridSize);
    FDS_TEMP_PLANE.material.color = tempToColor(avgTemp);
    FDS_TEMP_PLANE.material.opacity = Math.min(0.5, 0.05 + avgTemp / 200);
  }

  // Activate sprinklers
  if (step.sprinklers_activated > 0) {
    FDS_SPRINKLERS.slice(0, step.sprinklers_activated).forEach(s => {
      if (!s.activated) {
        s.activated = true;
        s.mesh.material.color.setHex(0xef4444);
      }
    });
  }

  // Update smoke particles
  const activeCount = Math.min(step.smoke_particles?.length || 0, FDS_PARTICLES.length);
  FDS_PARTICLES.forEach((p, i) => {
    if (i < activeCount && step.smoke_particles) {
      const sp = step.smoke_particles[i];
      p.mesh.visible = true;
      p.mesh.position.set(sp.x, sp.z, sp.y); // swap Y/Z for Three.js coords
      p.mesh.material.opacity = Math.min(0.7, (sp.density || 0.1) * 2);
      p.mesh.material.color.setHSL(0.6, 0.2, 0.4 + (sp.density || 0) * 0.3);
    } else {
      p.mesh.visible = false;
    }
  });

  // Update status text
  document.getElementById('fds-viz-status').textContent =
    `t=${step.time_s}s HRR=${step.hrr_kw}kW L=${step.layer_height_m}m ${step.at_flashover ? '🔥 FLASHOVER' : ''}`;
}

