// Play button
document.getElementById('btn-fds-play')?.addEventListener('click', async () => {
  if (fdsPlaying) {
    fdsPlaying = false;
    document.getElementById('btn-fds-play').textContent = '▶ Run';
    return;
  }

  // Check if we have simulation data; if not, run it
  if (!fdsSimData) {
    const hrrPeak = parseFloat(document.getElementById('fds-hrr-peak')?.value) || 3000;
    const alpha   = parseFloat(document.getElementById('fds-growth-alpha')?.value) || 0.12;
    const dur     = parseInt(document.getElementById('fds-duration')?.value) || 300;

    document.getElementById('fds-viz-status').textContent = 'Running simulation...';
    const occupancy = document.getElementById('fire-occupancy-type')?.value || 'office';

    try {
      const resp = await api('POST', '/api/fire-protection/fds/simulate', {
        hrr_peak_kw:       hrrPeak,
        growth_alpha:      alpha,
        simulation_time_s: dur,
        occupancy_type:    occupancy,
      });
      fdsSimData = resp.fds.timeSeries;

      // Update slider: max = number of timesteps (not seconds), step = 1
      const sliderEl = document.getElementById('fds-time-slider');
      sliderEl.max   = fdsSimData.length - 1;
      sliderEl.step  = 1;
      sliderEl.value = 0;
      const lastStep = fdsSimData[fdsSimData.length - 1];
      document.getElementById('fds-time-max').textContent  = (lastStep?.time_s || dur) + 's';

      // Populate summary stats
      document.getElementById('fds-results-table').style.display = 'block';
      document.getElementById('fds-stat-hrr').textContent      = resp.fds.summary.peak_hrr_kw + 'kW';
      document.getElementById('fds-stat-flashover').textContent = resp.fds.summary.flashover_time_s ? resp.fds.summary.flashover_time_s + 's' : 'N/A';
      document.getElementById('fds-stat-sprinkler').textContent = resp.fds.summary.first_sprinkler_activation_s ? resp.fds.summary.first_sprinkler_activation_s + 's' : 'N/A';
      document.getElementById('fds-stat-layer').textContent     = resp.fds.summary.smoke_layer_height_at_5min_m || '—';
      document.getElementById('fds-stat-fed').textContent        = resp.fds.summary.tenability_fed_at_5min || '—';
      document.getElementById('fds-stat-sthc').textContent       = 'N/A';

      // Build timeline table
      const tbody = document.getElementById('fds-timeline-body');
      const STEP  = Math.max(1, Math.floor(fdsSimData.length / 30));
      tbody.innerHTML = fdsSimData.filter((_, i) => i % STEP === 0).map(s => `
        <tr style="border-bottom:1px solid #0f172a">
          <td style="padding:3px 8px">${s.time_s}s</td>
          <td style="padding:3px 8px;text-align:right;color:#f97316">${s.hrr_kw}</td>
          <td style="padding:3px 8px;text-align:right;color:#60a5fa">${s.layer_height_m}</td>
          <td style="padding:3px 8px;text-align:right;color:${s.ceiling_temp_C > 100 ? '#ef4444' : '#94a3b8'}">${s.ceiling_temp_C}°C</td>
          <td style="padding:3px 8px;text-align:center;color:${s.at_flashover ? '#ef4444' : '#22c55e'}">${s.at_flashover ? '⚠' : '✓'}</td>
          <td style="padding:3px 8px;text-align:center">${s.sprinklers_activated}</td>
          <td style="padding:3px 8px;text-align:right;color:#f59e0b">${s.fed}</td>
        </tr>
      `).join('');

      // FDS checks
      const checks = [
        { id: 'fds-01', label: 'FDS input file (.fds) exported from BIM geometry', status: 'pass', value: '✓ Generate below' },
        { id: 'fds-02', label: `NIST FDS t² HRR: α=${alpha} kW/s² (peak ${hrrPeak} kW)`, status: 'pass', value: 'Simulated' },
        { id: 'fds-03', label: 'NFPA 92B smoke layer height model applied', status: 'pass', value: 'Active' },
        { id: 'fds-04', label: 'RTI sprinkler activation model', status: 'pass', value: 'K=5.6, 74°C' },
        { id: 'fds-05', label: 'FED / STHC tenability limits tracked', status: s => s.fed < 0.3 ? 'pass' : 'warning', value: 'Running' },
      ];
      document.getElementById('fds-checks').innerHTML = fireChecks(checks.map(c =>
        typeof c.status === 'function' ? { ...c, status: c.status(fdsSimData[fdsSimData.length - 1] || {}) } : c
      ));

    } catch (err) {
      document.getElementById('fds-viz-status').textContent = 'Error: ' + err.message;
      toast('FDS simulation failed: ' + err.message, 'error');
      return;
    }
  }

  fdsPlaying   = true;
  fdsTimestep  = 0;
  document.getElementById('btn-fds-play').textContent = '⏸ Pause';
  document.getElementById('fds-viz-status').textContent = '▶ Playing';
});

