function exportProcurementCsv() {
  if (!dbState.products.length) { toast('No products to export', 'error'); return; }
  const header = 'Product Name,Manufacturer,Code,Category,Qty,Unit,Unit Cost,Lead Time (days),Order Status';
  const rows = dbState.products.map(p =>
    [p.product_name, p.manufacturer||'', p.product_code||'', p.category||'',
     p.quantity||1, p.unit||'EA', p.estimated_cost||'', p.lead_time_days||'', p.order_status||'not_ordered']
    .map(v => `"${String(v).replace(/"/g,'""')}"`)
    .join(',')
  );
  const csv = [header, ...rows].join('\n');
  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `procurement-list-${new Date().toISOString().slice(0,10)}.csv`;
  a.click();
  URL.revokeObjectURL(url);
  toast('CSV exported', 'success', 1800);
}

