// escHtml defined once above (issue-list section)

// ═══════════════════════════════════════════════════════════════════════════
// AUTO-ALIGN VIEWS (Sheet Viewport + Grid-snap alignment)
// Owns: sheet viewport rendering, view placement state, auto-align logic,
//       drag-to-reposition, undo stack.
// Does NOT own: DAG solver, model geometry, placeholder CRUD.
// ═══════════════════════════════════════════════════════════════════════════

// ── Sheet viewport placement state ────────────────────────────────────────
// Maps sheetNo → Array<{id, title, x, y, w, h}>
// Stored in localStorage under 'atlantist_sheet_viewports' for persistence.
const _svpKey = 'atlantist_sheet_viewports';
let _svpState = {};   // { [sheetNo]: [{id,title,x,y,w,h}] }
let _svpUndoStack = []; // Array of {sheetNo, snapshot} for Ctrl+Z
let _svpCurrentSheet = null;
let _svpDragging = null; // {el, id, startX, startY, origLeft, origTop}

function _svpLoad() {
  try { _svpState = JSON.parse(localStorage.getItem(_svpKey) || '{}'); } catch { _svpState = {}; }
}
function _svpSave() {
  try { localStorage.setItem(_svpKey, JSON.stringify(_svpState)); } catch {}
}

// Default view layout for a given sheet — pre-populates sensible starting positions
function _defaultViewsForSheet(sheetNo, sheetTitle) {
  const SHEET_W = 680, SHEET_H = 480;
  // Each view tile is sized proportionally to the sheet area
  const views = [];
  if (sheetNo.startsWith('A-2')) {
    // Floor plan sheets: one large plan view + small legend box
    views.push({ id: 'plan-main', title: 'Floor Plan', x: 20, y: 20, w: 480, h: 380 });
    views.push({ id: 'plan-legend', title: 'Legend', x: 515, y: 20, w: 140, h: 120 });
    views.push({ id: 'plan-north', title: 'North Arrow', x: 515, y: 155, w: 80, h: 80 });
  } else if (sheetNo.startsWith('A-3')) {
    // Section sheets
    views.push({ id: 'sec-a', title: 'Section A-A', x: 20, y: 20, w: 380, h: 380 });
    views.push({ id: 'sec-detail', title: 'Detail 1', x: 415, y: 20, w: 240, h: 200 });
    views.push({ id: 'sec-notes', title: 'Notes', x: 415, y: 235, w: 240, h: 160 });
  } else if (sheetNo.startsWith('A-4') || sheetNo.startsWith('A-5')) {
    // Schedule sheets: wide table views
    views.push({ id: 'sched-main', title: sheetTitle, x: 20, y: 20, w: 630, h: 280 });
    views.push({ id: 'sched-notes', title: 'General Notes', x: 20, y: 315, w: 310, h: 120 });
  } else if (sheetNo.startsWith('EN-')) {
    // Energy sheets
    views.push({ id: 'en-table', title: 'Compliance Table', x: 20, y: 20, w: 450, h: 320 });
    views.push({ id: 'en-chart', title: 'Energy Chart', x: 485, y: 20, w: 170, h: 200 });
  } else {
    // Generic: two views side by side
    views.push({ id: 'view-a', title: sheetTitle, x: 20, y: 20, w: 400, h: 350 });
    views.push({ id: 'view-b', title: 'Notes & References', x: 435, y: 20, w: 220, h: 200 });
  }
  return views;
}

// ── Open the sheet viewport viewer (localStorage fallback) ─────────────────
function openSheetViewport(sheetNo, sheetTitle) {
  _svpLoad();
  _svpCurrentSheet = sheetNo;
  if (!_svpState[sheetNo]) {
    _svpState[sheetNo] = _defaultViewsForSheet(sheetNo, sheetTitle);
    _svpSave();
  }
  const wrap = document.getElementById('db-sheet-viewport-wrap');
  const titleEl = document.getElementById('db-svp-title');
  if (titleEl) titleEl.textContent = `${sheetNo} — ${sheetTitle}`;
  wrap?.classList.remove('hidden');
  renderSheetViewport(sheetNo);
  wrap?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

// ── Open sheet viewport from DB sheet ────────────────────────────────────
function openSheetViewportDb(sheetId, sheetNo, sheetName) {
  const sheet = dbState.sheets.find(s => s.id == sheetId);
  if (!sheet) return;
  _svpCurrentSheet = sheetNo;
  const wrap = document.getElementById('db-sheet-viewport-wrap');
  const titleEl = document.getElementById('db-svp-title');
  if (titleEl) titleEl.textContent = `${sheetNo}: ${sheetName}`;

  // Sync viewports from DB into _svpState
  const dbViewports = dbState.viewports[sheet.id] || [];
  if (dbViewports.length) {
    _svpState[sheetNo] = dbViewports.map(vp => ({
      id: String(vp.id),
      title: vp.title || vp.view_type || 'View',
      x: (vp.x_pt || 72),
      y: (vp.y_pt || 72),
      w: (vp.width_pt || 648),
      h: (vp.height_pt || 486),
    }));
  } else {
    _svpLoad();
    if (!_svpState[sheetNo]) {
      _svpState[sheetNo] = _defaultViewsForSheet(sheetNo, sheetName);
    }
  }
  _svpSave();
  wrap?.classList.remove('hidden');
  renderSheetViewport(sheetNo);
  wrap?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

document.getElementById('db-svp-close')?.addEventListener('click', () => {
  document.getElementById('db-sheet-viewport-wrap')?.classList.add('hidden');
  _svpCurrentSheet = null;
});

// ── Render placed views on canvas ─────────────────────────────────────────
function renderSheetViewport(sheetNo) {
  const canvas = document.getElementById('db-sheet-canvas');
  if (!canvas) return;
  const views = _svpState[sheetNo] || [];

  // Grid overlay element (reuse or create)
  let gridOverlay = canvas.querySelector('.db-align-grid-overlay');
  if (!gridOverlay) {
    gridOverlay = document.createElement('div');
    gridOverlay.className = 'db-align-grid-overlay';
    canvas.appendChild(gridOverlay);
  }

  // Remove old view tiles (keep overlay)
  canvas.querySelectorAll('.db-sheet-view').forEach(el => el.remove());

  for (const v of views) {
    const tile = document.createElement('div');
    tile.className = 'db-sheet-view';
    tile.id = `svp-view-${v.id}`;
    tile.style.left = v.x + 'px';
    tile.style.top = v.y + 'px';
    tile.style.width = v.w + 'px';
    tile.style.height = v.h + 'px';
    tile.innerHTML = `
      <div class="db-sheet-view-title">${escHtml(v.title)}</div>
      <div class="db-sheet-view-body">
        <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#4a7dbd" stroke-width="1.5" opacity=".4">
          <rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="9" y1="21" x2="9" y2="9"/>
        </svg>
      </div>`;

    // Drag to reposition
    tile?.addEventListener('mousedown', _svpOnDragStart);
    canvas.appendChild(tile);
  }
}

// ── Drag-to-reposition ────────────────────────────────────────────────────
function _svpOnDragStart(e) {
  if (e.button !== 0) return;
  const tile = e.currentTarget;
  const id = tile.id.replace('svp-view-', '');
  _svpDragging = {
    el: tile,
    id,
    startX: e.clientX,
    startY: e.clientY,
    origLeft: parseInt(tile.style.left, 10),
    origTop: parseInt(tile.style.top, 10),
  };
  tile.classList.add('dragging');
  e.preventDefault();
}

document.addEventListener('mousemove', e => {
  if (!_svpDragging) return;
  const dx = e.clientX - _svpDragging.startX;
  const dy = e.clientY - _svpDragging.startY;
  const newX = Math.max(0, _svpDragging.origLeft + dx);
  const newY = Math.max(0, _svpDragging.origTop + dy);
  _svpDragging.el.style.left = newX + 'px';
  _svpDragging.el.style.top = newY + 'px';
});

document.addEventListener('mouseup', () => {
  if (!_svpDragging) return;
  const { el, id } = _svpDragging;
  el.classList.remove('dragging');
  // Snap to grid on release
  const gridMm = parseFloat(document.getElementById('aap-grid-size')?.value || '3.175');
  const gridPx = _mmToPx(gridMm);
  const snappedX = Math.round(parseInt(el.style.left, 10) / gridPx) * gridPx;
  const snappedY = Math.round(parseInt(el.style.top, 10) / gridPx) * gridPx;
  el.style.left = snappedX + 'px';
  el.style.top = snappedY + 'px';
  // Persist
  if (_svpCurrentSheet && _svpState[_svpCurrentSheet]) {
    const v = _svpState[_svpCurrentSheet].find(v => v.id === id);
    if (v) { v.x = snappedX; v.y = snappedY; }
    _svpSave();
  }
  _svpDragging = null;
});

// ── Unit helper: treat 1px = 0.264583mm (96dpi) ──────────────────────────
function _mmToPx(mm) { return mm / 0.264583; }

// ── PDF Export ────────────────────────────────────────────────────────────

