// ── Auto-Align confirm ────────────────────────────────────────────────────
document.getElementById('aap-confirm')?.addEventListener('click', () => {
  document.getElementById('auto-align-popover')?.classList.add('hidden');
  const applyAll = document.getElementById('aap-all-sheets')?.checked;
  const gridMm = parseFloat(document.getElementById('aap-grid-size')?.value || '3.175');
  _svpLoad();

  const sheets = buildSheetIndex().filter(s => s.include);
  const targetSheets = applyAll ? sheets.map(s => s.no) : (_svpCurrentSheet ? [_svpCurrentSheet] : []);
  if (!targetSheets.length) { toast('No sheet open. Click a sheet row first.', 'info', 2200); return; }

  // Push undo snapshot before aligning
  _svpUndoStack.push({
    sheets: targetSheets,
    snapshot: JSON.parse(JSON.stringify(Object.fromEntries(targetSheets.map(no => [no, _svpState[no] || []])))),
  });
  if (_svpUndoStack.length > 20) _svpUndoStack.shift();

  let totalViews = 0;
  const gridPx = _mmToPx(gridMm);

  for (const sheetNo of targetSheets) {
    // Ensure sheet has default views if not yet visited
    if (!_svpState[sheetNo]) {
      const s = sheets.find(s => s.no === sheetNo);
      _svpState[sheetNo] = _defaultViewsForSheet(sheetNo, s ? s.title : sheetNo);
    }
    const views = _svpState[sheetNo];
    if (!views.length) continue;

    // Find shared origin: top-left corner of bounding union of all views
    const minX = Math.min(...views.map(v => v.x));
    const minY = Math.min(...views.map(v => v.y));

    // Snap every view to the grid, preserving relative positions from the shared origin
    for (const v of views) {
      const relX = v.x - minX;
      const relY = v.y - minY;
      const snappedRelX = Math.round(relX / gridPx) * gridPx;
      const snappedRelY = Math.round(relY / gridPx) * gridPx;
      // Anchor origin to grid too
      const anchorX = Math.round(minX / gridPx) * gridPx;
      const anchorY = Math.round(minY / gridPx) * gridPx;
      v.x = anchorX + snappedRelX;
      v.y = anchorY + snappedRelY;
      totalViews++;
    }
  }

  _svpSave();

  // Re-render current sheet with snap animation
  if (_svpCurrentSheet && targetSheets.includes(_svpCurrentSheet)) {
    renderSheetViewport(_svpCurrentSheet);
    // Brief grid flash
    const gridOverlay = document.querySelector('#db-sheet-canvas .db-align-grid-overlay');
    if (gridOverlay) {
      const sz = _mmToPx(gridMm) + 'px';
      gridOverlay.style.backgroundSize = `${sz} ${sz}`;
      gridOverlay.classList.add('show');
      // Animate tiles
      document.querySelectorAll('#db-sheet-canvas .db-sheet-view').forEach((el, i) => {
        setTimeout(() => el.classList.add('just-aligned'), i * 40);
        setTimeout(() => el.classList.remove('just-aligned'), i * 40 + 400);
      });
      setTimeout(() => gridOverlay.classList.remove('show'), 700);
    }
  }

  const sheetCount = targetSheets.length;
  toast(`Aligned ${totalViews} view${totalViews !== 1 ? 's' : ''} across ${sheetCount} sheet${sheetCount !== 1 ? 's' : ''}`, 'success', 2800);
});

// ── Undo (Ctrl+Z) for auto-align ──────────────────────────────────────────
document.addEventListener('keydown', e => {
  // Only fire when design book overlay is visible (does NOT have 'hidden')
  if (document.getElementById('design-book-overlay')?.classList.contains('hidden')) return;
  if ((e.ctrlKey || e.metaKey) && e.key === 'z' && !e.shiftKey) {
    if (!_svpUndoStack.length) { toast('Nothing to undo', 'info', 1400); return; }
    e.preventDefault();
    const entry = _svpUndoStack.pop();
    for (const [sheetNo, snap] of Object.entries(entry.snapshot)) {
      _svpState[sheetNo] = JSON.parse(JSON.stringify(snap));
    }
    _svpSave();
    if (_svpCurrentSheet && entry.sheets.includes(_svpCurrentSheet)) {
      renderSheetViewport(_svpCurrentSheet);
    }
    toast('Undo: alignment reverted', 'info', 1600);
  }
});

