  async function loadModuleOverlayStats() {
    if (!currentProjectId) return;
    try {
      const res = await fetch(`/api/attachments/overlays/${currentProjectId}`);
      const data = await res.json();
      const s = data.stats || { RED: 0, AMBER: 0, GREEN: 0 };
      const redEl = document.getElementById('overlay-red-count');
      const amberEl = document.getElementById('overlay-amber-count');
      const greenEl = document.getElementById('overlay-green-count');
      if (redEl) redEl.textContent = `${s.RED} RED`;
      if (amberEl) amberEl.textContent = `${s.AMBER} AMBER`;
      if (greenEl) greenEl.textContent = `${s.GREEN} GREEN`;
      const summary = document.getElementById('module-overlay-summary');
      if (summary) {
        if (s.RED > 0) summary.style.background = 'rgba(239,68,68,0.1)';
        else if (s.AMBER > 0) summary.style.background = 'rgba(245,158,11,0.1)';
        else summary.style.background = 'rgba(34,197,94,0.08)';
        summary.style.border = '1px solid var(--border)';
        summary.style.display = 'block';
      }
    } catch (err) { console.error('[module] overlay stats error:', err); }
  }

  // ─── 3D Attachment Overlay Rendering ─────────────────────────────────────
  /**
   * Render RED/AMBER/GREEN overlay badges on elements in the 3D view.
   * Overlays stored in module overlay table; rendered as colored edge overlays.
   */
  const overlayBadges3D = new Map(); // elementId → THREE.Mesh
  const overlayColors = { RED: 0xff4444, AMBER: 0xff9900, GREEN: 0x22cc66 };

  window.renderOverlay3D = renderOverlay3D;
  function renderOverlay3D(overlays) {
    // Clear old badges
    for (const [, mesh] of overlayBadges3D) {
      scene.remove(mesh);
    }
    overlayBadges3D.clear();

    for (const ov of overlays) {
      if (ov.verdict === 'GREEN' || !ov.resolved_at) {
        // Only show RED and unresolved AMBER/RED overlays in 3D
        if (ov.verdict === 'GREEN') continue;
      }

      // Find element in scene by ID
      const elObj = elementObjects.get(ov.element_id);
      if (!elObj) continue;

      const color = overlayColors[ov.verdict] || 0xff0000;
      const badge = createOverlayBadge(elObj, color, ov.verdict);
      if (badge) {
        scene.add(badge);
        overlayBadges3D.set(ov.element_id, badge);
      }
    }
  }

  function createOverlayBadge(elementObj, color, verdict) {
    const box = new THREE.Box3().setFromObject(elementObj);
    const size = new THREE.Vector3();
    box.getSize(size);
    const center = new THREE.Vector3();
    box.getCenter(center);

    // Place badge slightly above the element, offset to be visible
    const badgePos = new THREE.Vector3(center.x, center.y + size.y / 2 + 50, center.z);

    const geo = new THREE.SphereGeometry(verdict === 'RED' ? 60 : verdict === 'AMBER' ? 45 : 30, 16, 16);
    const mat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: verdict === 'RED' ? 0.85 : verdict === 'AMBER' ? 0.7 : 0.5,
      depthTest: false,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(badgePos);
    mesh.renderOrder = 999;
    // Make it always face camera
    mesh.userData.isOverlayBadge = true;
    mesh.userData.overlayVerdict = verdict;
    return mesh;
  }

  // Update badge positions on each render frame (called from animate loop)
  function updateOverlayBadges() {
    if (overlayBadges3D.size === 0) return;
    for (const [elementId, mesh] of overlayBadges3D) {
      const elObj = elementObjects.get(elementId);
      if (!elObj) { scene.remove(mesh); overlayBadges3D.delete(elementId); continue; }
      const box = new THREE.Box3().setFromObject(elObj);
      const size = new THREE.Vector3();
      box.getSize(size);
      const center = new THREE.Vector3();
      box.getCenter(center);
      mesh.position.set(center.x, center.y + size.y / 2 + 50, center.z);
    }
  }

  // Clear overlays on project change
  window.clearAttachmentOverlays = function() {
    for (const [, mesh] of overlayBadges3D) scene.remove(mesh);
    overlayBadges3D.clear();
  };

  // ─── Load Path Status Renderer ─────────────────────────────────────────────
  function renderLoadPathStatus(data) {
    const badge = document.getElementById('audit-load-path-badge');
    if (!badge) return;

    const summary = data.summary || {};
    const missing = data.missing_support || [];

    if (summary.missing_support_count > 0) {
      badge.style.display = 'block';
      badge.style.background = 'rgba(239,68,68,0.12)';
      badge.style.border = '1px solid rgba(239,68,68,0.3)';
      badge.style.color = '#ef4444';
      badge.textContent = `⚠ ${summary.missing_support_count} element(s) with missing structural support — DOB violation`;
    } else if (summary.has_lateral) {
      badge.style.display = 'block';
      badge.style.background = 'rgba(34,197,94,0.08)';
      badge.style.border = '1px solid rgba(34,197,94,0.2)';
      badge.style.color = '#22c55e';
      badge.textContent = `✓ Load path complete — lateral system: ${summary.lateral_system_types?.join(', ') || 'detected'}`;
    } else {
      badge.style.display = 'block';
      badge.style.background = 'rgba(245,158,11,0.08)';
      badge.style.border = '1px solid rgba(245,158,11,0.2)';
      badge.style.color = '#f59e0b';
      badge.textContent = '✓ Load path computed — no issues detected';
    }
  }

